LOCAL_ENV_FILES_LOADED = []


def _load_local_env_file(path):
    if not os.path.exists(path):
        return
    loaded_any = False
    with open(path, "r", encoding="utf-8") as handle:
        for raw_line in handle:
            line = raw_line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip().strip("'").strip('"')
            if key and key not in os.environ:
                os.environ[key] = value
                loaded_any = True
    if loaded_any:
        LOCAL_ENV_FILES_LOADED.append(path)


def _load_local_environment():
    if os.getenv("COINPILOTX_DISABLE_LOCAL_ENV", "").strip().lower() in {"1", "true", "yes", "on"}:
        return
    root = os.path.dirname(os.path.abspath(__file__))
    _load_local_env_file(os.path.join(root, ".env.local"))
    _load_local_env_file(os.path.join(root, ".env"))


def _deployment_environment_enabled():
    return any(os.getenv(key) for key in ("RAILWAY_ENVIRONMENT", "RAILWAY_PROJECT_ID", "RENDER", "FLY_APP_NAME")) or os.getenv("ENV", "").lower() == "production" or os.getenv("FLASK_ENV", "").lower() == "production"


def _env_bool(key, default):
    if key in os.environ:
        return os.getenv(key, "").strip().lower() in {"1", "true", "yes", "on"}
    return bool(default)


def _redact_database_url(value):
    if not value:
        return ""
    return re.sub(r"//([^:/@]+):([^@]+)@", r"//\1:***@", value)


