@webhook_app.route("/reset-pwa", methods=["GET"])
def reset_pwa_page():
    html = """
    <!doctype html>
    <html lang="en">
    <head>
      <meta charset="utf-8">
      <meta name="viewport" content="width=device-width, initial-scale=1">
      <title>Reset CoinPilotXAI App Cache</title>
      <style>
        body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:#050b14;color:#f2fbff;font-family:Inter,system-ui,Arial,sans-serif}
        main{width:min(100%,560px);padding:28px;border:1px solid rgba(0,229,255,.22);border-radius:14px;background:#0d1627;text-align:center;box-shadow:0 24px 70px rgba(0,0,0,.35)}
        p{color:#9fb5c0;line-height:1.6}
      </style>
    </head>
    <body>
      <main>
        <h1>Resetting CoinPilotXAI app cache</h1>
        <p>Clearing old offline cache, service workers, and local app flags. You will be returned to PulseSoc Home automatically.</p>
      </main>
      <script>
        (async function () {
          try {
            console.log("[CoinPilotXAI PWA] reset started");
            if ("serviceWorker" in navigator) {
              var regs = await navigator.serviceWorker.getRegistrations();
              await Promise.all(regs.map(function (reg) { return reg.unregister(); }));
              console.log("[CoinPilotXAI PWA] service workers unregistered", regs.length);
            }
            if ("caches" in window) {
              var keys = await caches.keys();
              await Promise.all(keys.map(function (key) { return caches.delete(key); }));
              console.log("[CoinPilotXAI PWA] caches deleted", keys);
            }
            if ("indexedDB" in window && indexedDB.databases) {
              var databases = await indexedDB.databases();
              await Promise.all(databases.map(function (db) {
                return db && db.name ? new Promise(function (resolve) {
                  var req = indexedDB.deleteDatabase(db.name);
                  req.onsuccess = req.onerror = req.onblocked = function () { resolve(); };
                }) : Promise.resolve();
              }));
              console.log("[CoinPilotXAI PWA] indexedDB cleared");
            }
            try { localStorage.clear(); } catch (err) {}
            try { sessionStorage.clear(); } catch (err) {}
            try {
              localStorage.removeItem("coinpilotx_install_popup_dismissed_until");
              localStorage.removeItem("coinpilotx_offline");
              localStorage.removeItem("coinpilotx_offline_mode");
              localStorage.removeItem("offline");
            } catch (err) {}
          } finally {
            setTimeout(function () { location.href = "/pulse?reset_pwa=1&ts=" + Date.now(); }, 1000);
          }
        })();
      </script>
    </body>
    </html>
    """
    response = Response(html, mimetype="text/html")
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


@webhook_app.before_request
def start_performance_trace():
    g.performance_trace_id = request.headers.get("X-Trace-Id") or secrets.token_hex(6)
    g.performance_start = time.perf_counter()
    g.db_query_count = 0
    g.db_duration_ms = 0
    g.db_connection_count = 0
    g.r2_duration_ms = 0
    g.rows_returned = 0
    g.db_query_signatures = {}
    return None


@webhook_app.before_request
def redirect_www_to_apex_domain():
    host = (request.host or "").split(":", 1)[0].lower()
    if host != "www.coinpilotx.app":
        return None
    path = request.full_path or request.path or "/"
    if path.endswith("?"):
        path = path[:-1]
    return redirect(f"https://pulsesoc.com{path}", code=301)


def record_performance_trace(path, method, status, duration_ms, db_queries, response_size, trace_id, level):
    try:
        if os.getenv("PERFORMANCE_TRACE_PERSIST_ENABLED", "").strip().lower() not in {"1", "true", "yes", "on"}:
            return
        if duration_ms < PERFORMANCE_SLOW_MS and level != "critical":
            return
        conn = db()
        cur = conn.cursor()
        duplicates = {
            key: count for key, count in (getattr(g, "db_query_signatures", {}) or {}).items()
            if int(count or 0) > 1
        }
        cur.execute(
            """
            INSERT INTO performance_traces
            (trace_id, path, method, status_code, duration_ms, db_query_count, db_connection_count, response_size, user_id, level, duplicate_queries_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                trace_id,
                str(path or "")[:500],
                str(method or "")[:12],
                int(status or 0),
                int(duration_ms or 0),
                int(db_queries or 0),
                int(getattr(g, "db_connection_count", 0) or 0),
                int(response_size or 0),
                int(account_user_id() or 0),
                level,
                json.dumps(duplicates)[:4000],
                datetime.utcnow().isoformat(timespec="seconds"),
            ),
        )
        conn.commit()
        conn.close()
    except Exception as exc:
        logging.debug("performance trace store skipped path=%s error=%s", path, exc)


@webhook_app.after_request
def add_pwa_headers(response):
    response.headers.setdefault("X-Content-Type-Options", "nosniff")
    response.headers.setdefault("Referrer-Policy", "strict-origin-when-cross-origin")
    for header_name, header_value in pulse_security_core.security_headers().items():
        response.headers.setdefault(header_name, header_value)
    pulse_call_surface = request.path == "/pulse" or request.path.startswith(("/pulse/", "/dashboard"))
    if request.path.startswith(("/pulse/camera", "/pulse/live")) or pulse_call_surface:
        response.headers.setdefault("Permissions-Policy", "camera=(self), microphone=(self), geolocation=()")
    else:
        response.headers.setdefault("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
    response.headers.setdefault("X-Frame-Options", "SAMEORIGIN")
    if request.headers.get("X-Forwarded-Proto", request.scheme) == "https":
        response.headers.setdefault("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
    if not request.path.startswith(("/api/", "/static/")):
        request_host = (request.host or "").split(":", 1)[0].lower()
        desktop_connector_enabled = os.getenv("UNDX_DESKTOP_CONNECTOR_ENABLED", "").strip().lower() in {"1", "true", "yes", "on"}
        local_request = request_host in {"localhost", "127.0.0.1", "0.0.0.0", "::1"}
        connector_sources = ""
        if local_request or desktop_connector_enabled:
            connector_sources = " http://127.0.0.1:8765 http://localhost:8765 http://127.0.0.1:* http://localhost:* ws://127.0.0.1:8765 ws://localhost:8765 ws://127.0.0.1:* ws://localhost:*"
        upgrade_insecure_requests = "" if connector_sources else " upgrade-insecure-requests;"
        response.headers.setdefault(
            "Content-Security-Policy",
            "default-src 'self'; object-src 'none'; img-src 'self' data: blob: https:; media-src 'self' blob: https:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://static.cloudflareinsights.com; connect-src 'self' https: wss:" + connector_sources + "; frame-ancestors 'self'; base-uri 'self'; form-action 'self' https://checkout.stripe.com;" + upgrade_insecure_requests,
        )
    if request.path in ("/static/service-worker.js", "/sw.js"):
        response.headers["Service-Worker-Allowed"] = "/"
        response.headers["Cache-Control"] = "no-store, max-age=0"
    elif request.path == "/pulse" or request.path.startswith("/pulse/") or request.path.startswith("/api/pulse/"):
        response.headers["Cache-Control"] = "no-store, max-age=0"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
    elif request.path.startswith(("/static/", "/icons/")):
        response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
    elif request.path in ("/sitemap.xml", "/sitemap-pages.xml", "/sitemap-live.xml", "/sitemap-replays.xml", "/robots.txt", "/llms.txt", "/ai-index.json", "/manifest.json", "/site.webmanifest"):
        response.headers["Cache-Control"] = "public, max-age=300"
    if (
        response.status_code == 200
        and not response.direct_passthrough
        and "text/html" in (response.headers.get("Content-Type") or "")
    ):
        try:
            html = response.get_data(as_text=True)
            if "</head>" in html.lower() and "/static/brand/pulse-favicon-32-20260606.png" not in html:
                favicon_tags = """
<link rel="icon" type="image/png" sizes="32x32" href="/static/brand/pulse-favicon-32-20260606.png">
<link rel="icon" type="image/png" sizes="16x16" href="/static/brand/pulse-favicon-16-20260606.png">
<link rel="shortcut icon" href="/favicon.ico">
<link rel="apple-touch-icon" sizes="180x180" href="/static/brand/pulsesoc-apple-touch-icon-20260606.png">
<link rel="manifest" href="/manifest.json">
<meta name="theme-color" content="#020817">
"""
                html = re.sub(r"</head>", favicon_tags + "</head>", html, count=1, flags=re.I)
                response.set_data(html)
                response.headers.pop("Content-Length", None)
            if "</body>" in html.lower() and "/static/js/pulse_pwa_install.js" not in html:
                pwa_install_script = '<script src="/static/js/pulse_pwa_install.js?v=install-20260606-restore" defer></script>'
                html = re.sub(r"</body>", pwa_install_script + "</body>", html, count=1, flags=re.I)
                response.set_data(html)
                response.headers.pop("Content-Length", None)
            if "</head>" in html.lower() and "/static/js/pulse_i18n.js" not in html:
                i18n_script = '<script src="/static/js/pulse_i18n.js?v=persistent-language-20260701" defer></script>'
                html = re.sub(r"</head>", i18n_script + "</head>", html, count=1, flags=re.I)
                response.set_data(html)
                response.headers.pop("Content-Length", None)
            call_overlay_allowed = bool(session.get("account_user_id")) and (
                request.path == "/pulse" or request.path.startswith(("/pulse/", "/dashboard"))
            )
            if call_overlay_allowed and "</head>" in html.lower() and "/static/css/pulsesoc_global_call_overlay.css" not in html:
                call_overlay_css = '<link rel="stylesheet" href="/static/css/pulsesoc_global_call_overlay.css?v=fullscreen-incoming-20260704">'
                html = re.sub(r"</head>", call_overlay_css + "</head>", html, count=1, flags=re.I)
                response.set_data(html)
                response.headers.pop("Content-Length", None)
            if call_overlay_allowed and "</body>" in html.lower() and "/static/js/pulsesoc_global_call_overlay.js" not in html:
                call_overlay_script = '<script src="/static/js/pulsesoc_global_call_overlay.js?v=fullscreen-incoming-20260704" defer></script>'
                html = re.sub(r"</body>", call_overlay_script + "</body>", html, count=1, flags=re.I)
                response.set_data(html)
                response.headers.pop("Content-Length", None)
        except Exception as exc:
            logging.info("GLOBAL_FAVICON_INJECT_SKIPPED path=%s error=%s", request.path, exc)
    try:
        duration_ms = int((time.perf_counter() - float(getattr(g, "performance_start", time.perf_counter()))) * 1000)
        response_size = response.calculate_content_length()
        if response_size is None:
            response_size = len(response.get_data()) if not response.direct_passthrough else 0
        db_queries = int(getattr(g, "db_query_count", 0) or 0)
        db_duration_ms = int(getattr(g, "db_duration_ms", 0) or 0)
        r2_duration_ms = int(getattr(g, "r2_duration_ms", 0) or 0)
        rows_returned = int(getattr(g, "rows_returned", 0) or 0)
        slowest_query = getattr(g, "db_slowest_query", {}) or {}
        trace_id = getattr(g, "performance_trace_id", secrets.token_hex(6))
        level = "critical" if duration_ms >= PERFORMANCE_CRITICAL_MS else "warning" if duration_ms >= PERFORMANCE_SLOW_MS else "info"
        response.headers.setdefault("X-Trace-Id", trace_id)
        response.headers.setdefault("X-Response-Time-Ms", str(duration_ms))
        response.headers.setdefault("X-DB-Query-Count", str(db_queries))
        response.headers.setdefault("X-DB-Duration-Ms", str(db_duration_ms))
        response.headers.setdefault("X-R2-Duration-Ms", str(r2_duration_ms))
        response.headers.setdefault("X-Rows-Returned", str(rows_returned))
        logging.log(
            logging.ERROR if level == "critical" else logging.WARNING if level == "warning" else logging.INFO,
            "PERF_REQUEST trace_id=%s method=%s path=%s status=%s duration_ms=%s db_duration_ms=%s r2_duration_ms=%s db_queries=%s db_connections=%s rows_returned=%s user_id=%s response_size=%s slowest_query_ms=%s slowest_query=%s level=%s",
            trace_id,
            request.method,
            request.path,
            response.status_code,
            duration_ms,
            db_duration_ms,
            r2_duration_ms,
            db_queries,
            int(getattr(g, "db_connection_count", 0) or 0),
            rows_returned,
            account_user_id() or 0,
            response_size,
            int(slowest_query.get("duration_ms") or 0),
            str(slowest_query.get("sql") or "")[:220],
            level,
        )
        if level in {"warning", "critical"}:
            record_performance_trace(request.path, request.method, response.status_code, duration_ms, db_queries, response_size, trace_id, level)
    except Exception as exc:
        logging.debug("PERF_REQUEST_LOG_SKIPPED path=%s error=%s", request.path, exc)
    if getattr(g, "persistent_session_clear_cookie", False):
        clear_persistent_session_cookie(response)
    rotated_refresh_token = getattr(g, "persistent_session_refresh_token", "")
    if rotated_refresh_token:
        set_persistent_session_cookie(response, rotated_refresh_token)
    return response


@webhook_app.before_request
def enforce_https():
    host = request.host.split(":")[0]
    if host in {"localhost", "127.0.0.1", "0.0.0.0"}:
        return None
    forwarded_proto = request.headers.get("X-Forwarded-Proto", request.scheme)
    if forwarded_proto == "http":
        return redirect(request.url.replace("http://", "https://", 1), code=301)


@webhook_app.before_request
def enforce_arena_pro_access():
    path = request.path or ""
    public_arena_prefixes = (
        "/arena-preview",
        "/arena/player/",
        "/api/arena/share/",
    )
    if not (path == "/arena" or path.startswith("/arena/") or path.startswith("/api/arena/")):
        return None
    if path.startswith(public_arena_prefixes):
        return None
    user = load_account_by_id(account_user_id())
    if not user:
        if path.startswith("/api/arena/"):
            log_security_event("arena_api_auth_required", "blocked", 0, path)
            return jsonify({"ok": False, "message": "Please log in to use Arena.", "login_url": url_for("login_page", next=path)}), 401
        return redirect(url_for("login_page", next=path))
    if not platform_pro_access(user):
        return arena_access_preview_response(user)
    return None
    return None


@webhook_app.before_request
def capture_referral_and_run_trial_maintenance():
    ref = (request.args.get("ref") or "").strip()[:80]
    if ref:
        session["referred_by"] = ref
    if request.path.startswith(("/static/", "/api/track", "/health")):
        return None
    if os.getenv("TRIAL_MAINTENANCE_ON_REQUEST", "").strip().lower() in {"1", "true", "yes", "on"}:
        run_trial_maintenance()
    return None


@webhook_app.before_request
def basic_abuse_guard():
    protected = {
        "/login": (12, 300),
        "/signup": (8, 300),
        "/forgot-password": (6, 300),
        "/forgot-username": (6, 300),
        "/admin/login": (8, 300),
        "/create-checkout-session": (8, 300),
        "/api/create-checkout-session": (8, 300),
        "/api/ai-assistant": (30, 300),
    }
    if request.method not in {"POST", "PUT"} or request.path not in protected:
        return None
    limit, window_seconds = protected[request.path]
    key = f"{client_ip_hash()}:{request.path}"
    now = time.time()
    bucket = [stamp for stamp in RATE_LIMIT_BUCKETS.get(key, []) if now - stamp < window_seconds]
    if len(bucket) >= limit:
        logging.warning("Rate limit triggered path=%s ip_hash=%s", request.path, client_ip_hash())
        if request.path.startswith("/api/"):
            return jsonify({"ok": False, "message": "Too many attempts. Please wait a few minutes and try again."}), 429
        return Response("Too many attempts. Please wait a few minutes and try again.", status=429)
    bucket.append(now)
    RATE_LIMIT_BUCKETS[key] = bucket
    return None


def pulse_cohost_guard_error(path, error_code, message, step, status, *, retry_after=0, unknown_fields=None):
    match = re.fullmatch(r"/api/pulse/live/([^/]+)/cohost/request", str(path or ""))
    if not match or request.method != "POST":
        return None
    raw_payload = request.get_json(silent=True)
    payload = raw_payload if isinstance(raw_payload, dict) else {}
    trace_id = clean_html(payload.get("trace_id") or secrets.token_hex(6))[:80]
    raw_live_id = match.group(1)
    live_id = int(raw_live_id) if raw_live_id.isdigit() else 0
    response_payload = {
        "ok": False,
        "success": False,
        "error_code": clean_html(error_code)[:80],
        "message": clean_html(message)[:500],
        "step": clean_html(step)[:80],
        "state": clean_html(step)[:80],
        "trace_id": trace_id,
        "live_id": live_id,
        "viewer_user_id": int(account_user_id() or 0),
        "host_user_id": 0,
        "request_id": 0,
    }
    if retry_after:
        response_payload["retry_after"] = int(retry_after)
    if unknown_fields:
        response_payload["unknown_fields"] = list(unknown_fields)[:20]
    logging.warning(
        "PULSE_COHOST_FAILURE trace_id=%s live_id=%s user_id=%s step_failed=%s reason=%s timestamp=%s",
        trace_id,
        live_id,
        response_payload["viewer_user_id"],
        step,
        error_code,
        datetime.utcnow().isoformat(timespec="seconds"),
    )
    return jsonify(response_payload), int(status)


@webhook_app.before_request
def pulse_security_core_guard():
    path = request.path or ""
    if request.method == "OPTIONS" or path.startswith(("/static/", "/icons/", "/health")):
        return None
    kill_switch = pulse_security_core.kill_switch_for(path)
    if kill_switch.get("blocked"):
        security_monitor.record(
            "pulse_security_kill_switch_block",
            "high",
            account_user_id() or 0,
            client_ip_hash(),
            path,
            {"switch": kill_switch.get("switch"), "env": kill_switch.get("env")},
        )
        cohost_denied = pulse_cohost_guard_error(path, "COHOST_DISABLED", "Co-host requests are temporarily disabled by safety controls.", "security_gate", 503)
        if cohost_denied:
            return cohost_denied
        return jsonify({
            "ok": False,
            "message": "This PulseSoc feature is temporarily restricted while safety controls are active.",
            "security_state": "feature_restricted",
            "feature": kill_switch.get("switch"),
        }), 503
    device_hash = pulse_security_core.device_fingerprint(
        request.headers.get("User-Agent", ""),
        request.headers.get("X-PulseSoc-Device-Id", "") or request.headers.get("X-Device-Id", ""),
    )
    g.pulse_device_hash = device_hash
    limited = pulse_security_core.rate_limited(
        path=path,
        method=request.method,
        ip_hash=client_ip_hash(),
        user_id=account_user_id() or 0,
        device_hash=device_hash,
    )
    if limited.get("limited"):
        security_monitor.record(
            "pulse_security_rate_limited",
            limited.get("severity") or "medium",
            account_user_id() or 0,
            client_ip_hash(),
            path,
            {
                "action": limited.get("action"),
                "limit": limited.get("limit"),
                "window_seconds": limited.get("window_seconds"),
                "device_hash": device_hash[:16],
            },
        )
        cohost_denied = pulse_cohost_guard_error(path, "RATE_LIMITED", "Slow down for a moment, then try the co-host request again.", "security_gate", 429, retry_after=limited.get("retry_after") or 60)
        if cohost_denied:
            cohost_denied[0].headers["Retry-After"] = str(limited.get("retry_after") or 60)
            return cohost_denied
        response = jsonify({
            "ok": False,
            "message": "Slow down for a moment, then try again.",
            "security_state": "rate_limited",
            "retry_after": limited.get("retry_after") or 60,
        })
        response.headers["Retry-After"] = str(limited.get("retry_after") or 60)
        return response, 429
    if request.mimetype == "application/json":
        payload = request.get_json(silent=True)
        shape = pulse_security_core.validate_json_shape(path, payload)
        if not shape.get("ok"):
            security_monitor.record(
                "pulse_security_unknown_json_fields",
                "medium",
                account_user_id() or 0,
                client_ip_hash(),
                path,
                {"unknown_fields": shape.get("unknown_fields") or []},
            )
            cohost_denied = pulse_cohost_guard_error(path, "INVALID_REQUEST_PAYLOAD", "The co-host request contains unsupported fields.", "entry_validation", 400, unknown_fields=shape.get("unknown_fields") or [])
            if cohost_denied:
                return cohost_denied
            return jsonify({
                "ok": False,
                "message": "Request contains unsupported fields.",
                "security_state": "schema_rejected",
                "unknown_fields": shape.get("unknown_fields") or [],
            }), 400
    return None


@webhook_app.before_request
def interactive_security_guard():
    limit = security_guard.request_limit_for(request.path or "", request.method)
    if limit:
        max_hits, window_seconds = limit
        key = f"{client_ip_hash()}:{request.path}"
        if security_guard.rate_limited(key, max_hits, window_seconds):
            security_monitor.record("interactive_rate_limit", "medium", account_user_id() or 0, client_ip_hash(), request.path, {"limit": max_hits, "window_seconds": window_seconds})
            return jsonify({"ok": False, "message": "Slow down for a moment, then try again."}), 429
    if request.method in {"POST", "PUT", "PATCH"} and request.content_length:
        max_request_mb = 30.0
        if request.path.startswith("/api/pulse/communications/v2/attachments/upload"):
            max_request_mb = float(os.getenv("PULSE_COMM_V2_MAX_REQUEST_MB", os.getenv("COMM_V2_FILE_MAX_MB", "1024")))
        elif request.path == "/api/messages/media/upload":
            max_request_mb = float(os.getenv("MESSENGER_MEDIA_MAX_REQUEST_MB", os.getenv("MESSENGER_VIDEO_MAX_MB", "200")))
        elif request.path == "/api/pulse/media/upload":
            max_request_mb = float(os.getenv("PULSE_MEDIA_MAX_REQUEST_MB", os.getenv("MEDIA_UPLOAD_MAX_VIDEO_MB", "150")))
        max_request_bytes = int(max_request_mb * 1024 * 1024)
        if request.content_length > max_request_bytes:
            security_monitor.record("oversized_request_blocked", "high", account_user_id() or 0, client_ip_hash(), request.path, {"content_length": request.content_length, "max_request_mb": max_request_mb})
            return jsonify({
                "ok": False,
                "success": False,
                "message": f"Upload is too large. Videos can be up to {int(max_request_mb)} MB.",
                "error": "file_too_large",
                "max_upload_mb": int(max_request_mb),
            }), 413
    if request.mimetype == "application/json":
        raw = request.get_data(cache=True, as_text=True)[:6000]
        if security_guard.suspicious_text(raw):
            security_monitor.record("xss_payload_blocked", "high", account_user_id() or 0, client_ip_hash(), request.path, {"sample": raw[:180]})
            return jsonify({"ok": False, "message": "That content contains unsafe markup."}), 400
    for upload in request.files.values():
        if not security_guard.file_extension_allowed(upload.filename):
            security_monitor.record("unsafe_upload_extension_blocked", "high", account_user_id() or 0, client_ip_hash(), request.path, {"filename": upload.filename})
            return jsonify({"ok": False, "message": "That file type is not allowed."}), 400
    return None


@webhook_app.before_request
def log_visitor_request():
    if os.getenv("PULSESOC_VISITOR_LOGGING_ENABLED", "").strip().lower() not in {"1", "true", "yes", "on"}:
        return None
    if request.path.startswith(("/static/", "/icons/", "/manifest", "/site.webmanifest", "/sw.js")):
        return None
    if request.path.startswith(("/api/", "/internal/", "/webhook/", "/stripe-webhook")):
        return None
    if request.path in {"/", "/login", "/logout", "/signup", "/health", "/health/database"}:
        return None
    try:
        visitor_session_id = session.get("visitor_session_id")
        if not visitor_session_id:
            visitor_session_id = secrets.token_urlsafe(18)
            session["visitor_session_id"] = visitor_session_id
        now = datetime.now()
        dedupe_after = (now - timedelta(minutes=1)).isoformat()
        user_id = account_user_id() or 0
        ip_hash = client_ip_hash()
        user_agent = (request.headers.get("User-Agent") or "")[:500]
        referrer = (request.headers.get("Referer") or "")[:500]
        device_type, browser, os_name, _is_bot = visitor_user_agent_meta(user_agent)
        path = request.path[:500]
        upsert_visitor_session(path)
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            SELECT id FROM visitor_logs
            WHERE session_id=? AND path=? AND timestamp>=?
            LIMIT 1
            """,
            (visitor_session_id, path, dedupe_after),
        )
        if not cur.fetchone():
            cur.execute(
                """
                INSERT INTO visitor_logs
                (user_id, session_id, ip_address, user_agent, path, referrer, device_type, browser, os, timestamp)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (user_id, visitor_session_id, ip_hash, user_agent, path, referrer, device_type, browser, os_name, now.isoformat()),
            )
            conn.commit()
        conn.close()
    except Exception as exc:
        logging.debug("visitor log skipped safely: %s", exc)
    return None


@webhook_app.before_request
def record_pulsesoc_presence_activity():
    if request.method != "GET":
        return None
    path = request.path or ""
    if not should_record_presence_for_path(path):
        return None
    user_id = account_user_id()
    if not user_id:
        return None
    now = time.time()
    last_sent = float(session.get("presence_activity_at") or 0)
    if now - last_sent < PRESENCE_ACTIVITY_THROTTLE_SECONDS:
        return None
    session["presence_activity_at"] = now
    source = "native" if native_app_request_context().get("is_native") else "web"
    device_label = presence_device_label()
    record_local_presence_activity(user_id, "online", source, device_label)
    try:
        command_center_client_service.enqueue_presence_event(int(user_id), "online", source=source, device_label=device_label)
    except Exception as exc:
        logging.info("COMMAND_CENTER_PRESENCE_DISPATCH_SKIPPED user_id=%s error=%s", int(user_id or 0), exc.__class__.__name__)
    return None


@webhook_app.before_request
def enforce_admin_first_password_change():
    if not request.path.startswith("/admin/"):
        return None
    allowed = {
        "/admin/login",
        "/admin/logout",
        "/admin/change-password",
        "/admin/bootstrap-owner",
    }
    if request.path in allowed:
        return None
    admin = admin_current_user()
    if admin and int(admin.get("must_change_password") or 0) == 1:
        return redirect(url_for("admin_change_password_page"))
    return None


def get_csrf_token():
    token = session.get("csrf_token")
    if not token:
        token = secrets.token_urlsafe(32)
        session["csrf_token"] = token
    return token


def verify_csrf():
    return request.form.get("csrf_token") and request.form.get("csrf_token") == session.get("csrf_token")


def set_persistent_session_cookie(response, refresh_token):
    if not refresh_token:
        return response
    response.set_cookie(
        PERSISTENT_SESSION_COOKIE,
        refresh_token,
        max_age=PERSISTENT_SESSION_MAX_AGE,
        httponly=True,
        secure=COINPILOTX_SESSION_COOKIE_SECURE,
        samesite=PERSISTENT_SESSION_SAMESITE,
        path="/",
    )
    return response


def clear_persistent_session_cookie(response):
    response.delete_cookie(PERSISTENT_SESSION_COOKIE, path="/", samesite=PERSISTENT_SESSION_SAMESITE)
    return response


def restore_account_from_persistent_cookie():
    if not has_request_context() or session.get("account_user_id"):
        return session.get("account_user_id")
    if request.path.startswith(("/static/", "/icons/", "/health", "/manifest", "/site.webmanifest", "/sw.js")):
        return None
    refresh_token = request.cookies.get(PERSISTENT_SESSION_COOKIE) or ""
    if not refresh_token:
        return None
    user, token_payload = rotate_mobile_refresh_token(refresh_token, {"source": "web_cookie_refresh", "device_label": presence_device_label()})
    if not user:
        session.pop("account_user_id", None)
        g.persistent_session_clear_cookie = True
        return None
    session.permanent = True
    session["account_user_id"] = user["user_id"]
    session.setdefault("pulse_welcome_reason", "session_return")
    if token_payload.get("refresh_token"):
        g.persistent_session_refresh_token = token_payload["refresh_token"]
    return user["user_id"]


def account_user_id():
    return session.get("account_user_id") or restore_account_from_persistent_cookie()


PRESENCE_ACTIVITY_PATHS = {
    "/pulse",
    "/pulse/messages",
    "/pulse/profile",
    "/pulse/reels",
    "/pulse/videos",
    "/pulse/status",
}
PRESENCE_ACTIVITY_THROTTLE_SECONDS = 60


def ensure_user_presence_schema(cur=None, conn=None):
    close_conn = False
    if cur is None:
        conn = db()
        cur = conn.cursor()
        close_conn = True
    try:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS user_presence (
                user_id INTEGER PRIMARY KEY,
                status TEXT NOT NULL DEFAULT 'offline',
                last_seen_at TEXT,
                last_active_at TEXT,
                source TEXT,
                device_label TEXT,
                updated_at TEXT
            )
            """
        )
        try:
            safe_create_index(cur, conn, "CREATE INDEX IF NOT EXISTS idx_user_presence_user_id ON user_presence(user_id)")
            safe_create_index(cur, conn, "CREATE INDEX IF NOT EXISTS idx_user_presence_status ON user_presence(status, updated_at)")
        except NameError:
            cur.execute("CREATE INDEX IF NOT EXISTS idx_user_presence_user_id ON user_presence(user_id)")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_user_presence_status ON user_presence(status, updated_at)")
        if close_conn:
            conn.commit()
        return True
    except Exception as exc:
        logging.info("USER_PRESENCE_SCHEMA_SKIPPED error=%s", exc.__class__.__name__)
        try:
            if close_conn:
                conn.rollback()
        except Exception:
            pass
        return False
    finally:
        if close_conn:
            try:
                conn.close()
            except Exception:
                pass


def normalize_presence_status(status):
    value = str(status or "").strip().lower()
    return value if value in {"online", "away", "offline"} else "offline"


def record_local_presence_activity(user_id, status="online", source="web", device_label=""):
    user_id = safe_int(user_id, 0)
    if user_id <= 0:
        return {"ok": False, "reason": "invalid_user"}
    now = datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    normalized = normalize_presence_status(status)
    last_active_at = now if normalized in {"online", "away"} else ""
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        ensure_user_presence_schema(cur, conn)
        cur.execute(
            """
            INSERT INTO user_presence (user_id, status, last_seen_at, last_active_at, source, device_label, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET
                status=excluded.status,
                last_seen_at=excluded.last_seen_at,
                last_active_at=COALESCE(NULLIF(excluded.last_active_at, ''), user_presence.last_active_at),
                source=excluded.source,
                device_label=excluded.device_label,
                updated_at=excluded.updated_at
            """,
            (user_id, normalized, now, last_active_at, str(source or "web")[:80], str(device_label or "")[:120], now),
        )
        conn.commit()
        return {"ok": True, "status": normalized, "updated_at": now}
    except Exception as exc:
        logging.info("USER_PRESENCE_LOCAL_UPDATE_SKIPPED user_id=%s error=%s", user_id, exc.__class__.__name__)
        try:
            conn.rollback()
        except Exception:
            pass
        return {"ok": False, "reason": "update_failed"}
    finally:
        conn.close()


def read_local_presence(user_id):
    user_id = safe_int(user_id, 0)
    if user_id <= 0:
        return {"user_id": user_id, "status": "offline", "available": False}
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        ensure_user_presence_schema(cur, conn)
        cur.execute("SELECT * FROM user_presence WHERE user_id=? LIMIT 1", (user_id,))
        row = cur.fetchone()
        if not row:
            return {"user_id": user_id, "status": "offline", "available": False}
        item = dict(row)
        return {
            "user_id": int(item.get("user_id") or user_id),
            "status": normalize_presence_status(item.get("status")),
            "last_seen_at": item.get("last_seen_at") or "",
            "last_active_at": item.get("last_active_at") or "",
            "updated_at": item.get("updated_at") or "",
            "available": True,
        }
    except Exception as exc:
        logging.info("USER_PRESENCE_READ_SKIPPED user_id=%s error=%s", user_id, exc.__class__.__name__)
        return {"user_id": user_id, "status": "offline", "available": False}
    finally:
        conn.close()


def presence_device_label():
    user_agent = (request.headers.get("User-Agent") or "").lower()
    if "iphone" in user_agent or "ipad" in user_agent:
        return "ios-web"
    if "android" in user_agent:
        return "android-web"
    if "mobile" in user_agent:
        return "mobile-web"
    return "desktop-web"


def should_record_presence_for_path(path):
    return path in PRESENCE_ACTIVITY_PATHS or path == "/pulse/messages-v2"


def safe_int(value, default=0):
    try:
        if value is None or value == "":
            return default
        return int(value)
    except (TypeError, ValueError):
        return default


def api_error(message, status=400, trace_id=None, **extra):
    trace_id = trace_id or secrets.token_hex(6)
    payload = {"ok": False, "success": False, "message": message, "trace_id": trace_id}
    payload.update(extra)
    return jsonify(payload), status


