DEFAULT_LANGUAGE_CODE = "en"
LANGUAGE_CODE_RE = re.compile(r"^[a-z]{2,3}(?:-[a-z0-9]{2,8}){0,3}$")


def normalize_preferred_language(value, default=DEFAULT_LANGUAGE_CODE):
    raw = str(value or "").strip().lower().replace("_", "-")[:16]
    if raw in {"auto", "browser", "system"}:
        return default
    if raw in SUPPORTED_LANGUAGE_CODES:
        return raw
    base = raw.split("-", 1)[0]
    if base in SUPPORTED_LANGUAGE_CODES:
        return raw if "-" in raw and LANGUAGE_CODE_RE.match(raw) else base
    if LANGUAGE_CODE_RE.match(raw):
        return raw
    return default


def account_language(user):
    return normalize_preferred_language((user or {}).get("preferred_language") or (user or {}).get("language") or DEFAULT_LANGUAGE_CODE)


def preferred_language_for_user(cur, user_id):
    try:
        cur.execute("SELECT preferred_language FROM users WHERE user_id=? LIMIT 1", (int(user_id or 0),))
        row = cur.fetchone()
        value = (row["preferred_language"] if hasattr(row, "keys") else row[0]) if row else ""
        return normalize_preferred_language(value)
    except Exception:
        return DEFAULT_LANGUAGE_CODE


def save_user_preferred_language(user_id, language, actor_user_id=0):
    normalized = normalize_preferred_language(language, default="")
    if not normalized:
        raise ValueError("Choose a supported language.")
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db()
    cur = conn.cursor()
    try:
        dashboard_account_command_center.ensure_schema(conn)
    except Exception:
        logging.info("LANGUAGE_SETTINGS_SCHEMA_SKIPPED user_id=%s", user_id)
    cur.execute("UPDATE users SET preferred_language=?, updated_at=? WHERE user_id=?", (normalized, now, int(user_id)))
    cur.execute(
        """
        INSERT INTO user_settings (user_id, setting_key, setting_value, updated_at)
        VALUES (?, 'language', ?, ?)
        ON CONFLICT(user_id, setting_key) DO UPDATE SET setting_value=excluded.setting_value, updated_at=excluded.updated_at
        """,
        (int(user_id), normalized, now),
    )
    try:
        cur.execute(
            "INSERT INTO user_security_events (user_id, event_type, ip_hash, user_agent_hash, device_label, metadata_json, created_at) VALUES (?, 'language_preference_changed', ?, ?, ?, ?, ?)",
            (
                int(user_id),
                client_ip_hash(),
                hashlib.sha256((request.headers.get("User-Agent") or "").encode()).hexdigest()[:32],
                presence_device_label(),
                json.dumps({"language": normalized, "actor_user_id": int(actor_user_id or user_id)})[:1000],
                now,
            ),
        )
    except Exception:
        logging.info("LANGUAGE_SECURITY_EVENT_SKIPPED user_id=%s", user_id)
    conn.commit()
    conn.close()
    return normalized


PRELAUNCH_RESTRICTED_LOGIN_MESSAGE = "Your PulseSoc account is temporarily restricted while PulseSoc remains in pre-launch development. Please contact support if you believe this is an error."


def account_login_restriction_message(user):
    user = user or {}
    account_status = (user.get("account_status") or "active").strip().lower()
    login_enabled = safe_int(user.get("login_enabled"), 1)
    access_enabled = safe_int(user.get("access_enabled"), 1)
    if account_status == "restricted" or login_enabled == 0 or access_enabled == 0:
        return PRELAUNCH_RESTRICTED_LOGIN_MESSAGE
    if account_status != "active":
        return "This account is not active. Please contact support@pulsesoc.com."
    return ""


def request_expects_json_response():
    try:
        return (
            request.path.startswith("/api/")
            or request.headers.get("X-Requested-With") == "XMLHttpRequest"
            or "application/json" in (request.headers.get("Accept") or "")
        )
    except RuntimeError:
        return False


def groups_advanced_disabled_response():
    return api_error("Advanced group controls are temporarily paused while Groups is stabilized.", 503, feature="groups_advanced")


def save_private_verification_document(user_id, file_storage, document_type):
    allowed = {"jpg", "jpeg", "png", "pdf", "webp"}
    if not file_storage or not file_storage.filename:
        return None
    original = secure_filename(file_storage.filename)
    ext = original.rsplit(".", 1)[-1].lower() if "." in original else ""
    if ext not in allowed:
        raise ValueError("Verification documents must be JPG, PNG, WEBP, or PDF.")
    file_storage.stream.seek(0, os.SEEK_END)
    size = file_storage.stream.tell()
    file_storage.stream.seek(0)
    if size > 8 * 1024 * 1024:
        raise ValueError("Verification documents must be under 8 MB.")
    root = os.path.join("instance", "private_uploads", "merchant_verification", str(int(user_id or 0)))
    os.makedirs(root, exist_ok=True)
    stored = f"{datetime.utcnow().strftime('%Y%m%d')}_{document_type}_{secrets.token_urlsafe(12)}.{ext}"
    path = os.path.join(root, stored)
    file_storage.save(path)
    return {
        "document_type": document_type,
        "original_filename": original,
        "stored_path": path,
        "mime_type": file_storage.mimetype or "application/octet-stream",
        "file_size": int(size),
        "private": True,
        "admin_only": True,
        "scanner_status": "queued_for_internal_review",
    }


def save_teacher_private_document(user_id, file_storage, document_type):
    allowed = {"jpg", "jpeg", "png", "pdf", "webp"}
    if not file_storage or not file_storage.filename:
        return None
    original = secure_filename(file_storage.filename)
    ext = original.rsplit(".", 1)[-1].lower() if "." in original else ""
    if ext not in allowed:
        raise ValueError("Teacher documents must be JPG, PNG, WEBP, or PDF.")
    file_storage.stream.seek(0, os.SEEK_END)
    size = file_storage.stream.tell()
    file_storage.stream.seek(0)
    if size > 8 * 1024 * 1024:
        raise ValueError("Teacher documents must be under 8 MB.")
    root = os.path.join("instance", "private_uploads", "teacher_verification", str(int(user_id or 0)))
    os.makedirs(root, exist_ok=True)
    stored = f"{datetime.utcnow().strftime('%Y%m%d')}_{document_type}_{secrets.token_urlsafe(12)}.{ext}"
    path = os.path.join(root, stored)
    file_storage.save(path)
    return {
        "document_type": document_type,
        "original_filename": original,
        "stored_path": path,
        "mime_type": file_storage.mimetype or "application/octet-stream",
        "file_size": int(size),
        "private": True,
        "admin_only": True,
        "scanner_status": "queued_for_internal_review",
    }


def parse_price_label_to_cents(value, default_currency="USD"):
    text = (value or "").strip()
    if not text or text.lower() in {"free", "request access", "paid later", "premium later"}:
        return 0, default_currency
    match = re.search(r"([A-Z]{3})?\s*\$?\s*([0-9]+(?:\.[0-9]{1,2})?)", text.upper())
    if not match:
        return 0, default_currency
    currency = (match.group(1) or default_currency or "USD").upper()
    return int(round(float(match.group(2)) * 100)), currency


def notify_user(
    cur,
    user_id,
    note_type,
    title,
    body,
    target_url="/pulse",
    actor_user_id=0,
    entity_type="",
    entity_id="",
    delivery_status="created",
    metadata=None,
):
    if not user_id:
        return
    now = datetime.utcnow().isoformat(timespec="seconds")
    metadata = dict(metadata or {})
    recipient_language = metadata.get("preferred_language") or metadata.get("language") or preferred_language_for_user(cur, user_id)
    metadata.setdefault("preferred_language", recipient_language)
    metadata.setdefault("language", recipient_language)
    try:
        cur.execute(
            """
            INSERT INTO pulse_notifications
            (user_id, actor_user_id, type, title, body, entity_type, entity_id, deep_link, target_url,
             is_read, delivery_status, metadata_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?)
            """,
            (
                int(user_id),
                int(actor_user_id or 0),
                str(note_type or "message")[:80],
                str(title or "PulseSoc notification")[:180],
                str(body or "")[:2000],
                str(entity_type or "")[:80],
                str(entity_id or "")[:120],
                str(target_url or "/pulse")[:700],
                str(target_url or "/pulse")[:700],
                str(delivery_status or "created")[:60],
                json.dumps(metadata or {})[:4000],
                now,
            ),
        )
        notification_id = int(cur.lastrowid or 0)
        cur.execute(
            """
            INSERT INTO pulse_notification_deliveries
            (notification_id, user_id, channel, provider, status, created_at, sent_at)
            VALUES (?, ?, 'in_app', 'pulse', ?, ?, ?)
            """,
            (notification_id, int(user_id), str(delivery_status or "created")[:60], now, now),
        )
        push_payload = {
            **(metadata or {}),
            "url": target_url or "/pulse",
            "deepLink": (metadata or {}).get("deepLink") or (metadata or {}).get("deep_link") or target_url or "/pulse",
            "type": note_type or "message",
            "notification_id": notification_id,
        }
        note_type_value = str(note_type or "message").strip().lower()
        entity_type_value = str(entity_type or "").strip().lower()
        target_value = str(target_url or "").strip().lower()
        message_like = (
            note_type_value in {"message", "chat_message", "voice_message", "group_message", "room_message", "private_message"}
            or entity_type_value in {"message", "messages", "chat", "conversation", "pulse_message", "pulse_conversation", "comm_v2_message"}
            or target_value.startswith(("/pulse/messages", "/messages", "/chat"))
        )
        if not message_like and command_center_client_service.is_enabled():
            def dispatch_notification_event():
                try:
                    command_center_client_service.enqueue_notification_event(
                        int(user_id),
                        str(note_type or "notification")[:80],
                        str(title or "PulseSoc notification")[:180],
                        str(body or "")[:2000],
                        int(actor_user_id or 0) or None,
                        {
                            **(metadata or {}),
                            "local_notification_id": notification_id,
                            "entity_type": str(entity_type or "")[:80],
                            "entity_id": str(entity_id or "")[:120],
                            "deep_link": str(target_url or "/pulse")[:700],
                        },
                        "in_app",
                        f"pulse-note-{notification_id}",
                    )
                except Exception as dispatch_exc:
                    logging.info("LEGACY_NOTIFICATION_COMMAND_CENTER_SKIPPED notification_id=%s error=%s", notification_id, dispatch_exc.__class__.__name__)

            threading.Thread(target=dispatch_notification_event, name="legacy-notification-dispatch", daemon=True).start()
        try:
            if push_service._async_push_enabled():
                push_result = push_service.enqueue_push_with_cursor(
                    cur,
                    int(user_id),
                    title,
                    body,
                    push_payload,
                    push_type=push_payload.get("push_type") or push_payload.get("type") or note_type or "general",
                    notification_id=notification_id,
                )
            else:
                push_result = notification_service.send_push_alert(int(user_id), title, body, push_payload)
            cur.execute(
                """
                INSERT INTO pulse_notification_deliveries
                (notification_id, user_id, channel, provider, status, error_message, provider_response, created_at, sent_at)
                VALUES (?, ?, 'push', 'web_expo_push', ?, ?, ?, ?, ?)
                """,
                (
                    notification_id,
                    int(user_id),
                    str(push_result.get("status") or ("sent" if push_result.get("ok") else "failed"))[:80],
                    str(push_result.get("message") or "; ".join(push_result.get("failures") or []))[:1200],
                    json.dumps(push_result or {}, default=str)[:4000],
                    now,
                    now,
                ),
            )
        except Exception as push_exc:
            logging.warning("PULSE_LEGACY_PUSH_DELIVERY_FAILED notification_id=%s user_id=%s error=%s", notification_id, user_id, type(push_exc).__name__)
        try:
            normalized_type = notification_service._pulse_type_for_alert(note_type)
            category = notification_service._pulse_category(normalized_type)
            metadata_channels = []
            raw_channels = (metadata or {}).get("channels") or (metadata or {}).get("notification_channels") or []
            if isinstance(raw_channels, str):
                metadata_channels = [part.strip().lower() for part in raw_channels.split(",") if part.strip()]
            elif isinstance(raw_channels, (list, tuple, set)):
                metadata_channels = [str(part or "").strip().lower() for part in raw_channels if str(part or "").strip()]
            email_enabled = os.getenv("BREVO_EMAIL_ENABLED", "true").strip().lower() not in {"0", "false", "off", "no"}
            email_allowed = False
            try:
                cur.execute("SELECT email FROM pulse_notification_preferences WHERE user_id=? AND category=? LIMIT 1", (int(user_id), category))
                pref_row = cur.fetchone()
                if pref_row is not None:
                    email_allowed = bool((pref_row["email"] if hasattr(pref_row, "keys") else pref_row[0]) or 0)
                else:
                    email_allowed = bool(notification_service.PULSE_NOTIFICATION_CATEGORIES.get(category, {}).get("email"))
            except Exception:
                email_allowed = bool(notification_service.PULSE_NOTIFICATION_CATEGORIES.get(category, {}).get("email"))
            if category in {"security", "admin_security"} or normalized_type in notification_service.SECURITY_NOTIFICATION_TYPES:
                email_allowed = True
            if "email" in metadata_channels:
                email_allowed = True
            if email_allowed:
                if not email_enabled:
                    cur.execute(
                        """
                        INSERT INTO pulse_notification_deliveries
                        (notification_id, user_id, channel, provider, status, error_message, created_at, sent_at)
                        VALUES (?, ?, 'email', 'brevo', 'skipped', 'Brevo email notifications are disabled.', ?, ?)
                        """,
                        (notification_id, int(user_id), now, now),
                    )
                else:
                    cur.execute("SELECT email FROM users WHERE user_id=? LIMIT 1", (int(user_id),))
                    user_email_row = cur.fetchone()
                    recipient_email = ""
                    if user_email_row is not None:
                        recipient_email = str((user_email_row["email"] if hasattr(user_email_row, "keys") else user_email_row[0]) or "").strip()
                    if recipient_email:
                        template = notification_service.BREVO_NOTIFICATION_TEMPLATES.get(
                            notification_service._template_key(normalized_type, category),
                            notification_service.BREVO_NOTIFICATION_TEMPLATES["welcome"],
                        )
                        email_subject = str(title or template.get("subject") or "PulseSoc notification")[:180]
                        email_body = str(body or template.get("body") or "")[:2000]
                        trace_id = str((metadata or {}).get("trace_id") or (metadata or {}).get("push_trace_id") or secrets.token_hex(8))[:120]
                        email_metadata = {
                            **(metadata or {}),
                            "event_type": normalized_type,
                            "category": category,
                            "notification_id": notification_id,
                            "trace_id": trace_id,
                            "deep_link": target_url or "/pulse",
                        }
                        digest = hashlib.sha256(
                            json.dumps(
                                {
                                    "user_id": int(user_id),
                                    "notification_id": int(notification_id or 0),
                                    "type": normalized_type,
                                    "email": recipient_email.lower(),
                                    "subject": email_subject,
                                },
                                sort_keys=True,
                                default=str,
                            ).encode("utf-8")
                        ).hexdigest()[:32]
                        idempotency_key = f"legacy-notification-email:{digest}"
                        cur.execute("SELECT id, status FROM failed_email_queue WHERE idempotency_key=? ORDER BY id DESC LIMIT 1", (idempotency_key,))
                        existing_email_job = cur.fetchone()
                        if existing_email_job:
                            queue_id = int((existing_email_job["id"] if hasattr(existing_email_job, "keys") else existing_email_job[0]) or 0)
                            queue_status = str((existing_email_job["status"] if hasattr(existing_email_job, "keys") else existing_email_job[1]) or "queued")
                        else:
                            cur.execute(
                                """
                                INSERT INTO failed_email_queue
                                (user_id, recipient_email, email_type, subject, html_body, text_body, metadata, status,
                                 retry_count, max_attempts, last_error, next_retry_at, trace_id, idempotency_key, created_at, updated_at)
                                VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', 0, 5, '', ?, ?, ?, ?, ?)
                                """,
                                (
                                    int(user_id),
                                    recipient_email[:320],
                                    normalized_type[:80],
                                    email_subject[:240],
                                    notification_service._branded_html(email_subject, email_body, target_url or "/pulse"),
                                    email_body,
                                    json.dumps(email_metadata, default=str)[:4000],
                                    datetime.utcnow().isoformat(timespec="seconds"),
                                    trace_id,
                                    idempotency_key[:240],
                                    now,
                                    now,
                                ),
                            )
                            queue_id = int(cur.lastrowid or 0)
                            queue_status = "queued"
                        cur.execute(
                            """
                            INSERT INTO pulse_notification_deliveries
                            (notification_id, user_id, channel, provider, status, provider_response, created_at, sent_at)
                            VALUES (?, ?, 'email', 'brevo', ?, ?, ?, NULL)
                            """,
                            (notification_id, int(user_id), queue_status, json.dumps({"queue_id": queue_id, "trace_id": trace_id}, default=str)[:4000], now),
                        )
                        cur.execute(
                            """
                            INSERT INTO notification_delivery_logs
                            (user_id, notification_id, channel, status, provider, provider_response, error_message, retry_count, created_at, sent_at)
                            VALUES (?, ?, 'email', ?, 'brevo', ?, '', 0, ?, NULL)
                            """,
                            (int(user_id), notification_id, queue_status, json.dumps({"queue_id": queue_id, "trace_id": trace_id}, default=str)[:4000], now),
                        )
                    else:
                        cur.execute(
                            """
                            INSERT INTO pulse_notification_deliveries
                            (notification_id, user_id, channel, provider, status, error_message, created_at, sent_at)
                            VALUES (?, ?, 'email', 'brevo', 'skipped', 'Recipient email missing.', ?, ?)
                            """,
                            (notification_id, int(user_id), now, now),
                        )
        except Exception as email_exc:
            logging.warning("PULSE_LEGACY_EMAIL_QUEUE_FAILED notification_id=%s user_id=%s error=%s", notification_id, user_id, type(email_exc).__name__)
    except Exception:
        logging.exception("PULSE_NOTIFICATION_INSERT_FAILED user_id=%s type=%s", user_id, note_type)


def notify_payment_status(user_id, note_type, title, body, target_url="/dashboard/economy/subscriptions", *, stripe_event_id="", entity_id="", metadata=None):
    if not user_id:
        return {"ok": False, "message": "User required."}
    payload = {
        **(metadata or {}),
        "stripe_event_id": stripe_event_id or "",
        "deep_link": target_url,
        "target_url": target_url,
        "source": "stripe_webhook",
        "category": "payments",
    }
    try:
        return notification_service.create_pulse_notification(
            int(user_id),
            note_type,
            title,
            body,
            actor_user_id=0,
            entity_type="payment",
            entity_id=str(entity_id or stripe_event_id or "")[:120],
            deep_link=target_url,
            metadata=payload,
        )
    except Exception as exc:
        logging.warning("PAYMENT_NOTIFICATION_FAILED user_id=%s type=%s stripe_event_id=%s error=%s", user_id, note_type, stripe_event_id, exc.__class__.__name__)
        return {"ok": False, "message": "Payment notification failed."}


def pulse_actor_display_name(user):
    user = user or {}
    return clean_html(user.get("display_name") or user.get("full_name") or user.get("username") or "Someone")


def pulse_notify_post_owner(cur, post_id, actor_user, note_type, title, body, *, entity_type="post", entity_id=None, deep_link=None, metadata=None):
    try:
        cur.execute("SELECT user_id, post_type FROM pulse_posts WHERE id=? AND deleted_at IS NULL LIMIT 1", (int(post_id or 0),))
        post = dict(cur.fetchone() or {})
    except Exception:
        post = {}
    owner_id = int(post.get("user_id") or 0)
    actor_id = int((actor_user or {}).get("user_id") or 0)
    if not owner_id or owner_id == actor_id:
        return
    notify_user(
        cur,
        owner_id,
        note_type,
        title,
        body,
        deep_link or f"/pulse/post/{int(post_id or 0)}",
        actor_user_id=actor_id,
        entity_type=entity_type,
        entity_id=str(entity_id or post_id or ""),
        metadata={**(metadata or {}), "post_id": int(post_id or 0), "post_type": post.get("post_type") or ""},
    )


def pulse_notify_mentions(cur, text, actor_user, *, note_type="mention", entity_type="post", entity_id="", deep_link="/pulse", metadata=None):
    handles = sorted({m.group(1).strip("._-") for m in re.finditer(r"@([A-Za-z0-9_.-]{2,40})", str(text or "")) if m.group(1)})
    if not handles:
        return
    actor_id = int((actor_user or {}).get("user_id") or 0)
    for handle in handles[:12]:
        try:
            cur.execute("SELECT user_id FROM arena_profiles WHERE lower(public_player_id)=lower(?) LIMIT 1", (handle,))
            target_id = int(dict(cur.fetchone() or {}).get("user_id") or 0)
        except Exception:
            target_id = 0
        if not target_id or target_id == actor_id:
            continue
        notify_user(
            cur,
            target_id,
            note_type,
            "You were mentioned on PulseSoc",
            f"{pulse_actor_display_name(actor_user)} mentioned you.",
            deep_link,
            actor_user_id=actor_id,
            entity_type=entity_type,
            entity_id=str(entity_id or ""),
            metadata={**(metadata or {}), "mention": handle},
        )


def pulse_notify_followers(cur, creator_user, note_type, title, body, deep_link, *, entity_type="", entity_id="", metadata=None, limit=100):
    creator_id = int((creator_user or {}).get("user_id") or 0)
    if not creator_id:
        return 0
    try:
        cur.execute(
            "SELECT follower_user_id FROM pulse_follows WHERE followed_user_id=? ORDER BY created_at DESC LIMIT ?",
            (creator_id, max(1, min(int(limit or 100), 250))),
        )
        follower_ids = [int(dict(row).get("follower_user_id") or 0) for row in cur.fetchall()]
    except Exception:
        follower_ids = []
    sent = 0
    for follower_id in follower_ids:
        if not follower_id or follower_id == creator_id:
            continue
        notify_user(
            cur,
            follower_id,
            note_type,
            title,
            body,
            deep_link,
            actor_user_id=creator_id,
            entity_type=entity_type,
            entity_id=str(entity_id or ""),
            metadata=metadata or {},
        )
        sent += 1
    return sent


def load_account_by_id(user_id):
    if not user_id:
        return None
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT * FROM users WHERE user_id=?", (user_id,))
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def load_account_by_email(email):
    email = normalize_email(email)
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM users
        WHERE lower(email)=lower(?) AND COALESCE(email,'')!=''
        ORDER BY
          CASE WHEN COALESCE(deleted_at,'')='' THEN 0 ELSE 1 END,
          CASE WHEN COALESCE(account_status,'active')='active' THEN 0 ELSE 1 END,
          user_id DESC
        LIMIT 1
        """,
        (email,),
    )
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def load_account_by_email_or_username(identifier):
    identifier = clean_html(identifier or "").strip().lstrip("@")
    if not identifier:
        return None
    if "@" in identifier:
        return load_account_by_email(identifier)
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM users
        WHERE lower(username)=lower(?) AND COALESCE(username,'')!=''
        ORDER BY
          CASE WHEN COALESCE(deleted_at,'')='' THEN 0 ELSE 1 END,
          CASE WHEN COALESCE(account_status,'active')='active' THEN 0 ELSE 1 END,
          user_id DESC
        LIMIT 1
        """,
        (identifier,),
    )
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def password_reset_diagnostic_for_user(user_id):
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT user_id, email, username, password_hash, updated_at, email_verified, account_status FROM users WHERE user_id=?", (user_id,))
    user_row = cur.fetchone()
    if not user_row:
        conn.close()
        return {"user_exists": False}
    user = dict(user_row)
    email = normalize_email(user.get("email") or "")
    duplicate_email_count = 0
    if email:
        cur.execute("SELECT COUNT(*) FROM users WHERE lower(email)=lower(?) AND COALESCE(email,'')!=''", (email,))
        duplicate_email_count = int(cur.fetchone()[0] or 0)
    cur.execute(
        """
        SELECT
          COUNT(*) AS total,
          SUM(CASE WHEN used_at IS NULL AND expires_at >= ? THEN 1 ELSE 0 END) AS active,
          MAX(created_at) AS latest_created_at,
          MAX(used_at) AS latest_used_at,
          MAX(expires_at) AS latest_expires_at
        FROM password_reset_tokens
        WHERE user_id=?
        """,
        (datetime.now().isoformat(), user_id),
    )
    token_row = dict(cur.fetchone() or {})
    conn.close()
    return {
        "user_exists": True,
        "user_id": user.get("user_id"),
        "email": mask_email(email),
        "username_present": bool(user.get("username")),
        "password_hash_present": bool(user.get("password_hash")),
        "password_last_changed_at": user.get("updated_at") or "",
        "account_confirmed": bool(int(user.get("email_verified") or 0)),
        "account_status": user.get("account_status") or "active",
        "duplicate_email_count": duplicate_email_count,
        "reset_token_status": {
            "total": int(token_row.get("total") or 0),
            "active": int(token_row.get("active") or 0),
            "latest_created_at": token_row.get("latest_created_at") or "",
            "latest_used_at": token_row.get("latest_used_at") or "",
            "latest_expires_at": token_row.get("latest_expires_at") or "",
        },
    }


def save_reset_password_and_verify(cur, user_id, password, now):
    password_hash = generate_password_hash(password)
    cur.execute("UPDATE users SET password_hash=?, updated_at=? WHERE user_id=?", (password_hash, now, user_id))
    if cur.rowcount != 1:
        raise RuntimeError("password_update_row_count_mismatch")
    cur.execute("SELECT password_hash FROM users WHERE user_id=?", (user_id,))
    row = cur.fetchone()
    saved_hash = row[0] if row else ""
    if not saved_hash or not check_password_hash(saved_hash, password):
        raise RuntimeError("password_update_verification_failed")
    try:
        ensure_mobile_security_session_schema(cur)
        cur.execute(
            "UPDATE mobile_security_sessions SET status='revoked', revoked_at=?, last_seen_at=?, revoked_reason='password_changed' WHERE user_id=? AND status IN ('active','rotated')",
            (now, now, user_id),
        )
    except Exception:
        logging.info("MOBILE_SECURITY_SESSION_REVOKE_SKIPPED user_id=%s", user_id)
    return saved_hash


def owner_repair_user_password(cur, user_id, password, now, confirm_email=True):
    if len(password or "") < 8:
        raise ValueError("Use at least 8 characters for the temporary password.")
    save_reset_password_and_verify(cur, user_id, password, now)
    assignments = ["account_status='active'", "updated_at=?"]
    params = [now]
    if confirm_email:
        assignments.insert(0, "email_verified=1")
    cur.execute(f"UPDATE users SET {', '.join(assignments)} WHERE user_id=?", params + [user_id])
    close_active_password_reset_tokens(cur, user_id, now)
    if confirm_email:
        cur.execute("UPDATE email_verification_tokens SET used_at=COALESCE(used_at, ?) WHERE user_id=? AND used_at IS NULL", (now, user_id))


def close_active_password_reset_tokens(cur, user_id, used_at):
    cur.execute("UPDATE password_reset_tokens SET used_at=? WHERE user_id=? AND used_at IS NULL", (used_at, user_id))


def owner_email_value():
    return normalize_email(os.getenv("OWNER_EMAIL", "cherieroody@gmail.com"))


def owner_super_user_enabled():
    return _env_bool("OWNER_SUPER_USER_ENABLED", True)


def owner_allows_multiple_super_users():
    return _env_bool("OWNER_ALLOW_MULTIPLE_SUPER_USERS", False)


def user_is_owner_account(user):
    email = normalize_email((user or {}).get("email") or "")
    return bool(email and owner_super_user_enabled() and email == owner_email_value())


def user_is_super_user(user):
    user = user or {}
    return bool(safe_int(user.get("is_super_user"), 0) or user_is_owner_account(user))


def ensure_owner_super_user(cur=None, conn=None):
    if not owner_super_user_enabled():
        return False
    email = owner_email_value()
    if not email:
        return False
    close_conn = False
    if cur is None:
        conn = db()
        cur = conn.cursor()
        close_conn = True
    try:
        if not owner_allows_multiple_super_users():
            cur.execute("SELECT user_id FROM users WHERE COALESCE(is_super_user,0)=1 AND lower(COALESCE(email,''))!=lower(?) LIMIT 1", (email,))
            if cur.fetchone():
                return False
        cur.execute("UPDATE users SET is_super_user=1, updated_at=? WHERE lower(email)=lower(?)", (datetime.now().isoformat(), email))
        if close_conn:
            conn.commit()
        return bool(getattr(cur, "rowcount", 0))
    except Exception as exc:
        logging.info("OWNER_SUPER_USER_BOOTSTRAP_SKIPPED email=%s error=%s", mask_email(email), exc)
        try:
            if close_conn:
                conn.rollback()
        except Exception:
            pass
        return False
    finally:
        if close_conn:
            try:
                conn.close()
            except Exception:
                pass


