LEGACY_PULSESOC_HOME_TARGETS = {
    "/home",
    "/feed",
    "/pulse/home",
    "/pulse/legacy-home",
    "/pulse/home-legacy",
    "/pulse/old-home",
    "/pulse/legacy",
}


def is_legacy_pulsesoc_home_target(target):
    raw = str(target or "").strip()
    if not raw or raw.startswith("//"):
        return False
    path = raw.split("?", 1)[0].split("#", 1)[0].rstrip("/") or "/"
    lowered = path.lower()
    if lowered in LEGACY_PULSESOC_HOME_TARGETS:
        return True
    query = raw.split("?", 1)[1].lower() if "?" in raw else ""
    return lowered == "/pulse" and any(marker in query for marker in ("legacy", "old_home", "old-home", "global_pulsesoc_feed"))


def safe_redirect_target(default_endpoint="dashboard_page"):
    target = request.args.get("next") or request.form.get("next") or ""
    if target and target.startswith("/") and not target.startswith("//"):
        if is_legacy_pulsesoc_home_target(target):
            return "/pulse"
        return target
    return "/pulse" if default_endpoint == "pulse_page" else url_for(default_endpoint)


def public_app_base_url():
    return (
        os.getenv("PUBLIC_BASE_URL")
        or os.getenv("PULSE_APP_URL")
        or os.getenv("APP_BASE_URL")
        or os.getenv("BASE_URL")
        or os.getenv("DOMAIN")
        or "https://coinpilotx.app"
    ).strip().rstrip("/")


def public_url_for(endpoint, **values):
    base_url = public_app_base_url()
    if has_request_context():
        relative = url_for(endpoint, **values)
    else:
        with webhook_app.test_request_context(base_url=base_url):
            relative = url_for(endpoint, **values)
    return f"{base_url}{relative}"


FAILED_LOGIN_IP_LIMIT = int(os.getenv("FAILED_LOGIN_IP_LIMIT", "8"))
FAILED_LOGIN_EMAIL_LIMIT = int(os.getenv("FAILED_LOGIN_EMAIL_LIMIT", "5"))
FAILED_LOGIN_DOMAIN_LIMIT = int(os.getenv("FAILED_LOGIN_DOMAIN_LIMIT", "14"))
FAILED_LOGIN_WINDOW_SECONDS = int(os.getenv("FAILED_LOGIN_WINDOW_SECONDS", "300"))
FAILED_LOGIN_ALERT_WINDOW_SECONDS = 60
FAILED_LOGIN_LOCKOUT_SECONDS = int(os.getenv("FAILED_LOGIN_LOCKOUT_SECONDS", "900"))
FAILED_LOGIN_CHALLENGE_AFTER = int(os.getenv("FAILED_LOGIN_CHALLENGE_AFTER", "3"))
FAILED_LOGIN_BLOCKED_MESSAGE = "Too many failed login attempts. Try again after the cooldown or reset your password."
FAILED_LOGIN_CHALLENGE_MESSAGE = "Complete the security challenge to continue."


def client_ip_address():
    if not has_request_context():
        return ""
    return (request.headers.get("X-Forwarded-For", request.remote_addr or "").split(",")[0].strip())[:80]


def request_country():
    if not has_request_context():
        return ""
    return clean_html(
        request.headers.get("CF-IPCountry")
        or request.headers.get("X-Appengine-Country")
        or request.headers.get("X-Country-Code")
        or request.headers.get("CloudFront-Viewer-Country")
        or ""
    )[:80]


def auth_email_domain(email):
    email = normalize_email(email or "")
    if "@" not in email:
        return ""
    return clean_html(email.rsplit("@", 1)[1].lower())[:180]


def auth_email_hash(email):
    email = normalize_email(email or "")
    if not email:
        return ""
    salt = os.getenv("ANALYTICS_SALT", "coinpilotxai-inc")
    return hashlib.sha256(f"{salt}:auth-email:{email}".encode("utf-8")).hexdigest()


def login_device_summary(user_agent=None):
    ua = user_agent if user_agent is not None else (request.headers.get("User-Agent", "") if has_request_context() else "")
    device, browser, os_name, is_bot = visitor_user_agent_meta(ua)
    return f"{device} / {browser} / {os_name}{' / bot-like' if is_bot else ''}"


def login_security_details(email="", user_id=0, extra=None):
    ua = (request.headers.get("User-Agent", "") if has_request_context() else "")[:500]
    device, browser, os_name, is_bot = visitor_user_agent_meta(ua)
    details = {
        "masked_email": mask_email(normalize_email(email)) if email else "",
        "email_domain": auth_email_domain(email),
        "ip_address": client_ip_address(),
        "country": request_country(),
        "user_agent": ua,
        "device": device,
        "browser": browser,
        "os": os_name,
        "is_bot": bool(is_bot),
        "route": request.path if has_request_context() else "",
        "method": request.method if has_request_context() else "",
        "user_id": int(user_id or 0),
        "db_engine": db_service.ENGINE_NAME,
    }
    if extra:
        details.update(extra)
    return details


def ensure_failed_login_security_tables(cur):
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS failed_login_controls (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            control_type TEXT NOT NULL,
            control_value TEXT NOT NULL,
            status TEXT DEFAULT 'active',
            reason TEXT,
            source_event_id INTEGER,
            created_by_admin_id INTEGER DEFAULT 0,
            expires_at TEXT,
            created_at TEXT,
            updated_at TEXT,
            UNIQUE(control_type, control_value)
        )
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS failed_login_safe_list (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            control_type TEXT NOT NULL,
            control_value TEXT NOT NULL,
            reason TEXT,
            created_by_admin_id INTEGER DEFAULT 0,
            created_at TEXT,
            updated_at TEXT,
            UNIQUE(control_type, control_value)
        )
        """
    )
    cur.execute("CREATE INDEX IF NOT EXISTS idx_failed_login_controls_lookup ON failed_login_controls(control_type, control_value, status, expires_at)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_failed_login_safe_lookup ON failed_login_safe_list(control_type, control_value)")


def auth_event_schema_guard(cur, conn=None):
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS auth_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT,
            email TEXT,
            email_hash TEXT,
            email_domain TEXT,
            user_id INTEGER,
            status TEXT,
            severity TEXT DEFAULT 'low',
            ip_address TEXT,
            country TEXT,
            user_agent TEXT,
            device TEXT,
            route TEXT,
            details TEXT,
            db_engine TEXT,
            created_at TEXT
        )
        """
    )
    add_columns_if_missing(cur, "auth_events", [
        ("email_hash", "TEXT"),
        ("email_domain", "TEXT"),
        ("severity", "TEXT DEFAULT 'low'"),
        ("ip_address", "TEXT"),
        ("country", "TEXT"),
        ("user_agent", "TEXT"),
        ("device", "TEXT"),
        ("route", "TEXT"),
    ], conn=conn)
    cur.execute("CREATE INDEX IF NOT EXISTS idx_auth_events_failed_ip ON auth_events(status, ip_address, created_at)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_auth_events_failed_email_hash ON auth_events(status, email_hash, created_at)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_auth_events_failed_domain ON auth_events(status, email_domain, created_at)")
    ensure_failed_login_security_tables(cur)


def failed_login_severity(total_count=0, blocked=False, challenged=False, is_bot=False):
    total = int(total_count or 0)
    if blocked or total >= 20:
        return "Critical"
    if total >= 10 or is_bot:
        return "High"
    if total >= FAILED_LOGIN_CHALLENGE_AFTER or challenged:
        return "Medium"
    return "Low"


def log_auth_event(event_type, email="", user_id=0, status="info", details=None):
    try:
        conn = db()
        cur = conn.cursor()
        auth_event_schema_guard(cur, conn)
        details = details or {}
        contextual = login_security_details(email, user_id, details)
        severity = clean_html(str(contextual.get("severity") or failed_login_severity(contextual.get("burst_count") or 0, contextual.get("blocked"), contextual.get("challenge_required"), contextual.get("is_bot"))))[:20]
        masked_email = mask_email(normalize_email(email)) if email else ""
        cur.execute(
            """
            INSERT INTO auth_events
            (event_type, email, email_hash, email_domain, user_id, status, severity, ip_address, country, user_agent, device, route, details, db_engine, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                clean_html(event_type)[:120],
                masked_email,
                auth_email_hash(email),
                auth_email_domain(email),
                int(user_id or 0),
                clean_html(status)[:40],
                severity,
                contextual.get("ip_address") or "",
                contextual.get("country") or "",
                contextual.get("user_agent") or "",
                contextual.get("device") or login_device_summary(contextual.get("user_agent") or ""),
                contextual.get("route") or "",
                json.dumps(contextual)[:4000],
                db_service.ENGINE_NAME,
                datetime.now().isoformat(),
            ),
        )
        conn.commit()
        conn.close()
    except Exception as exc:
        logging.info("Auth event logging failed: %s", exc)


def login_challenge_session_key(email):
    domain = auth_email_domain(email)
    return f"login_challenge:{domain or 'unknown'}:{hashlib.sha256(normalize_email(email).encode()).hexdigest()[:12]}"


def issue_login_challenge(email):
    a = secrets.randbelow(7) + 2
    b = secrets.randbelow(7) + 2
    session[login_challenge_session_key(email)] = {
        "answer_hash": hashlib.sha256(f"{a + b}:{app.secret_key}".encode("utf-8")).hexdigest(),
        "expires_at": (datetime.now() + timedelta(minutes=10)).isoformat(),
    }
    return {"prompt": f"What is {a} + {b}?", "required": True}


def verify_login_challenge(email, submitted):
    record = session.get(login_challenge_session_key(email)) or {}
    expires_at = record.get("expires_at") or ""
    try:
        expired = bool(expires_at and datetime.fromisoformat(expires_at) < datetime.now())
    except Exception:
        expired = True
    expected = record.get("answer_hash") or ""
    actual = hashlib.sha256(f"{str(submitted or '').strip()}:{app.secret_key}".encode("utf-8")).hexdigest()
    ok = bool(expected and not expired and hmac.compare_digest(expected, actual))
    if ok:
        session.pop(login_challenge_session_key(email), None)
    return ok


def active_failed_login_control(cur, control_type, control_value):
    if not control_value:
        return None
    now = datetime.now().isoformat()
    cur.execute(
        """
        SELECT * FROM failed_login_controls
        WHERE control_type=? AND control_value=? AND status='active'
          AND (expires_at IS NULL OR expires_at='' OR expires_at>?)
        LIMIT 1
        """,
        (control_type, control_value, now),
    )
    row = cur.fetchone()
    return dict(row) if row else None


def failed_login_marked_safe(cur, control_type, control_value):
    if not control_value:
        return False
    cur.execute("SELECT id FROM failed_login_safe_list WHERE control_type=? AND control_value=? LIMIT 1", (control_type, control_value))
    return bool(cur.fetchone())


def failed_login_recent_count(cur, where_sql, params, window_seconds=FAILED_LOGIN_WINDOW_SECONDS):
    since = (datetime.now() - timedelta(seconds=window_seconds)).isoformat()
    cur.execute(
        f"""
        SELECT COUNT(*) AS total
        FROM auth_events
        WHERE status='failed' AND created_at>=? {where_sql}
        """,
        (since, *params),
    )
    row = cur.fetchone()
    return int((row["total"] if hasattr(row, "keys") else row[0]) or 0)


def domain_has_local_accounts(cur, domain):
    if not domain:
        return False
    try:
        cur.execute("SELECT 1 FROM users WHERE lower(email) LIKE ? LIMIT 1", (f"%@{domain.lower()}",))
        return bool(cur.fetchone())
    except Exception:
        return False


def login_security_preflight(email, enforce_challenge=True):
    email = normalize_email(email or "")
    domain = auth_email_domain(email)
    ip = client_ip_address()
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    auth_event_schema_guard(cur, conn)
    now = datetime.now().isoformat()
    try:
        controls = [
            ("ip", ip),
            ("email", email),
            ("domain", domain),
        ]
        active_controls = []
        safe = set()
        for control_type, value in controls:
            if failed_login_marked_safe(cur, control_type, value):
                safe.add(control_type)
                continue
            control = active_failed_login_control(cur, control_type, value)
            if control:
                active_controls.append(control)
        if active_controls:
            strongest = active_controls[0]
            log_auth_event("login_blocked", email, 0, status="blocked", details={
                "reason": "failed_login_control",
                "control_type": strongest.get("control_type"),
                "expires_at": strongest.get("expires_at") or "",
                "severity": "Critical",
                "blocked": True,
            })
            return {
                "allowed": False,
                "status": 429,
                "message": FAILED_LOGIN_BLOCKED_MESSAGE,
                "challenge": None,
                "reason": "active_control",
            }
        ip_count = failed_login_recent_count(cur, "AND ip_address=?", (ip,)) if ip else 0
        email_count = failed_login_recent_count(cur, "AND email_hash=?", (auth_email_hash(email),)) if email else 0
        domain_count = failed_login_recent_count(cur, "AND email_domain=?", (domain,)) if domain else 0
        total = max(ip_count, email_count, domain_count)
        domain_velocity = domain_count if domain and not domain_has_local_accounts(cur, domain) else 0
        identity_velocity = max(email_count, domain_velocity)
        challenge_required = identity_velocity >= FAILED_LOGIN_CHALLENGE_AFTER and "email" not in safe and "domain" not in safe
        if enforce_challenge and challenge_required and not verify_login_challenge(email, request.form.get("login_challenge_answer") or (request.get_json(silent=True) or {}).get("login_challenge_answer")):
            challenge = issue_login_challenge(email)
            log_auth_event("login_challenge_required", email, 0, status="challenge", details={
                "reason": "suspicious_failed_login_velocity",
                "ip_failed_count": ip_count,
                "email_failed_count": email_count,
                "domain_failed_count": domain_count,
                "challenge_required": True,
                "severity": failed_login_severity(total, challenged=True),
            })
            return {
                "allowed": False,
                "status": 403,
                "message": FAILED_LOGIN_CHALLENGE_MESSAGE,
                "challenge": challenge,
                "reason": "challenge_required",
            }
        return {"allowed": True, "status": 200, "message": "", "challenge": None, "counts": {"ip": ip_count, "email": email_count, "domain": domain_count}}
    finally:
        conn.close()


def upsert_failed_login_control(cur, control_type, control_value, reason, source_event_id=0, created_by_admin_id=0, expires_at=None):
    if not control_value:
        return
    now = datetime.now().isoformat()
    cur.execute(
        """
        INSERT INTO failed_login_controls
        (control_type, control_value, status, reason, source_event_id, created_by_admin_id, expires_at, created_at, updated_at)
        VALUES (?, ?, 'active', ?, ?, ?, ?, ?, ?)
        ON CONFLICT(control_type, control_value) DO UPDATE SET
          status='active',
          reason=excluded.reason,
          source_event_id=excluded.source_event_id,
          created_by_admin_id=excluded.created_by_admin_id,
          expires_at=excluded.expires_at,
          updated_at=excluded.updated_at
        """,
        (control_type, control_value, clean_html(reason)[:500], int(source_event_id or 0), int(created_by_admin_id or 0), expires_at or "", now, now),
    )


def create_failed_login_alert(cur, email, user_id, counts, latest_event_id=0):
    burst_count = max(int(counts.get("ip") or 0), int(counts.get("email") or 0), int(counts.get("domain") or 0))
    if burst_count < FAILED_LOGIN_CHALLENGE_AFTER:
        return
    since = (datetime.now() - timedelta(seconds=FAILED_LOGIN_ALERT_WINDOW_SECONDS)).isoformat()
    domain = auth_email_domain(email)
    ip = client_ip_address()
    cur.execute(
        """
        SELECT id FROM security_events
        WHERE event_type='failed_login_burst' AND created_at>=? AND status IN ('High','Critical','alert')
          AND (details_json LIKE ? OR details_json LIKE ?)
        LIMIT 1
        """,
        (since, f"%{domain}%", f"%{ip}%"),
    )
    if cur.fetchone():
        return
    severity = failed_login_severity(burst_count, blocked=burst_count >= FAILED_LOGIN_IP_LIMIT)
    log_security_event("failed_login_burst", severity, user_id, request.path if has_request_context() else "/login", {
        "masked_email": mask_email(email),
        "email_domain": auth_email_domain(email),
        "ip_address": client_ip_address(),
        "country": request_country(),
        "user_agent": (request.headers.get("User-Agent", "") if has_request_context() else "")[:500],
        "device": login_device_summary(),
        "route": request.path if has_request_context() else "",
        "latest_auth_event_id": int(latest_event_id or 0),
        "counts": counts,
        "window_seconds": FAILED_LOGIN_ALERT_WINDOW_SECONDS,
    })
    try:
        create_task("security", f"Failed login burst from {auth_email_domain(email) or 'unknown domain'}", "critical" if severity == "Critical" else "high", "auth_event", latest_event_id)
    except Exception as exc:
        logging.info("FAILED_LOGIN_ALERT_TASK_SKIPPED error=%s", exc)


def register_failed_login(email, user_id=0, reason="invalid_credentials"):
    email = normalize_email(email or "")
    domain = auth_email_domain(email)
    ip = client_ip_address()
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    auth_event_schema_guard(cur, conn)
    try:
        ip_count = failed_login_recent_count(cur, "AND ip_address=?", (ip,)) + 1 if ip else 1
        email_count = failed_login_recent_count(cur, "AND email_hash=?", (auth_email_hash(email),)) + 1 if email else 1
        domain_count = failed_login_recent_count(cur, "AND email_domain=?", (domain,)) + 1 if domain else 1
        counts = {"ip": ip_count, "email": email_count, "domain": domain_count}
        blocked = ip_count >= FAILED_LOGIN_IP_LIMIT or email_count >= FAILED_LOGIN_EMAIL_LIMIT or domain_count >= FAILED_LOGIN_DOMAIN_LIMIT
        challenge_required = max(counts.values()) >= FAILED_LOGIN_CHALLENGE_AFTER
        severity = failed_login_severity(max(counts.values()), blocked=blocked, challenged=challenge_required)
        log_auth_event("login_failed", email, user_id, status="failed", details={
            "reason": reason,
            "found": bool(user_id),
            "ip_failed_count": ip_count,
            "email_failed_count": email_count,
            "domain_failed_count": domain_count,
            "challenge_required": challenge_required,
            "blocked": blocked,
            "severity": severity,
        })
        cur.execute("SELECT id FROM auth_events ORDER BY id DESC LIMIT 1")
        latest = cur.fetchone()
        latest_event_id = int((latest["id"] if latest else 0) or 0)
        expires_at = (datetime.now() + timedelta(seconds=FAILED_LOGIN_LOCKOUT_SECONDS)).isoformat()
        if ip and ip_count >= FAILED_LOGIN_IP_LIMIT and not failed_login_marked_safe(cur, "ip", ip):
            upsert_failed_login_control(cur, "ip", ip, "Automated cooldown after failed login burst.", latest_event_id, 0, expires_at)
        if email and email_count >= FAILED_LOGIN_EMAIL_LIMIT and not failed_login_marked_safe(cur, "email", email):
            upsert_failed_login_control(cur, "email", email, "Automated cooldown after repeated failed login.", latest_event_id, 0, expires_at)
        if domain and domain_count >= FAILED_LOGIN_DOMAIN_LIMIT and not failed_login_marked_safe(cur, "domain", domain):
            upsert_failed_login_control(cur, "domain", domain, "Automated domain cooldown after failed login burst.", latest_event_id, 0, expires_at)
        create_failed_login_alert(cur, email, user_id, counts, latest_event_id)
        conn.commit()
        if command_center_client_service.is_enabled():
            def dispatch_failed_login_security_event():
                try:
                    command_center_client_service.enqueue_security_event(
                        {
                            "event_id": f"auth-failed-{int(latest_event_id or 0)}",
                            "event_type": "login_bruteforce" if blocked else "login_failed",
                            "user_id": int(user_id or 0),
                            "payload": {
                                "reason": reason,
                                "masked_email": mask_email(email),
                                "email_domain": domain,
                                "ip_address": ip,
                                "country": request.headers.get("CF-IPCountry", "")[:80] if has_request_context() else "",
                                "user_agent": request.headers.get("User-Agent", "")[:500] if has_request_context() else "",
                                "route": request.path if has_request_context() else "/login",
                                "burst_count": max(counts.values()),
                                "counts": counts,
                                "challenge_required": challenge_required,
                                "blocked": blocked,
                            },
                        },
                        idempotency_key=f"auth-failed-{int(latest_event_id or 0)}",
                    )
                except Exception as exc:
                    logging.info("COMMAND_CENTER_FAILED_LOGIN_SECURITY_SKIPPED event_id=%s error=%s", latest_event_id, exc.__class__.__name__)

            threading.Thread(target=dispatch_failed_login_security_event, name="failed-login-security-dispatch", daemon=True).start()
        return {"counts": counts, "blocked": blocked, "severity": severity, "event_id": latest_event_id}
    finally:
        conn.close()


def create_account(full_name, email, password, phone="", country="", email_opt_in=False, sms_opt_in=False, username="", age_confirmed=False):
    email = normalize_email(email)
    logging.info("signup normalized email=%s db_engine=%s", mask_email(email), db_service.ENGINE_NAME)
    log_auth_event("signup_started", email, status="started", details={"db_engine": db_service.ENGINE_NAME})
    now_dt = datetime.now()
    now = now_dt.isoformat()
    trial_end = (now_dt + timedelta(days=PRO_TRIAL_DAYS)).isoformat()
    password_hash = generate_password_hash(password)
    referred_by = ""
    try:
        referred_by = (session.get("referred_by") or request.args.get("ref") or "").strip()[:80]
    except Exception:
        referred_by = ""
    conn = db()
    try:
        cur = conn.cursor()
        logging.info("database insert precheck for signup email=%s engine=%s", mask_email(email), db_service.ENGINE_NAME)
        if email:
            cur.execute("SELECT user_id FROM users WHERE lower(email)=lower(?) AND email!='' LIMIT 1", (email,))
            duplicate = cur.fetchone()
        else:
            cur.execute("SELECT user_id FROM users WHERE phone=? AND phone!='' LIMIT 1", (phone,))
            duplicate = cur.fetchone()
        if duplicate:
            conn.close()
            logging.info("duplicate email detection during signup email=%s", mask_email(email))
            log_auth_event("signup_duplicate", email, status="duplicate", details={"db_engine": db_service.ENGINE_NAME})
            return None, "An account already exists for that contact method."
        if username:
            cur.execute("SELECT user_id FROM users WHERE lower(username)=lower(?) LIMIT 1", (username,))
            if cur.fetchone():
                conn.close()
                return None, "That handle is already taken."
        referral_code = generate_referral_code()
        for _ in range(5):
            cur.execute("SELECT user_id FROM users WHERE referral_code=? LIMIT 1", (referral_code,))
            if not cur.fetchone():
                break
            referral_code = generate_referral_code()
        logging.info("database insert attempt for signup email=%s engine=%s", mask_email(email), db_service.ENGINE_NAME)
        initial_super_user = 1 if owner_super_user_enabled() and email == owner_email_value() else 0
        cur.execute(
            """
            INSERT INTO users (
                username, display_name, full_name, email, password_hash, phone, country, age_confirmed,
                email_verified, email_opt_in, sms_opt_in, plan, subscription_status,
                trial_start_date, trial_end_date, trial_used, pro_expires_at,
                referral_code, referred_by, usage_ai_count, usage_reset_at,
                signup_time, created_at, updated_at, onboarding_complete, alerts_enabled, is_pro,
                subscription_plan, subscription_started_at, subscription_expires_at, is_super_user
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, 'pro', 'trialing',
                    ?, ?, 1, ?, ?, ?, 0, ?,
                    ?, ?, ?, 1, 0, 1, 'pro', ?, ?, ?)
            """,
            (
                username,
                full_name,
                full_name,
                email,
                password_hash,
                phone,
                country,
                1 if age_confirmed else 0,
                int(email_opt_in),
                int(sms_opt_in),
                now,
                trial_end,
                trial_end,
                referral_code,
                referred_by,
                now[:10],
                now,
                now,
                now,
                now,
                trial_end,
                initial_super_user,
            )
        )
        user_id = cur.lastrowid
        logging.info("database insert generated user_id=%s email=%s", user_id, mask_email(email))
        pulsesoc_notification_system.ensure_user_notification_defaults(user_id, conn=conn)
        cur.execute(
            """
            INSERT INTO subscriptions
            (user_id, plan, status, payment_type, trial_start_date, trial_end_date, pro_expires_at, created_at, updated_at)
            VALUES (?, 'pro', 'trialing', 'trial', ?, ?, ?, ?, ?)
            """,
            (user_id, now, trial_end, trial_end, now, now)
        )
        pulsesoc_growth_engine.provision_user(
            conn,
            {
                "user_id": user_id,
                "username": username,
                "display_name": full_name,
                "full_name": full_name,
                "email": email,
                "email_verified": 0,
                "is_super_user": initial_super_user,
            },
            source="signup",
            commit=False,
        )
        conn.commit()
        logging.info("database commit success for signup user_id=%s engine=%s", user_id, db_service.ENGINE_NAME)
        log_auth_event("signup_completed", email, user_id, status="success", details={"db_engine": db_service.ENGINE_NAME})
    except Exception as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        logging.exception("database transaction rollback during signup email=%s engine=%s error=%s", mask_email(email), db_service.ENGINE_NAME, exc)
        log_auth_event("signup_failed", email, status="failed", details={"error": str(exc)[:500], "db_engine": db_service.ENGINE_NAME})
        return None, "Account creation is temporarily unavailable. Please try again shortly."
    finally:
        try:
            conn.close()
        except Exception:
            pass
    user = load_account_by_id(user_id)
    log_product_event(user_id, "signup_completed", {"source": "website_signup"})
    log_product_event(user_id, "pro_trial_started", {"trial_end_date": trial_end, "source": "website_signup"})
    record_referral_signup(user_id, referred_by)
    dispatch_brevo_contact_sync_safe({**(user or {}), "source": "website_account"}, entity_type="user", entity_id=user_id)
    return user, ""


def update_account_settings(user_id, full_name, phone, country, email_opt_in, sms_opt_in):
    now = datetime.now().isoformat()
    conn = db()
