def permanently_delete_account(user, password):
    user_id = int((user or {}).get("user_id") or 0)
    if not user_id:
        return False, "Account could not be identified."
    if not user.get("password_hash") or not check_password_hash(user["password_hash"], password or ""):
        return False, "Password confirmation did not match."
    now = datetime.utcnow().isoformat(timespec="seconds")
    deleted_handle = f"deleted-user-{user_id}-{secrets.token_hex(4)}"
    conn = db()
    cur = conn.cursor()
    try:
        user_columns = set(table_columns(cur, "users"))
        updates = {
            "username": deleted_handle,
            "display_name": "Deleted PulseSoc User",
            "full_name": "",
            "email": "",
            "password_hash": "",
            "phone": "",
            "phone_number": "",
            "country": "",
            "bio": "",
            "avatar_url": "",
            "avatar_thumbnail_url": "",
            "banner_url": "",
            "cover_url": "",
            "telegram_user_id": None,
            "telegram_username": "",
            "telegram_chat_id": None,
            "stripe_customer_id": None,
            "provider_customer_id": None,
            "account_status": "deleted",
            "email_opt_in": 0,
            "sms_opt_in": 0,
            "marketing_email_opt_in": 0,
            "notification_email_opt_in": 0,
            "alerts_enabled": 0,
            "deleted_at": now,
            "updated_at": now,
        }
        assignments = []
        values = []
        for column, value in updates.items():
            if column in user_columns:
                assignments.append(f"{column}=?")
                values.append(value)
        values.append(user_id)
        cur.execute(f"UPDATE users SET {', '.join(assignments)} WHERE user_id=?", values)

        for table in ("push_subscriptions", "password_reset_tokens", "email_verification_tokens", "telegram_link_codes"):
            columns = set(table_columns(cur, table))
            if "user_id" in columns:
                cur.execute(f"DELETE FROM {table} WHERE user_id=?", (user_id,))

        for table, owner_column in (
            ("pulse_posts", "user_id"),
            ("pulse_status", "user_id"),
            ("pulse_comments", "user_id"),
            ("pulse_group_posts", "user_id"),
            ("pulse_group_post_comments", "user_id"),
        ):
            columns = set(table_columns(cur, table))
            if owner_column not in columns:
                continue
            assignments = []
            values = []
            if "deleted_at" in columns:
                assignments.append("deleted_at=COALESCE(deleted_at, ?)")
                values.append(now)
            if "status" in columns:
                assignments.append("status='deleted'")
            if "moderation_status" in columns:
                assignments.append("moderation_status='removed'")
            if "updated_at" in columns:
                assignments.append("updated_at=?")
                values.append(now)
            if assignments:
                values.append(user_id)
                cur.execute(f"UPDATE {table} SET {', '.join(assignments)} WHERE {owner_column}=?", values)

        conn.commit()
        logging.info("ACCOUNT_DELETION_COMPLETED user_id=%s", user_id)
        return True, ""
    except Exception:
        conn.rollback()
        logging.exception("ACCOUNT_DELETION_FAILED user_id=%s", user_id)
        return False, "Account deletion could not be completed. Contact support@pulsesoc.com."
    finally:
        conn.close()


def generate_telegram_link_code(user_id):
    now = datetime.now()
    code = secrets.token_urlsafe(8).replace("-", "").replace("_", "")[:10].upper()
    conn = db()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO telegram_link_codes (user_id, code, status, expires_at, created_at) VALUES (?, ?, ?, ?, ?)",
        (user_id, code, "pending", (now + timedelta(minutes=10)).isoformat(), now.isoformat())
    )
    conn.commit()
    conn.close()
    return code


def create_password_reset(email):
    email = normalize_email(email)
    user = load_account_by_email(email)
    if not user:
        return None, None
    token = secrets.token_urlsafe(32)
    token_hash = password_reset_token_hash(token)
    now = datetime.now()
    conn = None
    try:
        conn = db()
        cur = conn.cursor()
        ensure_password_reset_token_columns(cur, conn)
        cur.execute(
            """
            INSERT INTO password_reset_tokens
            (user_id, token, token_hash, expires_at, delivery_status, created_at)
            VALUES (?, NULL, ?, ?, 'pending', ?)
            """,
            (user["user_id"], token_hash, (now + timedelta(hours=1)).isoformat(), now.isoformat()),
        )
        conn.commit()
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.exception("PASSWORD_RESET_TOKEN_CREATE_FAILED email=%s", mask_email(email))
        return user, None
    finally:
        if conn is not None:
            conn.close()
    return user, token


def ensure_password_reset_token_columns(cur, conn=None):
    add_columns_if_missing(cur, "password_reset_tokens", [
        ("token_hash", "TEXT"),
        ("delivery_status", "TEXT"),
        ("request_ip_hash", "TEXT"),
    ], conn=conn)


def password_reset_token_hash(token):
    token = str(token or "")
    secret = (os.getenv("SECRET_KEY") or os.getenv("FLASK_SECRET_KEY") or webhook_app.secret_key or "pulse-reset-token").encode("utf-8")
    return hmac.new(secret, token.encode("utf-8"), hashlib.sha256).hexdigest()


def _row_value(row, key, index, default=None):
    if row is None:
        return default
    try:
        if hasattr(row, "keys") and key in row.keys():
            return row[key]
    except Exception:
        pass
    try:
        return row[index]
    except Exception:
        return default


def load_password_reset_record(cur, token):
    token = clean_html(token or "")
    ensure_password_reset_token_columns(cur)
    token_hash = password_reset_token_hash(token)
    cur.execute(
        "SELECT id, user_id, expires_at, used_at, token_hash FROM password_reset_tokens WHERE token_hash=? ORDER BY id DESC LIMIT 1",
        (token_hash,),
    )
    row = cur.fetchone()
    if row:
        return row
    cur.execute(
        "SELECT id, user_id, expires_at, used_at, token_hash FROM password_reset_tokens WHERE token=? ORDER BY id DESC LIMIT 1",
        (token,),
    )
    return cur.fetchone()


def safe_password_reset_request(email, source="web"):
    """Create and queue a password reset without allowing provider failures to break the route."""
    email = normalize_email(clean_html(email or ""))
    result = {"ok": True, "generic_message": "If that email has an account, a password reset link will be sent.", "email": mask_email(email), "source": source}
    if not email or not is_valid_email(email):
        try:
            log_auth_event("forgot_password_invalid_email", email, status="invalid", details={"source": source, "db_engine": db_service.ENGINE_NAME})
        except Exception:
            logging.warning("PASSWORD_RESET_INVALID_EMAIL_LOG_FAILED source=%s", source)
        return result
    try:
        user, token = create_password_reset(email)
        if user and token:
            reset_link = public_url_for("reset_password_page", token=token)
            sent = False
            try:
                sent = bool(send_password_reset_email(user, reset_link))
            except Exception as exc:
                logging.exception("PASSWORD_RESET_EMAIL_QUEUE_FAILED user_id=%s source=%s error=%s", user.get("user_id"), source, exc.__class__.__name__)
            conn = None
            try:
                conn = db()
                cur = conn.cursor()
                ensure_password_reset_token_columns(cur, conn)
                cur.execute(
                    "UPDATE password_reset_tokens SET delivery_status=? WHERE user_id=? AND token_hash=?",
                    ("queued" if sent else "queue_failed", user.get("user_id"), password_reset_token_hash(token)),
                )
                conn.commit()
            except Exception as exc:
                if conn is not None:
                    try:
                        conn.rollback()
                    except Exception:
                        pass
                logging.warning("PASSWORD_RESET_DELIVERY_STATUS_FAILED user_id=%s source=%s error=%s", user.get("user_id"), source, exc.__class__.__name__)
            finally:
                if conn is not None:
                    conn.close()
            try:
                log_product_event(user.get("user_id"), "forgot_password_requested", {"source": source, "email_queued": bool(sent)})
                log_auth_event("forgot_password_token_created", email, user.get("user_id"), status="success", details={"db_engine": db_service.ENGINE_NAME, "source": source, "email_queued": bool(sent)})
            except Exception as exc:
                logging.warning("PASSWORD_RESET_AUDIT_LOG_FAILED user_id=%s source=%s error=%s", user.get("user_id"), source, exc.__class__.__name__)
        else:
            try:
                log_auth_event("forgot_password_no_match", email, status="not_found", details={"db_engine": db_service.ENGINE_NAME, "source": source})
            except Exception:
                logging.warning("PASSWORD_RESET_NO_MATCH_LOG_FAILED source=%s", source)
    except Exception as exc:
        logging.exception("PASSWORD_RESET_REQUEST_FAILED source=%s email=%s error=%s", source, mask_email(email), exc.__class__.__name__)
        try:
            log_auth_event("forgot_password_request_failed", email, status="failed", details={"source": source, "error_type": exc.__class__.__name__})
        except Exception:
            pass
        result["degraded"] = True
    return result


def create_email_verification(user_id):
    token = secrets.token_urlsafe(32)
    now = datetime.now()
    conn = db()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO email_verification_tokens (user_id, token, expires_at, created_at) VALUES (?, ?, ?, ?)",
        (user_id, token, (now + timedelta(hours=24)).isoformat(), now.isoformat())
    )
    conn.commit()
    conn.close()
    return token


def send_account_confirmation_email(user, source="signup"):
    if not user or not user.get("email"):
        return {"ok": False, "message": "User email not found.", "trace_id": secrets.token_hex(6)}
    trace_id = secrets.token_hex(6)
    token = create_email_verification(user["user_id"])
    verification_link = public_url_for("verify_email_page", token=token)
    logging.info(
        "ACCOUNT_CONFIRMATION_EMAIL_SEND trace_id=%s user_id=%s source=%s to_domain=%s base_url=%s",
        trace_id,
        user.get("user_id"),
        source,
        str(user.get("email") or "").split("@")[-1],
        public_app_base_url(),
    )
    subject = "Verify your PulseSoc email"
    idempotency_key = f"email-verification:{int(user.get('user_id') or 0)}:{hashlib.sha256(token.encode('utf-8')).hexdigest()[:20]}"
    ok = bool(send_email_verification(user, verification_link, trace_id=trace_id, idempotency_key=idempotency_key))
    if not ok:
        logging.warning(
            "ACCOUNT_CONFIRMATION_EMAIL_FAILED trace_id=%s user_id=%s source=%s reason=%s",
            trace_id,
            user.get("user_id"),
            source,
            getattr(send_platform_email, "last_error", "") or "Email provider did not accept the verification email.",
        )
    return {
        "ok": bool(ok),
        "queued": False,
        "trace_id": trace_id,
        "verification_link_base": public_app_base_url(),
        "message": "Confirmation email sent." if ok else f"Confirmation email could not be delivered. {getattr(send_platform_email, 'last_error', '') or ''}".strip(),
    }


def resend_account_confirmation_by_email(email, source="login"):
    email = normalize_email(email)
    if not email or not is_valid_email(email):
        return {"ok": False, "message": "Enter the email address for your PulseSoc account.", "status": 400}
    user = load_account_by_email(email)
    if not user:
        return {"ok": True, "message": "If that account exists and still needs confirmation, PulseSoc will send a confirmation email.", "status": 200}
    if int(user.get("email_verified") or 0):
        return {"ok": True, "message": "This email is already confirmed. You can log in.", "status": 200}
    result = send_account_confirmation_email(user, source=source)
    delivery_blocked = "not authorized in brevo" in str(result.get("message") or "").lower()
    return {
        **result,
        "status": 200 if result.get("ok") else 202 if delivery_blocked else 502,
        "message": "Check your email to confirm your account." if result.get("ok") else ("Verification email could not be delivered. Brevo is blocking the Railway outbound IP." if delivery_blocked else f"Confirmation email could not be sent. Trace ID: {result.get('trace_id')}"),
    }


def change_unverified_account_email(old_email, new_email, password, source="email_delivery_repair"):
    old_email = normalize_email(old_email)
    new_email = normalize_email(new_email)
    if not old_email or not is_valid_email(old_email):
        return {"ok": False, "message": "Enter the email address used to create your PulseSoc account.", "status": 400}
    if not new_email or not is_valid_email(new_email):
        return {"ok": False, "message": "Enter a valid new email address.", "status": 400}
    if old_email == new_email:
        return {"ok": False, "message": "Enter a different email address.", "status": 400}
    user = load_account_by_email(old_email)
    if not user:
        return {"ok": True, "message": "If that unverified account exists, PulseSoc will update the email and send a fresh confirmation.", "status": 200}
    if int(user.get("email_verified") or 0):
        return {"ok": False, "message": "This account is already verified. Log in to manage account settings.", "status": 403}
    if not user.get("password_hash") or not check_password_hash(user["password_hash"], password or ""):
        log_auth_event("unverified_email_change_failed", old_email, user.get("user_id"), status="failed", details={"reason": "bad_password", "source": source})
        return {"ok": False, "message": "Password is incorrect.", "status": 401}
    existing = load_account_by_email(new_email)
    if existing and int(existing.get("user_id") or 0) != int(user.get("user_id") or 0):
        return {"ok": False, "message": "That email address is already used by another account.", "status": 409}
    now = datetime.now().isoformat()
    conn = db()
    cur = conn.cursor()
    cur.execute("UPDATE users SET email=?, email_verified=0, updated_at=? WHERE user_id=?", (new_email, now, user["user_id"]))
    cur.execute("UPDATE email_verification_tokens SET used_at=COALESCE(used_at, ?) WHERE user_id=? AND used_at IS NULL", (now, user["user_id"]))
    conn.commit()
    conn.close()
    updated = load_account_by_id(user["user_id"]) or {**user, "email": new_email}
    log_auth_event("unverified_email_changed", new_email, user.get("user_id"), status="success", details={"source": source, "old_domain": old_email.split("@")[-1], "new_domain": new_email.split("@")[-1]})
    result = send_account_confirmation_email(updated, source=source)
    return {
        **result,
        "status": 200 if result.get("ok") else 202,
        "message": "Email address updated. Check your new email to confirm your account." if result.get("ok") else "Email address updated, but verification email could not be delivered. Use Resend Email after Brevo is unblocked.",
        "email": new_email,
    }


def unverified_signup_delivery_response(email, message="", trace_id=""):
    return {
        "ok": True,
        "authenticated": False,
        "requires_email_confirmation": True,
        "email_delivery_failed": bool(trace_id),
        "message": message or "Account created successfully but verification email could not be delivered.",
        "trace_id": trace_id or "",
        "email": email,
        "actions": {
            "resend_email": "/api/mobile/auth/resend-confirmation",
            "change_email_address": "/api/mobile/auth/change-confirmation-email",
        },
    }


@webhook_app.route("/signup", methods=["GET", "POST"])
def signup_page():
    init_db()
    if request.method == "GET" and require_account():
        return redirect(safe_redirect_target("pulse_page"))
    if request.method == "GET":
        log_product_event(0, "signup_started", {"source": "signup_page"})
    if request.method == "POST":
        logging.info("signup endpoint started")
        if not verify_csrf():
            return render_account_page("signup", "Create Account", error="Security check failed. Please try again.")
        full_name = clean_html(request.form.get("full_name", ""))[:160]
        username = clean_html(request.form.get("username", "")).strip().lstrip("@")[:40]
        email = normalize_email(clean_html(request.form.get("email", "")))
        password = request.form.get("password", "")
        # Initial registration is email-based. Phone and SMS consent are
        # optional account settings after signup, never signup requirements.
        phone = ""
        country = clean_html(request.form.get("country", ""))[:80]
        preferred_language = normalize_preferred_language(request.form.get("preferred_language") or request.form.get("language") or "", default="")
        email_opt_in = request.form.get("email_opt_in") == "on"
        sms_opt_in = False
        age_confirmed = request.form.get("age_confirmed") == "on" or request.form.get("age_confirmed") == "true"
        terms_accepted = request.form.get("terms_accepted") == "on" or request.form.get("terms_accepted") == "true"
        if not email:
            return render_account_page("signup", "Create Account", error="Enter your email address to create your account.")
        if not is_valid_email(email):
            return render_account_page("signup", "Create Account", error="Please enter a valid email address.")
        if username and not re.match(r"^[A-Za-z0-9_.-]{3,40}$", username):
            return render_account_page("signup", "Create Account", error="Use 3-40 letters, numbers, dots, underscores, or dashes for your handle.")
        if not age_confirmed:
            return render_account_page("signup", "Create Account", error="Confirm your age eligibility before creating your account.")
        if not terms_accepted:
            return render_account_page("signup", "Create Account", error="Agree to the Terms, Privacy Policy, and no-tolerance safety rules before creating your account.")
        if len(password) < 8:
            return render_account_page("signup", "Create Account", error="Use at least 8 characters for your password.")
        user, error = create_account(full_name, email, password, phone, country, email_opt_in, sms_opt_in, username, age_confirmed)
        if error:
            existing_user = load_account_by_email(email) if email else None
            if existing_user and not int(existing_user.get("email_verified") or 0):
                return render_account_page(
                    "login",
                    "Confirm Email",
                    message="Account created successfully but verification email could not be delivered. Use Resend Email or Change Email Address.",
                    resend_email=email,
                )
            return render_account_page("signup", "Create Account", error=error)
        session.permanent = True
        session["account_user_id"] = user["user_id"]
        if preferred_language:
            save_user_preferred_language(user["user_id"], preferred_language, user["user_id"])
            user = load_account_by_id(user["user_id"]) or user
        logging.info("user created successfully: user_id=%s", user["user_id"])
        logging.info("Signup successful for user_id: %s", user["user_id"])
        logging.info("calling send_welcome_email")
        send_signup_welcome_emails(user)
        logging.info("send_welcome_email completed")
        if user.get("email"):
            result = send_account_confirmation_email(user, source="signup")
            if not result.get("ok"):
                session.pop("account_user_id", None)
                return render_account_page(
                    "login",
                    "Confirm Email",
                    message=f"Account created successfully but verification email could not be delivered. Trace ID: {result.get('trace_id')}. Use Resend Email after Brevo is unblocked or Change Email Address.",
                    resend_email=email,
                )
            session.pop("account_user_id", None)
            return render_account_page("login", "Login", message="Account created. Check your email to confirm your account before logging in.", resend_email=email)
        token_payload = issue_mobile_security_tokens(user, {"source": "web_signup", "device_label": presence_device_label()})
        session["pulse_welcome_reason"] = "first_login"
        response = redirect("/pulse?signup_completed=1")
        return set_persistent_session_cookie(response, token_payload.get("refresh_token") or "")
    return render_account_page("signup", "Create Account")


@webhook_app.route("/login", methods=["GET", "POST"])
def login_page():
    init_db()
    if request.method == "GET" and require_account():
        return redirect("/pulse")
    if request.method == "POST":
        if not verify_csrf():
            return render_account_page("login", "Login", error="Security check failed. Please try again.")
        email = normalize_email(clean_html(request.form.get("email", "")))
        password = request.form.get("password", "")
        preferred_language = normalize_preferred_language(request.form.get("preferred_language") or request.form.get("language") or "", default="")
        terms_accepted = request.form.get("terms_accepted") == "on" or request.form.get("terms_accepted") == "true"
        if not terms_accepted:
            return render_account_page("login", "Login", error="Agree to the Terms, Privacy Policy, and no-tolerance safety rules before logging in.", resend_email=email), 400
        security_gate = login_security_preflight(email, enforce_challenge=False)
        if not security_gate.get("allowed"):
            return render_account_page(
                "login",
                "Login",
                error=security_gate.get("message") or "Security challenge required.",
                resend_email=email,
                login_challenge=security_gate.get("challenge"),
            ), int(security_gate.get("status") or 403)
        logging.info("login attempt email=%s db_engine=%s", mask_email(email), db_service.ENGINE_NAME)
        user = load_account_by_email(email)
        if not user:
            challenge_gate = login_security_preflight(email, enforce_challenge=True)
            if not challenge_gate.get("allowed"):
                return render_account_page(
                    "login",
                    "Login",
                    error=challenge_gate.get("message") or "Security challenge required.",
                    resend_email=email,
                    login_challenge=challenge_gate.get("challenge"),
                ), int(challenge_gate.get("status") or 403)
            register_failed_login(email, 0, "unknown_email")
            return render_account_page("login", "Login", error="Email or password is incorrect.")
        restriction_message = account_login_restriction_message(user)
        if restriction_message:
            log_auth_event("login_restricted", email, user["user_id"], status="blocked", details={"account_status": user.get("account_status") or "", "login_enabled": safe_int(user.get("login_enabled"), 1), "access_enabled": safe_int(user.get("access_enabled"), 1), "db_engine": db_service.ENGINE_NAME})
            return render_account_page("login", "Login", error=restriction_message), 403
        if user.get("email") and not int(user.get("email_verified") or 0):
            log_auth_event("login_unconfirmed", email, user["user_id"], status="blocked", details={"db_engine": db_service.ENGINE_NAME})
            return render_account_page("login", "Login", error="Please confirm your email before logging in.", resend_email=email)
        if not user.get("password_hash") or not check_password_hash(user["password_hash"], password):
            challenge_gate = login_security_preflight(email, enforce_challenge=True)
            if not challenge_gate.get("allowed"):
                return render_account_page(
                    "login",
                    "Login",
                    error=challenge_gate.get("message") or "Security challenge required.",
                    resend_email=email,
                    login_challenge=challenge_gate.get("challenge"),
                ), int(challenge_gate.get("status") or 403)
            register_failed_login(email, user.get("user_id") if user else 0, "invalid_password")
            return render_account_page("login", "Login", error="Email or password is incorrect.")
        session["account_user_id"] = user["user_id"]
        session["pulse_welcome_reason"] = "welcome_back" if user.get("last_login_at") else "first_login"
        log_auth_event("login_success", email, user["user_id"], status="success", details={"db_engine": db_service.ENGINE_NAME})
        conn = db()
        cur = conn.cursor()
        if user_is_owner_account(user):
            ensure_owner_super_user(cur, conn)
        cur.execute("UPDATE users SET last_login_at=?, last_seen_at=? WHERE user_id=?", (datetime.now().isoformat(), datetime.now().isoformat(), user["user_id"]))
        notify_user(
            cur,
            user["user_id"],
            "account_login",
            "New login to PulseSoc",
            "Your PulseSoc account was accessed successfully.",
            "/pulse/settings/notifications",
            actor_user_id=user["user_id"],
            entity_type="account",
            entity_id=str(user["user_id"]),
            metadata={"ip_present": bool(request.remote_addr), "user_agent_present": bool(request.headers.get("User-Agent"))},
        )
        notify_user(
            cur,
            user["user_id"],
            "new_device",
            "Device activity detected",
            "PulseSoc recorded a browser/device login for your account.",
            "/pulse/settings/notifications",
            actor_user_id=user["user_id"],
            entity_type="account",
            entity_id=str(user["user_id"]),
            metadata={"event": "device_login", "user_agent_present": bool(request.headers.get("User-Agent"))},
        )
        conn.commit()
        conn.close()
        if preferred_language:
            save_user_preferred_language(user["user_id"], preferred_language, user["user_id"])
            user = load_account_by_id(user["user_id"]) or user
        token_payload = issue_mobile_security_tokens(user, {"source": "web_login", "device_label": presence_device_label()})
        response = redirect(safe_redirect_target("pulse_page"))
        return set_persistent_session_cookie(response, token_payload.get("refresh_token") or "")
    return render_account_page("login", "Login")


@webhook_app.route("/resend-confirmation", methods=["POST"])
def resend_confirmation_page():
    init_db()
    if not verify_csrf():
        return render_account_page("login", "Login", error="Security check failed. Please try again.")
