def pulse_mobile_user_payload(user):
    user = user or {}
    return {
        "user_id": int(user.get("user_id") or 0),
        "email": user.get("email") or "",
        "username": user.get("username") or "",
        "display_name": user.get("display_name") or user.get("full_name") or user.get("username") or "PulseSoc member",
        "full_name": user.get("full_name") or "",
        "public_player_id": user.get("public_player_id") or "",
        "avatar_url": user.get("avatar_url") or "",
        "avatar_thumbnail_url": user.get("avatar_thumbnail_url") or user.get("avatar_url") or "",
        "cover_url": user.get("cover_url") or user.get("banner_url") or "",
        "banner_url": user.get("banner_url") or user.get("cover_url") or "",
        "account_status": user.get("account_status") or "active",
        "premium_status": user.get("premium_status") or user.get("subscription_status") or "",
        "preferred_language": account_language(user),
    }


