@webhook_app.route("/api/mobile/auth/refresh", methods=["POST"])
@webhook_app.route("/api/pulse/mobile/auth/refresh", methods=["POST"])
def api_mobile_auth_refresh():
    init_db()
    payload = request.get_json(silent=True) or {}
    refresh_token = payload.get("refresh_token") or request.cookies.get(PERSISTENT_SESSION_COOKIE) or ""
    explicit_refresh_token = bool(payload.get("refresh_token"))
    user = None
    token_payload = {}
    if refresh_token:
        user, token_payload = rotate_mobile_refresh_token(refresh_token, {**payload, "source": payload.get("source") or "mobile_refresh"})
    if not user and explicit_refresh_token:
        return api_error("Session expired. Please log in again.", 401, error="session_expired")
    if not user:
        user = require_account()
        if not user:
            return api_error("Session expired. Please log in again.", 401, error="session_expired")
    if user:
        session.permanent = True
        session["account_user_id"] = user["user_id"]
        if explicit_refresh_token:
            session["pulse_welcome_reason"] = "session_return"
    fresh_user = load_account_by_id(user["user_id"]) or user
    if not token_payload:
        token_payload = issue_mobile_security_tokens(fresh_user, {**payload, "source": payload.get("source") or "mobile_refresh"}, rotate_from=refresh_token)
    response = jsonify({"ok": True, "authenticated": True, "user": pulse_mobile_user_payload(fresh_user), **token_payload})
    return set_persistent_session_cookie(response, token_payload.get("refresh_token") or "")


@webhook_app.route("/api/mobile/auth/login", methods=["POST"])
@webhook_app.route("/api/pulse/mobile/auth/login", methods=["POST"])
def api_mobile_auth_login():
    init_db()
    payload = request.get_json(silent=True) or {}
    identifier = clean_html(payload.get("identifier") or payload.get("email") or payload.get("username") or "")
    email = normalize_email(identifier) if "@" in identifier else identifier.strip().lstrip("@")
    password = payload.get("password") or ""
    preferred_language = normalize_preferred_language(payload.get("preferred_language") or payload.get("language") or "", default="")
    security_gate = login_security_preflight(email, enforce_challenge=False)
    if not security_gate.get("allowed"):
        payload = {
            "error": "login_challenge_required" if security_gate.get("challenge") else "login_rate_limited",
            "challenge": security_gate.get("challenge") or {},
        }
        return api_error(security_gate.get("message") or "Security challenge required.", int(security_gate.get("status") or 403), **payload)
    user = load_account_by_email_or_username(email)
    if not user:
        challenge_gate = login_security_preflight(email, enforce_challenge=True)
        if not challenge_gate.get("allowed"):
            payload = {
                "error": "login_challenge_required" if challenge_gate.get("challenge") else "login_rate_limited",
                "challenge": challenge_gate.get("challenge") or {},
            }
            return api_error(challenge_gate.get("message") or "Security challenge required.", int(challenge_gate.get("status") or 403), **payload)
        register_failed_login(email, 0, "mobile_unknown_account")
        return api_error("Email or password is incorrect.", 401)
    restriction_message = account_login_restriction_message(user)
    if restriction_message:
        log_auth_event("mobile_login_restricted", email, user["user_id"], status="blocked", details={"account_status": user.get("account_status") or "", "login_enabled": safe_int(user.get("login_enabled"), 1), "access_enabled": safe_int(user.get("access_enabled"), 1), "db_engine": db_service.ENGINE_NAME})
        return api_error(restriction_message, 403, error="account_restricted")
    if user.get("email") and not int(user.get("email_verified") or 0):
        log_auth_event("mobile_login_unconfirmed", email, user["user_id"], status="blocked", details={"db_engine": db_service.ENGINE_NAME})
        return api_error("Please confirm your email before logging in.", 403, error="email_not_confirmed")
    if not user.get("password_hash") or not check_password_hash(user["password_hash"], password):
        challenge_gate = login_security_preflight(email, enforce_challenge=True)
        if not challenge_gate.get("allowed"):
            payload = {
                "error": "login_challenge_required" if challenge_gate.get("challenge") else "login_rate_limited",
                "challenge": challenge_gate.get("challenge") or {},
            }
            return api_error(challenge_gate.get("message") or "Security challenge required.", int(challenge_gate.get("status") or 403), **payload)
        register_failed_login(email, user.get("user_id") if user else 0, "mobile_invalid_password")
        return api_error("Email or password is incorrect.", 401)
    session["account_user_id"] = user["user_id"]
    session["pulse_welcome_reason"] = "welcome_back" if user.get("last_login_at") else "first_login"
    conn = db()
    cur = conn.cursor()
    now = datetime.now().isoformat()
    cur.execute("UPDATE users SET last_login_at=?, last_seen_at=? WHERE user_id=?", (now, now, user["user_id"]))
    notify_user(
        cur,
        user["user_id"],
        "account_login",
        "New login to PulseSoc",
        "Your PulseSoc account was accessed from the mobile app foundation.",
        "/pulse/settings/notifications",
        actor_user_id=user["user_id"],
        entity_type="account",
        entity_id=str(user["user_id"]),
        metadata={"source": "mobile_api", "ip_present": bool(request.remote_addr), "user_agent_present": bool(request.headers.get("User-Agent"))},
    )
    notify_user(
        cur,
        user["user_id"],
        "new_device",
        "Device activity detected",
        "PulseSoc recorded a mobile app session for your account.",
        "/pulse/settings/notifications",
        actor_user_id=user["user_id"],
        entity_type="account",
        entity_id=str(user["user_id"]),
        metadata={"event": "mobile_device_login", "user_agent_present": bool(request.headers.get("User-Agent"))},
    )
    conn.commit()
    conn.close()
    if preferred_language:
        save_user_preferred_language(user["user_id"], preferred_language, user["user_id"])
    log_auth_event("mobile_login_success", email, user["user_id"], status="success", details={"db_engine": db_service.ENGINE_NAME})
    fresh_user = load_account_by_id(user["user_id"]) or user
    token_payload = issue_mobile_security_tokens(fresh_user, {**payload, "source": "mobile_login"})
    response = jsonify({"ok": True, "authenticated": True, "user": pulse_mobile_user_payload(fresh_user), **token_payload})
    return set_persistent_session_cookie(response, token_payload.get("refresh_token") or "")


@webhook_app.route("/api/mobile/auth/register", methods=["POST"])
@webhook_app.route("/api/pulse/mobile/auth/register", methods=["POST"])
def api_mobile_auth_register():
    init_db()
    payload = request.get_json(silent=True) or {}
    full_name = clean_html(payload.get("full_name") or "")[:160]
    username = clean_html(payload.get("username") or "").strip().lstrip("@")[:40]
    email = normalize_email(clean_html(payload.get("email") or ""))
    password = payload.get("password") or ""
    phone = clean_html(payload.get("phone") or "").strip()
    country = clean_html(payload.get("country") or "")[:80]
    preferred_language = normalize_preferred_language(payload.get("preferred_language") or payload.get("language") or "", default="")
    email_opt_in = bool(payload.get("email_opt_in"))
    sms_opt_in = bool(payload.get("sms_opt_in"))
    age_confirmed = bool(payload.get("age_confirmed"))
    if email and not is_valid_email(email):
        return api_error("Please enter a valid email address.", 400)
    if not email and not phone:
        return api_error("Add an email or phone number to secure your account.", 400)
    if username and not re.match(r"^[A-Za-z0-9_.-]{3,40}$", username):
        return api_error("Use 3-40 letters, numbers, dots, underscores, or dashes for your handle.", 400)
    if not age_confirmed:
        return api_error("Confirm your age eligibility before creating your account.", 400)
    if len(password) < 8:
        return api_error("Use at least 8 characters for your password.", 400)
    if phone and not valid_phone(phone):
        return api_error("Please enter a valid phone number or leave it blank.", 400)
    if sms_opt_in and not phone:
        return api_error("SMS opt-in requires a phone number.", 400)
    user, error = create_account(full_name, email, password, phone, country, email_opt_in, sms_opt_in, username, age_confirmed)
    if error:
        existing_user = load_account_by_email(email) if email else None
        if existing_user and not int(existing_user.get("email_verified") or 0):
            return jsonify(unverified_signup_delivery_response(email, "Account created successfully but verification email could not be delivered.")), 200
        return api_error(error, 400)
    if preferred_language:
        save_user_preferred_language(user["user_id"], preferred_language, user["user_id"])
        user = load_account_by_id(user["user_id"]) or user
    send_signup_welcome_emails(user)
    if user.get("email"):
        result = send_account_confirmation_email(user, source="mobile_signup")
        if result.get("ok"):
            return jsonify({"ok": True, "authenticated": False, "requires_email_confirmation": True, "message": "Check your email to confirm your account.", "trace_id": result.get("trace_id"), "email": email}), 200
        return jsonify(unverified_signup_delivery_response(email, "Account created successfully but verification email could not be delivered.", result.get("trace_id") or "")), 200
    session.permanent = True
    session["account_user_id"] = user["user_id"]
    session["pulse_welcome_reason"] = "first_login"
    fresh_user = load_account_by_id(user["user_id"]) or user
    token_payload = issue_mobile_security_tokens(fresh_user, {**payload, "source": "mobile_signup"})
    response = jsonify({"ok": True, "authenticated": True, "user": pulse_mobile_user_payload(fresh_user), **token_payload})
    return set_persistent_session_cookie(response, token_payload.get("refresh_token") or "")


