@webhook_app.route("/api/mobile/auth/confirm-email", methods=["GET", "POST"])
@webhook_app.route("/api/pulse/mobile/auth/confirm-email", methods=["GET", "POST"])
def api_mobile_auth_confirm_email():
    init_db()
    payload = request.get_json(silent=True) or {}
    token = clean_html(payload.get("token") or request.args.get("token") or "")
    if not token:
        return api_error("This verification link is invalid.", 400, error="invalid_token")
    conn = db()
    cur = conn.cursor()
    cur.execute("SELECT user_id, expires_at, used_at FROM email_verification_tokens WHERE token=? ORDER BY id DESC LIMIT 1", (token,))
    row = cur.fetchone()
    if not row or row[2] or row[1] < datetime.now().isoformat():
        conn.close()
        return api_error("This verification link is invalid or expired.", 400, error="invalid_or_expired_token")
    now = datetime.now().isoformat()
    cur.execute("UPDATE users SET email_verified=1, updated_at=? WHERE user_id=?", (now, row[0]))
    cur.execute("UPDATE email_verification_tokens SET used_at=? WHERE token=?", (now, token))
    conn.commit()
    conn.close()
    verified_user = load_account_by_id(row[0])
    if verified_user and verified_user.get("referred_by"):
        conn = db()
        cur = conn.cursor()
        cur.execute("SELECT user_id FROM users WHERE referral_code=? LIMIT 1", (verified_user.get("referred_by"),))
        referrer = cur.fetchone()
        conn.close()
        if referrer:
            evaluate_referral_reward(referrer[0])
    return jsonify({"ok": True, "confirmed": True, "message": "Email verified. You can log in anytime."})


