@webhook_app.route("/api/i18n/missing", methods=["POST"])
def api_i18n_missing_translation():
    init_db()
    payload = request.get_json(silent=True) or {}
    key = clean_html(payload.get("key") or "")[:180]
    language = normalize_preferred_language(payload.get("language") or "", default="")
    if not key or not language:
        return jsonify({"ok": True, "logged": False})
    user_id = int(account_user_id() or 0)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); cur = conn.cursor()
    try:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS i18n_missing_translations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER DEFAULT 0,
                language TEXT,
                translation_key TEXT,
                path TEXT,
                created_at TEXT
            )
            """
        )
        cur.execute(
            "INSERT INTO i18n_missing_translations (user_id, language, translation_key, path, created_at) VALUES (?, ?, ?, ?, ?)",
            (user_id, language, key, (request.path or "")[:240], now),
        )
        conn.commit()
    except Exception:
        conn.rollback()
        logging.info("I18N_MISSING_TRANSLATION_LOG_SKIPPED key=%s language=%s", key, language)
    finally:
        conn.close()
    return jsonify({"ok": True, "logged": True})


