@webhook_app.route("/account/delete", methods=["GET", "POST"])
def account_delete_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next="/account/delete"))
    if request.method == "POST":
        if not verify_csrf():
            return render_account_page("delete_account", "Delete Account", current_user=user, error="Security check failed. Please try again.")
        if request.form.get("confirm_delete") != "on":
            return render_account_page("delete_account", "Delete Account", current_user=user, error="Confirm that you understand account deletion is permanent.")
        deleted, error = permanently_delete_account(user, request.form.get("password", ""))
        if not deleted:
            return render_account_page("delete_account", "Delete Account", current_user=user, error=error)
        session.clear()
        return render_account_page(
            "custom",
            "Account Deleted",
            current_user=None,
            custom_body="<section class='profile-card'><h2>Your PulseSoc account was deleted.</h2><p>Your personal profile was removed and this device was signed out.</p><div class='actions'><a class='button primary' href='/signup'>Create a new account</a><a class='button' href='/'>Return home</a></div></section>",
        )
    return render_account_page("delete_account", "Delete Account", current_user=user)


