@webhook_app.route("/dashboard", methods=["GET"])
def dashboard_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next="/dashboard"))
    fresh_user = load_account_by_id(user["user_id"]) or user
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        try:
            mission_control = pulse_dashboard_mission_control.build_mission_control_dashboard(
                conn,
                fresh_user,
                session_admin=admin_current_user(),
                include_details=False,
            )
        except Exception as exc:
            trace_id = getattr(g, "performance_trace_id", "") or secrets.token_hex(6)
            logging.exception(
                "DASHBOARD_RENDER_RECOVERY trace_id=%s user_id=%s path=%s error=%s",
                trace_id,
                fresh_user.get("user_id"),
                request.path,
                exc.__class__.__name__,
            )
            response = render_dashboard_recovery_page(trace_id)
            response.headers["Cache-Control"] = "no-store, max-age=0"
            return response
    finally:
        conn.close()
    response = webhook_app.make_response(render_template("dashboard.html", mission_control=mission_control, current_user=fresh_user))
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


def render_dashboard_recovery_page(trace_id):
    safe_trace = clean_html(trace_id or secrets.token_hex(6))
    body = f"""<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
  <meta name="robots" content="noindex,nofollow">
  <title>PulseSoc Dashboard Safe Mode</title>
  <style>
    :root{{color-scheme:dark;--bg:#030811;--panel:#081625;--line:rgba(110,223,246,.25);--text:#f2fbff;--muted:#9fb5c0;--green:#36e58f;--cyan:#6edff6}}
    *{{box-sizing:border-box}}body{{margin:0;min-height:100dvh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 20% 0,rgba(54,229,143,.2),transparent 28rem),linear-gradient(145deg,#030811,#07172a);font-family:Inter,system-ui,sans-serif;color:var(--text)}}
    main{{width:min(100%,640px);border:1px solid var(--line);border-radius:20px;background:linear-gradient(180deg,rgba(8,22,37,.96),rgba(4,11,20,.92));padding:24px;box-shadow:0 24px 90px rgba(0,0,0,.32)}}
    h1{{margin:0 0 8px;font-size:clamp(28px,6vw,44px);line-height:1}}p{{color:var(--muted);line-height:1.5}}.actions{{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}}
    a,button{{min-height:44px;border-radius:12px;border:1px solid var(--line);padding:10px 14px;font-weight:900;text-decoration:none;cursor:pointer}}
    a.primary{{background:linear-gradient(135deg,var(--green),var(--cyan));color:#06101b;border-color:transparent}}a.secondary,button{{background:rgba(110,223,246,.08);color:var(--text)}}.trace{{font-size:12px;color:#7f96a6}}
  </style>
</head>
<body>
  <main role="alert">
    <h1>Dashboard safe mode</h1>
    <p>PulseSoc kept you signed in. Try Dashboard again or open PulseSoc while the dashboard shell recovers.</p>
    <p class="trace">Trace ID: {safe_trace}</p>
    <div class="actions">
      <a class="primary" href="/pulse">Open PulseSoc</a>
      <a class="secondary" href="/dashboard">Retry Dashboard</a>
      <a class="secondary" href="/logout">Sign Out</a>
    </div>
  </main>
</body>
</html>"""
    return Response(body, status=200, mimetype="text/html")


