def _crypto_api_user_conn():
    user = api_account_user()
    if not user:
        return None, None, api_error("Login required.", 401)
    fresh_user = load_account_by_id(user["user_id"]) or user
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        dashboard_crypto_command_center.ensure_tables(conn)
    except Exception:
        conn.close()
        raise
    return fresh_user, conn, None


def _crypto_api_payload():
    if request.is_json:
        return request.get_json(silent=True) or {}
    return dict(request.form or {})


def _crypto_api_result(callback):
    correlation_id = secrets.token_hex(6)
    conn = None
    try:
        user, conn, error = _crypto_api_user_conn()
        if error:
            return error
        return jsonify(callback(conn, user))
    except ValueError as exc:
        if conn is not None:
            conn.rollback()
        return api_error(str(exc), 400)
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.exception(
            "CRYPTO_API_REQUEST_FAILED correlation_id=%s path=%s method=%s error=%s",
            correlation_id,
            request.path,
            request.method,
            exc,
        )
        return jsonify({
            "ok": False,
            "error": "crypto_request_failed",
            "message": "Crypto alerts are temporarily unavailable. Please try again.",
            "correlation_id": correlation_id,
        }), 503
    finally:
        if conn is not None:
            conn.close()


