@webhook_app.route("/dashboard/account", methods=["GET"])
def dashboard_account_command_page():
    init_db()
    user, state = _dashboard_account_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    intelligence = state.get("intelligence") or {}
    metric_cards = "".join(
        f"<article class='account-command-card'><strong>{clean_html(label)}</strong><div class='account-command-metric'>{clean_html(str(value))}</div></article>"
        for label, value in (
            ("Trust Score", f"{int(intelligence.get('trust_score') or 0)}%"),
            ("Account Score", f"{int(intelligence.get('account_score') or 0)}%"),
            ("Security Score", f"{int(intelligence.get('security_score') or 0)}%"),
            ("Profile Completion", f"{int(intelligence.get('profile_completion') or 0)}%"),
            ("Risk Level", intelligence.get("risk_level") or "Low"),
            ("Active Sessions", intelligence.get("active_sessions") or 0),
            ("Trusted Devices", intelligence.get("trusted_devices") or 0),
            ("Active Alerts", intelligence.get("active_alerts") or 0),
        )
    )
    recs = "".join(f"<li>{clean_html(item)}</li>" for item in intelligence.get("recommended_next_actions") or [])
    subsystem_cards = "".join(_account_subsystem_card_html(item) for item in (state.get("subsystems") or {}).values())
    events = "".join(
        f"<tr><td>{clean_html(item.get('action') or '')}</td><td>{clean_html(item.get('target_type') or '')}</td><td>{clean_html(item.get('created_at') or '')}</td></tr>"
        for item in state.get("recent_events") or []
    )
    body = f"""
    <section class="account-command-grid">{metric_cards}</section>
    <section class="account-command-card"><strong>Recommended next actions</strong><ul class="account-command-list">{recs}</ul></section>
    <section class="account-command-grid">{subsystem_cards}</section>
    <section class="account-command-card">
      <strong>Recent safe timeline</strong>
      <table class="account-command-table"><tr><th>Action</th><th>Target</th><th>Time</th></tr>{events or '<tr><td colspan="3">No recent owner-visible account events.</td></tr>'}</table>
    </section>
    """
    return dashboard_account_shell("Account Intelligence", "Readiness, risk, recommendations, protection, and recovery in one secure account view.", body)


@webhook_app.route("/dashboard/account/<subsystem_key>", methods=["GET"])
def dashboard_account_subsystem_page(subsystem_key):
    normalized = str(subsystem_key or "").strip().lower().replace("_", "-")
    key = normalized.replace("-", "_")
    aliases = {"health": "account_health", "advanced_security": "advanced_security"}
    key = aliases.get(key, key)
    if key not in dashboard_account_command_center.ACCOUNT_SUBSYSTEM_MAP:
        return dashboard_account_command_page()
    if key in {"profile", "verification", "account_health", "security", "settings"}:
        # Existing fully wired pages own the primary form/action workflows.
        if key == "profile":
            return dashboard_account_profile_page()
        if key == "verification":
            return dashboard_account_verification_page()
        if key == "account_health":
            return dashboard_account_health_page()
        if key == "security":
            return dashboard_account_security_page()
        if key == "settings":
            return dashboard_account_settings_page()
    init_db()
    user, state = _dashboard_account_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    subsystem = (state.get("subsystems") or {}).get(key)
    if not subsystem:
        return dashboard_account_command_page()
    return dashboard_account_shell(
        clean_html(subsystem.get("label") or "Account Subsystem"),
        "Account guidance, protection, recovery, and owner-visible signals.",
        _account_subsystem_detail_html(subsystem),
    )


