def _crypto_alert_create_script():
    return """
    (()=>{const form=document.getElementById('cryptoAlertForm');if(!form)return;const params=new URLSearchParams(location.search);if(params.get('asset'))form.assetSymbol.value=params.get('asset');form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);const payload={assetSymbol:fd.get('assetSymbol'),condition:fd.get('condition'),targetValue:Number(fd.get('targetValue')),note:fd.get('note'),notifyPush:fd.has('notifyPush'),notifyEmail:fd.has('notifyEmail'),notifySMS:fd.has('notifySMS'),notifyInApp:fd.has('notifyInApp')};const r=await fetch('/api/crypto/alerts',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const d=await r.json();document.getElementById('cryptoAlertResult').textContent=d.message||d.error||'Alert request finished.';if(d.ok)location.assign('/dashboard/crypto/alerts');});})();
    """


def _crypto_alert_script():
    return """
    (() => {
      const qs = new URLSearchParams(location.search);
      const highlightId = qs.get('alert_id') || qs.get('alert');
      if (highlightId) {
        const card = document.getElementById(`crypto-alert-${CSS.escape(highlightId)}`);
        if (card) {
          card.classList.add('is-highlighted');
          setTimeout(() => card.scrollIntoView({block: 'center', behavior: 'smooth'}), 80);
        }
      }
      const requestJson = async (url, options = {}) => {
        const response = await fetch(url, {
          credentials: 'same-origin',
          headers: {'Content-Type': 'application/json', ...(options.headers || {})},
          ...options
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || data.ok === false) throw new Error(data.message || data.error || 'Alert action failed.');
        return data;
      };
      const setBusy = (button, busy) => {
        if (!button) return;
        button.disabled = Boolean(busy);
        button.dataset.busy = busy ? '1' : '0';
      };
      const editAlert = async (button, id) => {
        const currentSymbol = button.dataset.alertSymbol || 'BTC';
        const currentCondition = button.dataset.alertCondition || 'above';
        const currentTarget = button.dataset.alertTarget || '';
        const symbol = prompt('Asset symbol', currentSymbol);
        if (symbol === null) return;
        const condition = prompt('Condition: above, below, moves_up_percent, moves_down_percent, volatility_above', currentCondition);
        if (condition === null) return;
        const targetValue = prompt('Target value', currentTarget);
        if (targetValue === null) return;
        await requestJson(`/api/crypto/alerts/${encodeURIComponent(id)}`, {
          method: 'PATCH',
          body: JSON.stringify({assetSymbol: symbol, condition, targetValue: Number(targetValue)})
        });
        location.reload();
      };
      const loadHistory = async (id) => {
        const panel = document.getElementById(`crypto-alert-history-${id}`);
        if (!panel) return;
        panel.classList.toggle('is-open');
        if (!panel.classList.contains('is-open')) return;
        panel.textContent = 'Loading trigger history...';
        try {
          const data = await requestJson(`/api/crypto/alerts/${encodeURIComponent(id)}/history`);
          const events = data.events || [];
          panel.innerHTML = events.length ? events.map(event => {
            const observed = event.observed_value == null ? 'Unavailable' : event.observed_value;
            const status = event.delivery_status || event.status || 'recorded';
            return `<div class="crypto-alert-history-item"><strong>${event.created_at || ''}</strong><br>${event.symbol || ''} ${event.condition || ''} target ${event.threshold_value || ''}, observed ${observed}.<br><small>${status}</small></div>`;
          }).join('') : '<p class="crypto-command-muted">No trigger history yet.</p>';
        } catch (error) {
          panel.textContent = error.message || 'History could not load.';
        }
      };
      document.addEventListener('click', async event => {
        const button = event.target.closest('[data-alert-action]');
        if (!button || button.dataset.busy === '1') return;
        const action = button.dataset.alertAction;
        const id = button.dataset.alertId;
        if (!id) return;
        try {
          setBusy(button, true);
          if (action === 'history') {
            await loadHistory(id);
            return;
          }
          if (action === 'edit') {
            await editAlert(button, id);
            return;
          }
          if (action === 'delete') {
            if (!confirm('Delete this alert? It will stop future triggers.')) return;
            await requestJson(`/api/crypto/alerts/${encodeURIComponent(id)}`, {method: 'DELETE'});
            location.reload();
            return;
          }
          if (action === 'duplicate') {
            await requestJson(`/api/crypto/alerts/${encodeURIComponent(id)}/duplicate`, {method: 'POST'});
            location.reload();
            return;
          }
          const status = action === 'pause' ? 'paused' : action === 'resume' ? 'active' : '';
          if (!status) return;
          await requestJson(`/api/crypto/alerts/${encodeURIComponent(id)}`, {method: 'PATCH', body: JSON.stringify({status})});
          location.reload();
        } catch (error) {
          alert(error.message || 'Alert action failed.');
        } finally {
          setBusy(button, false);
        }
      });
    })();
    """


def _crypto_watchlist_script():
    return """
    (()=>{const create=document.getElementById('cryptoWatchlistForm');if(create){create.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(create);const r=await fetch('/api/crypto/watchlists',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({name:fd.get('name')})});const d=await r.json();if(!d.ok)alert(d.message||'Watchlist failed.');location.reload();});}document.querySelectorAll('.js-watchlist-asset').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);const id=form.dataset.watchlistId;const r=await fetch(`/api/crypto/watchlists/${id}/assets`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({assetSymbol:fd.get('assetSymbol'),notes:fd.get('notes')})});const d=await r.json();if(!d.ok)alert(d.message||'Asset add failed.');location.reload();}));document.addEventListener('click',async e=>{const b=e.target.closest('[data-watchlist-action=\"remove\"]');if(!b)return;const r=await fetch(`/api/crypto/watchlists/${b.dataset.watchlistId}/assets/${b.dataset.assetId}`,{method:'DELETE',credentials:'same-origin'});const d=await r.json();if(!d.ok)alert(d.message||'Remove failed.');location.reload();});})();
    """


def _crypto_ai_script():
    return """
    (()=>{const form=document.getElementById('cryptoAiForm');if(!form)return;const enabled=form.dataset.cryptoAiEnabled==='1';const result=document.getElementById('cryptoAiResult');const esc=s=>String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));if(!enabled)return;document.querySelectorAll('[data-prompt]').forEach(b=>b.addEventListener('click',()=>{form.question.value=b.dataset.prompt;form.question.focus();}));form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;if(result)result.textContent='Checking Crypto AI availability...';try{const r=await fetch('/api/crypto/ask',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({question:fd.get('question'),asset:fd.get('asset')})});const d=await r.json();if(!r.ok||d.ok===false){if(result)result.textContent=d.message||'Crypto AI is unavailable.';return;}if(result){result.innerHTML=`<strong>${esc(d.status_label||d.state||'Crypto AI')}</strong><p>${esc(d.analysis)}</p><p><strong>Risk note:</strong> ${esc(d.risk_note)}</p><p>${esc(d.disclaimer)}</p>`;}}catch(err){if(result)result.textContent=err.message||'Crypto AI is unavailable.';}finally{if(submit)submit.disabled=false;}});})();
    """


def _crypto_token_scan_script():
    return """
    (()=>{const form=document.getElementById('cryptoTokenForm');if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);const r=await fetch('/api/crypto/token-scan',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({symbol:fd.get('symbol'),contract:fd.get('contract')})});const d=await r.json();document.getElementById('cryptoTokenResult').textContent=d.ok?`${d.symbol} risk score ${d.risk_score}/100. ${d.warnings.join(' ')}`:(d.message||'Scan failed.');});})();
    """


