@webhook_app.route("/dashboard/economy/<subsystem_key>", methods=["GET"])
def dashboard_economy_subsystem_page(subsystem_key):
    init_db()
    user, state = _dashboard_economy_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    key = (subsystem_key or "").strip().lower().replace("_", "-")
    fresh_user = load_account_by_id(user["user_id"]) or user
    if key == "seller-tools":
        conn = db()
        conn.row_factory = sqlite3.Row
        try:
            seller_state = pulsesoc_dashboard_centers.build_seller_tools(conn, fresh_user)
        finally:
            conn.close()
        return dashboard_economy_shell(
            "Seller Tools",
            "Store setup, products, readiness, inventory, orders, customers, finance, compliance, and AI seller guidance without fabricated commerce data.",
            _seller_tools_html(seller_state),
            _ps_center_script(),
        )
    if key == "subscriptions":
        conn = db()
        conn.row_factory = sqlite3.Row
        try:
            subscription_state = pulsesoc_dashboard_centers.build_subscriptions(conn, fresh_user)
        finally:
            conn.close()
        subscription_state["subscription_status_payload"] = subscription_status_payload(fresh_user)
        return dashboard_economy_shell(
            "Manage Subscriptions",
            "Plan, billing, access, failed-payment, invoice, notification, and entitlement controls with protected billing boundaries.",
            _subscriptions_html(subscription_state),
            _subscriptions_script(),
        )
    if key == "premium":
        conn = db()
        conn.row_factory = sqlite3.Row
        try:
            premium_state = pulsesoc_dashboard_centers.build_premium_center(conn, fresh_user)
        finally:
            conn.close()
        return dashboard_economy_shell(
            "Premium Center",
            "Premium access, benefit exploration, plans, usage, Founder status, labs, support, and billing handoff with entitlement-safe state.",
            _premium_center_html(premium_state),
            _ps_center_script(),
        )
    subsystem = dashboard_economy_command_center.SUBSYSTEMS_BY_KEY.get(key)
    if not subsystem:
        return redirect("/dashboard/economy")
    current = (state.get("subsystems") or {}).get(key.replace("-", "_"))
    if not current:
        current = dashboard_economy_command_center.state_for_widget(state, subsystem.get("widget_key") or "") or dict(subsystem)
    body = _economy_subsystem_detail_html(current)
    return dashboard_economy_shell(
        clean_html(current.get("label") or "Economy Subsystem"),
        "Financial guidance, automation, protection, recovery, and owner-visible signals.",
        body,
    )


