@webhook_app.route("/dashboard/ai/<subsystem_key>", methods=["GET"])
def dashboard_ai_subsystem_page(subsystem_key):
    init_db()
    user, state = _dashboard_ai_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    key = (subsystem_key or "").strip().lower().replace("_", "-")
    subsystem = dashboard_ai_command_center.SUBSYSTEMS_BY_KEY.get(key)
    if not subsystem:
        return redirect("/dashboard/ai")
    current = (state.get("subsystems") or {}).get(key.replace("-", "_"))
    if not current:
        current = dashboard_ai_command_center.state_for_widget(state, subsystem.get("widget_key") or "") or dict(subsystem)
    body = _ai_subsystem_detail_html(current)
    return dashboard_ai_shell(
        clean_html(current.get("label") or "PulseSoc AI"),
        "Owner-scoped intelligence, automation, protection, recovery, and audited AI operations.",
        body,
    )


