@webhook_app.route("/dashboard/network/notifications", methods=["GET"])
def dashboard_network_notifications_page():
    init_db()
    user, state = _dashboard_network_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    data = state.get("notifications") or {}
    metrics = state.get("metrics") or {}
    body = f"""
    <section class="network-command-grid">
      <article class="network-command-card"><strong>Unread</strong><p class="network-command-metric">{int(data.get('unread') or 0)}</p><small>General alerts only. Messenger unread counts stay separate.</small></article>
      <article class="network-command-card"><strong>Visible Records</strong><p class="network-command-metric">{int(data.get('visible') or 0)}</p><small>Read, unread, archived, and delivered notification records.</small></article>
      <article class="network-command-card"><strong>Delivery Health</strong><p class="network-command-metric">{int(metrics.get('delivery_health_score') or 100)}%</p><small>Alert reliability for this account.</small></article>
    </section>
    <section class="network-command-card">
      <strong>Notification controls</strong>
      <p class="network-command-muted">Open the full Notification Center to inspect alerts, mark read, delete, archive, and use deep links.</p>
      <div class="network-command-actions">
        <a class="button primary" href="/pulse/notifications">Manage Notifications</a>
        <a class="button" href="/pulse/settings/notifications">Notification Settings</a>
        <button data-network-mark-all-read>Mark All Read</button>
      </div>
    </section>
    """
    script = """
    document.addEventListener('click', async event => {
      const button = event.target.closest('[data-network-mark-all-read]');
      if (!button) return;
      button.disabled = true;
      try {
        const response = await fetch('/api/pulse/notifications/read-all', {method:'POST', credentials:'same-origin', headers:{'Content-Type':'application/json'}});
        const data = await response.json().catch(()=>({}));
        if (!response.ok || data.ok === false) throw new Error(data.message || 'Could not mark notifications read.');
        location.reload();
      } catch (error) {
        alert(error.message || 'Could not mark notifications read.');
      } finally {
        button.disabled = false;
      }
    });
    """
    return dashboard_network_shell("Notifications Command", "Unread state, preferences, delivery status, and deep-link controls.", body, script)


