@webhook_app.route("/dashboard/network/<subsystem_key>", methods=["GET"])
def dashboard_network_subsystem_page(subsystem_key):
    init_db()
    user, state = _dashboard_network_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    raw_key = str(subsystem_key or "").strip().lower()
    normalized = raw_key.replace("-", "_")
    aliases = {
        "messages": "messenger",
        "push_delivery": "delivery_intelligence",
        "blocks_mutes": "network_security",
        "bans": "network_security",
        "message_health": "messenger",
        "audit": "network_health",
    }
    key = aliases.get(normalized, normalized)
    subsystem = (state.get("subsystems") or {}).get(key) or (state.get("subsystems") or {}).get(raw_key)
    if not subsystem:
        return redirect("/dashboard/network")
    return dashboard_network_shell(
        clean_html(subsystem.get("label") or "Network Intelligence"),
        clean_html(subsystem.get("description") or "PulseSoc network subsystem."),
        _network_subsystem_detail_html(subsystem),
    )


