@webhook_app.route("/dashboard/creator/<subsystem_key>", methods=["GET"])
def dashboard_creator_subsystem_page(subsystem_key):
    init_db()
    user, state = _dashboard_creator_state_for_current_user()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    raw_key = str(subsystem_key or "").strip().lower()
    normalized = raw_key.replace("-", "_")
    aliases = {
        "my_posts": "posts",
        "stories": "statuses",
        "live": "live_studio",
        "live_studio": "live_studio",
        "audience_analytics": "audience_intelligence",
        "analytics": "content_performance",
        "media_health": "videos",
        "moderation": "creator_reputation",
        "audit": "creator_score",
    }
    key = aliases.get(normalized, normalized)
    if key in {"content_planner", "post_scheduler", "draft_studio", "ai_creator_assistant"}:
        fresh_user = load_account_by_id(user["user_id"]) or user
        conn = db()
        conn.row_factory = sqlite3.Row
        try:
            if key == "content_planner":
                center_state = pulsesoc_dashboard_centers.build_content_planner(conn, fresh_user)
                title = "Content Planner"
                subtitle = "Plan, draft, schedule, organize, and review creator content with backend-owned checklist state."
                body = _content_planner_html(center_state)
            elif key == "post_scheduler":
                center_state = pulsesoc_dashboard_centers.build_post_scheduler(conn, fresh_user)
                title = "Post Scheduler"
                subtitle = "Schedule owned drafts with validation, queue review, and safe unavailable states for unsupported scheduler features."
                body = _post_scheduler_html(center_state)
            elif key == "draft_studio":
                center_state = pulsesoc_dashboard_centers.build_draft_studio(conn, fresh_user)
                title = "Draft Studio"
                subtitle = "Create and manage private drafts with persisted checklist state and publish-safe validation."
                body = _draft_studio_html(center_state)
            else:
                center_state = pulsesoc_dashboard_centers.build_ai_creator_assistant(conn, fresh_user)
                title = "AI Creator Assistant"
                subtitle = "Creator-focused AI readiness, privacy review, and safe disabled AI actions until a live endpoint is available."
                body = _ai_creator_assistant_html(center_state)
        finally:
            conn.close()
        return dashboard_creator_shell(
            title,
            subtitle,
            body,
            _ps_center_script(),
        )
    subsystem = (state.get("subsystems") or {}).get(key)
    if not subsystem:
        return redirect("/dashboard/creator")
    return dashboard_creator_shell(
        clean_html(subsystem.get("label") or "Creator Intelligence"),
        clean_html(subsystem.get("description") or "PulseSoc creator subsystem."),
        _creator_subsystem_detail_html(subsystem),
    )


