@webhook_app.route("/api/dashboard/account/settings", methods=["GET", "POST"])
def api_dashboard_account_settings():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        if request.method == "GET":
            settings = dashboard_account_command_center.get_settings(conn, int(user["user_id"]))
            return jsonify({"ok": True, "settings": settings})
        payload = request.get_json(silent=True) or {}
        result = dashboard_account_command_center.update_settings(conn, int(user["user_id"]), payload, int(user["user_id"]))
        return jsonify({"ok": True, "message": "Settings saved.", "settings": result.get("settings")})
    except ValueError as exc:
        conn.rollback()
        return api_error(str(exc), 400)
    finally:
        conn.close()


