def _account_verification_file_allowed(file_storage):
    filename = getattr(file_storage, "filename", "") or ""
    stream = getattr(file_storage, "stream", None)
    if not stream:
        return False, "Verification document upload is invalid.", {}
    try:
        pos = stream.tell()
    except Exception:
        pos = 0
    head = stream.read(512)
    stream.seek(0, os.SEEK_END)
    size = stream.tell()
    stream.seek(pos)
    if size <= 0 or size > 8 * 1024 * 1024:
        return False, "Verification documents must be between 1 byte and 8 MB.", {}
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    mime_type = (getattr(file_storage, "mimetype", "") or "").lower()
    image_signatures = (
        head.startswith(b"\xff\xd8\xff"),
        head.startswith(b"\x89PNG\r\n\x1a\n"),
        head.startswith(b"RIFF") and b"WEBP" in head[:16],
    )
    if ext in {"jpg", "jpeg"} and image_signatures[0] and mime_type in {"image/jpeg", "image/jpg", ""}:
        return True, "", {"file_size": size, "mime_type": "image/jpeg"}
    if ext == "png" and image_signatures[1] and mime_type in {"image/png", ""}:
        return True, "", {"file_size": size, "mime_type": "image/png"}
    if ext == "webp" and image_signatures[2] and mime_type in {"image/webp", ""}:
        return True, "", {"file_size": size, "mime_type": "image/webp"}
    if ext == "pdf" and head.startswith(b"%PDF") and mime_type in {"application/pdf", ""}:
        return True, "", {"file_size": size, "mime_type": "application/pdf"}
    return False, "Upload a valid JPG, PNG, WEBP, or PDF document.", {}


@webhook_app.route("/api/dashboard/account/verification/document", methods=["POST"])
def api_dashboard_account_verification_document():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    file_storage = request.files.get("file")
    if not file_storage or not getattr(file_storage, "filename", ""):
        return api_error("Choose a verification document.", 400)
    ok, message, meta = _account_verification_file_allowed(file_storage)
    if not ok:
        return api_error(message, 400)
    document_type = clean_html(request.form.get("document_type") or "government_id")[:80]
    if document_type not in {"government_id", "business_document", "selfie"}:
        return api_error("Choose a valid document type.", 400)
    request_id = safe_int(request.form.get("request_id"), 0)
    storage_dir = os.path.join(webhook_app.instance_path, "private_uploads", "account_verification", str(int(user["user_id"])))
    os.makedirs(storage_dir, exist_ok=True)
    safe_name = re.sub(r"[^A-Za-z0-9_.-]", "_", os.path.basename(file_storage.filename or "document"))[:80]
    stored_name = f"{datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(8)}_{safe_name}"
    storage_path = os.path.join(storage_dir, stored_name)
    file_storage.save(storage_path)
    checksum = hashlib.sha256(open(storage_path, "rb").read()).hexdigest()
    conn = db()
    try:
        dashboard_account_command_center.ensure_schema(conn)
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO verification_documents
            (request_id, user_id, document_type, storage_path, original_filename, mime_type, file_size, checksum, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (request_id, int(user["user_id"]), document_type, storage_path, safe_name, meta.get("mime_type") or "", meta.get("file_size") or 0, checksum, datetime.utcnow().isoformat(timespec="seconds")),
        )
        dashboard_account_command_center.record_account_audit(conn, user_id=int(user["user_id"]), actor_user_id=int(user["user_id"]), action="verification_document_uploaded", target_type="verification_document", details={"document_type": document_type, "request_id": request_id, "file_size": meta.get("file_size")})
        conn.commit()
    finally:
        conn.close()
    return jsonify({"ok": True, "message": "Verification document uploaded for private review.", "document_type": document_type})


@webhook_app.route("/admin/account-command", methods=["GET"])
def admin_account_command_page():
    admin, denied = require_admin_page("users.manage")
    if denied:
        return denied
    init_db()
    conn = db()
