    profile_logs = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT vr.*, COALESCE(u.email,'') AS email, COALESCE(u.display_name,u.username,'User') AS name FROM verification_requests vr LEFT JOIN users u ON u.user_id=vr.user_id ORDER BY COALESCE(vr.updated_at,vr.created_at) DESC, vr.id DESC LIMIT 80")
