@webhook_app.route("/billing/portal", methods=["GET"])
def billing_portal_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next="/billing/portal"))
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=False)
