@webhook_app.route("/api/subscriptions/checklist", methods=["POST"])
def api_subscriptions_checklist():
    init_db()
    write_error = _subscription_action_requires_write()
    if write_error:
        return write_error
    user, auth_error = _subscription_action_user()
    if auth_error:
        return auth_error
    payload = request.get_json(silent=True) or {}
    key = str(payload.get("key") or "").strip()
    allowed = {"subscription_benefits_reviewed", "billing_history_reviewed", "cancellation_policy_reviewed"}
    if key not in allowed:
        return _subscription_json_response({"ok": False, "message": "Unsupported subscription checklist item."}, 400)
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        result = pulsesoc_dashboard_centers.save_pref(conn, user, key, "true" if str(payload.get("value") or "true").lower() != "false" else "false")
    finally:
        conn.close()
    if result.get("ok"):
        log_product_event(user["user_id"], "subscription_checklist_saved", {"key": key})
    return _subscription_json_response(result, 200 if result.get("ok") else 400)


