@webhook_app.route("/api/subscriptions/cancel", methods=["POST"])
def api_subscriptions_cancel():
    init_db()
    write_error = _subscription_action_requires_write()
    if write_error:
        return write_error
    user, auth_error = _subscription_action_user()
    if auth_error:
        return auth_error
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    subscription_id = _subscription_provider_subscription_id(user) or (_latest_user_subscription_row(user.get("user_id")).get("stripe_subscription_id") or "")
    if not STRIPE_SECRET_KEY:
        return _subscription_json_response({"ok": False, "message": "Billing portal not configured"}, 503)
    if not subscription_id:
        return _subscription_json_response({"ok": False, "message": "No provider subscription is connected to cancel."}, 409)
    try:
        stripe.api_key = STRIPE_SECRET_KEY
        updated = stripe.Subscription.modify(subscription_id, cancel_at_period_end=True)
        try:
            sync_stripe_subscription(dict(updated))
        except Exception:
            logging.info("SUBSCRIPTION_CANCEL_SYNC_SKIPPED user_id=%s", user.get("user_id"))
        log_product_event(user["user_id"], "subscription_cancel_at_period_end", {"provider": "stripe"})
        return _subscription_json_response({"ok": True, "message": "Subscription cancellation was scheduled at the provider."})
    except Exception as exc:
        error = safe_stripe_error(exc)
        logging.exception("SUBSCRIPTION_CANCEL_FAILED user_id=%s error=%s", user.get("user_id"), error)
        return _subscription_json_response({"ok": False, "message": error or "Subscription cancellation failed."}, 502)


