@webhook_app.route("/pulse/premium/success", methods=["GET"])
def pulse_premium_success_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.full_path))
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=False)
    session_id = clean_html(request.args.get("session_id", ""))[:180]
    status = subscription_status_payload(load_account_by_id(user["user_id"]) or user)
    is_active = bool(status.get("has_premium_access") or premium_entitlement_service.is_founder_member(user["user_id"]))
    body = f"""
    <section class='card premium-promo-card' data-premium-success>
      <span class='premium-badge'>Founder Checkout</span>
      <h2>{'Founder Premium is active.' if is_active else 'Checkout returned to PulseSoc.'}</h2>
      <p data-premium-success-message>{'Your backend subscription record is active.' if is_active else 'Stripe verification is still in progress. Founder/Premium access appears after the verified webhook updates your account.'}</p>
      <p class='muted'>This page never grants access from the URL alone. Server-side Stripe confirmation controls Premium state.</p>
      <p class='muted'>Session: {clean_html(session_id) if session_id else 'pending webhook confirmation'}</p>
      <div class='actions'>
        <a class='button primary' href='/pulse/premium'>Back to Premium</a>
        <a class='button' href='/pulse/profile'>Profile</a>
        <a class='button' href='/pulse'>Home</a>
        <a class='button' href='/billing/portal'>Billing</a>
      </div>
    </section>
    """
    script = """
    (() => {
      const box = document.querySelector('[data-premium-success]');
      const message = document.querySelector('[data-premium-success-message]');
      if (!box || !message) return;
      let attempts = 0;
      async function refreshPremiumStatus(){
        attempts += 1;
        try {
          const data = await pulseApi('/api/premium/status');
          if (data.founder_active || data.premium_active) {
            box.querySelector('h2').textContent = data.founder_active && data.founder_number ? `Founder Premium #${data.founder_number} is active.` : 'PulseSoc Premium is active.';
            message.textContent = data.message || 'Your backend subscription record is active.';
            toast('Premium status confirmed.');
            return;
          }
          message.textContent = data.message || 'Stripe verification is still pending. This page will keep checking briefly.';
          if (attempts < 8) window.setTimeout(refreshPremiumStatus, 2500);
        } catch (err) {
          message.textContent = err.message || 'Premium status could not be checked. Return to Premium to refresh.';
          if (attempts < 4) window.setTimeout(refreshPremiumStatus, 3000);
        }
      }
      refreshPremiumStatus();
    })();
    """
    return pulse_social_shell("Founder Checkout", "Founder checkout is being verified safely by Stripe webhook.", body, "", script)


@webhook_app.route("/pulse/premium/cancel", methods=["GET"])
def pulse_premium_cancel_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next="/pulse/premium"))
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=False)
    body = """
    <section class='card premium-promo-card'>
      <span class='premium-badge'>Checkout canceled</span>
      <h2>No changes were made.</h2>
      <p>Checkout canceled. You can activate Founder Premium anytime.</p>
      <p>No fake subscription state was created. Retry checkout only when you are ready.</p>
      <div class='actions'><button class='button primary' type='button' data-founder-checkout>Retry Founder Checkout</button><a class='button' href='/pulse/premium'>Back to Premium</a><a class='button' href='/pulse'>Explore Free PulseSoc</a></div>
    </section>
    """
    script = """
    document.addEventListener('click', async event => {
      const button = event.target.closest('[data-founder-checkout]');
      if (!button) return;
      button.disabled = true;
      const original = button.textContent;
      button.textContent = 'Opening Stripe...';
      try {
        const data = await pulseApi('/api/premium/checkout', {method:'POST', body: JSON.stringify({plan_key:'founder_premium', source:'premium_cancel_retry'})});
        const url = data.url || data.checkout_url;
        if (url) {
          window.location.assign(url);
          return;
        }
        toast(data.message || 'Checkout is not ready yet.');
      } catch (err) {
        toast(err.message || 'Checkout is not ready yet.');
      } finally {
        button.disabled = false;
        button.textContent = original;
      }
    });
    """
    return pulse_social_shell("Founder Checkout Canceled", "No billing changes were made.", body, "", script)


