@webhook_app.route("/api/billing/confirm-session", methods=["POST"])
def api_billing_confirm_session():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    if not STRIPE_SECRET_KEY:
        logging.error("STRIPE_SESSION_CONFIRM_CONFIG_ERROR user_id=%s reason=missing_secret", user.get("user_id"))
        return jsonify({"ok": False, "message": "Stripe is not configured. Contact support."}), 503
    payload = request.get_json(silent=True) or request.form or {}
    session_id = clean_html(payload.get("session_id") or request.args.get("session_id") or "")[:180]
    if not session_id or not session_id.startswith("cs_"):
        return jsonify({"ok": False, "message": "Missing checkout session."}), 400
    try:
        stripe.api_key = STRIPE_SECRET_KEY
        logging.info("STRIPE_SESSION_RETRIEVE_START user_id=%s session_id=%s", user.get("user_id"), session_id)
        session_obj = stripe.checkout.Session.retrieve(session_id, expand=["subscription"])
        logging.info("STRIPE_SESSION_RETRIEVED user_id=%s session_id=%s payment_status=%s", user.get("user_id"), session_id, stripe_object_get(session_obj, "payment_status", ""))
    except Exception as exc:
        logging.exception("STRIPE_SESSION_RETRIEVE_FAILED user_id=%s session_id=%s error=%s", user.get("user_id"), session_id, safe_stripe_error(exc))
        return jsonify({"ok": False, "message": "Could not confirm Stripe session yet."}), 502
    resolved_user_id, _ = resolve_checkout_session_user(session_obj)
    if resolved_user_id and int(resolved_user_id) != int(user["user_id"]):
        logging.warning("STRIPE_SESSION_CONFIRM_FORBIDDEN session_id=%s session_user=%s current_user=%s", session_id, resolved_user_id, user.get("user_id"))
        return jsonify({"ok": False, "message": "This payment belongs to a different account."}), 403
    result = activate_pro_from_stripe_session(session_obj, event_id=f"session_confirm_{session_id}", source="success_page")
    status_code = 200 if result.get("ok") else 400
    return jsonify(result), status_code


@webhook_app.errorhandler(405)
def friendly_method_not_allowed(error):
    if request_expects_json_response():
        return api_error(
            "This upload endpoint was called with the wrong method.",
            405,
            error="method_not_allowed",
            endpoint=request.path,
            method=request.method,
        )
    init_db()
    if request.path in {"/account", "/dashboard", "/upgrade", "/checkout/success", "/upgrade/success"}:
        if require_account():
            return redirect(url_for("dashboard_page"))
        return redirect(url_for("login_page"))
    return (
        "<!doctype html><html><head><meta name='viewport' content='width=device-width, initial-scale=1'>"
        "<title>CoinPlotXAI Inc. | Page Method</title>"
        "<style>body{margin:0;font-family:system-ui;background:#050b14;color:#f2fbff;display:grid;min-height:100vh;place-items:center;padding:24px}"
        ".card{max-width:620px;border:1px solid rgba(110,223,246,.22);border-radius:16px;background:#0d1627;padding:28px;box-shadow:0 24px 80px rgba(0,0,0,.32)}"
        "a{color:#36e58f}</style></head><body><main class='card'>"
        "<h1>Let’s get you back on track.</h1>"
        "<p>That page was opened with the wrong request method. Your account is safe.</p>"
        "<p><a href='/dashboard'>Open Dashboard</a> · <a href='/login'>Login</a> · <a href='/support'>Support</a></p>"
        "</main></body></html>",
        405,
    )


@webhook_app.errorhandler(RequestEntityTooLarge)
def friendly_request_too_large(error):
    trace_id = secrets.token_hex(6)
    logging.warning(
        "HTTP_413_UPLOAD_TOO_LARGE trace_id=%s path=%s method=%s content_length=%s",
        trace_id,
        request.path,
        request.method,
        request.content_length,
    )
    if request_expects_json_response():
        return jsonify({
            "ok": False,
            "success": False,
            "message": "File too large. Choose a smaller video or photo.",
            "error": "file_too_large",
            "trace_id": trace_id,
            "endpoint": request.path,
            "method": request.method,
        }), 413
    return friendly_internal_error(error)


@webhook_app.errorhandler(500)
def friendly_internal_error(error):
    trace_id = secrets.token_hex(6)
    logging.exception("HTTP_500 trace_id=%s path=%s method=%s", trace_id, request.path, request.method)
    if request_expects_json_response():
        if request.path.startswith(("/api/pulse/messages", "/api/pulse/chatrooms")):
            logging.error(
                "PULSE_CHAT_HTTP_500 trace_id=%s endpoint=%s method=%s remote=%s",
                trace_id,
                request.path,
                request.method,
                request.headers.get("X-Forwarded-For") or request.remote_addr or "",
            )
            return jsonify({
                "ok": False,
                "success": False,
                "message": "Messenger request failed.",
                "trace_id": trace_id,
                "endpoint": request.path,
                "method": request.method,
                "retriable": True,
            }), 500
        return jsonify({
            "ok": False,
            "success": False,
            "message": "Upload failed. Please retry or contact support with this trace ID.",
            "error": "server_error",
            "trace_id": trace_id,
            "endpoint": request.path,
            "method": request.method,
            "retriable": True,
        }), 500
    body = (
        "<!doctype html><html><head><meta name='viewport' content='width=device-width, initial-scale=1'>"
        "<title>CoinPilotXAI | System Notice</title>"
        "<style>body{margin:0;font-family:system-ui;background:#050b14;color:#f2fbff;display:grid;min-height:100vh;place-items:center;padding:24px}"
        ".card{max-width:680px;border:1px solid rgba(110,223,246,.22);border-radius:16px;background:#0d1627;padding:28px;box-shadow:0 24px 80px rgba(0,0,0,.32)}"
        "a{color:#36e58f}.trace{color:#9fb5c0;font-size:13px}</style></head><body><main class='card'>"
        "<h1>PulseSoc hit a temporary system issue.</h1>"
        "<p>The team can trace this safely without exposing raw server details.</p>"
        f"<p class='trace'>Trace ID: {trace_id}</p>"
        "<p><a href='/dashboard'>Open Dashboard</a> · <a href='/pulse'>Open PulseSoc</a> · <a href='/support'>Support</a></p>"
        "</main></body></html>"
    )
    return body, 500


@webhook_app.errorhandler(Exception)
def friendly_unhandled_exception(error):
    if isinstance(error, HTTPException):
        if request_expects_json_response():
            trace_id = secrets.token_hex(6)
            code = int(getattr(error, "code", 500) or 500)
            message = "Request failed."
            error_key = "http_error"
            if code == 401:
                message = "Session expired. Please sign in and retry."
                error_key = "session_expired"
            elif code == 403:
                message = "Upload was blocked by site security. Please try again or contact support."
                error_key = "access_denied"
            elif code == 404:
                message = "Upload endpoint was not found."
                error_key = "not_found"
            elif code == 413:
                message = "File too large. Choose a smaller video or photo."
                error_key = "file_too_large"
            elif code >= 500:
                message = "Upload failed. Please retry or contact support with this trace ID."
                error_key = "server_error"
            logging.warning(
                "API_HTTP_EXCEPTION trace_id=%s status=%s path=%s method=%s description=%s",
                trace_id,
                code,
                request.path,
                request.method,
                clean_html(getattr(error, "description", "") or ""),
            )
            return jsonify({
                "ok": False,
                "success": False,
                "message": message,
                "error": error_key,
                "trace_id": trace_id,
                "endpoint": request.path,
                "method": request.method,
            }), code
        return error
    return friendly_internal_error(error)


