def owner_update_user_status(user_id, status, reason, admin):
    status = clean_html(status or "")[:40].lower()
    allowed = {"active", "restricted", "suspended", "deleted"}
    if status not in allowed:
        return {"ok": False, "error": "Invalid status."}, 400
    field = "restricted_reason" if status == "restricted" else "suspended_reason" if status == "suspended" else None
    now = datetime.now().isoformat()
    conn = db()
    cur = conn.cursor()
    if status == "deleted":
        cur.execute("UPDATE users SET account_status='deleted', access_enabled=0, login_enabled=0, deleted_at=?, updated_at=? WHERE user_id=?", (now, now, user_id))
    elif field:
        access_enabled = 0 if status == "restricted" else 1
        login_enabled = 0 if status == "restricted" else 1
        cur.execute(f"UPDATE users SET account_status=?, access_enabled=?, login_enabled=?, {field}=?, updated_at=? WHERE user_id=?", (status, access_enabled, login_enabled, reason[:500], now, user_id))
    else:
        cur.execute("UPDATE users SET account_status='active', access_enabled=1, login_enabled=1, restricted_reason='', suspended_reason='', updated_at=? WHERE user_id=?", (now, user_id))
    conn.commit()
    conn.close()
    admin_user_action(admin, user_id, f"user_status_{status}", {"reason": reason})
    return {"ok": True, "user": backend_pro_status_payload(load_account_by_id(user_id) or {})}, 200


@webhook_app.route("/api/admin/users/<int:user_id>/pro", methods=["POST"])
def api_admin_user_pro(user_id):
    admin, denied = require_owner_api()
    if denied:
        return denied
    user = load_account_by_id(user_id)
    if not user:
        return jsonify({"ok": False, "error": "User not found."}), 404
    payload = request.get_json(silent=True) or {}
    action = clean_html(payload.get("action") or "activate").lower()
    now = datetime.now().isoformat()
    conn = db()
    cur = conn.cursor()
    if action in {"activate", "pro"}:
        days = int(payload.get("days") or 365)
        expires = (datetime.now() + timedelta(days=max(1, min(days, 3650)))).isoformat()
        cur.execute(
            """
            UPDATE users SET account_status='active', plan='pro', subscription_plan='pro',
                subscription_status='active', trial_status='converted', is_pro=1,
                pro_expires_at=?, subscription_expires_at=?, updated_at=?
            WHERE user_id=?
            """,
            (expires, expires, now, user_id),
        )
        conn.commit()
        conn.close()
        payment_id = record_payment_record(user_id, stripe_event_id=f"owner_pro_{int(time.time())}_{user_id}", amount=0, currency="USD", status="succeeded", payment_type="owner_manual_pro", manual=True, metadata={"admin_id": admin.get("id"), "action": action})
        fresh = load_account_by_id(user_id) or {}
        if fresh.get("email"):
            send_platform_email(fresh.get("email"), "PulseSoc Premium Activated", "Your PulseSoc Premium access has been activated by the owner/admin.", "<p>Your PulseSoc Premium access has been activated by the owner/admin.</p>", user_id)
        admin_user_action(admin, user_id, "owner_activate_pro", {"payment_record_id": payment_id, "expires": expires})
    elif action in {"downgrade", "free", "remove"}:
        cur.execute("UPDATE users SET plan='free', subscription_plan='free', subscription_status='inactive', trial_status='', is_pro=0, pro_expires_at='', subscription_expires_at='', updated_at=? WHERE user_id=?", (now, user_id))
        conn.commit()
        conn.close()
        fresh = load_account_by_id(user_id) or {}
        admin_user_action(admin, user_id, "owner_remove_pro", {})
    elif action in {"start_trial", "extend_trial"}:
        days = int(payload.get("days") or PRO_TRIAL_DAYS)
        existing = parse_iso_datetime(user.get("trial_end_date") or user.get("pro_expires_at")) if action == "extend_trial" else None
        base = existing if existing and existing > datetime.now(existing.tzinfo) else datetime.now()
        trial_end = (base + timedelta(days=max(1, min(days, 365)))).isoformat()
        cur.execute(
            """
            UPDATE users SET account_status='active', plan='pro', subscription_plan='pro',
                subscription_status='trialing', trial_status='active', is_pro=1,
                trial_start_date=COALESCE(trial_start_date, ?), trial_end_date=?, pro_expires_at=?, updated_at=?
            WHERE user_id=?
            """,
            (now, trial_end, trial_end, now, user_id),
        )
        conn.commit()
        conn.close()
        fresh = load_account_by_id(user_id) or {}
        admin_user_action(admin, user_id, f"owner_{action}", {"trial_end_date": trial_end})
    else:
        conn.close()
        return jsonify({"ok": False, "error": "Invalid Pro action."}), 400
    return jsonify({"ok": True, "message": "User Pro status updated.", "user": backend_pro_status_payload(fresh)})


@webhook_app.route("/api/admin/users/<int:user_id>/status", methods=["POST"])
@webhook_app.route("/api/admin/users/<int:user_id>/restrict", methods=["POST"])
@webhook_app.route("/api/admin/users/<int:user_id>/delete", methods=["POST"])
@webhook_app.route("/api/admin/users/<int:user_id>/restore", methods=["POST"])
def api_admin_user_status(user_id):
    admin, denied = require_owner_api()
    if denied:
        return denied
    if not load_account_by_id(user_id):
        return jsonify({"ok": False, "error": "User not found."}), 404
    payload = request.get_json(silent=True) or {}
    if request.path.endswith("/restrict"):
        status = "restricted"
    elif request.path.endswith("/delete"):
        status = "deleted"
    elif request.path.endswith("/restore"):
        status = "active"
    else:
        status = payload.get("account_status") or payload.get("status")
    result, code = owner_update_user_status(user_id, status, clean_html(payload.get("reason") or ""), admin)
    return jsonify(result), code


def prelaunch_restriction_email_content():
    subject = "PulseSoc Early Access Update"
    text = """Hello Nathan,

Thank you for being part of PulseSoc's early access program.

PulseSoc has not officially launched to the public yet. As we continue platform development, testing, security hardening, and infrastructure preparation, access to certain early-access accounts may be temporarily restricted.

Your account is being placed into a restricted state while we prepare for public launch.

Your content and account data will remain preserved. Once broader access becomes available, additional information will be provided regarding account availability and platform access.

Thank you for your support and participation during the development phase.

— PulseSoc Team"""
    html = branded_email_html(
        subject,
        """
        <p>Hello Nathan,</p>
        <p>Thank you for being part of PulseSoc's early access program.</p>
        <p>PulseSoc has not officially launched to the public yet. As we continue platform development, testing, security hardening, and infrastructure preparation, access to certain early-access accounts may be temporarily restricted.</p>
        <p>Your account is being placed into a restricted state while we prepare for public launch.</p>
        <p>Your content and account data will remain preserved. Once broader access becomes available, additional information will be provided regarding account availability and platform access.</p>
        <p>Thank you for your support and participation during the development phase.</p>
        <p>— PulseSoc Team</p>
        """,
    )
    return subject, text, html


def prelaunch_restriction_protected_account_reasons(cur, user):
    user = user or {}
    reasons = []
    user_id = safe_int(user.get("user_id"), 0)
    email = normalize_email(user.get("email") or "")
    username = str(user.get("username") or "")
    if user_is_super_user(user) or safe_int(user.get("is_super_user"), 0):
        reasons.append("administrator")
    if email and table_exists(cur, "admin_users"):
        cur.execute("SELECT role, status FROM admin_users WHERE lower(COALESCE(email,''))=lower(?) LIMIT 1", (email,))
        admin_row = dict(cur.fetchone() or {})
        if admin_row and (admin_row.get("status") or "active").lower() != "deleted":
            role = (admin_row.get("role") or "admin").lower()
            reasons.append("moderator" if "moderator" in role else "administrator")
    if user_id and table_exists(cur, "founder_memberships"):
        cur.execute("SELECT id FROM founder_memberships WHERE user_id=? AND COALESCE(status,'active')='active' LIMIT 1", (user_id,))
        if cur.fetchone():
            reasons.append("founder")
    lowered = f"{username} {email}".lower()
    if any(token in lowered for token in ("test", "audit", "automation", "example.test", "example.com")):
        reasons.append("test automation account")
    if user_id <= 0 or email in {owner_email_value(), "support@pulsesoc.com", "security@pulsesoc.com", "noreply@pulsesoc.com"} or username.lower() in {"system", "admin", "owner", "support"}:
        reasons.append("system account")
    return sorted(set(reasons))


@webhook_app.route("/api/admin/users/<int:user_id>/prelaunch-restrict", methods=["POST"])
def api_admin_user_prelaunch_restrict(user_id):
    admin, denied = require_owner_api()
    if denied:
        return denied
    payload = request.get_json(silent=True) or {}
    expected_email = normalize_email(clean_html(payload.get("expected_email") or ""))
    confirm = clean_html(payload.get("confirm") or "")
    if confirm != "RESTRICT_USER_20_PRELAUNCH":
        return jsonify({"ok": False, "error": "Confirmation token required."}), 400
    if user_id != 20:
        return jsonify({"ok": False, "error": "This endpoint is scoped to User ID 20 only."}), 400
    if not expected_email or not is_valid_email(expected_email):
        return jsonify({"ok": False, "error": "Expected account email is required."}), 400
    user = load_account_by_id(user_id)
    if not user:
        return jsonify({"ok": False, "error": "User not found."}), 404
    actual_email = normalize_email(user.get("email") or "")
    if actual_email != expected_email:
        admin_user_action(admin, user_id, "prelaunch_restriction_email_mismatch", {"expected": mask_email(expected_email), "actual": mask_email(actual_email)})
        return jsonify({"ok": False, "error": "Expected email does not match the account record."}), 409
    trace_id = secrets.token_hex(6)
    now = datetime.utcnow().isoformat(timespec="seconds")
    account_before = {
        "user_id": user_id,
        "email": mask_email(actual_email),
        "account_status": user.get("account_status") or "active",
        "access_enabled": safe_int(user.get("access_enabled"), 1),
        "login_enabled": safe_int(user.get("login_enabled"), 1),
        "plan": user.get("plan") or "",
        "subscription_plan": user.get("subscription_plan") or "",
        "subscription_status": user.get("subscription_status") or "",
        "is_pro": safe_int(user.get("is_pro"), 0),
        "is_super_user": safe_int(user.get("is_super_user"), 0),
        "email_verified": safe_int(user.get("email_verified"), 0),
    }
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    protected_reasons = prelaunch_restriction_protected_account_reasons(cur, user)
    conn.close()
    if protected_reasons:
        admin_user_action(admin, user_id, "prelaunch_restriction_blocked_protected_account", {"reasons": protected_reasons, "account_before": account_before, "trace_id": trace_id})
        return jsonify({"ok": False, "error": "Protected account cannot be restricted by this workflow.", "reasons": protected_reasons, "trace_id": trace_id}), 403
    admin_user_action(admin, user_id, "prelaunch_restriction_attempt", {"performed_by": "Owner", "reason": "Pre-launch access restriction", "account_before": account_before, "trace_id": trace_id, "timestamp_utc": now})
    subject, text_body, html_body = prelaunch_restriction_email_content()
    result = email_service_service.send_email(
        actual_email,
        subject,
        html_body,
        text_body=text_body,
        email_type="prelaunch_access_restriction",
        user_id=user_id,
        channel="transactional",
    )
    ok = bool(result.get("ok"))
    status = email_status_from_result(result)
    message_id = result.get("message_id") or ""
    safe_error = "" if ok else safe_brevo_error_reason(result)
    log_email_status(
        user_id,
        actual_email,
        subject,
        status,
        email_type="prelaunch_access_restriction",
        provider="brevo",
        provider_status_code=result.get("status_code"),
        provider_message_id=message_id,
        safe_error_reason=safe_error,
        metadata={"trace_id": trace_id, "action": "prelaunch_restrict_user_20", "performed_by": "Owner"},
        trace_id=trace_id,
    )
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, status, provider_message_id, trace_id, delivery_status
        FROM email_logs
        WHERE user_id=? AND trace_id=? AND subject=? AND lower(COALESCE(recipient_email,email,''))=lower(?)
        ORDER BY id DESC
        LIMIT 1
        """,
        (user_id, trace_id, subject, actual_email),
    )
    email_log = dict(cur.fetchone() or {})
    delivery_verified = bool(ok and message_id and email_log and str(email_log.get("status") or "").startswith("sent") and (email_log.get("provider_message_id") or "") == message_id)
    if not delivery_verified:
        conn.close()
        admin_user_action(admin, user_id, "prelaunch_restriction_email_failed", {"email_sent": bool(ok), "delivery_verified": False, "status": status, "trace_id": trace_id, "provider_message_id_present": bool(message_id), "error": safe_error})
        log_admin_audit(admin.get("id"), "prelaunch_restriction_admin_alert", "user", str(user_id), {"severity": "high", "reason": "email_failed_no_restriction", "trace_id": trace_id, "safe_error": safe_error})
        return jsonify({"ok": False, "error": "Email delivery was not verified. Account was not restricted.", "trace_id": trace_id, "email_sent": bool(ok), "delivery_verified": False, "safe_error_reason": safe_error}), 502
    cur.execute(
        """
        UPDATE users
        SET account_status='restricted', access_enabled=0, login_enabled=0,
            restricted_reason=?, updated_at=?
        WHERE user_id=?
        """,
        ("Pre-launch access restriction", now, user_id),
    )
    conn.commit()
    conn.close()
    admin_user_action(admin, user_id, "Restrict Account", {"reason": "Pre-launch access restriction", "email_sent": True, "delivery_verified": True, "performed_by": "Owner", "timestamp_utc": now, "account_before": account_before, "trace_id": trace_id, "provider_message_id": message_id, "email_log_id": email_log.get("id")})
    log_admin_audit(admin.get("id"), "prelaunch_restrict_account", "user", str(user_id), {"reason": "Pre-launch access restriction", "email_sent": True, "delivery_verified": True, "performed_by": "Owner", "timestamp_utc": now, "trace_id": trace_id, "provider_message_id": message_id, "email_log_id": email_log.get("id")})
    return jsonify({"ok": True, "user_id": user_id, "status": "restricted", "access_enabled": False, "login_enabled": False, "email_sent": True, "delivery_verified": True, "provider_message_id": message_id, "trace_id": trace_id, "email_log_id": email_log.get("id")})


