def valid_phone(phone):
    if not phone:
        return True
    return bool(re.match(r"^\+?[0-9 .()\-]{7,24}$", phone))


def sync_brevo_contact_safe(record, entity_type="user", entity_id=None):
    try:
        return brevo_contacts_service.sync_user_to_brevo(record, entity_type=entity_type, entity_id=entity_id)
    except Exception as exc:
        logging.warning("brevo contact sync failed safely: entity_type=%s entity_id=%s error=%s", entity_type, entity_id, exc)
        return {"ok": False, "status": "failed", "error": str(exc)}


def dispatch_brevo_contact_sync_safe(record, entity_type="user", entity_id=None):
    """Keep Brevo contact API latency and retries out of request workers."""
    safe_record = dict(record or {})

    def _run():
        if not BREVO_CONTACT_DISPATCH_LOCK.acquire(blocking=False):
            logging.warning("BREVO_CONTACT_SYNC_DEFERRED entity_type=%s entity_id=%s reason=dispatcher_busy", entity_type, entity_id)
            return
        try:
            result = sync_brevo_contact_safe(safe_record, entity_type=entity_type, entity_id=entity_id)
            logging.info("BREVO_CONTACT_SYNC_BACKGROUND_COMPLETE entity_type=%s entity_id=%s status=%s", entity_type, entity_id, result.get("status") or ("success" if result.get("ok") else "failed"))
        except Exception as exc:
            logging.warning("BREVO_CONTACT_SYNC_BACKGROUND_FAILED entity_type=%s entity_id=%s error=%s", entity_type, entity_id, exc.__class__.__name__)
        finally:
            BREVO_CONTACT_DISPATCH_LOCK.release()

    try:
        threading.Thread(target=_run, name="brevo-contact-sync", daemon=True).start()
        return {"ok": True, "status": "queued"}
    except Exception as exc:
        logging.warning("BREVO_CONTACT_SYNC_ENQUEUE_FAILED entity_type=%s entity_id=%s error=%s", entity_type, entity_id, exc.__class__.__name__)
        return {"ok": False, "status": "failed", "error": exc.__class__.__name__}


def log_product_event(user_id, event_name, metadata=None):
    try:
        in_request = has_request_context()
        user_agent = request.headers.get("User-Agent", "") if in_request else ""
        device_type, browser = parse_device(user_agent)
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO analytics_events
            (session_id, user_id, event_name, page_url, referrer, device_type, browser, ip_hash, country, metadata, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                request.cookies.get("coinpilotxai_session_id", "") if in_request else "",
                user_id,
                event_name,
                request.path if in_request else "",
                request.headers.get("Referer", "") if in_request else "",
                device_type,
                browser,
                client_ip_hash() if in_request else "",
                "",
                json.dumps(metadata or {})[:4000],
                datetime.now().isoformat(),
            ),
        )
        conn.commit()
        conn.close()
        track_conversion_step(user_id, request.cookies.get("coinpilotxai_session_id", "") if in_request else "", event_name, request.path if in_request else "", metadata or {})
    except Exception as exc:
        logging.info("Product event log failed: %s", exc)


