@webhook_app.route("/api/leads", methods=["POST"])
def leads_api():
    init_db()
    payload = request.get_json(silent=True) or {}
    email = normalize_email(clean_html(payload.get("email", "")))
    phone = clean_html(payload.get("phone", "")).strip()
    email_opt_in = 1 if payload.get("email_opt_in") is True else 0
    sms_opt_in = 1 if payload.get("sms_opt_in") is True else 0
    if not is_valid_email(email):
        return jsonify({"ok": False, "message": "Please enter a valid email address."}), 400
    if phone and not valid_phone(phone):
        return jsonify({"ok": False, "message": "Please enter a valid phone number or leave it blank."}), 400
    if sms_opt_in and not phone:
        return jsonify({"ok": False, "message": "SMS opt-in requires a phone number."}), 400
    if not email_opt_in and not sms_opt_in:
        return jsonify({"ok": False, "message": "Please choose at least one opt-in option."}), 400

    now = datetime.now().isoformat()
    utm_source, utm_medium, utm_campaign = get_utm_payload(payload)
    session_id = clean_html(payload.get("session_id", ""))[:100]
    conn = db()
    cur = conn.cursor()
    cur.execute("SELECT id FROM leads WHERE email=?", (email,))
    row = cur.fetchone()
    values = (
        clean_html(payload.get("full_name", ""))[:160],
        email,
        phone[:40],
        clean_html(payload.get("country", ""))[:80],
        clean_html(payload.get("source", "website"))[:120],
        utm_source,
        utm_medium,
        utm_campaign,
        email_opt_in,
        sms_opt_in,
        clean_html(payload.get("telegram_username", ""))[:120],
        now,
        now,
    )
    is_new_lead = not bool(row)
    if row:
        cur.execute(
            """
            UPDATE leads
            SET full_name=?, email=?, phone=?, country=?, source=?, utm_source=?, utm_medium=?, utm_campaign=?,
                email_opt_in=?, sms_opt_in=?, telegram_username=?, updated_at=?, last_seen_at=?
            WHERE email=?
            """,
            values + (email,)
        )
        lead_id = row[0]
    else:
        cur.execute(
            """
            INSERT INTO leads (full_name, email, phone, country, source, utm_source, utm_medium, utm_campaign,
                               email_opt_in, sms_opt_in, telegram_username, created_at, updated_at, last_seen_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            values[:11] + (now, now, now)
        )
        lead_id = cur.lastrowid
    if session_id:
        cur.execute(
            "INSERT INTO analytics_events (session_id, user_id, event_name, page_url, referrer, device_type, browser, ip_hash, country, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                session_id,
                lead_id,
                "signup_form_submit",
                clean_html(payload.get("page_url", ""))[:600],
                clean_html(payload.get("referrer", ""))[:600],
                parse_device(request.headers.get("User-Agent", ""))[0],
                parse_device(request.headers.get("User-Agent", ""))[1],
                client_ip_hash(),
                clean_html(payload.get("country", ""))[:80],
                json.dumps({"email_opt_in": bool(email_opt_in), "sms_opt_in": bool(sms_opt_in), "source": payload.get("source", "website")})[:4000],
                now,
            )
        )
    conn.commit()
    conn.close()
    lead_record = {
        "email": email,
        "full_name": values[0],
        "phone": values[2],
        "country": values[3],
        "source": values[4],
        "utm_source": utm_source,
        "utm_medium": utm_medium,
        "utm_campaign": utm_campaign,
        "email_opt_in": email_opt_in,
        "sms_opt_in": sms_opt_in,
        "telegram_username": values[10],
        "created_at": now,
        "plan": "free",
    }
    sync_brevo_contact_safe(lead_record, entity_type="lead", entity_id=lead_id)
    if email_opt_in and is_new_lead:
        send_update_signup_email({
            "id": lead_id,
            "email": email,
            "full_name": values[0],
        })
    return jsonify({"ok": True, "message": "Thanks — you’re on the CoinPlotXAI Inc. update list."})


def require_admin_password():
    if session.get("admin_user_id"):
        return True
    expected = os.getenv("ADMIN_ANALYTICS_PASSWORD", "")
    if not expected:
        return False
    supplied = request.args.get("password") or request.headers.get("X-Admin-Password", "")
    return supplied == expected


def admin_current_user():
    admin_id = session.get("admin_user_id")
    if not admin_id:
        return None
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT * FROM admin_users WHERE id=? AND status='active' LIMIT 1", (admin_id,))
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def admin_is_owner_level(admin):
    return (admin or {}).get("role", "").strip().lower() in {"owner", "super_admin"}


def load_admin_by_email(email):
    email = normalize_email(email)
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT * FROM admin_users WHERE lower(email)=lower(?) LIMIT 1", (email,))
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def log_admin_audit(admin_user_id, action, target_type="", target_id="", metadata=None):
    try:
        admin = admin_current_user() if has_request_context() else None
        now = datetime.now().isoformat()
        metadata_text = json.dumps(metadata or {})[:4000]
        ip_hash = client_ip_hash() if has_request_context() else ""
        user_agent = request.headers.get("User-Agent", "")[:500] if has_request_context() else ""
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO admin_audit_logs
            (admin_user_id, admin_email, action, target_type, target_id, metadata, ip_hash, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                admin_user_id or (admin or {}).get("id") or 0,
                (admin or {}).get("email") or "",
                action,
                target_type,
                target_id,
                metadata_text,
                ip_hash,
                now,
            ),
        )
        cur.execute(
            """
            INSERT INTO admin_activity_logs
            (admin_user_id, department, action, route, target_type, target_id, before_json, after_json, ip_hash, user_agent, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                admin_user_id or (admin or {}).get("id") or 0,
                target_type if str(target_type or "") in (globals().get("ADMIN_DEPARTMENTS") or {}) else "",
                action,
                request.path if has_request_context() else "",
                target_type,
                target_id,
                "",
                metadata_text,
                ip_hash,
                user_agent,
                now,
            ),
        )
        conn.commit()
        conn.close()
    except Exception as exc:
        logging.info("Admin audit log failed: %s", exc)


def _verification_admin_or_redirect():
    admin = admin_current_user()
    if not admin:
        return None, redirect(url_for("admin_login_page", next=request.path))
    role = str(admin.get("role") or "").strip().lower()
    allowed = pulsesoc_dashboard_centers.ADMIN_ROLES | pulsesoc_dashboard_centers.READONLY_ADMIN_ROLES | {"owner", "super_admin", "admin"}
    if role not in allowed:
        log_admin_audit(admin.get("id"), "verification_admin_denied", "route", request.path, {"role": role})
        return None, Response("Forbidden", status=403)
    return admin, None


def _verification_admin_shell(title, body):
    html = f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{clean_html(title)} | PulseSoc Admin</title><style>:root{{color-scheme:dark;--bg:#050b14;--panel:#0d1627;--line:rgba(110,223,246,.22);--text:#f2fbff;--muted:#9fb5c0;--cyan:#6edff6;--gold:#ffd166;--green:#36e58f}}*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(circle at 12% 0,rgba(110,223,246,.16),transparent 26rem),linear-gradient(135deg,#050b14,#081421);color:var(--text);font-family:Inter,system-ui,sans-serif}}main{{width:min(100% - 28px,1240px);margin:auto;padding:24px 0 90px}}.nav,.actions{{display:flex;gap:10px;flex-wrap:wrap}}.button,button{{min-height:42px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.06);color:var(--text);font-weight:900;padding:9px 12px;text-decoration:none;cursor:pointer}}.primary{{background:linear-gradient(135deg,var(--green),var(--cyan));color:#06101b;border:0}}.card{{border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.045);padding:14px;margin:12px 0;overflow:auto}}table{{width:100%;border-collapse:collapse}}th,td{{text-align:left;padding:10px;border-bottom:1px solid rgba(255,255,255,.09);vertical-align:top}}.pill{{display:inline-flex;border:1px solid var(--line);border-radius:999px;padding:5px 9px;color:var(--cyan);font-weight:900;text-transform:uppercase}}textarea,input,select{{width:100%;min-height:40px;border:1px solid var(--line);border-radius:10px;background:#071322;color:var(--text);padding:9px}}@media(max-width:760px){{.actions,.nav{{display:grid}}table{{display:block;overflow-x:auto}}}}</style></head><body><main><div class="nav"><a class="button" href="/admin/dashboard">Admin</a><a class="button" href="/admin/command-center/account/verification">Verification Queue</a><a class="button" href="/admin/verification/badges">Badges</a><a class="button" href="/admin/verification/appeals">Appeals</a></div><h1>{clean_html(title)}</h1>{body}</main><script>document.addEventListener('submit',async e=>{{const form=e.target.closest('[data-admin-verification-action]');if(!form)return;e.preventDefault();const fd=new FormData(form);const r=await fetch('/api/admin/verification/action',{{method:'POST',credentials:'same-origin',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(Object.fromEntries(fd.entries()))}});const d=await r.json();alert(d.message||'Action recorded.');if(d.ok)location.reload();}});</script></body></html>"""
    return Response(html, mimetype="text/html")


@webhook_app.route("/admin/command-center/account/verification", methods=["GET"])
@webhook_app.route("/admin/verification", methods=["GET"])
def admin_verification_command_center_page():
    init_db()
    admin, failure = _verification_admin_or_redirect()
    if failure:
        return failure
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        queue = pulsesoc_dashboard_centers.admin_queue(conn, admin, request.args.get("status", ""), request.args.get("track", ""))
    finally:
        conn.close()
    track_options = "".join(f"<option value='{track}'>{track}</option>" for track in pulsesoc_dashboard_centers.VERIFICATION_TRACKS)
    status_options = "".join(f"<option value='{status}'>{status}</option>" for status in sorted(pulsesoc_dashboard_centers.VERIFICATION_STATUSES))
    rows = []
    for item in queue.get("requests") or []:
        allowed = bool(item.get("review_allowed"))
        doc_links = "".join(
            f"<a class='button' href='/admin/verification/document/{int(doc.get('id') or 0)}' target='_blank'>{clean_html(doc.get('document_type') or 'Document')} · {clean_html(doc.get('review_status') or 'pending')}</a>"
            for doc in item.get("document_refs") or []
        ) or f"{int(item.get('documents') or 0)} private docs"
        actions = "<span class='pill'>Readonly</span>"
        if allowed:
            actions = f"""<form data-admin-verification-action><input type="hidden" name="request_id" value="{int(item.get('id') or 0)}"><select name="action"><option value="approve">Approve</option><option value="needs_more_info">Request More Info</option><option value="reject">Reject</option><option value="suspend">Suspend</option><option value="revoke">Revoke</option></select><textarea name="reason" placeholder="Safe reviewer note or decision reason"></textarea><button class="primary">Save Decision</button></form>"""
        rows.append(
            f"<tr><td>{int(item.get('id') or 0)}</td><td>{int(item.get('user_id') or 0)}</td><td>{clean_html(item.get('track') or '')}</td><td><span class='pill'>{clean_html(item.get('status') or '')}</span></td><td>{int(item.get('progress_percent') or 0)}%</td><td><div class='actions'>{doc_links}</div></td><td>{actions}</td></tr>"
        )
    empty = "<tr><td colspan='7'>No verification requests.</td></tr>"
    body = f"""
    <section class="card"><strong>Queue Summary</strong><p>Badges: {int(queue.get('badges') or 0)} · Appeals: {int(queue.get('appeals') or 0)} · Audit logs: {int(queue.get('audit_logs') or 0)}</p><form class="actions"><select name="track"><option value="">All tracks</option>{track_options}</select><select name="status"><option value="">All statuses</option>{status_options}</select><button>Filter</button></form></section>
    <section class="card"><table><thead><tr><th>ID</th><th>User</th><th>Track</th><th>Status</th><th>Progress</th><th>Evidence</th><th>Review</th></tr></thead><tbody>{''.join(rows) or empty}</tbody></table></section>
    <section class="card"><strong>Security boundary</strong><p>Normal users cannot access this queue. Reviewer notes, document storage IDs, and private evidence are not exposed publicly. Sensitive actions write verification audit logs.</p></section>
    """
    return _verification_admin_shell("Verification Command Center", body)


@webhook_app.route("/api/admin/verification/action", methods=["POST"])
def api_admin_verification_action():
    admin, failure = _verification_admin_or_redirect()
    if failure:
        return jsonify({"ok": False, "message": "Forbidden."}), 403
    payload = request.get_json(silent=True) or {}
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        result = pulsesoc_dashboard_centers.admin_decision(conn, admin, int(payload.get("request_id") or 0), payload.get("action") or "", payload.get("reason") or "", client_ip_hash(), request.headers.get("User-Agent", "")[:240])
    finally:
        conn.close()
    log_admin_audit(admin.get("id"), "verification_action", "verification_request", str(payload.get("request_id") or ""), {"action": payload.get("action"), "ok": bool(result.get("ok"))})
    return jsonify(result), (200 if result.get("ok") else 400)


@webhook_app.route("/admin/verification/badges", methods=["GET"])
def admin_verification_badges_page():
    init_db()
    admin, failure = _verification_admin_or_redirect()
    if failure:
        return failure
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        pulsesoc_dashboard_centers.ensure_tables(conn)
        cur = conn.cursor()
        cur.execute("SELECT * FROM verification_badges ORDER BY id DESC LIMIT 100")
        badges = [dict(row) for row in cur.fetchall()]
    finally:
        conn.close()
