@webhook_app.route("/admin/verification/document/<int:doc_id>", methods=["GET"])
def admin_verification_document_file(doc_id):
    init_db()
    admin, failure = _verification_admin_or_redirect()
    if failure:
        abort(403)
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        doc = pulsesoc_dashboard_centers.verification_document_for_admin(conn, doc_id, admin, client_ip_hash(), request.headers.get("User-Agent", "")[:240])
    finally:
        conn.close()
    if not doc.get("ok"):
        abort(404 if doc.get("message") == "Document not found." else 403)
    full_path = os.path.abspath(doc.get("storage_path") or "")
    root = os.path.abspath(os.path.join(webhook_app.instance_path, "private_uploads", "account_verification"))
    if not full_path.startswith(root + os.sep) or not os.path.exists(full_path):
        abort(404)
    return send_file(
        full_path,
        mimetype=doc.get("mime_type") or None,
        as_attachment=bool(request.args.get("download")),
        download_name=doc.get("original_filename") or f"verification-document-{doc_id}",
        max_age=0,
    )


