@webhook_app.route("/admin/system/<module_key>", methods=["GET"])
def admin_system_module_page(module_key):
    init_db()
    admin = admin_login_required()
    if not admin:
        return redirect(url_for("admin_login_page"))
    state = _dashboard_system_state(admin=True)
    normalized = str(module_key or "").strip().lower()
    module = next((item for item in state.get("modules") or [] if item.get("key") == normalized), None)
    if not module:
        return redirect("/admin/system")
    rows = [
        {"signal": "state", "value": module.get("state") or ""},
        {"signal": "score", "value": f"{int(module.get('score') or 0)}%"},
        {"signal": "signals", "value": int(module.get("signal_count") or 0)},
        {"signal": "available_tables", "value": f"{int(module.get('available_tables') or 0)}/{int(module.get('required_tables') or 0)}"},
        {"signal": "latency_ms", "value": int(module.get("latency_ms") or 0)},
        {"signal": "prediction", "value": module.get("prediction") or ""},
        {"signal": "recommendation", "value": module.get("recommendation") or ""},
    ]
    action_routes = {
        "feed": [("/admin/feed-health", "Feed Health"), ("/admin/product-health", "Product Health")],
        "messenger": [("/admin/network-command-center", "Network Command Center"), ("/admin/notification-delivery", "Delivery Logs")],
        "live": [("/admin/live", "Live Admin"), ("/admin/pulse-infrastructure", "Infrastructure")],
        "radio": [("/admin/music", "Music Review"), ("/admin/media", "Media Admin")],
        "marketplace": [("/admin/marketplace", "Marketplace Admin"), ("/admin/payments-command-center", "Payments")],
        "notifications": [("/admin/notifications", "Notification Health"), ("/admin/notification-delivery", "Delivery Logs")],
        "ai": [("/admin/ai-command-center", "AI Command Center"), ("/admin/ai-usage", "AI Usage")],
        "scam-shield": [("/admin/security", "Security"), ("/admin/scam-shield", "Scam Shield")],
        "advertising": [("/admin/ads-review", "Ads Review"), ("/admin/ad-delivery", "Ad Delivery")],
        "creator": [("/admin/creator-command-center", "Creator Command Center"), ("/admin/moderation", "Moderation")],
    }.get(normalized, [("/admin/system", "System")])
    actions = "".join(f"<a class='button' href='{clean_html(route)}'>{clean_html(label)}</a>" for route, label in action_routes)
    body = (
        f"<h1>{clean_html(module.get('label') or 'System')}</h1>"
        "<p class='muted'>Admin-only aggregate diagnostics. This page intentionally avoids raw secrets, raw push tokens, private message bodies, and provider credential values.</p>"
        f"<div class='actions'>{actions}<a class='button' href='/admin/system'>System Mission Control</a></div>"
        f"<div class='card'>{admin_rows_table(rows, [('signal','Signal'),('value','Value')])}</div>"
        "<h2>Operational Guidance</h2>"
        f"<div class='card'><p>{clean_html(module.get('recommendation') or 'Keep monitoring.')}</p></div>"
    )
    return admin_page_html(clean_html(module.get("label") or "System"), body, admin)


def service_health_commit():
    for key in ("RAILWAY_GIT_COMMIT_SHA", "GIT_COMMIT", "SOURCE_VERSION", "COMMIT_SHA"):
        value = os.getenv(key, "").strip()
        if value:
            return value[:40]
    try:
        return subprocess.check_output(
            ["git", "rev-parse", "--short=12", "HEAD"],
            cwd=os.path.dirname(os.path.abspath(__file__)),
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=1,
        ).strip()
    except Exception:
        return ""


