        ("Database", "DATABASE_URL", bool(os.getenv("DATABASE_URL")), "Production database connection."),
        ("R2 Attachments", "Cloudflare R2", bool(readiness.get("attachments")), "Image, file, and voice-note storage for Communications V2."),
