@webhook_app.route("/api/admin/email/direct-test", methods=["POST"])
def api_admin_email_direct_test():
    admin, denied = require_admin_api("emails.resend")
    if denied:
        return denied
    payload = request.get_json(silent=True) or request.form.to_dict() or {}
    email = normalize_email(clean_html(payload.get("email", "")))
    email_type = clean_html(payload.get("email_type") or "direct_brevo_test")[:80]
    if not is_valid_email(email):
        return jsonify({"ok": False, "error": "A valid recipient email is required."}), 400
    trace_id = secrets.token_hex(6)
    subject = "PulseSoc email delivery incident test"
    html = branded_email_html(
        "PulseSoc Email Delivery Test",
        f"<p>This is a production delivery test for PulseSoc transactional email.</p><p>Trace ID: <strong>{trace_id}</strong></p>",
    )
    text = f"PulseSoc email delivery test. Trace ID: {trace_id}"
    logging.info(
        "PRODUCTION_EMAIL_DIRECT_TEST trace_id=%s recipient_domain=%s email_type=%s base_url=%s brevo_key_loaded=%s",
        trace_id,
        email.split("@")[-1],
        email_type,
        public_app_base_url(),
        bool(os.getenv("BREVO_API_KEY")),
    )
    result = email_service_service.send_email(
        email,
        subject,
        html,
        text_body=text,
        email_type=email_type,
        user_id=0,
        channel="transactional",
    )
    ok = bool(result.get("ok"))
    safe_error = "" if ok else safe_brevo_error_reason(result)
    log_email_status(
        0,
        email,
        subject,
        email_status_from_result(result),
        email_type=email_type,
        provider="brevo",
        provider_status_code=result.get("status_code"),
        provider_message_id=result.get("message_id") or "",
        safe_error_reason=safe_error,
        metadata={"direct_test": True, "trace_id": trace_id, "missing_fields": result.get("missing_fields") or []},
        trace_id=trace_id,
    )
    log_admin_audit(
        admin.get("id"),
        "admin_email_direct_test",
        "email",
        mask_email(email),
        {"ok": ok, "status_code": result.get("status_code"), "trace_id": trace_id, "message_id_present": bool(result.get("message_id"))},
    )
    return jsonify({
        "ok": ok,
        "trace_id": trace_id,
        "provider": "brevo",
        "status_code": result.get("status_code"),
        "provider_message_id": result.get("message_id") or "",
        "sender_masked": mask_email((result.get("sender") or {}).get("email") or email_sender_identity()[0]),
        "sender_domain": ((result.get("sender") or {}).get("email") or email_sender_identity()[0] or "").split("@")[-1],
        "recipient": mask_email(email),
        "safe_error_reason": safe_error,
        "response": result.get("response") or {},
    }), (200 if ok else 502)


@webhook_app.route("/api/admin/email/outbound-ip", methods=["GET"])
def api_admin_email_outbound_ip():
    admin, denied = require_admin_api("emails.resend")
    if denied:
        return denied
    trace_id = secrets.token_hex(6)
    providers = [
        "https://api.ipify.org?format=json",
        "https://ifconfig.me/all.json",
    ]
    observed_ip = ""
    source = ""
    error = ""
    for provider_url in providers:
        try:
            response = requests.get(provider_url, timeout=6, headers={"Accept": "application/json,text/plain"})
            if response.status_code < 200 or response.status_code >= 300:
                error = f"http_{response.status_code}"
                continue
            body = response.json() if "json" in response.headers.get("content-type", "").lower() else {"ip": response.text.strip()}
            observed_ip = clean_html(str(body.get("ip") or body.get("ip_addr") or ""))[:80]
            if observed_ip:
                source = provider_url.split("/")[2]
                break
        except Exception as exc:
            error = clean_html(str(exc))[:200]
    log_admin_audit(admin.get("id"), "admin_email_outbound_ip_checked", "email", "", {"ok": bool(observed_ip), "source": source, "trace_id": trace_id})
    return jsonify({
        "ok": bool(observed_ip),
        "trace_id": trace_id,
        "provider": source,
        "outbound_ip": observed_ip,
        "message": "Add this Railway outbound IP/range to Brevo Authorized IPs, or disable Brevo blocking for API keys." if observed_ip else "Could not determine outbound IP from this runtime.",
        "error": error,
    }), (200 if observed_ip else 502)


