@webhook_app.route("/api/brevo/webhook", methods=["POST"])
@webhook_app.route("/webhooks/brevo", methods=["POST"])
def brevo_delivery_webhook():
    init_db()
    expected_secret = os.getenv("BREVO_WEBHOOK_SECRET", "").strip()
    if expected_secret:
        supplied = request.headers.get("X-Brevo-Webhook-Secret", "") or request.args.get("secret", "")
        if not secrets.compare_digest(str(supplied), expected_secret):
            logging.warning("BREVO_WEBHOOK_REJECTED reason=secret_mismatch supplied_present=%s", bool(supplied))
            return jsonify({"ok": False, "message": "Unauthorized webhook."}), 401
    payload = request.get_json(silent=True) or {}
    events = payload if isinstance(payload, list) else [payload]
    conn = db()
    cur = conn.cursor()
    updated = 0
    now = datetime.now().isoformat()
    for event in events:
        if not isinstance(event, dict):
            continue
        event_type = clean_html(str(event.get("event") or event.get("event_type") or event.get("type") or ""))[:80]
        message_id = clean_html(str(event.get("message-id") or event.get("messageId") or event.get("message_id") or ""))[:160]
        email = normalize_email(clean_html(str(event.get("email") or "")))
        if not event_type:
            continue
        delivery_status = {
            "delivered": "delivered",
            "opened": "opened",
            "click": "clicked",
            "clicked": "clicked",
            "hard_bounce": "bounced",
            "soft_bounce": "bounced",
            "blocked": "blocked",
            "spam": "spam",
            "invalid": "invalid",
            "deferred": "deferred",
        }.get(event_type.lower(), event_type.lower())
        if message_id:
            cur.execute(
                "UPDATE email_logs SET delivery_status=?, last_webhook_event=?, last_webhook_at=? WHERE provider_message_id=?",
                (delivery_status, event_type, now, message_id),
            )
            updated += cur.rowcount
        elif email:
            cur.execute(
                """
                UPDATE email_logs
                SET delivery_status=?, last_webhook_event=?, last_webhook_at=?
                WHERE lower(COALESCE(recipient_email,email,''))=lower(?)
                  AND id=(SELECT id FROM email_logs WHERE lower(COALESCE(recipient_email,email,''))=lower(?) ORDER BY created_at DESC LIMIT 1)
                """,
                (delivery_status, event_type, now, email, email),
            )
            updated += cur.rowcount
    conn.commit()
    conn.close()
    logging.info("BREVO_WEBHOOK_RECEIVED events=%s updated=%s", len(events), updated)
    return jsonify({"ok": True, "updated": updated})


def _count_table_safe(cur, table):
    table_name = _migration_identifier(table)
    try:
        cur.execute(f"SELECT COUNT(*) FROM {table_name}")
        return cur.fetchone()[0]
    except Exception:
        return None


def sqlite_recovery_snapshot():
    path = os.path.join(os.getcwd(), DB_FILE)
    if not os.path.exists(path):
        return {"available": False, "path": path, "counts": {}, "error": "Local SQLite file not found."}
    try:
        conn = sqlite3.connect(path)
        cur = conn.cursor()
        counts = {}
        for table in ["users", "admin_users", "payment_records", "stripe_events", "unmatched_payments"]:
            counts[table] = _count_table_safe(cur, table)
        conn.close()
        return {"available": True, "path": path, "counts": counts, "error": ""}
    except Exception as exc:
        return {"available": False, "path": path, "counts": {}, "error": str(exc)[:300]}


