def pulse_ads_json_payload():
    payload = request.get_json(silent=True)
    if isinstance(payload, dict):
        return payload
    return request.form.to_dict()


def pulse_ads_verify_write():
    session_token = session.get("csrf_token")
    header_token = request.headers.get("X-CSRF-Token") or request.headers.get("X-CSRFToken")
    return bool(
        verify_csrf()
        or (session_token and header_token and hmac.compare_digest(str(session_token), str(header_token)))
    )


def pulse_ads_api_user_required():
    init_db()
    user = require_account()
    if not user:
        return None, (jsonify({"ok": False, "error": "Login required."}), 401)
    return user, None


def pulse_ads_api_optional_user():
    init_db()
    return require_account()


def pulse_ads_error_response(exc):
    if isinstance(exc, pulse_ads_service.PulseAdsError):
        return jsonify({"ok": False, "error": str(exc)}), exc.status_code
    logging.exception("PULSE_ADS_API_ERROR path=%s", request.path)
    return jsonify({"ok": False, "error": "Ads system temporarily unavailable."}), 500


def pulse_ads_rate_limited(bucket, max_hits=60, window_seconds=60):
    try:
        user_part = str(account_user_id() or "anon")
        key = f"pulse_ads:{bucket}:{user_part}:{client_ip_hash()[:16]}"
        return security_guard.rate_limited(key, max_hits, window_seconds)
    except Exception:
        return False


def pulse_ads_session_id():
    try:
        sid = session.get("_id") or (session.sid if hasattr(session, "sid") else "")
        return str(sid or session.get("csrf_token") or "")
    except Exception:
        return ""


@webhook_app.route("/api/pulse/ads/placements", methods=["GET"])
def api_pulse_ads_placements():
    user = pulse_ads_api_optional_user()
    if pulse_ads_rate_limited("placements", 120, 60):
        return jsonify({"ok": False, "error": "Too many ad requests."}), 429
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        context = request.args.get("context") or "home"
        device_type = request.args.get("device_type") or parse_device(request.headers.get("User-Agent", ""))[0]
        ads = pulse_ads_service.select_ads(
            conn,
            user_id=user.get("user_id") if user else None,
            session_id=pulse_ads_session_id(),
            context=context,
            device_type=device_type,
            viewport=request.args.get("viewport") or "",
            country=request.args.get("country") or "",
            language=request.args.get("language") or "",
            contextual_category=request.args.get("contextual_category") or request.args.get("category") or "",
            search_query=request.args.get("search_query") or "",
            feed_context=request.args.get("feed_context") or "",
            marketplace_context=request.args.get("marketplace_context") or "",
            radio_context=request.args.get("radio_context") or "",
            placement_hint=request.args.get("placement_hint") or "",
            is_premium=bool(user and (user.get("is_premium") or user.get("premium_active"))),
            limit=min(max(int(request.args.get("limit", "3") or 3), 1), 6),
        )
        return jsonify({"ok": True, "ads": ads, "placement_metadata": pulse_ads_service.placement_metadata(context, device_type)})
    except Exception as exc:
        return pulse_ads_error_response(exc)
    finally:
        conn.close()


@webhook_app.route("/api/pulse/ads/placement-metadata", methods=["GET"])
def api_pulse_ads_placement_metadata():
    pulse_ads_api_optional_user()
