def pulse_promotion_error_response(exc):
    if isinstance(exc, pulsesoc_promotions.PromotionError):
        payload = {"ok": False, "message": str(exc)}
        if exc.promotion:
            payload["promotion"] = exc.promotion
            payload["draft_saved"] = True
        return jsonify(payload), int(exc.status_code or 400)
    logging.exception("PULSESOC_PROMOTION_API_FAILED error=%s", exc)
    return jsonify({"ok": False, "message": "Promotion request could not be completed."}), 500


