@webhook_app.route("/api/reels/<int:reel_id>/promotions/<int:promotion_id>", methods=["PATCH"])
def api_pulsesoc_reel_promotion_update(reel_id, promotion_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        pulsesoc_promotions.assert_content_owner(conn, "reel", reel_id, user["user_id"])
        current = pulsesoc_promotions.get_promotion(conn, user["user_id"], promotion_id)
        if current.get("content_type") != "reel" or int(current.get("content_id") or 0) != reel_id:
            raise pulsesoc_promotions.PromotionError("Promotion does not belong to this Reel.", 404)
        return jsonify({"ok": True, "promotion": pulsesoc_promotions.update_promotion(conn, user["user_id"], promotion_id, request.get_json(silent=True) or {})})
    except Exception as exc:
        return pulse_promotion_error_response(exc)
    finally:
        conn.close()


