@webhook_app.route("/api/pulse/ads/accounts/<int:account_id>/media/upload", methods=["POST"])
def api_pulse_ads_media_upload(account_id):
    user, denied = pulse_ads_api_user_required()
    if denied:
        return denied
    if not pulse_ads_verify_write():
        return jsonify({"ok": False, "error": "Security check failed."}), 403
    if pulse_ads_rate_limited("ad_media_upload", 24, 300):
        return jsonify({"ok": False, "error": "Too many ad media uploads. Please wait and retry."}), 429
    file = request.files.get("file")
    if not file or not (file.filename or "").strip():
        return jsonify({"ok": False, "error": "Choose an image, video, or audio file to upload."}), 400
    filename = clean_html(file.filename or "")[:180].lower()
    mime_type = clean_html(file.mimetype or "")[:120].lower()
    if any(token in filename for token in (".svg", ".html", ".htm", ".js", ".mjs", ".exe", ".dmg", ".pkg", ".sh", ".bat", ".cmd")) or any(
        token in mime_type for token in ("svg", "html", "javascript", "script", "executable")
    ):
        return jsonify({"ok": False, "error": "That file type is not allowed for ads."}), 400
    asset_kind = clean_html(request.form.get("asset_kind") or "creative_media")[:40]
    if asset_kind not in {"creative_media", "thumbnail", "companion_image"}:
        return jsonify({"ok": False, "error": "Unsupported ad media asset type."}), 400
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        pulse_ads_service.get_ad_account(conn, user.get("user_id"), account_id)
    except Exception as exc:
        conn.close()
        return pulse_ads_error_response(exc)
    try:
        file.stream.seek(0, os.SEEK_END)
        size = file.stream.tell()
        file.stream.seek(0)
        if asset_kind in {"thumbnail", "companion_image"} and not mime_type.startswith("image/"):
            return jsonify({"ok": False, "error": "Custom thumbnails must be image files."}), 400
        check = camera_filter_engine.validate_media(file.filename or "", file.mimetype or "", size)
        if not check.get("ok"):
            return jsonify({"ok": False, "error": check.get("message") or "Media could not be validated."}), 400
        result, status = upload_progress_service.stage_upload(
            user["user_id"],
            file,
            context_type="pulse_ad_creative",
            context_id=f"account:{account_id}:{asset_kind}",
        )
        if not result.get("ok") or not result.get("media"):
            return jsonify({"ok": False, "error": result.get("message") or "Ad media upload failed."}), status or 400
        asset = pulse_ads_service.create_ad_media_asset(conn, user.get("user_id"), account_id, result.get("media") or {}, asset_kind=asset_kind)
        return jsonify({"ok": True, "asset": asset, "message": "Ad media uploaded and ready for creative review."})
    except Exception as exc:
        return pulse_ads_error_response(exc)
    finally:
        conn.close()


