@webhook_app.route("/admin/pulse-ads-review-board", methods=["GET"])
def admin_pulse_ads_review_board_page():
    init_db()
    admin = admin_login_required()
    if not admin:
        return redirect(url_for("admin_login_page"))
    if not admin_has_permission(admin, "pulse.moderate"):
        return admin_page_html("Ads Review Board", "<h1>Ads Review Board</h1><div class='card error'>Permission denied.</div>", admin), 403
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        items = pulse_ads_service.review_board(conn, 80)
        finance = pulse_ad_payments.admin_finance_summary(conn)
    finally:
        conn.close()
    status_cards = (
        "<div class='grid'>"
        f"<div class='card'><div class='muted'>Wallet Balances</div><div class='metric'>{clean_html(finance.get('total_wallet'))}</div></div>"
        f"<div class='card'><div class='muted'>Lifetime Funded</div><div class='metric'>{clean_html(finance.get('lifetime_funded'))}</div></div>"
        f"<div class='card'><div class='muted'>Lifetime Spent</div><div class='metric'>{clean_html(finance.get('lifetime_spent'))}</div></div>"
        f"<div class='card'><div class='muted'>Reserved</div><div class='metric'>{clean_html(finance.get('reserved'))}</div></div>"
        "</div>"
    )
    rows = ""
    token = get_csrf_token()
    for item in items:
        creative_id = safe_int(item.get("creative_id"), 0)
        campaign_id = safe_int(item.get("campaign_id"), 0)
        media_asset = item.get("media_asset") or {}
        media_url = clean_html(media_asset.get("public_url") or item.get("media_url") or "")
        thumb_url = clean_html((item.get("thumbnail_asset") or {}).get("thumbnail_url") or media_asset.get("thumbnail_url") or "")
        media_type = clean_html(media_asset.get("media_type") or item.get("creative_type") or "text")
        if media_url and media_type == "video":
            preview_html = f"<video src='{media_url}' poster='{thumb_url}' controls muted playsinline preload='metadata' style='max-width:180px;max-height:110px;border-radius:12px'></video>"
        elif media_url and media_type == "audio":
            preview_html = f"<audio src='{media_url}' controls preload='metadata' style='max-width:220px'></audio>"
        elif media_url or thumb_url:
            preview_html = f"<img src='{thumb_url or media_url}' alt='Ad creative preview' loading='lazy' style='max-width:180px;max-height:110px;border-radius:12px;object-fit:cover'>"
        else:
            preview_html = "<span class='muted'>Text creative</span>"
        metadata_html = (
            f"<span class='muted'>{media_type}</span><br>"
            f"<span class='muted'>{safe_int(media_asset.get('width'), 0)}x{safe_int(media_asset.get('height'), 0)} · {safe_int(media_asset.get('file_size'), 0)} bytes</span><br>"
            f"<span class='pill'>{clean_html(media_asset.get('security_status') or 'scan pending')}</span>"
        )
        rows += (
            "<tr>"
            f"<td>{clean_html(item.get('business_name') or '')}</td>"
            f"<td>{clean_html(item.get('title') or '')}<br><span class='muted'>{clean_html(item.get('campaign_name') or '')}</span></td>"
            f"<td>{preview_html}<br>{metadata_html}</td>"
            f"<td><span class='pill'>{clean_html(item.get('review_status') or 'pending')}</span></td>"
            f"<td>{safe_int(item.get('risk_score'), 0)}</td>"
            "<td>"
            f"<form method='post' action='/admin/pulse-ads-review-board/action'><input type='hidden' name='csrf_token' value='{token}'><input type='hidden' name='creative_id' value='{creative_id}'><input type='hidden' name='action' value='approve'><button>Approve</button></form>"
            f"<form method='post' action='/admin/pulse-ads-review-board/action'><input type='hidden' name='csrf_token' value='{token}'><input type='hidden' name='creative_id' value='{creative_id}'><input type='hidden' name='action' value='needs_changes'><input name='reason' placeholder='Required changes'><button>Needs Changes</button></form>"
            f"<form method='post' action='/admin/pulse-ads-review-board/action'><input type='hidden' name='csrf_token' value='{token}'><input type='hidden' name='creative_id' value='{creative_id}'><input type='hidden' name='action' value='reject'><input name='reason' placeholder='Rejection reason'><button>Reject</button></form>"
            f"<form method='post' action='/admin/pulse-ads-review-board/action'><input type='hidden' name='csrf_token' value='{token}'><input type='hidden' name='campaign_id' value='{campaign_id}'><input type='hidden' name='action' value='suspend'><input name='reason' placeholder='Suspend reason'><button> Suspend Campaign</button></form>"
            "</td></tr>"
        )
    body = (
        "<h1>PulseSoc Ads Review Board</h1>"
        "<p class='muted'>Human review, moderation state, wallet finance visibility, and safe platform controls.</p>"
        f"{status_cards}"
        "<div class='card'><h2>Pending and Recent Reviews</h2><table><tr><th>Advertiser</th><th>Creative</th><th>Uploaded Media</th><th>Status</th><th>Risk</th><th>Actions</th></tr>"
        f"{rows or '<tr><td colspan=\"6\" class=\"muted\">No ads awaiting review.</td></tr>'}</table></div>"
    )
    return admin_page_html("Ads Review Board", body, admin)


@webhook_app.route("/admin/pulse-ads-review-board/action", methods=["POST"])
def admin_pulse_ads_review_board_action():
    init_db()
    admin = admin_login_required()
    if not admin:
        return redirect(url_for("admin_login_page"))
    if not admin_has_permission(admin, "pulse.moderate"):
        return admin_page_html("Ads Review Board", "<h1>Ads Review Board</h1><div class='card error'>Permission denied.</div>", admin), 403
    if not verify_csrf():
        return admin_page_html("Ads Review Board", "<h1>Security check failed.</h1>", admin), 403
    action = (request.form.get("action") or "").strip().lower()
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        if action == "approve":
            pulse_ads_service.approve_creative(conn, admin.get("id"), safe_int(request.form.get("creative_id"), 0), request.form.get("reason") or "Approved by admin review.")
        elif action == "reject":
            pulse_ads_service.reject_creative(conn, admin.get("id"), safe_int(request.form.get("creative_id"), 0), request.form.get("reason") or "Creative did not meet PulseSoc ad policy.")
        elif action == "needs_changes":
            pulse_ads_service.reject_creative(conn, admin.get("id"), safe_int(request.form.get("creative_id"), 0), request.form.get("reason") or "Creative needs changes before approval.")
        elif action == "suspend":
            pulse_ads_service.suspend_campaign(conn, admin.get("id"), safe_int(request.form.get("campaign_id"), 0), request.form.get("reason") or "Suspended by admin review.")
    finally:
        conn.close()
    return redirect("/admin/pulse-ads-review-board")


