@webhook_app.route("/api/admin/pulse/ads/accounts/disable", methods=["POST"])
def api_admin_pulse_ads_account_disable():
    admin, denied = require_admin_api("pulse.moderate")
    if denied:
        return denied
    if not pulse_ads_verify_write():
        return jsonify({"ok": False, "error": "Security check failed."}), 403
    conn = db()
    conn.row_factory = sqlite3.Row
    try:
        payload = pulse_ads_json_payload()
        account_id = safe_int(payload.get("account_id"), 0)
        cur = conn.cursor()
        cur.execute("SELECT * FROM pulse_ad_accounts WHERE id=?", (account_id,))
        before = pulse_ads_service.row_to_dict(cur.fetchone())
        if not before:
            return jsonify({"ok": False, "error": "Ad account not found."}), 404
        cur.execute("UPDATE pulse_ad_accounts SET status='suspended', updated_at=? WHERE id=?", (datetime.utcnow().isoformat(timespec="seconds"), account_id))
        pulse_ads_service.audit_log(conn, admin.get("id"), "ad_account_disabled", "pulse_ad_accounts", account_id, before=before, after={"reason": pulse_ads_service.clean_text(payload.get("reason"), 300)})
        conn.commit()
        return jsonify({"ok": True, "account_id": account_id, "status": "suspended"})
    except Exception as exc:
        return pulse_ads_error_response(exc)
    finally:
        conn.close()


