@webhook_app.route("/admin/security", methods=["GET", "POST"])
def admin_security_page():
    admin, denied = require_admin_page("system.view")
    if denied:
        return denied
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    auth_event_schema_guard(cur, conn)
    message = ""
    if request.method == "POST":
        if not verify_csrf():
            conn.close()
            return admin_page_html("Security", "<h1>Security Center</h1><div class='card error'>Security check failed.</div>", admin), 403
        action = clean_html(request.form.get("security_action") or "")[:40]
        value = clean_html(request.form.get("control_value") or "")[:240].lower()
        event_id = safe_int(request.form.get("event_id"), 0)
        now = datetime.utcnow().isoformat()
        before = {}
        if event_id:
            cur.execute("SELECT * FROM auth_events WHERE id=?", (event_id,))
            before = dict(cur.fetchone() or {})
        if action == "block_ip" and value:
            expires_at = (datetime.utcnow() + timedelta(hours=24)).isoformat()
            upsert_failed_login_control(cur, "ip", value, "Blocked from admin security center.", event_id, admin.get("id"), expires_at)
            message = f"IP blocked for 24 hours: {value}"
        elif action == "block_domain" and value:
            expires_at = (datetime.utcnow() + timedelta(hours=24)).isoformat()
            upsert_failed_login_control(cur, "domain", value, "Blocked from admin security center.", event_id, admin.get("id"), expires_at)
            message = f"Domain blocked for 24 hours: {value}"
        elif action == "mark_safe" and value:
            control_type = "domain" if "." in value and "@" not in value and not re.match(r"^\d+\.\d+\.\d+\.\d+$", value) else "ip"
            cur.execute(
                """
                INSERT INTO failed_login_safe_list (control_type, control_value, reason, created_by_admin_id, created_at, updated_at)
                VALUES (?, ?, 'Marked safe from admin security center.', ?, ?, ?)
                ON CONFLICT(control_type, control_value) DO UPDATE SET reason=excluded.reason, created_by_admin_id=excluded.created_by_admin_id, updated_at=excluded.updated_at
                """,
                (control_type, value, admin.get("id"), now, now),
            )
            cur.execute("UPDATE failed_login_controls SET status='safe', updated_at=? WHERE control_type=? AND control_value=?", (now, control_type, value))
            message = f"Marked safe: {value}"
        elif action == "investigate" and value:
            message = f"Investigation noted for: {value}"
        elif action == "explain_risk" and value:
            if command_center_client_service.is_enabled() and command_center_client_service.ai_enabled():
                ai_result = command_center_client_service.request_scam_explanation(
                    {
                        "event_id": value,
                        "event_type": before.get("event_type") or "login_failed",
                        "severity": before.get("severity") or "",
                        "details": auth_event_details(before) if before else {},
                    },
                    user_id=safe_int(before.get("user_id"), 0) if before else 0,
                    event_id=f"admin-security-explain-{value}",
                )
                message = "AI risk analysis requested." if ai_result.get("available") else "AI analysis not enabled."
            else:
                message = "AI analysis not enabled."
        if action:
            cur.execute(
                """
                INSERT INTO admin_activity_logs
                (admin_user_id, department, action, route, target_type, target_id, before_json, after_json, ip_hash, user_agent, created_at)
                VALUES (?, 'security', ?, ?, 'failed_login_control', ?, ?, ?, ?, ?, ?)
                """,
                (
                    admin.get("id"), action, request.path, value,
                    json.dumps(before, default=str)[:4000],
                    json.dumps({"value": value, "event_id": event_id, "message": message})[:4000],
                    client_ip_hash(), request.headers.get("User-Agent", "")[:500], now,
                ),
            )
            log_admin_audit(admin.get("id"), action, "failed_login_control", value, {"event_id": event_id, "message": message})
            conn.commit()
    active_tab = clean_html(request.args.get("tab") or "all").lower()
    filters = {
        "all": ("All", "", ()),
        "failed-logins": ("Failed Logins", "WHERE status='failed' OR event_type LIKE '%login_failed%'", ()),
        "admin-actions": ("Admin Actions", "", ()),
    }
    where_sql, where_params = filters.get(active_tab, filters["all"])[1], filters.get(active_tab, filters["all"])[2]
    cur.execute(f"""
        SELECT id, event_type, email, email_domain, user_id, status, severity, ip_address, country, user_agent, device, route, details, db_engine, created_at
        FROM auth_events
        {where_sql}
        ORDER BY id DESC LIMIT 160
    """, where_params)
    auth_rows = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT admin_email, action, target_type, target_id, created_at FROM admin_audit_logs ORDER BY id DESC LIMIT 120")
    audit_rows = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT control_type, control_value, status, reason, expires_at, updated_at FROM failed_login_controls WHERE status='active' ORDER BY updated_at DESC LIMIT 120")
    blocked_rows = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT control_type, control_value, reason, created_at FROM failed_login_safe_list ORDER BY updated_at DESC LIMIT 120")
    safe_rows = [dict(row) for row in cur.fetchall()]
    cur.execute("""
        SELECT email_domain AS domain, COUNT(*) AS failures, MAX(severity) AS severity, MAX(created_at) AS latest
        FROM auth_events
        WHERE status='failed' AND COALESCE(email_domain,'')!=''
        GROUP BY email_domain
        HAVING COUNT(*) >= 3
        ORDER BY failures DESC, latest DESC
        LIMIT 120
    """)
    suspicious_domains = [dict(row) for row in cur.fetchall()]
    conn.close()
    pipeline_recent = {"available": False, "events": []}
    if command_center_client_service.is_enabled():
        pipeline_recent = command_center_client_service.get_recent_security_events(limit=50)

    def failed_login_rows_table(rows):
        if not rows:
            return "<table><tr><th>Severity</th><th>Event</th><th>Email</th><th>IP</th><th>Country</th><th>Device</th><th>User Agent</th><th>Route</th><th>Status</th><th>Actions</th><th>Date</th></tr><tr><td colspan='11'>No records yet.</td></tr></table>"
        body_rows = []
        for row in rows:
            details = auth_event_details(row)
            ip = row.get("ip_address") or details.get("ip_address") or ""
            domain = row.get("email_domain") or details.get("email_domain") or ""
            actions = (
                admin_security_action_form("block_ip", ip, "Block IP", row.get("id"))
                + admin_security_action_form("block_domain", domain, "Block Domain", row.get("id"))
                + admin_security_action_form("mark_safe", ip or domain, "Mark Safe", row.get("id"))
                + admin_security_action_form("investigate", ip or domain or row.get("event_type"), "Investigate", row.get("id"))
            )
            body_rows.append(
                "<tr>"
                f"<td>{security_label_html(row.get('severity') or details.get('severity') or 'Low')}</td>"
                f"<td>{clean_html(row.get('event_type') or '')}</td>"
                f"<td>{clean_html(row.get('email') or details.get('masked_email') or '')}</td>"
                f"<td>{clean_html(ip)}</td>"
                f"<td>{clean_html(row.get('country') or details.get('country') or '')}</td>"
                f"<td>{clean_html(row.get('device') or details.get('device') or '')}</td>"
                f"<td>{clean_html((row.get('user_agent') or details.get('user_agent') or '')[:180])}</td>"
                f"<td>{clean_html(row.get('route') or details.get('route') or '')}</td>"
                f"<td>{clean_html(row.get('status') or '')}</td>"
                f"<td>{actions}</td>"
                f"<td>{clean_html(row.get('created_at') or '')}</td>"
                "</tr>"
            )
        return "<table><tr><th>Severity</th><th>Event</th><th>Email</th><th>IP</th><th>Country</th><th>Device</th><th>User Agent</th><th>Route</th><th>Status</th><th>Actions</th><th>Date</th></tr>" + "".join(body_rows) + "</table>"

    def controls_table(rows):
        if not rows:
            return "<table><tr><th>Type</th><th>Value</th><th>Status</th><th>Reason</th><th>Expires</th><th>Actions</th></tr><tr><td colspan='6'>No active controls.</td></tr></table>"
        body_rows = []
        for row in rows:
            value = row.get("control_value") or ""
            body_rows.append(
                "<tr>"
                f"<td>{clean_html(row.get('control_type') or '')}</td>"
                f"<td>{clean_html(value)}</td>"
                f"<td>{clean_html(row.get('status') or '')}</td>"
                f"<td>{clean_html(row.get('reason') or '')}</td>"
                f"<td>{clean_html(row.get('expires_at') or '')}</td>"
                f"<td>{admin_security_action_form('mark_safe', value, 'Mark Safe')}</td>"
                "</tr>"
            )
        return "<table><tr><th>Type</th><th>Value</th><th>Status</th><th>Reason</th><th>Expires</th><th>Actions</th></tr>" + "".join(body_rows) + "</table>"

    def suspicious_domains_table(rows):
        if not rows:
            return "<table><tr><th>Domain</th><th>Failures</th><th>Severity</th><th>Latest</th><th>Actions</th></tr><tr><td colspan='5'>No suspicious domains.</td></tr></table>"
        body_rows = []
        for row in rows:
            domain = row.get("domain") or ""
            body_rows.append(
                "<tr>"
                f"<td>{clean_html(domain)}</td>"
                f"<td>{clean_html(str(row.get('failures') or 0))}</td>"
                f"<td>{security_label_html(row.get('severity') or 'Medium')}</td>"
                f"<td>{clean_html(row.get('latest') or '')}</td>"
                f"<td>{admin_security_action_form('block_domain', domain, 'Block Domain')}{admin_security_action_form('mark_safe', domain, 'Mark Safe')}</td>"
                "</tr>"
            )
        return "<table><tr><th>Domain</th><th>Failures</th><th>Severity</th><th>Latest</th><th>Actions</th></tr>" + "".join(body_rows) + "</table>"

    ai_analysis_enabled = bool(command_center_client_service.is_enabled() and command_center_client_service.ai_enabled())

    def command_center_security_table(events):
        if not events:
            return "<table><tr><th>Risk</th><th>Severity</th><th>Event Type</th><th>User</th><th>Status</th><th>AI</th><th>Date</th></tr><tr><td colspan='7'>Command Center security events are not available yet.</td></tr></table>"
        body_rows = []
        for event in events:
            user_id = int(event.get("user_id") or 0)
            event_id = clean_html(event.get("event_id") or "")
            ai_action = (
                admin_security_action_form("explain_risk", event_id, "Explain Risk")
                if ai_analysis_enabled and event_id
                else "<span class='muted'>AI analysis not enabled</span>"
            )
            body_rows.append(
                "<tr>"
                f"<td>{clean_html(str(event.get('score') or 0))}</td>"
                f"<td>{security_label_html(event.get('severity') or 'Low')}</td>"
                f"<td>{clean_html(event.get('event_type') or '')}</td>"
                f"<td>{clean_html(str(user_id or ''))}</td>"
                f"<td>{clean_html(event.get('status') or '')}</td>"
                f"<td>{ai_action}</td>"
                f"<td>{clean_html(event.get('created_at') or '')}</td>"
                "</tr>"
            )
        return "<table><tr><th>Risk</th><th>Severity</th><th>Event Type</th><th>User</th><th>Status</th><th>AI</th><th>Date</th></tr>" + "".join(body_rows) + "</table>"

    tabs = [
        ("all", "All"),
        ("failed-logins", "Failed Logins"),
        ("blocked-ips", "Blocked IPs"),
        ("suspicious-domains", "Suspicious Domains"),
        ("admin-actions", "Admin Actions"),
    ]
    tab_html = "<nav aria-label='Security filters'>" + "".join(
        f"<a class='button {'command-center-link' if active_tab == slug else ''}' href='/admin/security?tab={slug}'>{label}</a>"
        for slug, label in tabs
    ) + "</nav>"
    if active_tab == "blocked-ips":
        main_panel = controls_table(blocked_rows)
    elif active_tab == "suspicious-domains":
        main_panel = suspicious_domains_table(suspicious_domains)
    elif active_tab == "admin-actions":
        main_panel = admin_rows_table(audit_rows, [("admin_email","Admin"),("action","Action"),("target_type","Target"),("target_id","ID"),("created_at","Date")])
    else:
        main_panel = failed_login_rows_table(auth_rows)
    body = (
        "<h1>Security Center</h1>"
        "<p class='muted'>Failed-login monitoring and Command Center scam-shield scoring with IP, country, user-agent, device, route, severity, cooldowns, challenges, and reversible admin controls. Emails remain masked.</p>"
        + (f"<div class='card'>{clean_html(message)}</div>" if message else "")
        + f"<div class='grid'><div class='card'><strong>Security Engine</strong><p class='metric'>{'Online' if pipeline_recent.get('available') else 'Disabled'}</p></div><div class='card'><strong>Recent Risk Events</strong><p class='metric'>{len(pipeline_recent.get('events') or [])}</p></div></div>"
        + tab_html
        + f"<div class='card'>{main_panel}</div>"
        + "<h2>Command Center Risk Signals</h2>"
        + f"<div class='card'>{command_center_security_table(pipeline_recent.get('events') or [])}</div>"
        + "<h2>Safe List</h2>"
        + f"<div class='card'>{admin_rows_table(safe_rows, [('control_type','Type'),('control_value','Value'),('reason','Reason'),('created_at','Created')])}</div>"
    )
    return admin_page_html("Security", body, admin)


