UNDX_DESKTOP_CONNECTOR_URL = os.getenv("UNDX_DESKTOP_CONNECTOR_URL", "http://127.0.0.1:8765").rstrip("/")
UNDX_DESKTOP_CONNECTOR_PATHS = {
    "health",
    "workspace/register",
    "repo/scan",
    "file/read",
    "proposal/generate",
    "patch/apply",
    "validate/run",
    "git/status",
    "git/commit",
    "git/push",
}


@webhook_app.route("/api/undx/desktop-connector/<path:connector_path>", methods=["GET", "POST"])
def api_undx_desktop_connector_proxy(connector_path):
    user, gated = undx_kernel_user()
    if gated:
        return gated
    connector_path = (connector_path or "").strip("/")
    if connector_path not in UNDX_DESKTOP_CONNECTOR_PATHS:
        return api_error("UNDX Desktop Connector endpoint is not allowlisted.", 404)
    try:
        target_url = f"{UNDX_DESKTOP_CONNECTOR_URL}/{connector_path}"
        if request.method == "GET":
            connector_response = requests.get(target_url, timeout=8)
        else:
            connector_response = requests.post(target_url, json=request.get_json(silent=True) or {}, timeout=30)
        payload = connector_response.json()
        if connector_path == "proposal/generate":
            logging.info(
                "UNDX_ACTIVE_PROPOSAL_ROUTE proxy target=%s status=%s ACTIVE_PROPOSAL_ENGINE=%s ACTIVE_MISSION_CLASSIFIER=%s ACTIVE_FILE_SELECTOR=%s brainLayerActive=%s proposalType=%s",
                target_url,
                connector_response.status_code,
                payload.get("activeProposalEngine") or payload.get("engineSource") or "unknown",
                payload.get("activeMissionClassifier") or "unknown",
                payload.get("activeFileSelector") or "unknown",
                payload.get("brainLayerActive"),
                payload.get("proposalType"),
            )
        response = jsonify(payload)
        response.status_code = connector_response.status_code
        response.headers["Cache-Control"] = "no-store, max-age=0"
        return response
    except requests.RequestException as exc:
        logging.info("UNDX_DESKTOP_CONNECTOR_PROXY_FAILED path=%s error=%s", connector_path, exc)
        return api_error("Desktop Connector Offline. Start the local connector on your Mac before scanning local folders.", 503)
    except ValueError:
        return api_error("UNDX Desktop Connector returned an unreadable response.", 502)


