                """
                INSERT INTO scam_shield_scans
                (user_id, scan_type, input_hash, risk_score, risk_level, summary, red_flags_json,
                 safe_actions_json, confidence, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
