def mobile_security_device_context(payload=None):
    payload = payload if isinstance(payload, dict) else {}
    device_id = clean_html(
        payload.get("device_id")
        or request.headers.get("X-PulseSoc-Device-Id")
        or request.headers.get("X-Device-Id")
        or ""
    )[:160]
    device_label = clean_html(payload.get("device_label") or request.headers.get("X-PulseSoc-Device-Label") or "")[:160]
    user_agent = request.headers.get("User-Agent", "")[:500]
    device_hash = pulse_security_core.device_fingerprint(user_agent, device_id)
    native_context = native_app_request_context()
    platform = clean_html(payload.get("platform") or native_context.get("platform") or ("native" if native_context.get("is_native") else "web"))[:40]
    return {
        "device_id": device_id,
        "device_label": device_label,
        "device_hash": device_hash,
        "user_agent": user_agent,
        "ip_hash": client_ip_hash(),
        "country": request_country(),
        "platform": platform,
        "source": clean_html(payload.get("source") or "mobile_auth")[:80],
    }


def ensure_mobile_security_session_schema(cur):
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS mobile_security_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            device_hash TEXT NOT NULL,
            device_label TEXT,
            refresh_token_hash TEXT UNIQUE,
            access_token_hash TEXT,
            status TEXT DEFAULT 'active',
            ip_hash TEXT,
            user_agent TEXT,
            created_at TEXT,
            last_seen_at TEXT,
            access_expires_at TEXT,
            refresh_expires_at TEXT,
            rotated_at TEXT,
            revoked_at TEXT,
            metadata_json TEXT
        )
        """
    )
    add_columns_if_missing(cur, "mobile_security_sessions", [
        ("session_family_id", "TEXT"),
        ("platform", "TEXT"),
        ("country", "TEXT"),
        ("revoked_reason", "TEXT"),
        ("reuse_detected_at", "TEXT"),
        ("last_refresh_at", "TEXT"),
        ("last_risk_score", "INTEGER DEFAULT 0"),
        ("last_trace_id", "TEXT"),
    ])
    cur.execute("CREATE INDEX IF NOT EXISTS idx_mobile_security_sessions_user_status ON mobile_security_sessions(user_id, status, last_seen_at)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_mobile_security_sessions_refresh ON mobile_security_sessions(refresh_token_hash, status)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_mobile_security_sessions_family ON mobile_security_sessions(session_family_id, user_id, status)")


def mobile_token_hash(token):
    return hashlib.sha256(str(token or "").encode("utf-8")).hexdigest()


def mobile_refresh_reuse_grace_allowed(stale, context):
    if not stale or str(stale.get("status") or "").lower() != "rotated":
        return False
    rotated_at = parse_iso_datetime(stale.get("rotated_at") or stale.get("last_refresh_at") or stale.get("last_seen_at"))
    if not rotated_at:
        return False
    now_dt = datetime.now(rotated_at.tzinfo) if rotated_at.tzinfo else datetime.utcnow()
    if (now_dt - rotated_at).total_seconds() > PERSISTENT_REFRESH_REUSE_GRACE_SECONDS:
        return False
    same_device = bool(stale.get("device_hash") and context.get("device_hash") and stale.get("device_hash") == context.get("device_hash"))
    same_ip = bool(stale.get("ip_hash") and context.get("ip_hash") and stale.get("ip_hash") == context.get("ip_hash"))
    return same_device or same_ip


def mobile_access_token(user_id, device_hash, issued_at=None):
    issued_at = int(issued_at or time.time())
    expires_at = issued_at + MOBILE_ACCESS_TOKEN_TTL_SECONDS
    payload = {
        "uid": int(user_id or 0),
        "dh": str(device_hash or "")[:64],
        "iat": issued_at,
        "exp": expires_at,
        "jti": secrets.token_urlsafe(12),
    }
    body = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")
    sig = hmac.new(COINPILOTX_SECRET_KEY.encode("utf-8"), body.encode("utf-8"), hashlib.sha256).hexdigest()
    return f"{body}.{sig}", expires_at


def issue_mobile_security_tokens(user, payload=None, *, rotate_from=""):
    if not user:
        return {}
    context = mobile_security_device_context(payload)
    now_dt = datetime.utcnow()
    now = now_dt.isoformat(timespec="seconds")
    access_token, access_expires_at = mobile_access_token(user["user_id"], context["device_hash"], int(now_dt.timestamp()))
    refresh_token = "psr_" + secrets.token_urlsafe(36)
    refresh_expires_at = (now_dt + timedelta(seconds=MOBILE_REFRESH_TOKEN_TTL_SECONDS)).isoformat(timespec="seconds")
    session_family_id = "pssf_" + secrets.token_urlsafe(18)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    try:
        ensure_mobile_security_session_schema(cur)
        if rotate_from:
            cur.execute(
                "SELECT session_family_id FROM mobile_security_sessions WHERE refresh_token_hash=? AND user_id=? LIMIT 1",
                (mobile_token_hash(rotate_from), user["user_id"]),
            )
            previous = dict(cur.fetchone() or {})
            session_family_id = previous.get("session_family_id") or session_family_id
            cur.execute(
                """
                UPDATE mobile_security_sessions
                SET status='rotated', rotated_at=?, last_seen_at=?, last_refresh_at=?, revoked_reason='refresh_rotated'
                WHERE refresh_token_hash=? AND user_id=? AND status='active'
                """,
                (now, now, now, mobile_token_hash(rotate_from), user["user_id"]),
            )
        cur.execute(
            """
            INSERT INTO mobile_security_sessions
                (user_id, device_hash, device_label, refresh_token_hash, access_token_hash, status, ip_hash, user_agent,
                 created_at, last_seen_at, access_expires_at, refresh_expires_at, session_family_id, platform, country,
                 last_refresh_at, last_trace_id, metadata_json)
            VALUES (?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                user["user_id"],
                context["device_hash"],
                context["device_label"],
                mobile_token_hash(refresh_token),
                mobile_token_hash(access_token),
                context["ip_hash"],
                context["user_agent"],
                now,
                now,
                datetime.utcfromtimestamp(access_expires_at).isoformat(timespec="seconds"),
                refresh_expires_at,
                session_family_id,
                context["platform"],
                context["country"],
                now,
                getattr(g, "performance_trace_id", "") if has_request_context() else "",
                json.dumps({"device_id_present": bool(context["device_id"]), "source": context["source"], "persistent": True}, default=str),
            ),
        )
        conn.commit()
    except Exception:
        conn.rollback()
        logging.exception("MOBILE_SECURITY_SESSION_ISSUE_FAILED user_id=%s", user.get("user_id"))
    finally:
        conn.close()
    pulse_security_core.cache_device_trust(user["user_id"], context["device_hash"], {"status": "active", "last_seen_at": now}, ttl_seconds=60)
    return {
        "access_token": access_token,
        "access_token_expires_in": MOBILE_ACCESS_TOKEN_TTL_SECONDS,
        "refresh_token": refresh_token,
        "refresh_token_expires_in": MOBILE_REFRESH_TOKEN_TTL_SECONDS,
        "device_hash": context["device_hash"][:16],
    }


def rotate_mobile_refresh_token(refresh_token, payload=None):
    refresh_hash = mobile_token_hash(refresh_token)
    if not refresh_token:
        return None, {}
    now = datetime.utcnow().isoformat(timespec="seconds")
    trace_id = getattr(g, "performance_trace_id", secrets.token_hex(6)) if has_request_context() else secrets.token_hex(6)
    context = mobile_security_device_context(payload)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    try:
        ensure_mobile_security_session_schema(cur)
        cur.execute(
            """
            SELECT s.*, u.*
            FROM mobile_security_sessions s
            JOIN users u ON u.user_id=s.user_id
            WHERE s.refresh_token_hash=? AND s.status='active' AND COALESCE(s.revoked_at,'')='' AND COALESCE(s.refresh_expires_at,'')>=?
            LIMIT 1
            """,
            (refresh_hash, now),
        )
        row = dict(cur.fetchone() or {})
        if not row:
            cur.execute(
                """
                SELECT *
                FROM mobile_security_sessions
                WHERE refresh_token_hash=?
                ORDER BY id DESC
                LIMIT 1
                """,
                (refresh_hash,),
            )
            stale = dict(cur.fetchone() or {})
            if stale:
                user_id = int(stale.get("user_id") or 0)
                session_family_id = stale.get("session_family_id") or ""
                if mobile_refresh_reuse_grace_allowed(stale, context):
                    cur.execute("SELECT * FROM users WHERE user_id=? LIMIT 1", (user_id,))
                    user_row = dict(cur.fetchone() or {})
                    if user_row and not account_login_restriction_message(user_row):
                        cur.execute(
                            """
                            UPDATE mobile_security_sessions
                            SET last_seen_at=?, last_refresh_at=?, ip_hash=?, country=?, last_trace_id=?
                            WHERE id=?
                            """,
                            (now, now, context.get("ip_hash") or "", context.get("country") or "", trace_id, int(stale.get("id") or 0)),
                        )
                        conn.commit()
                        conn.close()
                        logging.info(
                            "MOBILE_REFRESH_ROTATED_GRACE trace_id=%s user_id=%s session_family_id=%s source=%s",
                            trace_id,
                            user_id,
                            session_family_id,
                            context.get("source") or "refresh",
                        )
                        return user_row, issue_mobile_security_tokens(user_row, payload, rotate_from=refresh_token)
                cur.execute(
                    """
                    UPDATE mobile_security_sessions
                    SET status='revoked', revoked_at=COALESCE(NULLIF(revoked_at,''), ?), reuse_detected_at=?, revoked_reason='refresh_token_reuse', last_trace_id=?
                    WHERE user_id=? AND (session_family_id=? OR refresh_token_hash=?)
                      AND status IN ('active','rotated')
                    """,
                    (now, now, trace_id, user_id, session_family_id, refresh_hash),
                )
                try:
                    notify_user(
                        cur,
                        user_id,
                        "security_alert",
                        "Suspicious session activity detected",
                        "PulseSoc detected a reused or invalid refresh token and signed out the affected session.",
                        "/pulse/settings/security",
                        actor_user_id=user_id,
                        entity_type="account",
                        entity_id=str(user_id),
                        metadata={"event": "refresh_token_reuse", "trace_id": trace_id, "source": context.get("source") or "refresh"},
                    )
                except Exception:
                    logging.info("REFRESH_REUSE_NOTIFICATION_SKIPPED user_id=%s trace_id=%s", user_id, trace_id)
                conn.commit()
                log_security_event("refresh_token_reuse", "Critical", user_id, request.path if has_request_context() else "/api/mobile/auth/refresh", {"trace_id": trace_id, "session_family_id": session_family_id, "reason": "stale_refresh_token_reuse"})
            conn.close()
            return None, {}
        if row.get("device_hash") and context.get("device_hash") and row.get("device_hash") != context.get("device_hash"):
            user_id = int(row.get("user_id") or 0)
            cur.execute(
                """
                UPDATE mobile_security_sessions
                SET status='revoked', revoked_at=?, revoked_reason='device_mismatch', last_trace_id=?, last_seen_at=?
                WHERE id=?
                """,
                (now, trace_id, now, int(row.get("id") or 0)),
            )
            try:
                notify_user(
                    cur,
                    user_id,
                    "security_alert",
                    "Suspicious device activity detected",
                    "PulseSoc blocked a session refresh from a different device fingerprint.",
                    "/pulse/settings/security",
                    actor_user_id=user_id,
                    entity_type="account",
                    entity_id=str(user_id),
                    metadata={"event": "refresh_device_mismatch", "trace_id": trace_id},
                )
            except Exception:
                logging.info("REFRESH_DEVICE_MISMATCH_NOTIFICATION_SKIPPED user_id=%s trace_id=%s", user_id, trace_id)
            conn.commit()
            log_security_event("refresh_device_mismatch", "High", user_id, request.path if has_request_context() else "/api/mobile/auth/refresh", {"trace_id": trace_id})
            conn.close()
            return None, {}
        user = {key: row[key] for key in row.keys() if key in {"user_id", "email", "username", "display_name", "full_name", "avatar_url", "premium_status", "subscription_status", "email_verified", "account_status", "access_enabled", "login_enabled"}}
        if account_login_restriction_message(user):
            cur.execute(
                "UPDATE mobile_security_sessions SET status='revoked', revoked_at=?, revoked_reason='account_restricted', last_trace_id=? WHERE user_id=? AND status='active'",
                (now, trace_id, int(user.get("user_id") or 0)),
            )
            conn.commit(); conn.close()
            return None, {}
        cur.execute(
            "UPDATE mobile_security_sessions SET last_seen_at=?, last_refresh_at=?, ip_hash=?, country=?, last_trace_id=? WHERE id=?",
            (now, now, context.get("ip_hash") or "", context.get("country") or "", trace_id, row.get("id")),
        )
        conn.commit(); conn.close()
        return user, issue_mobile_security_tokens(user, payload, rotate_from=refresh_token)
    except Exception:
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        logging.exception("MOBILE_SECURITY_SESSION_ROTATE_FAILED")
        return None, {}


def revoke_mobile_refresh_token(refresh_token, reason="user_logout"):
    if not refresh_token:
        return False
    conn = db(); cur = conn.cursor()
    try:
        ensure_mobile_security_session_schema(cur)
        now = datetime.utcnow().isoformat(timespec="seconds")
        cur.execute(
            "UPDATE mobile_security_sessions SET status='revoked', revoked_at=?, last_seen_at=?, revoked_reason=? WHERE refresh_token_hash=? AND status='active'",
            (now, now, clean_html(reason)[:120], mobile_token_hash(refresh_token)),
        )
        conn.commit()
        changed = cur.rowcount > 0
        conn.close()
        return changed
    except Exception:
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        return False


def revoke_all_mobile_security_sessions(user_id, reason="user_sign_out_all"):
    if not user_id:
        return 0
    conn = db(); cur = conn.cursor()
    try:
        ensure_mobile_security_session_schema(cur)
        now = datetime.utcnow().isoformat(timespec="seconds")
        cur.execute(
            """
            UPDATE mobile_security_sessions
            SET status='revoked', revoked_at=COALESCE(NULLIF(revoked_at,''), ?), last_seen_at=?, revoked_reason=?
            WHERE user_id=? AND status IN ('active','rotated')
            """,
            (now, now, clean_html(reason)[:120], int(user_id)),
        )
        changed = int(cur.rowcount or 0)
        cur.execute(
            "INSERT INTO user_security_events (user_id, event_type, ip_hash, user_agent_hash, device_label, metadata_json, created_at) VALUES (?, 'sessions_revoked', ?, ?, ?, ?, ?)",
            (
                int(user_id),
                client_ip_hash() if has_request_context() else "",
                hashlib.sha256(((request.headers.get("User-Agent") if has_request_context() else "") or "").encode()).hexdigest()[:32],
                presence_device_label() if has_request_context() else "server",
                json.dumps({"reason": reason, "revoked_count": changed})[:1000],
                now,
            ),
        )
        conn.commit()
        conn.close()
        log_security_event("sessions_revoked", "observed", int(user_id), request.path if has_request_context() else "", {"reason": reason, "revoked_count": changed})
        return changed
    except Exception:
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        logging.exception("MOBILE_SECURITY_SESSION_REVOKE_ALL_FAILED user_id=%s", user_id)
        return 0


