def arena_rank_for_xp(xp):
    rank = "Rookie"
    for threshold, label in ARENA_RANKS:
        if int(xp or 0) >= threshold:
            rank = label
    return rank


def arena_username_for_user(user):
    user = user or {}
    raw = user.get("username") or user.get("display_name") or user.get("full_name") or (user.get("email") or "").split("@")[0] or f"pulse{user.get('user_id') or ''}"
    slug = re.sub(r"[^a-zA-Z0-9_]", "", raw.replace(" ", "_")).strip("_").lower()
    return (slug or f"pulse{user.get('user_id') or 'x'}")[:32]


def arena_public_id_for_user(user):
    user = user or {}
    base = "PulseSoc"
    role = (user.get("display_name") or user.get("full_name") or user.get("username") or "").lower()
    if "scam" in role:
        base = "ScamHunter"
    elif "btc" in role:
        base = "BTCGuardian"
    elif "whale" in role:
        base = "WhaleWatcher"
    elif "galaxy" in role:
        base = "GalaxyPilot"
    suffix = str(1000 + (int(user.get("user_id") or 0) * 7919) % 9000)
    return f"{base}-{suffix}"


