PULSE_NOTIFICATION_SAFE_FALLBACK = "/pulse/notifications"
PULSE_NOTIFICATION_ALLOWED_ROUTE_PREFIXES = (
    "/pulse/notifications",
    "/pulse/messages",
    "/pulse/live",
    "/pulse/reels",
    "/pulse/videos",
    "/pulse/post",
    "/pulse/status",
    "/pulse/profile",
    "/pulse/alerts",
    "/pulse/purchases",
    "/pulse/premium",
    "/pulse/marketplace",
    "/dashboard/crypto",
    "/dashboard/account/security",
    "/dashboard/economy",
    "/account/security",
    "/billing/portal",
)


def _pulse_notification_meta(note):
    if isinstance((note or {}).get("metadata"), dict):
        return (note or {}).get("metadata") or {}
    raw = (note or {}).get("metadata_json")
    if isinstance(raw, dict):
        return raw
    if raw:
        try:
            loaded = json.loads(raw)
            return loaded if isinstance(loaded, dict) else {}
        except Exception:
            return {}
    return {}


def _pulse_note_value(note, meta, *keys):
    for key in keys:
        value = (note or {}).get(key)
        if value not in (None, ""):
            return value
        value = (meta or {}).get(key)
        if value not in (None, ""):
            return value
    return ""


def _pulse_notification_native_to_web(raw):
    parsed = urlparse(raw)
    host = (parsed.netloc or "").strip().lower()
    path = (parsed.path or "").strip("/")
    query = parse_qs(parsed.query or "")
    if host == "pulse":
        if path.startswith("messages-v2"):
            conversation_id = (query.get("conversation") or query.get("conversation_id") or [""])[0]
            return f"/pulse/messages/{quote(str(conversation_id))}" if conversation_id else "/pulse/messages"
        if path == "live/studio" or path.startswith("live/studio/"):
            return f"/pulse/{path}"
        if path.startswith("profile/"):
            return f"/pulse/{path}"
        if path:
            return f"/{path}"
    if host == "post":
        parts = [part for part in path.split("/") if part]
        post_id = parts[0] if parts else ""
        comment_id = parts[2] if len(parts) >= 3 and parts[1] == "comment" else ""
        return f"/pulse/post/{quote(post_id)}#comment-{quote(comment_id)}" if post_id and comment_id else (f"/pulse/post/{quote(post_id)}" if post_id else "")
    if host == "status":
        status_id = path.split("/")[0] if path else ""
        return f"/pulse/status/{quote(status_id)}" if status_id else "/pulse/status"
    if host == "live":
        live_id = path.split("/")[0] if path else ""
        return f"/pulse/reels?live={quote(live_id)}" if live_id else "/pulse/reels"
    if host == "alerts":
        alert_id = path.split("/")[0] if path else ""
        return f"/pulse/alerts/{quote(alert_id)}" if alert_id else "/pulse/alerts"
    if host == "purchase":
        purchase_id = path.split("/")[0] if path else ""
        return f"/pulse/purchases/{quote(purchase_id)}" if purchase_id else "/pulse/purchases"
    if host == "account" and path == "security":
        return "/account/security"
    return ""


def _pulse_notification_normalize_target(raw):
    value = str(raw or "").strip()
    if not value or any(ch in value for ch in "\r\n\t"):
        return ""
    lowered = value.lower()
    if lowered.startswith(("javascript:", "data:", "blob:", "file:")):
        return ""
    if lowered.startswith("pulse://"):
        value = _pulse_notification_native_to_web(value)
        if not value:
            return ""
    parsed = urlparse(value)
    if parsed.scheme in {"http", "https"}:
        host = (parsed.netloc or "").split("@")[-1].split(":")[0].lower()
        allowed_hosts = {"pulsesoc.com", "www.pulsesoc.com"}
        if has_request_context():
            allowed_hosts.add((request.host or "").split(":")[0].lower())
        if host and host not in allowed_hosts:
            return ""
        value = parsed.path or "/"
        if parsed.query:
            value = f"{value}?{parsed.query}"
        if parsed.fragment:
            value = f"{value}#{parsed.fragment}"
    elif parsed.netloc:
        return ""
    if not value.startswith("/") or value.startswith("//") or "\\" in value:
        return ""
    path = urlparse(value).path or ""
    if path.startswith(("/api/", "/static/", "/admin/")):
        return ""
    return value[:700]


def _pulse_notification_semantic_targets(note):
    note = note or {}
    meta = _pulse_notification_meta(note)
    note_type = str(_pulse_note_value(note, meta, "type", "notification_type", "event_type") or "").lower()
    entity_type = str(_pulse_note_value(note, meta, "entity_type", "content_type", "source_type") or "").lower()
    entity_id = _pulse_note_value(note, meta, "entity_id", "content_id")
    conversation_id = _pulse_note_value(note, meta, "conversation_id", "conversationId", "thread_id", "threadId")
    post_id = _pulse_note_value(note, meta, "post_id", "postId")
    reel_id = _pulse_note_value(note, meta, "reel_id", "reelId")
    video_id = _pulse_note_value(note, meta, "video_id", "videoId")
    status_id = _pulse_note_value(note, meta, "status_id", "statusId")
    comment_id = _pulse_note_value(note, meta, "comment_id", "commentId", "reply_id", "replyId")
    profile_id = _pulse_note_value(note, meta, "profile_user_id", "profile_id", "followed_user_id", "sender_user_id", "actor_user_id")
    live_id = _pulse_note_value(note, meta, "live_id", "liveId", "stream_id", "streamId")
    alert_id = _pulse_note_value(note, meta, "alert_id", "alert_rule_id", "rule_id", "alertId")
    purchase_id = _pulse_note_value(note, meta, "order_id", "purchase_id", "payment_id", "receipt_id", "orderId", "purchaseId")
    symbol = str(_pulse_note_value(note, meta, "symbol", "coin", "asset", "ticker") or "").strip().upper()

    if entity_id:
        if not conversation_id and any(token in entity_type for token in ("message", "chat", "conversation")):
            conversation_id = entity_id
        if not post_id and "post" in entity_type:
            post_id = entity_id
        if not reel_id and "reel" in entity_type:
            reel_id = entity_id
        if not video_id and "video" in entity_type:
            video_id = entity_id
        if not status_id and "status" in entity_type:
            status_id = entity_id
        if not profile_id and any(token in entity_type for token in ("profile", "user", "follow")):
            profile_id = entity_id
        if not live_id and "live" in entity_type:
            live_id = entity_id
        if not alert_id and any(token in entity_type for token in ("alert", "crypto")):
            alert_id = entity_id
        if not purchase_id and any(token in entity_type for token in ("order", "purchase", "payment", "receipt", "subscription")):
            purchase_id = entity_id

    targets = []
    if conversation_id or "message" in note_type or "chat" in note_type:
        targets.append(f"/pulse/messages/{quote(str(conversation_id))}" if conversation_id else "/pulse/messages")
    if "cohost_request" in note_type:
        targets.append(f"/pulse/live/studio/{quote(str(live_id))}" if live_id else "/pulse/live/studio")
    elif live_id or "live" in note_type or "cohost" in note_type:
        targets.append(f"/pulse/reels?live={quote(str(live_id))}" if live_id else "/pulse/reels")
    if reel_id:
        targets.append(f"/pulse/reels/{quote(str(reel_id))}")
    if video_id:
        targets.append(f"/pulse/videos/{quote(str(video_id))}")
    if post_id:
        suffix = f"#comment-{quote(str(comment_id))}" if comment_id else ""
        targets.append(f"/pulse/post/{quote(str(post_id))}{suffix}")
    if status_id:
        targets.append(f"/pulse/status/{quote(str(status_id))}")
    if profile_id and ("follow" in note_type or "profile" in entity_type or "user" in entity_type):
        targets.append(f"/pulse/profile/{quote(str(profile_id))}")
    if alert_id or "crypto" in note_type or "scam" in note_type:
        targets.append(f"/dashboard/crypto/alerts?alert_id={quote(str(alert_id))}" if alert_id else (f"/dashboard/crypto/alerts?symbol={quote(symbol)}" if symbol else "/dashboard/crypto/alerts"))
    if note_type in {"account_login", "new_device", "suspicious_login", "password_changed", "password_reset", "password_reset_requested", "email_changed", "phone_changed", "account_locked", "security_alert"} or "security" in note_type:
        targets.append("/account/security")
    if purchase_id or any(token in note_type for token in ("purchase", "payment", "order", "subscription")):
        targets.append(f"/pulse/purchases/{quote(str(purchase_id))}" if purchase_id else "/dashboard/economy/subscriptions")
    if "premium" in note_type:
        targets.append("/pulse/premium")
    return targets


def _pulse_notification_route_exists(target_url):
    normalized = _pulse_notification_normalize_target(target_url)
    if not normalized:
        return False
    path = urlparse(normalized).path or "/"
    if not any(path == prefix or path.startswith(f"{prefix}/") for prefix in PULSE_NOTIFICATION_ALLOWED_ROUTE_PREFIXES):
        return False
    try:
        webhook_app.url_map.bind("localhost").match(path, method="GET")
        return True
    except RequestRedirect:
        return True
    except Exception:
        return False


def pulse_notification_resolve_target(note, user_id=0, trace_id=""):
    trace_id = str(trace_id or secrets.token_hex(6))[:80]
    note = dict(note or {})
    meta = _pulse_notification_meta(note)
    explicit = [
        note.get("deep_link"),
        note.get("target_url"),
        meta.get("deep_link"),
        meta.get("target_url"),
        meta.get("next_url"),
        meta.get("url"),
        meta.get("href"),
        meta.get("web_url"),
        meta.get("mobile_deep_link"),
        meta.get("native_url"),
        meta.get("app_url"),
        meta.get("deepLink"),
    ]
    candidates = []
    for raw in [*_pulse_notification_semantic_targets(note), *explicit, PULSE_NOTIFICATION_SAFE_FALLBACK]:
        normalized = _pulse_notification_normalize_target(raw)
        if normalized in {"/", "/pulse"}:
            normalized = ""
        if normalized and normalized not in candidates:
            candidates.append(normalized)
    for candidate in candidates:
        if _pulse_notification_route_exists(candidate):
            fallback_used = candidate == PULSE_NOTIFICATION_SAFE_FALLBACK and bool(candidates[:-1])
            if fallback_used:
                raw_target = str(note.get("deep_link") or note.get("target_url") or meta.get("deep_link") or meta.get("target_url") or "")[:700]
                logging.warning(
                    "PULSE_NOTIFICATION_BAD_TARGET trace_id=%s notification_id=%s type=%s target_url=%s user_id=%s fallback=%s",
                    trace_id,
                    int(note.get("id") or 0),
                    str(note.get("type") or meta.get("type") or "")[:80],
                    raw_target,
                    int(user_id or 0),
                    PULSE_NOTIFICATION_SAFE_FALLBACK,
                )
            return {
                "ok": True,
                "target_url": candidate,
                "fallback_used": fallback_used,
                "trace_id": trace_id,
            }
    raw_target = str(note.get("deep_link") or note.get("target_url") or meta.get("deep_link") or meta.get("target_url") or "")[:700]
    logging.warning(
        "PULSE_NOTIFICATION_BAD_TARGET trace_id=%s notification_id=%s type=%s target_url=%s user_id=%s fallback=%s",
        trace_id,
        int(note.get("id") or 0),
        str(note.get("type") or meta.get("type") or "")[:80],
        raw_target,
        int(user_id or 0),
        PULSE_NOTIFICATION_SAFE_FALLBACK,
    )
    return {
        "ok": True,
        "target_url": PULSE_NOTIFICATION_SAFE_FALLBACK,
        "fallback_used": True,
        "reason": "missing_or_invalid_target",
        "trace_id": trace_id,
    }


@webhook_app.route("/api/pulse/notifications/<int:notification_id>/resolve", methods=["GET", "POST"])
def api_pulse_notification_resolve(notification_id):
    init_db()
    user = api_account_user()
    trace_id = request.headers.get("X-Trace-Id") or secrets.token_hex(6)
    if not user:
        response = jsonify({"ok": False, "message": "Login required.", "target_url": PULSE_NOTIFICATION_SAFE_FALLBACK, "trace_id": trace_id})
        response.headers["Cache-Control"] = "no-store, max-age=0"
        return response, 401
    note, note_source = _pulse_notification_os_get_or_legacy(user["user_id"], notification_id)
    if not note:
        logging.warning(
            "PULSE_NOTIFICATION_BAD_TARGET trace_id=%s notification_id=%s type=%s target_url=%s user_id=%s fallback=%s",
            trace_id, int(notification_id or 0), "missing", "", int(user["user_id"]), PULSE_NOTIFICATION_SAFE_FALLBACK,
        )
        response = jsonify({"ok": False, "message": "Notification is no longer available.", "target_url": PULSE_NOTIFICATION_SAFE_FALLBACK, "trace_id": trace_id})
        response.headers["Cache-Control"] = "no-store, max-age=0"
        return response, 404
    result = pulse_notification_resolve_target(note, user["user_id"], trace_id)
    payload = request.get_json(silent=True) or {}
    if request.method == "POST" and payload.get("mark_read", True):
        result["read"] = _pulse_notification_os_mark_read_or_legacy(user["user_id"], notification_id)
        result["badge_counts"] = result["read"].get("badge_counts") or _pulse_notification_os_badge_counts(user["user_id"])
    result["source"] = note_source
    response = jsonify(result)
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


