@webhook_app.route("/api/push/status", methods=["GET"])
def api_push_status():
    init_db()
    user = api_account_user()
    if not user:
        response = jsonify({"ok": False, "message": "Login required."})
        response.headers["Cache-Control"] = "no-store, max-age=0"
        return response, 401
    conn = db()
    cur = conn.cursor()
    cur.execute(
        "SELECT COUNT(*) AS total FROM push_subscriptions WHERE user_id=? AND COALESCE(active,1)=1 AND COALESCE(is_active,1)=1",
        (int(user["user_id"]),),
    )
    row = cur.fetchone()
    active_subscriptions = int((row["total"] if hasattr(row, "keys") else row[0]) or 0)
    try:
        cur.execute(
            "SELECT COUNT(*) AS total FROM user_device_tokens WHERE user_id=? AND COALESCE(enabled,1)=1 AND COALESCE(revoked_at,'')=''",
            (int(user["user_id"]),),
        )
        row = cur.fetchone()
        active_devices = int((row["total"] if hasattr(row, "keys") else row[0]) or 0)
    except Exception:
        active_devices = active_subscriptions
    conn.close()
    os_device_status = pulsesoc_notification_system.device_status(user["user_id"])
    response = jsonify({
        "ok": True,
        "push_enabled": active_subscriptions > 0,
        "active_subscriptions": active_subscriptions,
        "active_devices": max(active_devices, int(os_device_status.get("notification_os_active_devices") or 0)),
        "notification_os_active_devices": int(os_device_status.get("notification_os_active_devices") or 0),
        "web_push_configured": bool((os.getenv("WEB_PUSH_PUBLIC_KEY") or os.getenv("VAPID_PUBLIC_KEY")) and (os.getenv("WEB_PUSH_PRIVATE_KEY") or os.getenv("VAPID_PRIVATE_KEY"))),
        "expo_supported": True,
    })
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


@webhook_app.route("/api/push/devices", methods=["GET"])
def api_push_devices():
    """Return the current user's active push devices without exposing tokens."""
    init_db()
    user = api_account_user()
    if not user:
        response = jsonify({"ok": False, "message": "Login required."})
        response.headers["Cache-Control"] = "no-store, max-age=0"
        return response, 401
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT platform, device_id, push_provider, environment, app_version, device_label,
                   enabled, created_at, updated_at, last_seen_at, revoked_at, push_token
            FROM user_device_tokens
            WHERE user_id=?
            ORDER BY COALESCE(last_seen_at, updated_at, created_at) DESC, id DESC
            LIMIT 20
            """,
            (int(user["user_id"]),),
        )
        token_rows = [dict(row) for row in cur.fetchall()]
    except Exception:
        token_rows = []
    try:
        cur.execute(
            """
            SELECT endpoint, device_type, browser, active, is_active, created_at, updated_at, last_seen_at
            FROM push_subscriptions
            WHERE user_id=?
            ORDER BY COALESCE(last_seen_at, updated_at, created_at) DESC, id DESC
            LIMIT 20
            """,
            (int(user["user_id"]),),
        )
        subscription_rows = [dict(row) for row in cur.fetchall()]
    except Exception:
        subscription_rows = []
    conn.close()

    def token_hash(value):
        return hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()[:16] if value else ""

    devices = []
    for row in token_rows:
        enabled = bool(int(row.get("enabled") or 0)) and not row.get("revoked_at")
        devices.append(
            {
                "platform": clean_html(row.get("platform") or "")[:80],
                "provider": clean_html(row.get("push_provider") or "")[:40],
                "environment": clean_html(row.get("environment") or "")[:80],
                "app_version": clean_html(row.get("app_version") or "")[:80],
                "device_label": clean_html(row.get("device_label") or "")[:160],
                "device_id_hash": token_hash(row.get("device_id")),
                "token_hash": token_hash(row.get("push_token")),
                "active": enabled,
                "created_at": row.get("created_at") or "",
                "updated_at": row.get("updated_at") or "",
                "last_seen_at": row.get("last_seen_at") or "",
            }
        )
    if not devices:
        for row in subscription_rows:
            active = bool(int(row.get("active") if row.get("active") is not None else 1)) and bool(int(row.get("is_active") if row.get("is_active") is not None else 1))
            devices.append(
                {
                    "platform": "web" if row.get("device_type") != "native" else "native",
                    "provider": "expo" if str(row.get("endpoint") or "").startswith(("ExpoPushToken[", "ExponentPushToken[")) else "webpush",
                    "environment": os.getenv("RAILWAY_ENVIRONMENT_NAME") or os.getenv("ENV") or "",
                    "app_version": "",
                    "device_label": clean_html(" ".join(part for part in [row.get("device_type"), row.get("browser")] if part))[:160],
                    "device_id_hash": "",
                    "token_hash": token_hash(row.get("endpoint")),
                    "active": active,
                    "created_at": row.get("created_at") or "",
                    "updated_at": row.get("updated_at") or "",
                    "last_seen_at": row.get("last_seen_at") or "",
                }
            )
    response = jsonify(
        {
            "ok": True,
            "active_devices": sum(1 for item in devices if item.get("active")),
            "devices": devices,
        }
    )
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


