@webhook_app.route("/api/pulse/music/search", methods=["GET"])
def api_pulse_music_search():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    mood = clean_html(request.args.get("mood") or "")[:80]
    genre = clean_html(request.args.get("genre") or "")[:80]
    language = clean_html(request.args.get("language") or "")[:80]
    lane = clean_html(request.args.get("lane") or "")[:40]
    items = music_service.search_tracks(
        query=clean_html(request.args.get("q") or "")[:120],
        mood=mood,
        genre=genre,
        topic=clean_html(request.args.get("topic") or request.args.get("video_topic") or "")[:160],
        length=safe_int(request.args.get("length") or request.args.get("duration"), 0),
        limit=request.args.get("limit") or 40,
    )
    if language:
        items = [item for item in items if language.lower() in str(item.get("language") or "").lower()]
    if lane == "trending":
        items.sort(key=lambda item: (int(item.get("trend_score") or 0), int(item.get("usage_count") or 0)), reverse=True)
    elif lane in {"new", "new_releases"}:
        items.sort(key=lambda item: str(item.get("id") or ""), reverse=True)
    return jsonify({"ok": True, "items": items[:40], "surfaces": ["reel", "video", "status", "post"], "provider": music_service.provider_status(), "trace_id": secrets.token_hex(6)})


@webhook_app.route("/api/pulse/music/radio", methods=["GET"])
def api_pulse_music_radio():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    limit = safe_int(request.args.get("limit"), 80)
    items = music_service.radio_tracks(limit=limit)
    return jsonify({
        "ok": True,
        "items": items,
        "shuffle": True,
        "surfaces": ["radio", "reel", "video", "status", "post"],
        "provider": music_service.provider_status(),
        "trace_id": secrets.token_hex(6),
    })


