@webhook_app.route("/api/pulse/status", methods=["POST"])
def api_pulse_status_create():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or {}
    trace_id = secrets.token_hex(6)
    try:
        if not request.is_json:
            return pulse_status_error("PulseSoc Status requires a JSON request body.", 415, trace_id, "invalid_content_type")
        body = clean_html(payload.get("body") or "")[:1200]
        status_type = clean_html(payload.get("status_type") or payload.get("type") or "text")[:40]
        raw_media_ids = payload.get("media_ids") or payload.get("media_id") or []
        if isinstance(raw_media_ids, (str, int)):
            raw_media_ids = [raw_media_ids]
        media_ids = [int(x) for x in (raw_media_ids or []) if str(x).isdigit()][:8]
        if status_type == "image":
            status_type = "photo"
        if status_type not in {"text", "photo", "video", "music", "live", "ai"}:
            status_type = "text" if body.strip() and not media_ids else "photo"
        music_track_id = clean_html(payload.get("music_track_id") or "")[:120]
        music_media_id = safe_int(payload.get("music_media_id"), 0)
        if status_type == "text" and not body.strip() and not media_ids:
            return pulse_status_error("Write something or add media before posting a status.", 400, trace_id, "empty_status")
        if status_type == "music" and not (body.strip() or media_ids or music_track_id or music_media_id):
            return pulse_status_error("Choose music or add text before posting.", 400, trace_id, "empty_music_status")
        if not body and not media_ids and status_type not in {"live", "ai", "music", "text"}:
            return pulse_status_error("Add text or media before posting a status.", 400, trace_id, "empty_status")
        now = datetime.utcnow()
        duration_hours = max(1, min(int(payload.get("duration_hours") or 24), 168))
        expires = (now + timedelta(hours=duration_hours)).isoformat(timespec="seconds")
        visibility = clean_html(payload.get("visibility") or "public")[:40]
        if visibility not in {"public", "followers", "private"}:
            visibility = "public"
        ai_context = payload.get("ai_context") or {}
        if not isinstance(ai_context, dict):
            ai_context = {}
        if music_track_id:
            music_payload = music_service.attach_music_payload(music_track_id)
            if not music_payload.get("is_creator_safe"):
                return pulse_status_error("That music track is not approved for PulseSoc use.", 400, trace_id, "music_not_approved")
            ai_context["music"] = music_payload
        raw_status_style = payload.get("status_style") if isinstance(payload.get("status_style"), dict) else {}
        allowed_style = {
            "gradient": {"aurora", "midnight", "sunrise", "emerald", "none"},
            "font_family": {"Inter", "Serif", "Mono", "Display"},
            "text_align": {"left", "center", "right"},
            "card_style": {"soft", "glass", "poster", "minimal"},
        }
        def clean_status_color(value, fallback):
            value = str(value or "").strip()
            return value if re.fullmatch(r"#[0-9a-fA-F]{6}", value) else fallback
        style_gradient = clean_html(str(raw_status_style.get("gradient") or "aurora"))[:40]
        style_font = clean_html(str(raw_status_style.get("font_family") or "Inter"))[:40]
        style_align = clean_html(str(raw_status_style.get("text_align") or "left"))[:20]
        style_card = clean_html(str(raw_status_style.get("card_style") or "soft"))[:40]
        status_style = {
            "background_color": clean_status_color(raw_status_style.get("background_color"), "#111827"),
            "text_color": clean_status_color(raw_status_style.get("text_color"), "#f8fafc"),
            "gradient": style_gradient if style_gradient in allowed_style["gradient"] else "aurora",
            "font_family": style_font if style_font in allowed_style["font_family"] else "Inter",
            "font_size": max(18, min(safe_int(raw_status_style.get("font_size"), 26), 38)),
            "text_align": style_align if style_align in allowed_style["text_align"] else "left",
            "card_style": style_card if style_card in allowed_style["card_style"] else "soft",
            "bold": bool(raw_status_style.get("bold", True)),
            "italic": bool(raw_status_style.get("italic", False)),
        }
        tool_context = {
            "effect_name": clean_html(payload.get("effect_name") or "natural")[:80],
            "sticker": clean_html(payload.get("sticker") or "")[:80],
            "link_url": clean_html(payload.get("link_url") or "")[:500],
            "status_style": status_style,
            "source": "create_status_editor",
        }
        ai_context["status_tools"] = {key: value for key, value in tool_context.items() if value}
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO pulse_status (user_id, status_type, body, media_ids_json, visibility, ai_context_json, created_at, expires_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(user["user_id"]),
                status_type,
                body,
                json.dumps(media_ids),
                visibility,
                json.dumps(ai_context, default=str)[:3000],
                now.isoformat(timespec="seconds"),
                expires,
            ),
        )
        status_id = int(cur.lastrowid)
        for media_id in media_ids:
            cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
            media_row = dict(cur.fetchone() or {})
            if not media_row:
                conn.close()
                return pulse_status_error("Selected media could not be found. Please choose it again.", 400, trace_id, "media_not_found")
            resolved = media_service.resolve_media(media_row)
            cur.execute(
                """
                INSERT INTO pulse_status_media (status_id, media_id, media_url, thumbnail_url, media_type, width, height, aspect_ratio, fit_mode, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'smart', ?)
                """,
                (
                    status_id,
                    media_id,
                    resolved.get("valid_url") or resolved.get("media_url") or "",
                    resolved.get("thumbnail_url") or "",
                    resolved.get("media_type") or status_type,
                    int(resolved.get("width") or 0),
                    int(resolved.get("height") or 0),
                    float(resolved.get("aspect_ratio") or 0),
                    now.isoformat(timespec="seconds"),
                ),
            )
        if music_media_id or music_track_id:
            music_payload = ai_context.get("music") or {}
            cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (music_media_id,))
            media_row = dict(cur.fetchone() or {})
            cur.execute(
                """
                INSERT INTO pulse_status_music (status_id, audio_track_id, title, artist, waveform_json, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    status_id,
                    music_media_id or 0,
                    clean_html(music_payload.get("title") or media_row.get("original_filename") or "Original PulseSoc sound")[:180],
                    clean_html(music_payload.get("artist") or "PulseSoc creator")[:180],
                    json.dumps(music_payload.get("waveform") or [], default=str),
                    now.isoformat(timespec="seconds"),
                ),
            )
            if music_track_id:
                attach_result = pulse_attach_music_to_content(cur, content_type="status", content_id=status_id, track_id=music_track_id, user_id=user["user_id"])
                if not attach_result.get("ok"):
                    conn.close()
                    return pulse_status_error("That music track is not approved for PulseSoc use.", 400, trace_id, "music_not_approved")
        conn.commit()
        cur.execute("SELECT * FROM pulse_status WHERE id=? LIMIT 1", (status_id,))
        status = pulse_status_payload(cur.fetchone(), user["user_id"])
        conn.close()
        first_media = (status.get("media") or [{}])[0] if isinstance(status, dict) else {}
        return jsonify({
            "ok": True,
            "success": True,
            "status": status,
            "status_id": status_id,
            "media_url": first_media.get("valid_url") or first_media.get("media_url") or "",
            "message": "PulseSoc Status created.",
            "trace_id": trace_id,
        })
    except Exception as exc:
        logging.exception("PULSE_STATUS_CREATE_FAILED trace_id=%s user_id=%s error=%s", trace_id, user.get("user_id"), exc)
        return pulse_status_storage_error(exc, trace_id)


@webhook_app.route("/api/pulse/status/<int:status_id>", methods=["PATCH", "DELETE"])
def api_pulse_status_manage(status_id):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_status_error("Login required.", 401, error_code="login_required")
    trace_id = secrets.token_hex(6)
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_status WHERE id=? AND deleted_at IS NULL LIMIT 1", (int(status_id),))
    status = dict(cur.fetchone() or {})
    if not status:
        conn.close()
        return pulse_status_error("Status is no longer available.", 404, trace_id, "status_not_found")
    owner_id = safe_int(status.get("user_id"), 0)
    viewer_id = safe_int(user.get("user_id"), 0)
    if owner_id != viewer_id and not pulse_group_user_is_admin(user):
        conn.close()
        return pulse_status_error("You can only manage your own PulseSoc Status.", 403, trace_id, "status_forbidden")
    now = datetime.utcnow().isoformat(timespec="seconds")
    if request.method == "DELETE":
        try:
            cur.execute("UPDATE pulse_status SET deleted_at=? WHERE id=? AND user_id=?", (now, int(status_id), owner_id))
            try:
                cur.execute("UPDATE pulse_statuses SET deleted_at=? WHERE id=? AND user_id=?", (now, int(status_id), owner_id))
            except Exception:
                pass
            conn.commit()
        except Exception as exc:
            conn.rollback()
            logging.exception("PULSE_STATUS_DELETE_FAILED trace_id=%s user_id=%s status_id=%s error=%s", trace_id, viewer_id, status_id, exc)
            return pulse_status_error("Status could not be deleted.", 500, trace_id, "status_delete_failed")
        finally:
            conn.close()
        pulse_emit_event("pulse_status_deleted", {"status_id": int(status_id), "trace_id": trace_id}, viewer_id, int(status_id))
        return jsonify({"ok": True, "message": "Status deleted.", "status_id": int(status_id), "trace_id": trace_id})

    payload = request.get_json(silent=True) or {}
    body = clean_html(payload.get("body") if "body" in payload else status.get("body") or "")[:1200]
    visibility = clean_html(payload.get("visibility") if "visibility" in payload else status.get("visibility") or "public")[:40]
    if visibility not in {"public", "followers", "private"}:
        conn.close()
        return pulse_status_error("Choose a valid status privacy setting.", 400, trace_id, "invalid_visibility")
    status_type = clean_html(payload.get("status_type") if "status_type" in payload else status.get("status_type") or "text")[:40]
    if status_type == "image":
        status_type = "photo"
    if status_type not in {"text", "photo", "video", "music", "live", "ai"}:
        status_type = clean_html(status.get("status_type") or "text")[:40] or "text"
    try:
        media_ids = json.loads(status.get("media_ids_json") or "[]")
    except Exception:
        media_ids = []
    if status_type in {"text", "music"} and not body.strip() and not media_ids:
        conn.close()
        return pulse_status_error("Add text or media before saving this Status.", 400, trace_id, "empty_status")
    expires_at = status.get("expires_at") or ""
    if "duration_hours" in payload:
        duration_hours = max(1, min(safe_int(payload.get("duration_hours"), 24), 168))
        expires_at = (datetime.utcnow() + timedelta(hours=duration_hours)).isoformat(timespec="seconds")
    try:
        ai_context = json.loads(status.get("ai_context_json") or "{}")
    except Exception:
        ai_context = {}
    if "status_style" in payload and isinstance(payload.get("status_style"), dict):
        raw_style = payload.get("status_style") or {}
        status_tools = ai_context.get("status_tools") if isinstance(ai_context.get("status_tools"), dict) else {}
        allowed_gradient = {"aurora", "midnight", "sunrise", "emerald", "none"}
        allowed_font = {"Inter", "Serif", "Mono", "Display"}
        allowed_align = {"left", "center", "right"}
        allowed_card = {"soft", "glass", "poster", "minimal"}
        def clean_status_color(value, fallback):
            value = str(value or "").strip()
            return value if re.fullmatch(r"#[0-9a-fA-F]{6}", value) else fallback
        style = status_tools.get("status_style") if isinstance(status_tools.get("status_style"), dict) else {}
        style.update({
            "background_color": clean_status_color(raw_style.get("background_color"), style.get("background_color") or "#111827"),
            "text_color": clean_status_color(raw_style.get("text_color"), style.get("text_color") or "#f8fafc"),
            "gradient": clean_html(str(raw_style.get("gradient") or style.get("gradient") or "aurora"))[:40],
            "font_family": clean_html(str(raw_style.get("font_family") or style.get("font_family") or "Inter"))[:40],
            "text_align": clean_html(str(raw_style.get("text_align") or style.get("text_align") or "left"))[:20],
            "card_style": clean_html(str(raw_style.get("card_style") or style.get("card_style") or "soft"))[:40],
            "font_size": max(18, min(safe_int(raw_style.get("font_size"), safe_int(style.get("font_size"), 26)), 38)),
            "bold": bool(raw_style.get("bold", style.get("bold", True))),
            "italic": bool(raw_style.get("italic", style.get("italic", False))),
        })
        if style["gradient"] not in allowed_gradient:
            style["gradient"] = "aurora"
        if style["font_family"] not in allowed_font:
            style["font_family"] = "Inter"
        if style["text_align"] not in allowed_align:
            style["text_align"] = "left"
        if style["card_style"] not in allowed_card:
            style["card_style"] = "soft"
        status_tools["status_style"] = style
        ai_context["status_tools"] = status_tools
    try:
        cur.execute(
            "UPDATE pulse_status SET status_type=?, body=?, visibility=?, ai_context_json=?, expires_at=? WHERE id=? AND user_id=?",
            (status_type, body, visibility, json.dumps(ai_context, default=str)[:3000], expires_at, int(status_id), owner_id),
        )
        conn.commit()
        updated_row = pulse_status_row_for_viewer(cur, status_id, viewer_id)
        updated = pulse_status_payload(updated_row, viewer_id) if updated_row else {}
    except Exception as exc:
        conn.rollback()
        logging.exception("PULSE_STATUS_UPDATE_FAILED trace_id=%s user_id=%s status_id=%s error=%s", trace_id, viewer_id, status_id, exc)
        return pulse_status_error("Status could not be updated.", 500, trace_id, "status_update_failed")
    finally:
        conn.close()
    pulse_emit_event("pulse_status_updated", {"status_id": int(status_id), "trace_id": trace_id}, viewer_id, int(status_id))
    return jsonify({"ok": True, "message": "Status updated.", "status_id": int(status_id), "status": updated, "trace_id": trace_id})


@webhook_app.route("/api/pulse/status/<int:status_id>/view", methods=["POST"])
def api_pulse_status_view(status_id):
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    now = datetime.utcnow().isoformat(timespec="seconds")
    status_row = pulse_status_row_for_viewer(cur, status_id, user["user_id"])
    if not status_row:
        conn.close()
        return jsonify({"ok": False, "message": "Status is no longer available."}), 404
    payload = request.get_json(silent=True) or {}
    completed = bool(payload.get("completed"))
    try:
        raw_completion = float(payload.get("completion_ratio") or payload.get("completion") or (1 if completed else 0) or 0)
    except (TypeError, ValueError):
        raw_completion = 1.0 if completed else 0.0
    completion_ratio = max(0.0, min(1.0, raw_completion))
    watch_ms = max(0, min(600000, safe_int(payload.get("watch_ms") or payload.get("duration_ms"), 0)))
    source = clean_html(payload.get("source") or "viewer")[:80]
    cur.execute("SELECT id, completion_ratio, watch_ms FROM pulse_status_views WHERE status_id=? AND viewer_user_id=? LIMIT 1", (int(status_id), int(user["user_id"])))
    existing_view = dict(cur.fetchone() or {})
    if not existing_view:
        cur.execute(
            "INSERT INTO pulse_status_views (status_id, viewer_user_id, viewed_at, completed_at, completion_ratio, watch_ms, source) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (int(status_id), int(user["user_id"]), now, now if completed else "", completion_ratio, watch_ms, source),
        )
    else:
        next_completion_ratio = max(float(existing_view.get("completion_ratio") or 0), completion_ratio)
        next_watch_ms = max(safe_int(existing_view.get("watch_ms"), 0), watch_ms)
        cur.execute(
            """
            UPDATE pulse_status_views
            SET completed_at=CASE WHEN ?=1 THEN COALESCE(NULLIF(completed_at,''), ?) ELSE completed_at END,
                completion_ratio=?,
                watch_ms=?,
                source=COALESCE(NULLIF(?,''), source)
            WHERE status_id=? AND viewer_user_id=?
            """,
            (1 if completed else 0, now, next_completion_ratio, next_watch_ms, source, int(status_id), int(user["user_id"])),
        )
    cur.execute("SELECT COUNT(DISTINCT viewer_user_id) AS total FROM pulse_status_views WHERE status_id=?", (int(status_id),))
    view_count = int((cur.fetchone() or [0])[0] or 0)
    cur.execute("SELECT AVG(COALESCE(completion_ratio,0)) AS avg_completion FROM pulse_status_views WHERE status_id=? AND COALESCE(completion_ratio,0)>0", (int(status_id),))
    completion_rate = round(float((cur.fetchone() or [0])[0] or 0), 3)
    conn.commit(); conn.close()
    owner_analytics = {}
    if int(status_row.get("user_id") or 0) == int(user["user_id"]):
        owner_analytics = {"views": view_count, "completion_rate": completion_rate}
    return jsonify({"ok": True, "status_id": int(status_id), "view_count": view_count, "completion_rate": completion_rate, "owner_analytics": owner_analytics})


@webhook_app.route("/api/pulse/status/<int:status_id>/react", methods=["POST"])
def api_pulse_status_react(status_id):
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or {}
    reaction = clean_html(payload.get("reaction_type") or "fire")[:40]
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    now = datetime.utcnow().isoformat(timespec="seconds")
    status_row = pulse_status_row_for_viewer(cur, status_id, user["user_id"])
    if not status_row:
        conn.close()
        return jsonify({"ok": False, "message": "Status is no longer available."}), 404
    cur.execute("DELETE FROM pulse_status_reactions WHERE status_id=? AND user_id=?", (int(status_id), int(user["user_id"])))
    cur.execute("INSERT INTO pulse_status_reactions (status_id, user_id, reaction_type, created_at) VALUES (?, ?, ?, ?)", (int(status_id), int(user["user_id"]), reaction, now))
    owner_id = int(status_row.get("user_id") or 0)
    if owner_id and owner_id != int(user["user_id"]):
        notify_user(
            cur,
            owner_id,
            "status_reaction",
            "New status reaction",
            f"{pulse_actor_display_name(user)} reacted to your PulseSoc Status.",
            f"/pulse/status?status_id={int(status_id)}",
            actor_user_id=user["user_id"],
            entity_type="status",
            entity_id=str(status_id),
            metadata={"reaction_type": reaction},
        )
    cur.execute("SELECT COUNT(DISTINCT user_id) AS total FROM pulse_status_reactions WHERE status_id=?", (int(status_id),))
    reaction_count = int((cur.fetchone() or [0])[0] or 0)
    conn.commit(); conn.close()
    return jsonify({"ok": True, "status_id": int(status_id), "reaction_type": reaction, "reaction_count": reaction_count})


@webhook_app.route("/api/pulse/status/<int:status_id>/reply", methods=["POST"])
def api_pulse_status_reply(status_id):
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or {}
    body = clean_html(payload.get("body") or "")[:1000].strip()
    if not body:
        return jsonify({"ok": False, "message": "Reply cannot be empty."}), 400
    trace_id = secrets.token_hex(6)
    try:
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        now = datetime.utcnow().isoformat(timespec="seconds")
        status_row = pulse_status_row_for_viewer(cur, status_id, user["user_id"])
        if not status_row:
            conn.close()
            return jsonify({"ok": False, "message": "Status is no longer available.", "trace_id": trace_id}), 404
        cur.execute(
            "INSERT INTO pulse_status_replies (status_id, user_id, body, created_at) VALUES (?, ?, ?, ?)",
            (int(status_id), int(user["user_id"]), body, now),
        )
        reply_id = int(cur.lastrowid)
        owner_id = int(status_row.get("user_id") or 0)
        if owner_id and owner_id != int(user["user_id"]):
            actor_name = pulse_actor_display_name(user)
            preview = clean_html(body)[:240]
            original_preview = clean_html(status_row.get("body") or status_row.get("status_type") or "PulseSoc Status")[:240]
            notify_user(
                cur,
                owner_id,
                "status_reply",
                "New status reply",
                f"{actor_name} replied: “{preview}”",
                f"/pulse/status?status_id={int(status_id)}&reply_id={reply_id}",
                actor_user_id=user["user_id"],
                entity_type="status_reply",
                entity_id=str(reply_id),
                metadata={
                    "status_id": int(status_id),
                    "reply_id": reply_id,
                    "preview_text": preview,
                    "reply_preview": preview,
                    "original_preview": original_preview,
                    "status_preview": original_preview,
                    "actor_name": actor_name,
                    "actor_avatar": user.get("avatar_url") or "",
                    "content_type": "status_reply",
                    "mobile_deep_link": f"pulse://status/{int(status_id)}/reply/{reply_id}",
                },
            )
        pulse_notify_mentions(
            cur,
            body,
            user,
            note_type="status_mention",
            entity_type="status_reply",
            entity_id=str(reply_id),
            deep_link=f"/pulse/status?status_id={int(status_id)}",
            metadata={"status_id": int(status_id)},
        )
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "reply": {"id": reply_id, "status_id": int(status_id), "body": body, "created_at": now}, "trace_id": trace_id})
    except Exception as exc:
        logging.exception("PULSE_STATUS_REPLY_FAILED trace_id=%s status_id=%s user_id=%s error=%s", trace_id, status_id, user.get("user_id"), exc)
        return jsonify({"ok": False, "message": "Status reply could not be sent.", "trace_id": trace_id}), 500


@webhook_app.route("/api/pulse/status/<int:status_id>/share", methods=["POST"])
def api_pulse_status_share(status_id):
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or {}
    surface = clean_html(payload.get("surface") or payload.get("source") or "viewer")[:80]
    trace_id = secrets.token_hex(6)
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    status_row = pulse_status_row_for_viewer(cur, status_id, user["user_id"])
    if not status_row:
        conn.close()
        return jsonify({"ok": False, "message": "Status is no longer available.", "trace_id": trace_id}), 404
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute(
        "INSERT INTO pulse_status_shares (status_id, user_id, surface, created_at) VALUES (?, ?, ?, ?)",
        (int(status_id), int(user["user_id"]), surface, now),
    )
    cur.execute("SELECT COUNT(*) AS total FROM pulse_status_shares WHERE status_id=?", (int(status_id),))
    share_count = int((cur.fetchone() or [0])[0] or 0)
    conn.commit()
    conn.close()
    return jsonify({"ok": True, "status_id": int(status_id), "share_count": share_count, "trace_id": trace_id})


def pulse_section_shell(title, description, cards=None, primary_href="/pulse#create", primary_label="Create PulseSoc"):
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    card_html = "".join(
        f"<article class='card'><h2>{clean_html(card.get('title') or '')}</h2><p>{clean_html(card.get('description') or '')}</p><div class='actions'><a class='button primary' href='{clean_html(card.get('href') or primary_href)}'>{clean_html(card.get('cta') or primary_label)}</a></div></article>"
        for card in (cards or [])
    )
    if not card_html:
        card_html = f"<article class='card'><h2>Ready when the community is.</h2><p>{clean_html(description)}</p><a class='button primary' href='{clean_html(primary_href)}'>{clean_html(primary_label)}</a></article>"
    nav_html = "".join(f"<a class='button' href='{href}'>{label}</a>" for label, href in [("PulseSoc", "/pulse"), ("Create", "/pulse#create"), ("My Posts", "/pulse/my-posts"), ("Spaces", "/pulse/spaces")])
    return Response(f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{clean_html(title)} | PulseSoc</title><style>:root{{color-scheme:dark;--line:rgba(110,223,246,.22);--muted:#9fb5c0;--cyan:#6edff6;--green:#36e58f}}*{{box-sizing:border-box}}html,body{{max-width:100%;overflow-x:hidden}}body{{margin:0;background:radial-gradient(circle at 12% 0,rgba(110,223,246,.16),transparent 28rem),linear-gradient(145deg,#050b14,#081421);color:#f2fbff;font-family:Inter,system-ui,sans-serif}}.wrap{{width:min(100% - 28px,1100px);margin:auto;padding:20px 0 calc(88px + env(safe-area-inset-bottom))}}.actions,.grid{{display:flex;gap:10px;flex-wrap:wrap}}.grid{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch}}.card{{border:1px solid var(--line);border-radius:16px;background:rgba(13,22,39,.9);padding:16px;margin:12px 0;box-shadow:0 20px 70px rgba(0,0,0,.24)}}h1{{font-size:clamp(36px,7vw,68px);line-height:.96;margin:12px 0}}p{{color:var(--muted);line-height:1.55}}a{{color:inherit}}.button{{min-height:44px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.06);color:#f2fbff;padding:10px 12px;font-weight:900;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}}.primary{{background:linear-gradient(135deg,var(--green),var(--cyan));color:#06101b;border:0}}@media(max-width:820px){{.grid{{grid-template-columns:1fr}}.button{{width:100%}}}}</style></head><body><main class="wrap"><nav class="actions">{nav_html}</nav><section class="card"><h1>{clean_html(title)}</h1><p>{clean_html(description)}</p><p>{clean_html(PULSE_DISCLAIMER)}</p></section><section class="grid">{card_html}</section></main></body></html>""")


def _pulse_primary_label(row=None, badge_keys=None, badge_labels=None):
    try:
        return pulse_identity_engine.primary_label(row, badge_keys, badge_labels)
    except Exception:
        return "Member"


def get_pulse_identity_display(user_id, cur=None):
    close_conn = False
    conn = None
    if cur is None:
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        close_conn = True
    row = {"user_id": user_id}
    try:
        cur.execute(
            """
            SELECT u.user_id, u.username, u.email, u.full_name, u.display_name AS user_display_name,
                   u.display_name, u.avatar_url AS user_avatar_url, u.avatar_url, u.bio, COALESCE(u.cover_url,u.banner_url,'') AS banner_url,
                   u.plan, u.subscription_plan, u.subscription_status, u.is_pro, u.pro_active,
                   u.pro_expires_at, u.subscription_expires_at, u.premium_status, u.premium_expires_at,
                   u.lifetime_premium, u.premium_glow_manual_grant, u.premium_mark_override, u.premium_mark_type,
                   fm.founder_number, fm.founder_tier, fm.status AS founder_status,
                   COALESCE(upp.trust_score,0) AS trust_score, COALESCE(upp.current_level,'New User') AS current_level,
                   la.status AS livestream_status, ap.public_player_id, ap.avatar_url AS arena_avatar_url
            FROM users u
            LEFT JOIN founder_memberships fm ON fm.user_id=u.user_id AND fm.status='active'
            LEFT JOIN arena_profiles ap ON ap.user_id=u.user_id
            LEFT JOIN user_privilege_profiles upp ON upp.user_id=u.user_id
            LEFT JOIN livestream_access la ON la.user_id=u.user_id
            WHERE u.user_id=?
            LIMIT 1
            """,
            (int(user_id or 0),),
        )
        row = dict(cur.fetchone() or row)
    except Exception as exc:
        logging.warning("PULSE_IDENTITY_USER_QUERY_FAILED user_id=%s error=%s", user_id, exc)
    badge_keys = []
    badge_labels = []
    try:
        cur.execute(
            """
            SELECT ub.badge_key, COALESCE(b.label, ub.badge_key) AS label
            FROM pulse_user_badges ub
            LEFT JOIN pulse_badges b ON b.badge_key=ub.badge_key
            WHERE ub.user_id=? AND COALESCE(b.active,1)=1
            ORDER BY ub.id ASC
            LIMIT 24
            """,
            (int(user_id or 0),),
        )
        for badge_row in cur.fetchall():
            item = dict(badge_row)
            key = str(item.get("badge_key") or "")
            label = str(item.get("label") or key)
            if key:
                badge_keys.append(key)
            if label:
                badge_labels.append(label)
    except Exception as exc:
        logging.warning("PULSE_IDENTITY_BADGE_QUERY_FAILED user_id=%s error=%s", user_id, exc)
    identity = pulse_identity_engine.build_identity(row, badge_keys, badge_labels)
    if close_conn and conn:
        conn.close()
    return identity


