def pulse_universal_dock_runtime_script():
    return """
(function(){
  const dock = document.querySelector(".mobile-bottom-nav");
  if (!dock) return;
  if (dock.dataset.universalDockReady === "1") return;
  dock.dataset.universalDockReady = "1";
  dock.classList.add("pulse-universal-dock");
  dock.setAttribute("aria-label", "Primary PulseSoc navigation");
  const createSheet = document.getElementById("createSheet");
  const closeCreateSheet = () => {
    if (!createSheet) return;
    createSheet.classList.remove("open");
    createSheet.setAttribute("aria-hidden", "true");
  };
  const openCreateSheet = () => {
    if (!createSheet) return false;
    createSheet.classList.add("open");
    createSheet.setAttribute("aria-hidden", "false");
    window.setTimeout(() => createSheet.querySelector("button, a")?.focus({ preventScroll: true }), 40);
    return true;
  };
  const items = Array.from(dock.querySelectorAll("[data-pulse-dock-item]"));
  const activeFor = action => {
    const path = location.pathname;
    if (action === "home") return path === "/pulse";
    if (action === "reels") return path.startsWith("/pulse/reels");
    if (action === "messages") return path.startsWith("/pulse/messages");
    if (action === "profile") return path.startsWith("/pulse/profile") || /^\\/pulse\\/@/.test(path);
    return false;
  };
  items.forEach(item => {
    const active = activeFor(item.dataset.dockAction || "");
    item.classList.toggle("is-active", active);
    if (active) item.setAttribute("aria-current", "page");
    else item.removeAttribute("aria-current");
  });
  const modalSelectors = [
    "#createSheet.open",
    "#reelUploadModal.open",
    "#reelMoreModal.open",
    "#reelEditModal.open",
    "#reelDeleteModal.open",
    "#soundModal.open",
    ".pulse-media-lightbox.open",
    ".pulse-promotion-modal.open",
    ".video-owner-sheet.open",
    "[data-status-viewer].open",
    "#pulseStatusStoryViewer.open"
  ];
  let lastY = window.scrollY || 0;
  let hidden = false;
  let ticking = false;
  let keyboardOpen = false;
  const isPinned = () => {
    const active = document.activeElement;
    const typing = active && /^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName);
    return keyboardOpen || typing || document.body.classList.contains("drawer-open") || modalSelectors.some(selector => document.querySelector(selector));
  };
  const setHidden = next => {
    if (isPinned()) next = false;
    if (hidden === next) return;
    hidden = next;
    dock.classList.toggle("is-hidden", hidden);
    document.body.classList.toggle("pulse-dock-hidden", hidden);
  };
  const requestDockUpdate = () => {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => {
      const y = window.scrollY || 0;
      const delta = y - lastY;
      if (Math.abs(delta) > 8) setHidden(delta > 0 && y > 120);
      dock.classList.toggle("is-pinned", isPinned());
      document.body.classList.toggle("pulse-dock-pinned", isPinned());
      lastY = y;
      ticking = false;
    });
  };
  window.addEventListener("scroll", requestDockUpdate, { passive: true });
  window.addEventListener("focusin", requestDockUpdate, true);
  window.addEventListener("focusout", requestDockUpdate, true);
  document.addEventListener("click", event => {
    const createTrigger = event.target.closest("[data-pulse-create-trigger], a[href='/pulse/create'], a[href='#create'], a[href='/pulse#create']");
    if (createTrigger) {
      event.preventDefault();
      const type = createTrigger.dataset.sheetType || createTrigger.dataset.createType || (createTrigger.dataset.openComposerPicker === "video" ? "video" : "text");
      if (typeof window.openPulseComposer === "function") window.openPulseComposer(type);
      else openCreateSheet();
      requestDockUpdate();
      return;
    }
    if (createSheet?.classList.contains("open") && !event.target.closest("#createSheet") && !event.target.closest("[data-pulse-create-trigger]")) {
      closeCreateSheet();
      requestDockUpdate();
    }
  }, true);
  document.addEventListener("keydown", event => {
    if (event.key !== "Escape") return;
    closeCreateSheet();
    requestDockUpdate();
  });
  if (window.visualViewport) {
    const baseHeight = window.visualViewport.height;
    window.visualViewport.addEventListener("resize", () => {
      keyboardOpen = window.visualViewport.height < baseHeight - 90;
      requestDockUpdate();
    }, { passive: true });
  }
  requestDockUpdate();
})();
"""


def pulse_social_shell(title, description, main_html, side_html="", script_html="", show_intro=True):
    user = require_account()
