def pulse_livekit_mux_destination(live):
    stream_key = (live.get("mux_stream_key") or live.get("stream_key") or "").strip()
    if not stream_key:
        return ""
    ingest_url = (live.get("ingest_url") or live.get("rtmp_url") or mux_live_service.MUX_RTMP_INGEST_URL or "").strip().rstrip("/")
    if not ingest_url:
        return ""
    if ingest_url.endswith("/" + stream_key) or ingest_url.endswith(stream_key):
        return ingest_url
    return f"{ingest_url}/{stream_key}"


def pulse_livekit_safe_error(data, fallback="LiveKit egress was rejected."):
    if not isinstance(data, dict):
        return fallback
    parts = []
    for key in ("msg", "message", "error", "details", "code"):
        value = data.get(key)
        if value is None:
            continue
        text = clean_html(str(value))[:240]
        text = re.sub(r"rtmps?://[^\s\"'<>]+", "rtmp://[redacted]", text)
        text = re.sub(r"(stream[_ -]?key|key|token|secret)[=:]\s*[^\s\"'<>]+", r"\1=[redacted]", text, flags=re.IGNORECASE)
        if text and text not in parts:
            parts.append(text)
    message = " | ".join(parts).strip() or fallback
    return message[:500]


def pulse_livekit_egress_resource_exhausted(egress):
    if not isinstance(egress, dict):
        return False
    text = " ".join(
        str(egress.get(key) or "")
        for key in (
            "message",
            "reason",
            "error",
            "participant_error",
            "room_composite_error",
            "status_code",
        )
    ).lower()
    return any(marker in text for marker in ("resource_exhausted", "egress minutes exceeded", "quota", "minutes exceeded"))


def pulse_live_safe_debug_payload(payload, *, max_depth=3):
    blocked_keys = ("secret", "token", "stream_key", "mux_stream_key", "authorization", "password", "rtmp_url", "url")

    def clean_value(value, depth=0):
        if depth > max_depth:
            return "[truncated]"
        if isinstance(value, dict):
            safe = {}
            for key, item in value.items():
                safe_key = clean_html(str(key))[:80]
                if any(marker in safe_key.lower() for marker in blocked_keys):
                    safe[safe_key] = "[redacted]"
                else:
                    safe[safe_key] = clean_value(item, depth + 1)
            return safe
        if isinstance(value, (list, tuple)):
            return [clean_value(item, depth + 1) for item in list(value)[:24]]
        if isinstance(value, bool) or value is None:
            return value
        if isinstance(value, (int, float)):
            return value
        text = clean_html(str(value))[:500]
        text = re.sub(r"rtmps?://[^\s\"'<>]+", "rtmp://[redacted]", text)
        text = re.sub(r"(token|secret|stream[_ -]?key|authorization)[=:]\s*[^\s\"'<>]+", r"\1=[redacted]", text, flags=re.IGNORECASE)
        return text

    return clean_value(payload if isinstance(payload, dict) else {"value": payload})


def pulse_live_record_timeline_event(cur, event_type, *, live_id=0, actor_user_id=0, payload=None, post_id=0):
    now = datetime.utcnow().isoformat(timespec="seconds")
    event_name = clean_html(event_type or "live_debug_event")[:80]
    if not event_name.startswith("live_"):
        event_name = f"live_{event_name}"
    safe_payload = pulse_live_safe_debug_payload({
        "live_id": int(live_id or 0),
        "event": event_name,
        **(payload if isinstance(payload, dict) else {}),
    })
    cur.execute(
        "INSERT INTO pulse_live_events (event_type, actor_user_id, post_id, payload_json, created_at) VALUES (?, ?, ?, ?, ?)",
        (event_name, int(actor_user_id or 0), int(post_id or 0), json.dumps(safe_payload, default=str)[:8000], now),
    )
    return {"event": event_name, "created_at": now}


