@webhook_app.route("/api/pulse/live/<int:live_id>/cohost/debug", methods=["GET"])
def api_pulse_live_cohost_debug(live_id):
    trace_id = clean_html(request.args.get("trace_id") or secrets.token_hex(6))[:80]
    pulse_live_cohost_step_log(trace_id, "debug_entry_received", live_id=live_id, payload={"path": request.path})
    if live_id <= 0:
        return pulse_live_cohost_error("INVALID_LIVE_ID", status=400, step="entry_validation", trace_id=trace_id)
    user = api_account_user()
    if not user or not int(user.get("user_id") or 0):
        return pulse_live_cohost_error("AUTH_FAILED", status=401, step="auth_validation", trace_id=trace_id, live_id=live_id)
    result = {
        "ok": True,
        "trace_id": trace_id,
        "live_id": live_id,
        "live_id_exists": False,
        "live_status": "missing",
        "viewer_authenticated": True,
        "viewer_id": int(user["user_id"]),
        "viewer_exists": False,
        "live_owner_id": 0,
        "host_exists": False,
        "cohost_enabled": False,
        "viewer_is_host": False,
        "viewer_banned": False,
        "db_connection_ok": False,
        "schema_ok": False,
        "schema_snapshot": {},
        "duplicate_request_check": False,
        "insert_possible": False,
    }
    try:
        init_db()
        conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
        result["db_connection_ok"] = True
        cur.execute("SELECT user_id FROM users WHERE user_id=? LIMIT 1", (user["user_id"],))
        result["viewer_exists"] = bool(cur.fetchone())
        cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
        live = dict(cur.fetchone() or {})
        result["live_id_exists"] = bool(live)
        result["live_status"] = pulse_live_cohost_live_status(live) if live else "missing"
        result["live_owner_id"] = int(live.get("user_id") or 0) if live else 0
        if result["live_owner_id"]:
            cur.execute("SELECT user_id FROM users WHERE user_id=? LIMIT 1", (result["live_owner_id"],))
            result["host_exists"] = bool(cur.fetchone())
        result["cohost_enabled"] = bool(live and pulse_live_session_accepts_guest_requests(live))
        result["viewer_is_host"] = bool(live and pulse_live_is_host(live, user))
        result["viewer_banned"] = bool(live and pulse_live_user_is_blocked(cur, live_id, user["user_id"]))
        latest = pulse_live_latest_guest_request(cur, live_id, user["user_id"]) if live else {}
        result["duplicate_request_check"] = bool(latest and latest.get("status") == "pending")
        schema_ok = False
        try:
            schema_snapshot = pulse_live_guest_request_schema_snapshot(cur)
            schema_ok = bool(schema_snapshot.get("schema_ok"))
            result["schema_ok"] = schema_ok
            result["schema_snapshot"] = schema_snapshot
        except Exception as schema_exc:
            result["schema_error_type"] = type(schema_exc).__name__
            if pulse_live_cohost_debug_enabled():
                result["debug_error"] = clean_html(str(schema_exc))[:500]
            logging.exception("PULSE_COHOST_DEBUG_SCHEMA_FAILED trace_id=%s live_id=%s user_id=%s", trace_id, live_id, user["user_id"])
        result["insert_possible"] = bool(
            live
            and result["live_status"] == "active"
            and result["viewer_exists"]
            and result["host_exists"]
            and result["cohost_enabled"]
            and not result["viewer_is_host"]
            and not result["viewer_banned"]
            and not result["duplicate_request_check"]
            and schema_ok
        )
        conn.close()
    except Exception as exc:
        result["error_code"] = "DB_CONNECTION_FAILED"
        result["step"] = "db_connection"
        result["error_type"] = type(exc).__name__
        if pulse_live_cohost_debug_enabled():
            result["debug_error"] = clean_html(str(exc))[:500]
        logging.exception("PULSE_COHOST_DEBUG_FAILED trace_id=%s live_id=%s user_id=%s", trace_id, live_id, user["user_id"])
        try:
            conn.close()
        except Exception:
            pass
    pulse_live_cohost_step_log(trace_id, "debug_completed", live_id=live_id, viewer_user_id=user["user_id"], payload=result)
    return jsonify(result)


