@webhook_app.route("/api/pulse/live/<int:live_id>/join-status", methods=["GET"])
def api_pulse_live_join_status(live_id):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_live_cohost_error("NOT_AUTHENTICATED", status=401, live_id=live_id)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
    live = dict(cur.fetchone() or {})
    if not live:
        conn.close()
        return pulse_live_cohost_error("LIVE_NOT_FOUND", status=404, live_id=live_id, viewer_user_id=user.get("user_id"))
    latest = pulse_live_latest_guest_request(cur, live_id, user["user_id"])
    guest = pulse_live_active_guest(cur, live_id, user["user_id"])
    conn.close()
    status = latest.get("status") if latest else "none"
    cohost_step = "host_accepted" if guest else "waiting_for_host" if status == "pending" else "request_denied" if status == "denied" else "request_cancelled" if status == "cancelled" else "request_expired" if status == "expired" else "idle"
    return jsonify({
        "ok": True,
        "live_id": live_id,
        "status": status,
        "step": cohost_step,
        "error_code": "REQUEST_DENIED" if status == "denied" else "REQUEST_EXPIRED" if status == "expired" else "",
        "message": PULSE_COHOST_ERROR_CODES.get("REQUEST_DENIED")[0] if status == "denied" else PULSE_COHOST_ERROR_CODES.get("REQUEST_EXPIRED")[0] if status == "expired" else "Waiting for host approval." if status == "pending" else "",
        "request": pulse_live_guest_request_payload(latest) if latest else None,
        "guest": pulse_live_guest_payload(guest) if guest else None,
        "can_publish": bool(guest),
        "livekit_configured": bool(pulse_livekit_config().get("configured")),
        "token_url": f"/api/pulse/live/{live_id}/livekit/token" if guest else "",
    })


@webhook_app.route("/api/pulse/live/<int:live_id>/cohost-trace", methods=["POST"])
def api_pulse_live_cohost_trace(live_id):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_live_cohost_error("NOT_AUTHENTICATED", status=401, live_id=live_id)
    payload = request.get_json(silent=True) or {}
    trace_id = clean_html(payload.get("trace_id") or secrets.token_hex(6))[:80]
    step = clean_html(payload.get("step") or "cohost_failure")[:80]
    error_code = clean_html(payload.get("error_code") or "")[:80].upper()
    request_id = safe_int(payload.get("request_id"), 0)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
        live = dict(cur.fetchone() or {})
        if not live:
            conn.close()
            return pulse_live_cohost_error("LIVE_NOT_FOUND", status=404, trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)
        viewer_user_id = safe_int(payload.get("viewer_user_id"), 0) or int(user.get("user_id") or 0)
        is_host = pulse_live_is_host(live, user) or bool(admin_current_user())
        if viewer_user_id != int(user.get("user_id") or 0) and not is_host:
            conn.close()
            return pulse_live_cohost_error("NOT_AUTHORIZED", status=403, trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), host_user_id=live.get("user_id"), request_id=request_id)
        details = payload.get("details") if isinstance(payload.get("details"), dict) else {}
        pulse_live_cohost_trace(
            cur,
            live_id=live_id,
            viewer_user_id=viewer_user_id,
            host_user_id=int(live.get("user_id") or 0),
            request_id=request_id,
            step=step,
            trace_id=trace_id,
            error_code=error_code,
            status="failed" if error_code else "ok",
            metadata={"source": clean_html(details.get("source") or "live_room")[:40], **details},
            post_id=int(live.get("feed_post_id") or 0),
        )
        conn.commit(); conn.close()
        return jsonify({"ok": True, "trace_id": trace_id, "step": step})
    except Exception as exc:
        logging.exception("PULSE_LIVE_COHOST_TRACE_FAILED live_id=%s user_id=%s error=%s", live_id, user.get("user_id"), exc)
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        return pulse_live_cohost_error("UNKNOWN_COHOST_ERROR", status=500, message="Co-host trace could not be recorded.", trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)


@webhook_app.route("/api/pulse/live/<int:live_id>/cohost/trace/<trace_id>", methods=["GET"])
def api_pulse_live_cohost_trace_detail(live_id, trace_id):
    init_db()
    user = api_account_user()
    trace_id = clean_html(trace_id or "")[:80]
    if not user:
        return pulse_live_cohost_error("AUTH_FAILED", status=401, step="trace_lookup", trace_id=trace_id, live_id=live_id)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
    live = dict(cur.fetchone() or {})
    if not live:
        conn.close()
        return pulse_live_cohost_error("LIVE_NOT_FOUND", status=404, step="trace_lookup", trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"))
    is_host = pulse_live_is_host(live, user) or bool(admin_current_user())
    cur.execute("SELECT * FROM pulse_live_audit_logs WHERE live_id=? ORDER BY id DESC LIMIT 400", (live_id,))
    stages = []
    for row in cur.fetchall():
        item = dict(row)
        try:
            metadata = json.loads(item.get("metadata_json") or "{}")
        except Exception:
            metadata = {}
        if str(metadata.get("trace_id") or "") != trace_id:
            continue
        if not is_host and int(item.get("actor_user_id") or 0) != int(user.get("user_id") or 0):
            continue
        stages.append({
            "stage_number": int(metadata.get("stage_number") or 0),
            "stage_name": clean_html(metadata.get("stage_name") or item.get("action") or "")[:100],
            "step": clean_html(metadata.get("step") or item.get("action") or "")[:80],
            "started_at": clean_html(metadata.get("started_at") or item.get("created_at") or "")[:80],
            "completed_at": clean_html(metadata.get("completed_at") or "")[:80],
            "duration_ms": max(0, safe_int(metadata.get("duration_ms"), 0)),
            "result": clean_html(metadata.get("result") or item.get("status") or "")[:40],
            "error_code": clean_html(metadata.get("error_code") or "")[:80],
            "error_message": clean_html(metadata.get("error_message") or "")[:500],
        })
    conn.close()
    stages.reverse()
    failed_stage = next((stage for stage in reversed(stages) if stage.get("result") in {"failed", "error"} or stage.get("error_code")), None)
    return jsonify({"ok": True, "trace_id": trace_id, "live_id": live_id, "stage_count": len(stages), "stages": stages, "failed_stage": failed_stage})


@webhook_app.route("/api/pulse/live/<int:live_id>/join-requests", methods=["GET"])
def api_pulse_live_join_requests(live_id):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_live_cohost_error("NOT_AUTHENTICATED", status=401, live_id=live_id)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
    live = dict(cur.fetchone() or {})
    if not live:
        conn.close()
        return pulse_live_cohost_error("LIVE_NOT_FOUND", status=404, live_id=live_id, viewer_user_id=user.get("user_id"))
    if not pulse_live_is_host(live, user) and not admin_current_user():
        conn.close()
        return pulse_live_cohost_error("NOT_AUTHORIZED", status=403, message="Only the live host can manage join requests.", live_id=live_id, viewer_user_id=user.get("user_id"), host_user_id=live.get("user_id"))
    requests = pulse_live_pending_guest_requests(cur, live_id)
    guests = pulse_live_active_guests(cur, live_id)
    conn.close()
    return jsonify({"ok": True, "requests": requests, "guests": guests})


@webhook_app.route("/api/pulse/live/<int:live_id>/join-requests/<int:request_id>/<action>", methods=["POST"])
def api_pulse_live_join_request_action(live_id, request_id, action):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_live_cohost_error("NOT_AUTHENTICATED", status=401, live_id=live_id, request_id=request_id)
    action = clean_html(action or "")[:24].lower()
    if action not in {"accept", "deny"}:
        return pulse_live_cohost_error("UNKNOWN_COHOST_ERROR", status=400, message="Invalid join request action.", live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)
    payload = request.get_json(silent=True) or {}
    trace_id = clean_html(payload.get("trace_id") or secrets.token_hex(6))[:80]
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    current_step = "request_action_entry"
    target_user_id = 0
    transaction_started_at = time.perf_counter()
    try:
        pulse_live_cohost_step_log(trace_id, "request_action_entry", live_id=live_id, viewer_user_id=user["user_id"], payload={"request_id": request_id, "action": action, "authenticated_user_id": int(user["user_id"])})
        current_step = "live_lookup"
        cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
        live = dict(cur.fetchone() or {})
        if not live:
            conn.close()
            return pulse_live_cohost_error("LIVE_NOT_FOUND", status=404, trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)
        if not pulse_live_is_host(live, user) and not admin_current_user():
            conn.close()
            return pulse_live_cohost_error("NOT_AUTHORIZED", status=403, message="Only the live host can manage join requests.", trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), host_user_id=live.get("user_id"), request_id=request_id)
        cur.execute(
            """
            SELECT r.*, COALESCE(u.display_name,u.username,'Viewer') AS display_name, COALESCE(u.avatar_url,'') AS avatar_url
            FROM pulse_live_guest_requests r
            LEFT JOIN users u ON u.user_id=r.user_id
            WHERE r.id=? AND r.live_id=? LIMIT 1
            """,
            (request_id, live_id),
        )
        guest_request = dict(cur.fetchone() or {})
        if not guest_request:
            conn.close()
            return pulse_live_cohost_error("REQUEST_NOT_FOUND", status=404, trace_id=trace_id, live_id=live_id, viewer_user_id=0, host_user_id=live.get("user_id"), request_id=request_id)
        if guest_request.get("status") != "pending":
            conn.close()
            prior = str(guest_request.get("status") or "closed").lower()
            code = "REQUEST_DENIED" if prior == "denied" else "REQUEST_EXPIRED" if prior == "expired" else "UNKNOWN_COHOST_ERROR"
            return pulse_live_cohost_error(code, status=409, message=f"Join request is already {prior}.", trace_id=trace_id, live_id=live_id, viewer_user_id=guest_request.get("user_id"), host_user_id=live.get("user_id"), request_id=request_id)
        target_user_id = int(guest_request.get("user_id") or 0)
        pulse_live_cohost_step_log(trace_id, "request_action_loaded", live_id=live_id, viewer_user_id=target_user_id, payload={"request_id": request_id, "action": action, "host_user_id": int(live.get("user_id") or 0), "requester_user_id": target_user_id, "authenticated_user_id": int(user["user_id"]), "request_status": guest_request.get("status")})
        request_trace = {}
        try:
            request_trace = json.loads(guest_request.get("audit_json") or "{}")
        except Exception:
            request_trace = {}
        if action == "accept" and request_trace.get("trace_id"):
            trace_id = clean_html(request_trace.get("trace_id"))[:80]
        if action == "deny":
            reason = clean_html(payload.get("reason") or "Host denied the request.")[:280]
            current_step = "request_denial_update"
            cur.execute(
                "UPDATE pulse_live_guest_requests SET status='denied', denied_reason=?, host_action_by=?, host_action_at=?, updated_at=? WHERE id=? AND live_id=? AND status='pending'",
                (reason, user["user_id"], now, now, request_id, live_id),
            )
            if cur.rowcount != 1:
                conn.rollback(); conn.close()
                return pulse_live_cohost_error("UNKNOWN_COHOST_ERROR", status=409, message="Join request was already handled.", trace_id=trace_id, live_id=live_id, viewer_user_id=target_user_id, host_user_id=live.get("user_id"), request_id=request_id)
            pulse_live_audit(cur, live_id, user["user_id"], "join_request_denied", target_user_id=target_user_id, metadata={"request_id": request_id, "reason": reason})
            pulse_live_cohost_trace(cur, live_id=live_id, viewer_user_id=target_user_id, host_user_id=int(live.get("user_id") or 0), request_id=request_id, step="cohost_failure", trace_id=trace_id, error_code="REQUEST_DENIED", status="denied", post_id=int(live.get("feed_post_id") or 0))
            pulse_live_record_timeline_event(cur, "live_guest_request_denied", live_id=live_id, actor_user_id=user["user_id"], post_id=int(live.get("feed_post_id") or 0), payload={"request_id": request_id, "target_user_id": target_user_id})
            notify_user(
                cur,
                target_user_id,
                "cohost_denied",
                "Co-host request denied",
                reason or "The host denied your co-host request.",
                pulse_live_watch_url(live_id),
                actor_user_id=user["user_id"],
                entity_type="live",
                entity_id=str(live_id),
                metadata={
                    "event_type": "cohost_denied",
                    "live_id": live_id,
                    "request_id": request_id,
                    "trace_id": trace_id,
                    "priority": "normal",
                    "mobile_deep_link": f"pulse://reels?live={live_id}",
                    "deep_link": pulse_live_watch_url(live_id),
                },
            )
            conn.commit(); conn.close()
            return jsonify({"ok": True, "status": "denied", "step": "request_denied", "error_code": "REQUEST_DENIED", "trace_id": trace_id, "request_id": request_id, "message": "Join request denied."})
        if not pulse_live_session_accepts_guest_requests(live):
            conn.close()
            return pulse_live_cohost_error("HOST_NOT_ACCEPTING_GUESTS", status=409, message="This Live is no longer accepting guests.", trace_id=trace_id, live_id=live_id, viewer_user_id=target_user_id, host_user_id=live.get("user_id"), request_id=request_id)
        room_name = clean_html(live.get("webrtc_room_id") or f"pulse-live-{live_id}")[:120]
        identity = f"pulse-live-guest-{int(live_id)}-{target_user_id}-{request_id}"
        pulse_live_cohost_step_log(trace_id, "cohost_identity_generated", live_id=live_id, viewer_user_id=target_user_id, payload={"stage_number": 12, "identity": identity, "room": room_name, "request_id": request_id})
        current_step = "request_acceptance_update"
        cur.execute(
            "UPDATE pulse_live_guest_requests SET status='accepted', host_action_by=?, host_action_at=?, updated_at=? WHERE id=? AND live_id=? AND status='pending'",
            (user["user_id"], now, now, request_id, live_id),
        )
        if cur.rowcount != 1:
            conn.rollback(); conn.close()
            return pulse_live_cohost_error("UNKNOWN_COHOST_ERROR", status=409, message="Join request was already handled.", trace_id=trace_id, live_id=live_id, viewer_user_id=target_user_id, host_user_id=live.get("user_id"), request_id=request_id)
        current_step = "active_guest_revocation"
        cur.execute(
            "UPDATE pulse_live_guests SET status='removed', removed_at=?, removed_by=?, updated_at=? WHERE live_id=? AND user_id=? AND status IN ('active','accepted','joining','joined','publishing','live')",
            (now, user["user_id"], now, live_id, target_user_id),
        )
        current_step = "guest_permission_insert"
        cur.execute(
            """
            INSERT INTO pulse_live_guests
                (live_id, user_id, request_id, status, guest_role, livekit_identity, livekit_room, audio_muted, video_enabled, layout_position, joined_at, created_at, updated_at, permissions_json, metadata_json)
            VALUES (?, ?, ?, 'accepted', 'cohost', ?, ?, 0, 1, 0, ?, ?, ?, ?, ?)
            """,
            (
                live_id,
                target_user_id,
                request_id,
                identity,
                room_name,
                None,
                now,
                now,
                json.dumps({"can_publish_audio": True, "can_publish_video": True, "can_share_screen": False}, default=str),
                json.dumps({"approved_by": user["user_id"], "request_id": request_id, "role": "cohost", "trace_id": trace_id}, default=str),
            ),
        )
        guest_id = int(cur.lastrowid)
        guest = pulse_live_active_guest(cur, live_id, target_user_id)
        current_step = "request_acceptance_commit"
        conn.commit()
        pulse_live_cohost_step_log(trace_id, "cohost_host_accepted", live_id=live_id, viewer_user_id=target_user_id, payload={"stage_number": 11, "request_id": request_id, "guest_id": guest_id, "state": "accepted"})
        try:
            pulse_live_audit(cur, live_id, user["user_id"], "join_request_accepted", target_user_id=target_user_id, metadata={"request_id": request_id, "guest_id": guest_id, "trace_id": trace_id})
            pulse_live_cohost_trace(cur, live_id=live_id, viewer_user_id=target_user_id, host_user_id=int(live.get("user_id") or 0), request_id=request_id, step="cohost_host_accepted", trace_id=trace_id, metadata={"guest_id": guest_id, "result": "completed"}, post_id=int(live.get("feed_post_id") or 0))
            pulse_live_cohost_trace(cur, live_id=live_id, viewer_user_id=target_user_id, host_user_id=int(live.get("user_id") or 0), request_id=request_id, step="cohost_identity_generated", trace_id=trace_id, metadata={"guest_id": guest_id, "identity": identity, "room": room_name, "result": "completed"}, post_id=int(live.get("feed_post_id") or 0))
            pulse_live_record_timeline_event(cur, "live_guest_request_accepted", live_id=live_id, actor_user_id=user["user_id"], post_id=int(live.get("feed_post_id") or 0), payload={"request_id": request_id, "guest_id": guest_id, "target_user_id": target_user_id, "trace_id": trace_id})
            cur.execute(
                "INSERT INTO pulse_live_chat (live_id, user_id, body, message_type, moderation_status, pinned, metadata_json, created_at) VALUES (?, ?, ?, 'system', 'approved', 0, ?, ?)",
                (live_id, user["user_id"], f"{guest_request.get('display_name') or 'A viewer'} was approved to join Live.", json.dumps({"kind": "guest_accepted", "request_id": request_id, "guest_id": guest_id, "trace_id": trace_id}, default=str), now),
            )
            notify_user(
                cur,
                target_user_id,
                "cohost_accepted",
                "Co-host request accepted",
                "The host approved your co-host request. Join the Live now.",
                pulse_live_watch_url(live_id),
                actor_user_id=user["user_id"],
                entity_type="live",
                entity_id=str(live_id),
                metadata={
                    "event_type": "cohost_accepted",
                    "live_id": live_id,
                    "request_id": request_id,
                    "guest_id": guest_id,
                    "trace_id": trace_id,
                    "priority": "high",
                    "mobile_deep_link": f"pulse://reels?live={live_id}",
                    "deep_link": pulse_live_watch_url(live_id),
                },
            )
            conn.commit()
        except Exception as side_effect_exc:
            conn.rollback()
            logging.exception("PULSE_COHOST_ACCEPT_SIDE_EFFECT_FAILED trace_id=%s live_id=%s request_id=%s guest_id=%s error=%s", trace_id, live_id, request_id, guest_id, side_effect_exc)
        conn.close()
        try:
            pulse_emit_event("live_cohost_request_accepted", {"live_id": live_id, "request_id": request_id, "guest_id": guest_id, "viewer_user_id": target_user_id, "host_user_id": int(live.get("user_id") or 0), "trace_id": trace_id}, user["user_id"], int(live.get("feed_post_id") or 0))
        except Exception:
            logging.exception("PULSE_COHOST_ACCEPT_REALTIME_FAILED trace_id=%s live_id=%s request_id=%s", trace_id, live_id, request_id)
        return jsonify({"ok": True, "status": "accepted", "step": "host_accepted", "trace_id": trace_id, "request_id": request_id, "guest": pulse_live_guest_payload(guest), "message": "Guest approved."})
    except Exception as exc:
        logging.exception("PULSE_LIVE_JOIN_REQUEST_ACTION_FAILED live_id=%s request_id=%s action=%s user_id=%s error=%s", live_id, request_id, action, user.get("user_id"), exc)
        owner_debug = pulse_live_log_db_exception(exc, trace_id=trace_id, live_id=live_id, viewer_user_id=target_user_id or user.get("user_id"), host_user_id=user.get("user_id"), request_id=request_id, stage=current_step, transaction_started_at=transaction_started_at)
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        return pulse_live_cohost_error("ACCEPTANCE_TRANSACTION_FAILED" if action == "accept" else "REQUEST_PIPELINE_FAILED", status=500, step=current_step or ("request_acceptance" if action == "accept" else "request_denial"), trace_id=trace_id, live_id=live_id, viewer_user_id=target_user_id or user.get("user_id"), request_id=request_id, debug_error=exc, diagnostic=owner_debug.get("db_error"))


@webhook_app.route("/api/pulse/live/<int:live_id>/join-requests/<int:request_id>/cancel", methods=["POST"])
def api_pulse_live_join_request_cancel(live_id, request_id):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_live_cohost_error("NOT_AUTHENTICATED", status=401, live_id=live_id, request_id=request_id)
    payload = request.get_json(silent=True) or {}
    trace_id = clean_html(payload.get("trace_id") or secrets.token_hex(6))[:80]
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_live_guest_requests WHERE id=? AND live_id=? LIMIT 1", (request_id, live_id))
    guest_request = dict(cur.fetchone() or {})
    if not guest_request:
        conn.close()
        return pulse_live_cohost_error("REQUEST_NOT_FOUND", status=404, trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)
    if int(guest_request.get("user_id") or 0) != int(user["user_id"] or 0):
        conn.close()
        return pulse_live_cohost_error("NOT_AUTHORIZED", status=403, message="Only the requesting viewer can cancel this request.", trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)
    if guest_request.get("status") != "pending":
        conn.close()
        prior = str(guest_request.get("status") or "closed").lower()
        code = "REQUEST_DENIED" if prior == "denied" else "REQUEST_EXPIRED" if prior == "expired" else "UNKNOWN_COHOST_ERROR"
        return pulse_live_cohost_error(code, status=409, message=f"Join request is already {prior}.", trace_id=trace_id, live_id=live_id, viewer_user_id=user.get("user_id"), request_id=request_id)
    cur.execute("UPDATE pulse_live_guest_requests SET status='cancelled', cancelled_at=?, updated_at=? WHERE id=?", (now, now, request_id))
    pulse_live_audit(cur, live_id, user["user_id"], "join_request_cancelled", target_user_id=user["user_id"], metadata={"request_id": request_id})
    pulse_live_cohost_trace(cur, live_id=live_id, viewer_user_id=user["user_id"], host_user_id=int(guest_request.get("host_user_id") or 0), request_id=request_id, step="cohost_failure", trace_id=trace_id, error_code="REQUEST_CANCELLED", status="cancelled")
    conn.commit(); conn.close()
    return jsonify({"ok": True, "status": "cancelled", "step": "request_cancelled", "trace_id": trace_id, "request_id": request_id, "message": "Join request cancelled."})


@webhook_app.route("/api/pulse/live/<int:live_id>/guests/<int:guest_id>/<action>", methods=["POST"])
def api_pulse_live_guest_action(live_id, guest_id, action):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    action = clean_html(action or "")[:24].lower()
    if action not in {"mute", "unmute", "remove", "leave"}:
        return api_error("Invalid guest action.", 400)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
        live = dict(cur.fetchone() or {})
        if not live:
            conn.close()
            return api_error("Live stream not found.", 404)
        cur.execute("SELECT * FROM pulse_live_guests WHERE id=? AND live_id=? LIMIT 1", (guest_id, live_id))
        guest = dict(cur.fetchone() or {})
        if not guest:
            conn.close()
            return api_error("Guest not found.", 404)
        is_host = pulse_live_is_host(live, user) or bool(admin_current_user())
        is_self_guest = int(guest.get("user_id") or 0) == int(user["user_id"] or 0)
        if action in {"mute", "unmute", "remove"} and not is_host:
            conn.close()
            return api_error("Only the host can manage guests.", 403)
        if action == "leave" and not is_self_guest:
            conn.close()
            return api_error("Only the guest can leave their guest slot.", 403)
        if action in {"mute", "unmute"}:
            muted = 1 if action == "mute" else 0
            cur.execute("UPDATE pulse_live_guests SET audio_muted=?, updated_at=? WHERE id=?", (muted, now, guest_id))
            pulse_live_audit(cur, live_id, user["user_id"], f"guest_{action}", target_user_id=int(guest.get("user_id") or 0), metadata={"guest_id": guest_id})
            conn.commit(); conn.close()
            return jsonify({"ok": True, "status": "muted" if muted else "unmuted", "guest_id": guest_id})
        next_status = "left" if action == "leave" else "removed"
        cur.execute(
            "UPDATE pulse_live_guests SET status=?, left_at=CASE WHEN ?='left' THEN ? ELSE left_at END, removed_at=CASE WHEN ?='removed' THEN ? ELSE removed_at END, removed_by=?, updated_at=? WHERE id=?",
            (next_status, next_status, now, next_status, now, user["user_id"], now, guest_id),
        )
        if int(guest.get("request_id") or 0):
            cur.execute("UPDATE pulse_live_guest_requests SET status=?, updated_at=? WHERE id=?", (next_status, now, int(guest.get("request_id") or 0)))
        pulse_live_audit(cur, live_id, user["user_id"], f"guest_{next_status}", target_user_id=int(guest.get("user_id") or 0), metadata={"guest_id": guest_id})
        pulse_live_record_timeline_event(cur, f"live_guest_{next_status}", live_id=live_id, actor_user_id=user["user_id"], post_id=int(live.get("feed_post_id") or 0), payload={"guest_id": guest_id, "target_user_id": int(guest.get("user_id") or 0)})
        conn.commit(); conn.close()
        return jsonify({"ok": True, "status": next_status, "guest_id": guest_id})
    except Exception as exc:
        logging.exception("PULSE_LIVE_GUEST_ACTION_FAILED live_id=%s guest_id=%s action=%s user_id=%s error=%s", live_id, guest_id, action, user.get("user_id"), exc)
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        return api_error("Guest action could not be completed.", 500)


@webhook_app.route("/api/pulse/live/<int:live_id>/end", methods=["POST"])
def api_pulse_live_end(live_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_live_sessions WHERE id=? LIMIT 1", (live_id,))
    live = dict(cur.fetchone() or {})
    if not live:
        conn.close()
        return api_error("Live stream not found.", 404)
    if int(live.get("user_id") or 0) != int(user["user_id"] or 0) and not admin_current_user():
        conn.close()
        return api_error("Only the host or an admin can end this stream.", 403)
    replay_url = clean_html((request.get_json(silent=True) or {}).get("replay_url") or live.get("replay_url") or "")[:700]
    replay_is_cdn = bool(replay_url and replay_url.startswith((os.getenv("R2_PUBLIC_BASE_URL", "").rstrip("/") or "https://cdn.coinpilotx.app") + "/"))
    recording_status = "replay_ready" if replay_is_cdn else "replay_unavailable"
    recording_error = "" if replay_is_cdn else "No durable live recording asset was produced for this session."
    viewer_count = int(live.get("viewer_count") or 0)
    cur.execute(
        "UPDATE pulse_live_sessions SET status='ended', publish_state='ended', stream_health='ended', replay_url=?, recording_status=?, recording_error=?, ended_at=?, updated_at=? WHERE id=?",
        (replay_url if replay_is_cdn else "", recording_status, recording_error, now, now, live_id),
    )
    cur.execute("UPDATE pulse_live_streams SET status='ended', ended_at=?, updated_at=? WHERE session_id=?", (now, now, live_id))
    cur.execute("UPDATE pulse_live_viewers SET status='left', left_at=?, last_seen_at=? WHERE live_id=? AND status IN ('watching','hosting')", (now, now, live_id))
    feed_post_id = live_feed_service.mark_live_feed_ended(cur, live_id=live_id, replay_url=replay_url if replay_is_cdn else "", viewer_count=viewer_count)
    live_restream_service.mark_targets_ended(cur, live_id=live_id)
    share_options = live_archive_share_service.create_post_live_options(cur, live_id=live_id, replay_url=replay_url if replay_is_cdn else "")
    cur.execute("INSERT INTO pulse_live_chat (live_id, user_id, body, message_type, moderation_status, pinned, metadata_json, created_at) VALUES (?, ?, 'Live stream ended.', 'system', 'approved', 1, ?, ?)", (live_id, user["user_id"], json.dumps({"kind": "ended"}, default=str), now))
    conn.commit(); conn.close()
    replay_playback_id = live.get("mux_recording_playback_id") or ""
    replay_playback_url = f"https://stream.mux.com/{replay_playback_id}.m3u8" if replay_playback_id else (replay_url if replay_is_cdn else "")
    if replay_playback_url:
        try:
            pulse_video_index_upsert(
                user["user_id"], "replay", live_id, 0, live.get("title") or "PulseSoc Live Replay",
                live.get("description") or "", live.get("visibility") or "public",
                media={
                    "media_type": "video",
                    "media_url": replay_url if replay_is_cdn else "",
                    "playback_url": replay_playback_url,
                    "mux_playback_id": replay_playback_id,
                    "mux_asset_id": live.get("mux_recording_asset_id") or "",
                    "mux_status": "ready",
                    "processing_status": "ready",
                    "thumbnail_url": live.get("thumbnail_url") or "",
                },
            )
        except Exception:
            logging.exception("PULSE_LIVE_REPLAY_INDEX_FAILED live_id=%s", live_id)
        try:
            conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
            replay_notifications = pulse_notify_followers(
                cur,
                user,
                "replay_available",
                "Live replay available",
                f"{pulse_actor_display_name(user)} has a new PulseSoc Live replay.",
                pulse_live_watch_url(live_id, "replay"),
                entity_type="live_replay",
                entity_id=str(live_id),
                metadata={"live_id": live_id, "replay_url_present": True},
            )
            conn.commit(); conn.close()
            logging.info("PULSE_LIVE_REPLAY_NOTIFICATIONS live_id=%s count=%s", live_id, replay_notifications)
        except Exception:
            logging.exception("PULSE_LIVE_REPLAY_NOTIFY_FAILED live_id=%s", live_id)
    try:
        pulse_emit_event("livestream_ended", {"live_id": live_id, "message": "Live stream ended."}, user["user_id"], None)
    except Exception:
        logging.exception("PULSE_LIVE_END_EMIT_FAILED live_id=%s", live_id)
    return jsonify({
        "ok": True,
        "message": "Live stream ended.",
        "live_id": live_id,
        "feed_post_id": feed_post_id,
        "recording_status": recording_status,
        "recording_error": recording_error,
        "replay_url": replay_url if replay_is_cdn else "",
        "replay_available": replay_is_cdn,
        "post_live_options": share_options,
    })


@webhook_app.route("/pulse/creator-status", methods=["GET"])
def pulse_creator_status_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    profile = pulse_trust_profile_for_user(cur, user)
    conn.commit(); conn.close()
    privileges = profile["privileges"]
    refs = profile["referrals"]
    unlocked = "".join(f"<li>{clean_html(k.replace('_',' ').title())}</li>" for k, v in privileges.items() if k.startswith("can_") and v is True)
    locked = "".join(f"<li>{clean_html(step)}</li>" for step in privileges.get("required_next_steps") or [])
    badges = "".join(f"<span class='pill'>{clean_html(badge)}</span> " for badge in privileges.get("profile_badges") or [])
    main = f"""
    <section class='card'><h2>{clean_html(privileges['current_level'])}</h2><p>Trust score: {int(profile['trust_score'])}/100 · {clean_html(profile['trust_band'])}</p><p>{badges or '<span class="pill">Growing Creator</span>'}</p></section>
    <section class='card'><h2>Your Next Unlock</h2><p>Invite 30 real members for Live: {refs['completed']}/{refs['required']} completed.</p><a class='button primary' href='/pulse/invite'>Grow Creator Level</a></section>
    <section class='grid'><article class='card'><h2>Unlocked Privileges</h2><ul>{unlocked or '<li>Basic PulseSoc posting and community access.</li>'}</ul></article><article class='card'><h2>Next Steps</h2><ul>{locked or '<li>You are ready for advanced creator tools.</li>'}</ul></article></section>
    """
    return pulse_social_shell("Creator Status", "Grow your creator level, earn verified trust, unlock Live, and build safely.", main)


@webhook_app.route("/pulse/create/camera", methods=["GET"])
def pulse_creator_camera_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    filters = ["Beauty Glow", "Smooth Skin", "Bright Eyes", "Cyber Neon", "Golden Trader", "Arena Energy", "Crypto Glow", "Studio Pro", "Night Vision", "Soft Portrait", "Sharp HD", "Meme Pop", "Scam Alert Red", "Teacher Clean"]
    filter_buttons = "".join(f"<button data-filter='{clean_html(name)}'>{clean_html(name)}</button>" for name in filters)
    main = f"""
    <section class='card'><h2>Creator Camera</h2><p>Take a photo, upload media, preview filters, then post to PulseSoc. If native camera is unavailable, file upload is used.</p><input id='cameraFile' type='file' accept='image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime' capture='environment'><div id='cameraPreview' class='card'><p class='muted'>Preview appears here.</p></div><div class='actions'>{filter_buttons}</div><textarea id='cameraCaption' placeholder='Add caption...'></textarea><button class='primary' id='cameraPost'>Post to PulseSoc</button></section>
    """
    script = """
    const preview=document.getElementById('cameraPreview');let selectedFilter='';document.getElementById('cameraFile').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const url=URL.createObjectURL(file);preview.innerHTML=file.type.startsWith('video/')?`<video src="${url}" controls playsinline style="width:100%;border-radius:14px"></video>`:`<img src="${url}" alt="filter preview" style="width:100%;border-radius:14px">`;});document.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;selectedFilter=b.dataset.filter;preview.style.filter=selectedFilter.includes('Bright')?'brightness(1.18) contrast(1.05)':selectedFilter.includes('Night')?'contrast(1.25) saturate(.8)':selectedFilter.includes('Sharp')?'contrast(1.16) saturate(1.1)':'saturate(1.15)';toast(selectedFilter+' preview applied. Original is preserved.');});document.getElementById('cameraPost').addEventListener('click',()=>toast('Filtered posting pipeline is ready for media upload. Use Full Composer for final publish.'));
    """
    return pulse_social_shell("Creator Camera", "Mobile-first creator filters, captions, stickers-ready architecture, and short media upload.", main, "", script)


@webhook_app.route("/pulse/spaces", methods=["GET"])
def pulse_spaces_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT space_slug, COUNT(*) AS total FROM pulse_space_members GROUP BY space_slug")
    counts = {dict(row).get("space_slug"): int(dict(row).get("total") or 0) for row in cur.fetchall()}
    conn.close()
    cards = ""
    for space in PULSE_SPACES:
        metrics = space_discovery_engine.score_space(space, counts.get(space["slug"], space.get("member_count", 0)))
        featured = " featured-space" if space.get("featured") else ""
        cards += f"<article class='card{featured}'><span class='pill'>{clean_html(space.get('category') or 'Community')}</span><h2>{clean_html(space['name'])}</h2><p>{clean_html(space['description'])}</p><p><span class='pill'>{clean_html(space.get('region') or 'Global')}</span> <span class='pill'>{counts.get(space['slug'], space.get('member_count',0))} members</span> <span class='pill'>Trust {metrics['trust_score']}%</span> <span class='pill'>Energy {metrics['activity_score']}%</span></p><div class='mini-chart'><span style='width:{int(metrics['score'])}%'></span></div><div class='actions'><a class='button primary' href='/pulse/spaces/{space['slug']}'>Open Space</a><button data-join-space='{space['slug']}'>Join</button><a class='button' href='/pulse?topic={space['slug']}'>Preview</a></div></article>"
    script = "document.addEventListener('click',async e=>{const b=e.target.closest('[data-join-space]');if(!b)return;try{await pulseApi('/api/pulse/spaces/join',{method:'POST',body:JSON.stringify({space_slug:b.dataset.joinSpace})});toast('Joined space.')}catch(err){toast(err.message)}});"
    return pulse_social_shell("PulseSoc Spaces", "Global intelligence communities for countries, crypto, cybersecurity, creators, sports, AI, business, and education.", f"<style>.featured-space{{border-color:rgba(255,209,102,.4);box-shadow:0 0 34px rgba(255,209,102,.14)}}.mini-chart{{height:8px;border-radius:999px;background:rgba(255,255,255,.08);overflow:hidden}}.mini-chart span{{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#36e58f,#6edff6,#ffd166)}}</style><section class='grid'>{cards}</section>", "", script)


@webhook_app.route("/pulse/spaces/<slug>", methods=["GET"])
def pulse_space_detail_page(slug):
    init_db()
    space = next((item for item in PULSE_SPACES if item["slug"] == slug), None)
    if not space:
        return pulse_section_shell("PulseSoc Space", "This space is being prepared.", [{"title": "Explore Spaces", "description": "Find active CoinPilotXAI communities.", "href": "/pulse/spaces", "cta": "Browse Spaces"}])
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT title, body, post_type, topic, quality_score, energy_score, created_at FROM pulse_ai_posts WHERE space_slug=? AND status IN ('published','queued','pending_approval') ORDER BY id DESC LIMIT 3", (slug,))
    ai_posts = [dict(row) for row in cur.fetchall()]
    conn.close()
    ai_html = "".join(f"<article class='card'><span class='pill'>PulseSoc Intelligence</span> <span class='pill'>{clean_html(row.get('post_type') or 'insight')}</span><h3>{clean_html(row.get('title') or 'Space intelligence')}</h3><p>{clean_html((row.get('body') or '')[:420])}{'...' if len(row.get('body') or '') > 420 else ''}</p><p><span class='pill'>Quality {int(row.get('quality_score') or 0)}%</span> <span class='pill'>Energy {int(row.get('energy_score') or 0)}%</span> <span class='pill'>{clean_html(row.get('topic') or 'topic')}</span></p></article>" for row in ai_posts)
    main = f"""
    <section class='card'><h2>Pinned Knowledge</h2><p>{clean_html(space['description'])}</p><p>Discussion prompt: What is one useful lesson, warning, question, or resource you can share with this space today?</p><div class='actions'><button class='primary' data-join-space='{clean_html(slug)}'>Join Space</button><a class='button' href='/pulse#create'>Create Full Post</a></div></section>
    <section class='card'><h2>AI Intelligence Drops</h2><p class='muted'>This space receives morning and evening educational prompts designed to spark safer, smarter discussion.</p>{ai_html or '<p class="muted">The first AI intelligence drops are scheduled.</p>'}</section>
    <section class='card'><h2>Create in {clean_html(space['name'])}</h2><textarea id='spacePostBody' placeholder='Share a lesson, warning, question, or update for this space.'></textarea><button class='primary' id='spacePostBtn'>Post to Space</button></section>
    <section class='card'><h2>Space Feed</h2><p>Posts tagged for this space appear below.</p></section>
    <iframe title='Space feed' src='/pulse?topic={clean_html(slug)}' style='width:100%;min-height:760px;border:0;border-radius:16px;background:#071321'></iframe>
    """
    script = f"""
    document.addEventListener('click',async e=>{{const b=e.target.closest('[data-join-space]');if(!b)return;try{{await pulseApi('/api/pulse/spaces/join',{{method:'POST',body:JSON.stringify({{space_slug:b.dataset.joinSpace}})}});toast('Joined {clean_html(space['name'])}.')}}catch(err){{toast(err.message)}}}});
    document.getElementById('spacePostBtn').addEventListener('click',async()=>{{const body=document.getElementById('spacePostBody').value;try{{const d=await pulseApi('/api/pulse/spaces/post',{{method:'POST',body:JSON.stringify({{space_slug:'{clean_html(slug)}',body}})}});location.href=d.next_url;}}catch(err){{toast(err.message)}}}});
    """
    return pulse_social_shell(space["name"], "A focused PulseSoc Space with resources, contributors, and live discussion.", main, "", script)


def pulse_camera_feature_enabled():
    return str(os.getenv("PULSE_CAMERA_ENABLED", "false")).strip().lower() in {"1", "true", "yes", "on"}


def pulse_banuba_safe_diagnostics():
    return {
        "pulse_camera_enabled": pulse_camera_feature_enabled(),
        "banuba_token_present": bool(os.getenv("BANUBA_TOKEN")),
    }


def pulse_camera_safe_public_config(target="feed", mode="photo"):
    target = clean_html(target or "feed")
    mode = clean_html(mode or "photo")
    diagnostics = pulse_banuba_safe_diagnostics()
    banuba_ready = bool(diagnostics["pulse_camera_enabled"] and diagnostics["banuba_token_present"])
    return {
        "enabled": diagnostics["pulse_camera_enabled"],
        "provider": "banuba" if banuba_ready else "native_fallback",
        "target": target,
        "mode": mode,
        "uploadEndpoint": "/api/pulse/media/upload",
        "configEndpoint": "/api/pulse/camera/config",
        "banuba": {
            "enabled": banuba_ready,
            "token_present": diagnostics["banuba_token_present"],
            "public_client_token": "",
        },
        "fallback": {
            "enabled": True,
            "type": "device_file_picker",
            "accept": "image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime",
        },
        "targets": ["status", "reel", "feed", "post", "message", "live"],
        "phase2": {"live": "placeholder", "voice": "placeholder", "video_calls": "placeholder"},
    }


@webhook_app.route("/api/pulse/camera/config", methods=["GET"])
def api_pulse_camera_config():
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required.", "camera": pulse_camera_safe_public_config()}), 401
    target = clean_html(request.args.get("target") or "feed")
    mode = clean_html(request.args.get("mode") or "photo")
    public_config = pulse_camera_safe_public_config(target, mode)
    return jsonify({
        "ok": True,
        "camera": public_config,
        "diagnostics": pulse_banuba_safe_diagnostics(),
    })


