def premium_user_is_grantable(user):
    return bool(user and (int(user.get("lifetime_premium") or 0) == 1 or int(user.get("premium_glow_manual_grant") or 0) == 1 or str(user.get("premium_status") or "").lower() in {"active", "founder", "lifetime"}))


def grant_pulse_premium(cur, user_id, actor_id=0, source="manual"):
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute(
        "UPDATE users SET premium_status='active', lifetime_premium=1, premium_glow_manual_grant=1, premium_mark_override=1, premium_mark_type='star', updated_at=? WHERE user_id=?",
        (now, int(user_id)),
    )
    for entitlement in ["premium_identity", "creator_ai", "advanced_analytics", "premium_studio", "livestream_prestige"]:
        cur.execute(
            """
            INSERT INTO pulse_premium_entitlements (user_id, entitlement_key, source, status, granted_by, starts_at, created_at, updated_at)
            VALUES (?, ?, ?, 'active', ?, ?, ?, ?)
            ON CONFLICT(user_id, entitlement_key) DO UPDATE SET status='active', source=excluded.source, granted_by=excluded.granted_by, updated_at=excluded.updated_at
            """,
            (int(user_id), entitlement, source, int(actor_id or 0), now, now, now),
        )
    cur.execute(
        """
        INSERT INTO pulse_premium_profiles (user_id, tier, aura_style, badge_style, status, granted_by, created_at, updated_at)
        VALUES (?, 'premium', 'founder_gold', 'elite_creator', 'active', ?, ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET status='active', tier='premium', updated_at=excluded.updated_at, granted_by=excluded.granted_by
        """,
        (int(user_id), int(actor_id or 0), now, now),
    )
    cur.execute(
        """
        INSERT INTO pulse_profile_themes (user_id, theme_key, accent_color, background_style, active, created_at, updated_at)
        VALUES (?, 'midnight_elite', '#ffd166', 'premium_gradient', 1, ?, ?)
        ON CONFLICT(user_id, theme_key) DO UPDATE SET active=1, updated_at=excluded.updated_at
        """,
        (int(user_id), now, now),
    )
    cur.execute(
        "INSERT INTO pulse_premium_audit_logs (actor_id, target_user_id, action, metadata_json, created_at) VALUES (?, ?, 'grant', ?, ?)",
        (int(actor_id or 0), int(user_id), json.dumps({"source": source}), now),
    )


@webhook_app.route("/pulse/premium/activate", methods=["GET"])
def pulse_premium_activate_page():
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=False)
    init_db()
    uid = int(user.get("user_id") or 0)
    if premium_entitlement_service.is_founder_member(uid):
        return redirect("/pulse/premium")
    checkout_ready = founder_checkout_configured()
    cta = "<button class='button primary' type='button' data-founder-checkout>Activate Founder Membership</button>" if checkout_ready else "<a class='button primary' href='/pulse/premium'>Back to Premium</a>"
    notice = "" if checkout_ready else "<p class='premium-empty-state'>Founder checkout is being connected. Admin Founder access is available now.</p>"
    body = """
        <section class='card premium-promo-card'>
          <span class='premium-badge'>Founder Access</span>
          <h2>Founder Access Available</h2>
          <p>Become a PulseSoc Founder. Lock in Premium for $4.99/month forever before public pricing increases to $9.99/month.</p>
          {notice}
          <div class='actions'>{cta}<a class='button' href='/pulse'>Explore Free PulseSoc</a><a class='button' href='/pulse/premium'>Back to Premium</a></div>
        </section>
        """.format(notice=notice, cta=cta)
    script = """
    document.addEventListener('click',async e=>{const b=e.target.closest('[data-founder-checkout]');if(!b)return;b.disabled=true;b.textContent='Opening Stripe...';try{const d=await pulseApi('/api/premium/checkout',{method:'POST',body:JSON.stringify({plan_key:'founder_premium'})});location.href=d.url||d.checkout_url}catch(err){toast(err.message||'Founder checkout is being connected. Admin Founder access is available now.');b.disabled=false;b.textContent='Activate Founder Membership'}});
    """
    return pulse_social_shell("Premium Activation", "Founder checkout is verified by Stripe before access changes.", body, "", script)


@webhook_app.route("/api/pulse/premium/activate", methods=["POST"])
def pulse_premium_activate_api():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    try:
        uid = int(user.get("user_id") or 0)
        if premium_entitlement_service.is_founder_member(uid):
            return jsonify({"ok": True, "message": "Founder Premium is already active.", "founder": premium_entitlement_service.founder_membership(uid)})
        if founder_checkout_configured():
            session_obj, error = create_founder_checkout_session(user)
            url = getattr(session_obj, "url", "") if session_obj else ""
            if not url and session_obj:
                url = session_obj.get("url", "")
            if url:
                return jsonify({"ok": True, "message": "Opening Founder checkout.", "url": url, "checkout_url": url})
            return jsonify({"ok": False, "message": error or "Founder checkout is temporarily unavailable.", "payment": founder_checkout_status_payload()}), 503
        return jsonify({
            "ok": False,
            "message": "Founder checkout is being connected. Admin Founder access is available now.",
            "coming_soon": True,
            "payment": founder_checkout_status_payload(),
        }), 200
    except Exception as exc:
        trace_id = secrets.token_hex(6)
        logging.exception("PULSE_PREMIUM_ACTIVATE_FAILED trace_id=%s user_id=%s", trace_id, user.get("user_id"))
        return jsonify({"ok": False, "message": str(exc), "trace_id": trace_id}), 500


@webhook_app.route("/api/pulse/premium/identity-effects", methods=["GET", "POST"])
def pulse_premium_identity_effects_api():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    if request.method == "GET":
        cur.execute("SELECT effect_key, label, effect_type, premium_only, status, metadata_json FROM pulse_identity_effects WHERE status='active' ORDER BY id")
        effects = [dict(row) for row in cur.fetchall()]
        conn.close()
        return jsonify({"ok": True, "premium": premium_visibility_engine.is_premium_user(user), "effects": effects})
    data = request.get_json(silent=True) or request.form.to_dict()
    effect_key = str(data.get("effect_key") or "founder_gold")[:80]
    if not premium_visibility_engine.is_premium_user(user):
        conn.close()
        return api_error("Premium identity effects require PulseSoc Premium.", 403)
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute(
        """
        INSERT INTO pulse_premium_profiles (user_id, aura_style, status, created_at, updated_at)
        VALUES (?, ?, 'active', ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET aura_style=excluded.aura_style, updated_at=excluded.updated_at
        """,
        (int(user.get("user_id") or 0), effect_key, now, now),
    )
    conn.commit(); conn.close()
    return jsonify({"ok": True, "message": "Identity effect updated.", "effect_key": effect_key})


@webhook_app.route("/api/pulse/premium/profile-theme", methods=["GET", "POST"])
def pulse_premium_profile_theme_api():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    if request.method == "GET":
        cur.execute("SELECT * FROM pulse_profile_themes WHERE user_id=? AND active=1 ORDER BY updated_at DESC LIMIT 1", (int(user.get("user_id") or 0),))
        theme = cur.fetchone()
        conn.close()
        return jsonify({"ok": True, "theme": dict(theme) if theme else {"theme_key": "midnight_elite", "accent_color": "#ffd166"}})
    if not premium_visibility_engine.is_premium_user(user):
        conn.close()
        return api_error("Premium profile themes require PulseSoc Premium.", 403)
    data = request.get_json(silent=True) or request.form.to_dict()
    theme_key = str(data.get("theme_key") or "midnight_elite")[:80]
    accent = str(data.get("accent_color") or "#ffd166")[:32]
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("UPDATE pulse_profile_themes SET active=0 WHERE user_id=?", (int(user.get("user_id") or 0),))
    cur.execute(
        """
        INSERT INTO pulse_profile_themes (user_id, theme_key, accent_color, background_style, active, created_at, updated_at)
        VALUES (?, ?, ?, 'premium_gradient', 1, ?, ?)
        ON CONFLICT(user_id, theme_key) DO UPDATE SET active=1, accent_color=excluded.accent_color, updated_at=excluded.updated_at
        """,
        (int(user.get("user_id") or 0), theme_key, accent, now, now),
    )
    conn.commit(); conn.close()
    return jsonify({"ok": True, "message": "Profile theme updated.", "theme_key": theme_key})


def creator_ai_payload(kind, text, topic=""):
    seed = clean_html((text or topic or "your next PulseSoc post").strip())[:700]
    topic = clean_html((topic or "creator growth").strip())[:120]
    if kind == "hook":
        output = f"Most people scroll past {topic} because the first line feels safe. Try this: {seed[:90] or 'Here is the simple mistake creators keep making'}... and make the next sentence reveal the tension."
    elif kind == "caption":
        output = f"{seed}\n\nMake it useful in one swipe: one clear lesson, one proof point, one question people can answer fast."
    elif kind == "virality":
        score = min(94, max(41, 58 + len(seed) // 18 + (12 if "?" in seed else 0)))
        return {"score": score, "retention_tip": "Open with contrast, keep paragraphs under two lines, and end with a specific question.", "risk_note": "No guaranteed outcomes or misleading claims detected by the safety heuristic."}
    else:
        output = f"{topic.title()} Live: the useful breakdown people can join before it gets noisy"
    return {"output": output, "safety": "educational framing; no guaranteed profit, betting pick, or unsafe instruction"}


@webhook_app.route("/api/pulse/creator-ai/<tool>", methods=["POST"])
def pulse_creator_ai_tool_api(tool):
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    tool = str(tool or "").strip().lower()
    if tool not in {"hook", "caption", "virality", "live-title"}:
        return api_error("Unknown creator AI tool.", 404)
    data = request.get_json(silent=True) or request.form.to_dict()
    payload = creator_ai_payload(tool, data.get("text") or data.get("caption") or data.get("idea") or "", data.get("topic") or data.get("category") or "")
    return jsonify({"ok": True, "tool": tool, **payload})


@webhook_app.route("/pulse/creator/dashboard", methods=["GET"])
def pulse_creator_dashboard_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=False)
    uid = int(user.get("user_id") or 0)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    def count(sql, params=()):
        try:
            cur.execute(sql, params)
            return int(dict(cur.fetchone() or {}).get("total") or 0)
        except Exception:
            return 0
    posts = count("SELECT COUNT(*) AS total FROM pulse_posts WHERE user_id=? AND deleted_at IS NULL", (uid,))
    reels = count("SELECT COUNT(*) AS total FROM pulse_reels WHERE user_id=? AND COALESCE(status,'active')='active'", (uid,))
    statuses = count("SELECT COUNT(*) AS total FROM pulse_status WHERE user_id=?", (uid,))
    followers = count("SELECT COUNT(*) AS total FROM pulse_follows WHERE followed_user_id=?", (uid,))
    comments_today = count("SELECT COUNT(*) AS total FROM pulse_comments c JOIN pulse_posts p ON p.id=c.post_id WHERE p.user_id=? AND c.created_at>=?", (uid, (datetime.utcnow()-timedelta(days=1)).isoformat(timespec="seconds")))
    shares_today = count("SELECT COALESCE(SUM(share_count),0) AS total FROM pulse_posts WHERE user_id=?", (uid,))
    saves_today = count("SELECT COUNT(*) AS total FROM pulse_saved_items WHERE user_id=?", (uid,))
    views_today = count("SELECT COUNT(*) AS total FROM pulse_status_views v JOIN pulse_status s ON s.id=v.status_id WHERE s.user_id=? AND v.created_at>=?", (uid, (datetime.utcnow()-timedelta(days=1)).isoformat(timespec="seconds")))
    cur.execute("SELECT p.id, p.title, p.body, p.post_type, p.created_at, COALESCE(p.engagement_score,0) AS engagement_score FROM pulse_posts p WHERE p.user_id=? AND p.deleted_at IS NULL ORDER BY engagement_score DESC, created_at DESC LIMIT 5", (uid,))
    top_posts = [dict(r) for r in cur.fetchall()]
    cur.execute("SELECT id, original_filename, media_type, mime_type, media_url, playback_url, mux_playback_id, created_at FROM chat_media_uploads WHERE uploader_user_id=? ORDER BY id DESC LIMIT 8", (uid,))
    media_rows = [dict(r) for r in cur.fetchall()]
    conn.close()
    total_content = posts + reels + statuses
    engagement_rate = round(((comments_today + shares_today + saves_today) / max(posts, 1)) * 100, 1) if posts else 0
    metric_cards = [
        ("Total Posts", posts), ("Total Reels", reels), ("Total Statuses", statuses), ("Followers", followers),
        ("Engagement Rate", f"{engagement_rate}%"), ("Views Today", views_today), ("Comments Today", comments_today), ("Saves", saves_today), ("Shares", shares_today),
    ]
    metric_html = "".join(f"<article class='studio-metric'><span>{clean_html(label)}</span><strong>{clean_html(str(value))}</strong></article>" for label, value in metric_cards)
    shortcuts = [("Create Post","/pulse#create"),("Create Reel","/pulse/reels"),("Create Status","/pulse/status"),("PulseSoc Music","/pulse/music"),("Start Live","/pulse/live/studio?context_type=creator_studio"),("Upload Video","/pulse#pulseComposer"),("Drafts","/pulse/my-posts"),("Scheduled Posts","/pulse/creator/dashboard#calendar")]
    shortcut_html = "".join(f"<a class='studio-shortcut' href='{clean_html(href)}'>{clean_html(label)}</a>" for label, href in shortcuts)
    top_html = "".join(f"<article class='studio-list-row'><strong>{clean_html(p.get('title') or p.get('body') or 'PulseSoc post')}</strong><span>{clean_html(p.get('post_type') or 'post')} · score {int(p.get('engagement_score') or 0)}</span></article>" for p in top_posts) or "<p class='muted'>Not enough data yet. Publish a few posts and Reels to unlock stronger analytics.</p>"
    media_html = "".join(f"<article class='studio-media-card'><span>{clean_html(m.get('media_type') or 'media')}</span><strong>{clean_html(m.get('original_filename') or 'Uploaded media')}</strong><small>{clean_html(m.get('mime_type') or '')}</small></article>" for m in media_rows) or "<p class='muted'>No uploaded media yet. Upload images or videos from PulseSoc Composer or Reels.</p>"
    tools = [("Hook generator","hook"),("Caption enhancer","caption"),("Reel idea generator","hook"),("Hashtag generator","caption"),("Scam-safe wording checker","virality"),("Education content assistant","caption"),("Live title generator","live-title"),("Community post ideas","hook")]
    tool_html = "".join(f"<button type='button' data-ai-tool='{tool}'>{clean_html(label)}</button>" for label, tool in tools)
    main = f"""
    <style>
    body:has(.creator-studio) .wrap{{width:min(100% - 28px,1500px)}}body:has(.creator-studio) .layout{{grid-template-columns:minmax(0,1fr)}}body:has(.creator-studio) .layout>aside{{display:none}}
    .creator-studio{{display:grid;grid-template-columns:220px minmax(0,1fr) 300px;gap:14px;align-items:start}}.studio-sidebar,.studio-right{{position:sticky;top:12px;display:grid;gap:10px}}.studio-main{{display:grid;gap:14px;min-width:0}}.studio-hero h2{{font-size:clamp(38px,7vw,78px);line-height:.9;margin:6px 0}}.studio-tabs,.studio-shortcuts,.studio-tool-row{{display:flex;gap:8px;flex-wrap:wrap}}.studio-tabs a,.studio-shortcut{{text-decoration:none;border:1px solid rgba(110,223,246,.18);border-radius:999px;padding:9px 12px;background:rgba(255,255,255,.05);font-weight:900}}.studio-metrics{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}}.studio-metric{{border:1px solid rgba(110,223,246,.15);border-radius:16px;padding:14px;background:rgba(255,255,255,.05)}}.studio-metric span{{display:block;color:#9fb5c0}}.studio-metric strong{{font-size:clamp(26px,4vw,42px)}}.studio-section-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}}.studio-list-row,.studio-media-card{{border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:12px;background:rgba(255,255,255,.04);display:grid;gap:4px}}.studio-media-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}}.studio-output{{white-space:pre-wrap;min-height:58px}}@media(max-width:1050px){{.creator-studio{{grid-template-columns:1fr}}.studio-sidebar,.studio-right{{position:static}}.studio-metrics,.studio-section-grid{{grid-template-columns:1fr}}}}
    </style>
    <section class='creator-studio' data-creator-studio>
      <aside class='studio-sidebar card'><h3>Creator Studio</h3><nav class='studio-tabs'><a href='#overview'>Overview</a><a href='#content'>Content</a><a href='#analytics'>Analytics</a><a href='#live'>Live</a><a href='#monetization'>Monetization</a><a href='#media'>Media Library</a><a href='#resources'>Resources</a></nav></aside>
      <main class='studio-main'>
        <section class='card studio-hero' id='overview'><span class='badge'>Full Creator Studio</span><h2>Build your PulseSoc creator engine.</h2><p>Use real PulseSoc activity where available. Empty analytics tell the truth and show what to create next.</p></section>
        <section class='studio-metrics'>{metric_html}</section>
        <section class='card' id='content'><h2>Content Studio</h2><div class='studio-shortcuts'>{shortcut_html}</div></section>
        <section class='card' id='creator-ai'><h2>Creator AI Tools</h2><p>Paste an idea and choose a tool.</p><textarea id='creatorAiText' placeholder='Post idea, Reel caption, lesson topic, live title, or marketplace product...'></textarea><div class='studio-tool-row'>{tool_html}</div><pre class='card studio-output' id='creatorAiOutput'>Creator AI output appears here.</pre></section>
        <section class='studio-section-grid' id='analytics'><article class='card'><h2>Analytics</h2><div>{top_html}</div></article><article class='card'><h2>Growth Tools</h2><p>Trending topics, creator challenges, recommended rooms, collaboration suggestions, audience questions, and content calendar.</p><a class='button primary' href='/pulse/groups'>Find Rooms</a></article></section>
        <section class='studio-section-grid'><article class='card' id='monetization'><h2>Monetization / Marketplace</h2><p>Creator products, services, digital downloads, paid rooms, paid lessons, premium content readiness, and payout checklist.</p><a class='button primary' href='/pulse/marketplace/create'>Create Product</a></article><article class='card' id='live'><h2>Live Studio</h2><p>Mux Live setup, protected stream key, live status, replay library, and upcoming schedule.</p><a class='button primary' href='/pulse/live/studio?context_type=creator_studio'>Open Live Studio</a></article></section>
        <section class='card' id='media'><h2>Media Library</h2><div class='studio-media-grid'>{media_html}</div></section>
        <section class='studio-section-grid'><article class='card'><h2>Safety / Trust</h2><p>Scam Shield score, flagged content, moderation guidance, trust signals, and creator safety checklist.</p><button type='button' data-ai-tool='virality'>Run Trust Check</button></article><article class='card' id='resources'><h2>Resources</h2><p>Creator guides, better Reels, audience growth, safe selling, live setup, and PulseSoc AI playbooks.</p><a class='button' href='/pulse/teachers'>Open Guides</a></article></section>
      </main>
      <aside class='studio-right'><section class='card'><h3>PulseSoc Intelligence</h3><p>Total creator items: {total_content}</p><p>{'You have enough activity for useful recommendations.' if total_content >= 5 else 'Create at least five items to unlock stronger recommendations.'}</p></section><section class='card'><h3>Premium</h3><p>{'Premium active.' if premium_visibility_engine.is_premium_user(user) else 'Premium tools are previewing. Activate when checkout opens.'}</p><a class='button primary' href='/pulse/premium'>Open Premium</a></section></aside>
    </section>
    """
    script = """
    document.querySelectorAll('[data-ai-tool]').forEach(btn=>btn.addEventListener('click',async()=>{const out=document.getElementById('creatorAiOutput');out.textContent='Thinking...';try{const d=await pulseApi(`/api/pulse/creator-ai/${btn.dataset.aiTool}`,{method:'POST',body:JSON.stringify({text:document.getElementById('creatorAiText')?.value||btn.textContent,topic:'PulseSoc creator studio'})});out.textContent=d.output||JSON.stringify(d,null,2);toast('Creator AI ready.')}catch(err){out.textContent=err.message;toast(err.message)}}));
    """
    return pulse_social_shell("Creator Studio", "A complete PulseSoc creator dashboard for content, AI tools, analytics, live, monetization, media, growth, safety, and resources.", main, "", script)


def pulse_gateway_card_html(title, body, actions=None, disabled_actions=None):
    actions = actions or []
    disabled_actions = disabled_actions or []
    action_html = "".join(
        f"<a class='button {'primary' if i == 0 else ''}' href='{clean_html(href)}'>{clean_html(label)}</a>"
        for i, (label, href) in enumerate(actions)
    )
    disabled_html = "".join(
        f"<button type='button' disabled title='{clean_html(reason)}'>{clean_html(label)}</button>"
        for label, reason in disabled_actions
    )
    return (
        "<section class='card pulse-gateway-card'>"
        f"<h2>{clean_html(title)}</h2>"
        f"<p class='muted'>{clean_html(body)}</p>"
        f"<div class='actions'>{action_html}{disabled_html}</div>"
        "</section>"
    )


