@webhook_app.route("/admin/premium-command", methods=["GET", "POST"])
def admin_premium_command_page():
    init_db()
    premium_entitlement_service.ensure_founder_schema()
    admin, denied = require_admin_page("settings.edit")
    if denied:
        return denied
    message = ""
    if request.method == "POST":
        if not verify_csrf():
            message = "Security check failed."
        else:
            action = str(request.form.get("action") or "").strip()
            target_user_id = int(request.form.get("user_id") or 0)
            conn = db(); cur = conn.cursor()
            if target_user_id and action == "grant":
                grant_pulse_premium(cur, target_user_id, int(admin.get("id") or 0), "admin_manual")
                message = f"Premium granted to user {target_user_id}."
            elif target_user_id and action == "grant_founder":
                conn.close()
                conn = None
                result = premium_entitlement_service.grant_founder_membership(target_user_id, int(admin.get("id") or 0), "admin_founder_manual")
                message = f"Founder Premium granted to user {target_user_id} as Founder #{int(result.get('founder_number') or 0)}."
            elif target_user_id and action == "revoke":
                conn.close()
                conn = None
                premium_entitlement_service.revoke_premium_access(target_user_id, int(admin.get("id") or 0), "admin_revoke")
                message = f"Premium revoked for user {target_user_id}."
            else:
                message = "Enter a valid user ID and action."
            if conn:
                conn.commit(); conn.close()
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT user_id, username, display_name, email, premium_status, lifetime_premium, premium_glow_manual_grant FROM users WHERE COALESCE(premium_status,'')='active' OR COALESCE(lifetime_premium,0)=1 OR COALESCE(premium_glow_manual_grant,0)=1 ORDER BY updated_at DESC LIMIT 40")
    users = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT * FROM pulse_premium_entitlements ORDER BY updated_at DESC, created_at DESC LIMIT 60")
    entitlements = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT * FROM pulse_premium_feature_flags ORDER BY flag_key")
    flags = [dict(row) for row in cur.fetchall()]
    cur.execute("""
        SELECT fm.user_id, fm.founder_number, fm.founder_tier, fm.locked_price, fm.currency, fm.status, fm.activated_at,
               COALESCE(u.display_name,u.username,u.email,'PulseSoc user') AS display_name,
               u.email, u.stripe_customer_id, u.stripe_subscription_id,
               us.provider, us.provider_status, us.current_period_end, us.cancel_at_period_end, us.stripe_price_id
        FROM founder_memberships fm
        LEFT JOIN users u ON u.user_id=fm.user_id
        LEFT JOIN user_subscriptions us ON us.user_id=fm.user_id AND us.plan_key='founder_premium'
        ORDER BY fm.founder_number ASC
        LIMIT 80
    """)
    founders = [dict(row) for row in cur.fetchall()]
    conn.close()
    registry = premium_capability_engine.capability_summary()
    caps = "".join(f"<article class='card'><h2>{clean_html(item['label'])}</h2><p><span class='pill'>{clean_html(item['status'])}</span></p><p>{clean_html(item['user_facing_availability'])}</p></article>" for item in registry["capabilities"].values())
    user_rows = "".join(f"<tr><td>{int(u.get('user_id') or 0)}</td><td>{clean_html(u.get('display_name') or u.get('username') or u.get('email') or '')}</td><td>{clean_html(u.get('premium_status') or '')}</td><td>{int(u.get('lifetime_premium') or 0)}</td></tr>" for u in users) or "<tr><td colspan='4'>No premium grants yet.</td></tr>"
    entitlement_rows = "".join(f"<tr><td>{int(e.get('user_id') or 0)}</td><td>{clean_html(e.get('entitlement_key') or '')}</td><td>{clean_html(e.get('status') or '')}</td><td>{clean_html(e.get('source') or '')}</td></tr>" for e in entitlements) or "<tr><td colspan='4'>No entitlements yet.</td></tr>"
    flag_rows = "".join(f"<tr><td>{clean_html(f.get('flag_key') or '')}</td><td>{'Enabled' if int(f.get('enabled') or 0) else 'Disabled'}</td><td>{clean_html(f.get('description') or '')}</td></tr>" for f in flags)
    founder_rows = "".join(f"<tr><td>#{int(f.get('founder_number') or 0)}</td><td>{int(f.get('user_id') or 0)}</td><td>{clean_html(f.get('display_name') or '')}</td><td>{clean_html(f.get('founder_tier') or '')}</td><td>${int(f.get('locked_price') or 0)/100:.2f}</td><td>{clean_html(f.get('status') or '')}</td><td>{clean_html(f.get('provider') or 'manual')}</td><td>{clean_html(f.get('provider_status') or '')}</td><td>{'Yes' if int(f.get('cancel_at_period_end') or 0) else 'No'}</td><td>{clean_html(f.get('stripe_customer_id') or '')}</td><td>{clean_html(f.get('stripe_subscription_id') or '')}</td><td>{clean_html(f.get('stripe_price_id') or '')}</td><td>{smart_time_html(f.get('current_period_end') or f.get('activated_at'))}</td></tr>" for f in founders) or "<tr><td colspan='13'>No Founder members yet.</td></tr>"
    body = f"""
    <section class='card'><h1>Premium Command</h1><p class='muted'>Capability registry, entitlement grants, feature flags, and safely scaffolded premium promises.</p>{f"<p>{clean_html(message)}</p>" if message else ""}</section>
    <section class='grid'><article class='card'><h2>Capabilities</h2><p class='metric'>{registry['total']}</p><p>{clean_html(json.dumps(registry['status_counts']))}</p></article><article class='card'><h2>Premium Users</h2><p class='metric'>{len(users)}</p><p>Manual and founder grants.</p></article><article class='card'><h2>Feature Flags</h2><p class='metric'>{len(flags)}</p><p>Safe visibility controls.</p></article></section>
    <section class='card'><h2>Manual Grant / Revoke</h2><form method='post'><input type='hidden' name='csrf_token' value='{get_csrf_token()}'><p><input name='user_id' inputmode='numeric' placeholder='User ID'></p><p><select name='action'><option value='grant_founder'>Grant Founder Premium</option><option value='grant'>Grant Premium</option><option value='revoke'>Revoke Premium / Founder</option></select></p><button type='submit'>Apply</button></form><p class='muted'>Founder grants assign a unique Founder number and activate backend entitlements. Regular users cannot self-grant Founder access.</p></section>
    <section class='card table-wrap'><h2>Founder Members</h2><table><tr><th>Founder #</th><th>User ID</th><th>Name</th><th>Tier</th><th>Locked Price</th><th>Status</th><th>Provider</th><th>Stripe Status</th><th>Canceling</th><th>Customer</th><th>Subscription</th><th>Price</th><th>Period / Activated</th></tr>{founder_rows}</table></section>
    <section class='grid'>{caps}</section>
    <section class='card table-wrap'><h2>Premium Users</h2><table><tr><th>User ID</th><th>Name</th><th>Status</th><th>Lifetime</th></tr>{user_rows}</table></section>
    <section class='card table-wrap'><h2>Entitlements</h2><table><tr><th>User ID</th><th>Entitlement</th><th>Status</th><th>Source</th></tr>{entitlement_rows}</table></section>
    <section class='card table-wrap'><h2>Flags</h2><table><tr><th>Flag</th><th>Status</th><th>Description</th></tr>{flag_rows}</table></section>
    """
    return admin_page_html("Premium Command", body, admin)


@webhook_app.route("/admin/mobile-audit", methods=["GET"])
def admin_mobile_audit_page():
    admin, denied = require_admin_page("system.view")
    if denied:
        return denied
    body = """
    <section class='card'><h1>Mobile Audit</h1><p class='muted'>Viewport, overflow, fixed element, safe-area, and clipping diagnostics for the current admin browser.</p><button type='button' id='runMobileAudit'>Run Audit</button></section>
    <section class='grid' id='mobileAuditCards'></section>
    <section class='card'><h2>Details</h2><pre id='mobileAuditOutput' style='white-space:pre-wrap'></pre></section>
    <script>
    function runMobileAudit(){
      const doc=document.documentElement;
      const all=[...document.querySelectorAll('body *')];
      const vw=window.innerWidth;
      const vh=window.innerHeight;
      const horizontal=doc.scrollWidth>vw+1;
      const clipped=all.filter(el=>{const r=el.getBoundingClientRect();return r.width>0&&r.height>0&&(r.right>vw+2||r.left<-2)}).slice(0,30).map(el=>({tag:el.tagName,cls:el.className,text:(el.textContent||'').trim().slice(0,60),right:Math.round(el.getBoundingClientRect().right)}));
      const fixed=all.filter(el=>getComputedStyle(el).position==='fixed').map(el=>({tag:el.tagName,cls:el.className,z:getComputedStyle(el).zIndex,bottom:getComputedStyle(el).bottom}));
      const cards=document.getElementById('mobileAuditCards');
      cards.innerHTML=[
        ['Viewport',`${vw} x ${vh}`],
        ['Horizontal scroll',horizontal?'Needs attention':'Clear'],
        ['Clipped candidates',clipped.length],
        ['Fixed elements',fixed.length]
      ].map(([k,v])=>`<article class='card'><h2>${k}</h2><p class='metric'>${v}</p></article>`).join('');
      document.getElementById('mobileAuditOutput').textContent=JSON.stringify({viewport:{vw,vh,scrollWidth:doc.scrollWidth},horizontal,clipped,fixed},null,2);
    }
    document.getElementById('runMobileAudit')?.addEventListener('click',runMobileAudit);
    runMobileAudit();
    </script>
    """
    return admin_page_html("Mobile Audit", body, admin)


@webhook_app.route("/admin/performance", methods=["GET"])
def admin_performance_page():
    init_db()
    admin, denied = require_admin_page("system.view")
    if denied:
        return denied
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT path, COUNT(*) AS hits, ROUND(AVG(duration_ms),0) AS avg_ms, MAX(duration_ms) AS max_ms, ROUND(AVG(db_query_count),0) AS avg_queries, ROUND(AVG(response_size),0) AS avg_size FROM performance_traces WHERE created_at >= ? GROUP BY path ORDER BY max_ms DESC LIMIT 30", ((datetime.utcnow() - timedelta(hours=24)).isoformat(timespec="seconds"),))
    slow = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT * FROM performance_traces ORDER BY created_at DESC LIMIT 30")
    traces = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT * FROM worker_heartbeats WHERE worker_name IN ('coinpilotx-media-engine','media_worker') ORDER BY last_seen_at DESC LIMIT 2")
    media_worker_heartbeats = [dict(row) for row in cur.fetchall()]
    conn.close()
    slow_rows = "".join(f"<tr><td>{clean_html(r.get('path'))}</td><td>{int(r.get('hits') or 0)}</td><td>{int(r.get('avg_ms') or 0)}</td><td>{int(r.get('max_ms') or 0)}</td><td>{int(r.get('avg_queries') or 0)}</td><td>{int(r.get('avg_size') or 0)}</td></tr>" for r in slow) or "<tr><td colspan='6'>No slow traces recorded yet.</td></tr>"
    trace_rows = "".join(f"<tr><td>{clean_html(t.get('trace_id'))}</td><td>{clean_html(t.get('level'))}</td><td>{clean_html(t.get('method'))}</td><td>{clean_html(t.get('path'))}</td><td>{int(t.get('duration_ms') or 0)}</td><td>{int(t.get('db_query_count') or 0)}</td><td>{int(t.get('response_size') or 0)}</td><td>{smart_time_html(t.get('created_at'))}</td></tr>" for t in traces) or "<tr><td colspan='8'>No traces yet.</td></tr>"
    media_worker_rows = "".join(
        f"<tr><td>{clean_html(row.get('worker_name'))}</td><td>{clean_html(row.get('status'))}</td><td>{smart_time_html(row.get('last_seen_at'))}</td><td>{clean_html(row.get('last_error') or '')}</td><td><code>{clean_html((row.get('metadata_json') or '')[:320])}</code></td></tr>"
        for row in media_worker_heartbeats
    ) or "<tr><td colspan='5'>No media engine heartbeat has been recorded yet.</td></tr>"
    cache_status = cache_engine.cache_status()
    media_status = media_storage.storage_status()
    body = f"""
    <section class='card'><h1>Performance Command</h1><p class='muted'>Route latency, DB pressure, cache readiness, media storage readiness, and latest slow traces.</p></section>
    <section class='grid'>
      <article class='card'><h2>Cache</h2><p class='metric'>{clean_html(cache_status.get('provider'))}</p><p>{'Ready' if cache_status.get('ok') else 'Needs attention'}</p></article>
      <article class='card'><h2>Media Storage</h2><p class='metric'>{clean_html(media_status.get('provider'))}</p><p>{'Configured' if media_status.get('configured') else 'Configure R2/S3 env vars'}</p></article>
      <article class='card'><h2>Slow Threshold</h2><p class='metric'>{PERFORMANCE_SLOW_MS}ms</p><p>Critical at {PERFORMANCE_CRITICAL_MS}ms.</p></article>
    </section>
    <section class='card table-wrap'><h2>Slowest Routes - 24h</h2><table><tr><th>Path</th><th>Hits</th><th>Avg ms</th><th>Max ms</th><th>Avg DB</th><th>Avg bytes</th></tr>{slow_rows}</table></section>
    <section class='card table-wrap'><h2>Latest Slow Traces</h2><table><tr><th>Trace</th><th>Level</th><th>Method</th><th>Path</th><th>ms</th><th>DB</th><th>Bytes</th><th>Time</th></tr>{trace_rows}</table></section>
    <section class='card table-wrap'><h2>Media Engine Heartbeat</h2><p class='muted'>Railway worker start command: <code>python media_worker.py</code></p><table><tr><th>Worker</th><th>Status</th><th>Last Seen</th><th>Last Error</th><th>Details</th></tr>{media_worker_rows}</table></section>
    <section class='card'><h2>Railway Production Shape</h2><p><code>gunicorn bot:app --workers 2 --threads 4 --timeout 120 --access-logfile - --error-logfile -</code></p><p class='muted'>Redis and Cloudflare are optional accelerators; private authenticated HTML must stay uncached.</p></section>
    """
    return admin_page_html("Performance", body, admin)


