def mask_email_address(value):
    raw = str(value or "").strip()
    if "@" not in raw:
        return ""
    name, domain = raw.split("@", 1)
    return f"{name[:1]}***@{domain}" if name else f"***@{domain}"


def mask_phone_number(value):
    digits = re.sub(r"\D+", "", str(value or ""))
    return f"***-***-{digits[-4:]}" if len(digits) >= 4 else ""


def account_security_score(user, recovery_codes_count=0, trusted_devices_count=0, suspicious_alerts=0):
    score = 0
    score += 15 if int(user.get("email_verified") or 0) else 0
    score += 15 if int(user.get("phone_verified") or 0) else 0
    score += 25 if int(user.get("two_factor_enabled") or 0) else 0
    score += 10 if user.get("recovery_email") else 0
    score += 10 if user.get("recovery_phone") else 0
    score += 10 if recovery_codes_count > 0 else 0
    score += 5 if trusted_devices_count > 0 else 0
    score += 10 if suspicious_alerts <= 0 else 0
    return max(0, min(100, score))


def account_security_label(score):
    if score <= 30:
        return "Low"
    if score <= 60:
        return "Basic"
    if score <= 80:
        return "Strong"
    return "Excellent"


def account_trust_level(user, score=0):
    if user_is_super_user(user):
        return "Admin Verified"
    if int(user.get("verified_badge") or 0):
        return "Creator Verified"
    if score >= 80 and int(user.get("email_verified") or 0) and int(user.get("phone_verified") or 0):
        return "Trusted User"
    if int(user.get("email_verified") or 0) or int(user.get("phone_verified") or 0):
        return "Verified User"
    return "Basic User"


def account_security_payload(user_id):
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM users WHERE user_id=? LIMIT 1", (user_id,))
    user = dict(cur.fetchone() or {})
    cur.execute("SELECT COUNT(*) AS total FROM user_recovery_codes WHERE user_id=? AND used_at IS NULL", (user_id,))
    recovery_count = int((dict(cur.fetchone() or {}).get("total") or 0))
    cur.execute("SELECT COUNT(*) AS total FROM user_trusted_devices WHERE user_id=?", (user_id,))
    trusted_count = int((dict(cur.fetchone() or {}).get("total") or 0))
    cur.execute("SELECT COUNT(*) AS total FROM user_security_events WHERE user_id=? AND event_type IN ('suspicious_login','failed_login_burst')", (user_id,))
    suspicious_count = int((dict(cur.fetchone() or {}).get("total") or 0))
    try:
        ensure_mobile_security_session_schema(cur)
        cur.execute("SELECT COUNT(*) AS total FROM mobile_security_sessions WHERE user_id=? AND status='active' AND COALESCE(revoked_at,'')=''", (user_id,))
        active_session_count = int((dict(cur.fetchone() or {}).get("total") or 0))
    except Exception:
        active_session_count = 0
    score = account_security_score(user, recovery_count, trusted_count, suspicious_count)
    trust = account_trust_level(user, score)
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("UPDATE users SET security_score=?, trust_level=?, last_security_review_at=? WHERE user_id=?", (score, trust, now, user_id))
    conn.commit()
    conn.close()
    return {
        "score": score,
        "label": account_security_label(score),
        "trust_level": trust,
        "email": mask_email_address(user.get("email")),
        "phone": mask_phone_number(user.get("phone") or user.get("phone_number")),
        "email_verified": bool(user.get("email_verified")),
        "phone_verified": bool(user.get("phone_verified")),
        "two_factor_enabled": bool(user.get("two_factor_enabled")),
        "recovery_email": mask_email_address(user.get("recovery_email")),
        "recovery_phone": mask_phone_number(user.get("recovery_phone")),
        "recovery_codes_ready": recovery_count > 0,
        "trusted_devices_count": trusted_count,
        "active_sessions_count": active_session_count,
        "suspicious_alerts": suspicious_count,
        "recommended_steps": ["Verify email", "Verify phone", "Enable two-factor authentication", "Add recovery options", "Save recovery codes"],
    }


def pulse_security_settings_page(active="security"):
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    data = account_security_payload(int(user["user_id"]))
    tabs = [("Security", "/pulse/settings/security"), ("Account", "/pulse/settings/account"), ("Privacy", "/pulse/settings/privacy"), ("Devices", "/pulse/settings/devices"), ("Recovery", "/pulse/settings/recovery")]
    tabs_html = "".join(f"<a class='button {'primary' if label.lower()==active else ''}' href='{href}'>{label}</a>" for label, href in tabs)
    account_delete_card = ""
    if active == "account":
        account_delete_card = """
        <article class='security-item danger-zone'>
          <h3>Delete account</h3>
          <p class='muted'>Permanently delete your PulseSoc account from inside the app. Password confirmation is required before deletion completes.</p>
          <a class='button' href='/account/delete'>Delete my account</a>
        </article>
        """
    main = f"""
    <style>.security-settings{{display:grid;gap:14px}}.security-score-card{{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:14px;align-items:center}}.security-score-meter{{height:12px;border-radius:999px;background:rgba(255,255,255,.1);overflow:hidden}}.security-score-meter i{{display:block;height:100%;width:{int(data['score'])}%;background:linear-gradient(90deg,#ff6b7a,#ffd166,#36e58f,#6edff6)}}.security-grid{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}}.security-item{{border:1px solid rgba(110,223,246,.16);border-radius:14px;padding:12px;background:rgba(255,255,255,.045)}}@media(max-width:760px){{.security-score-card,.security-grid{{grid-template-columns:1fr}}}}</style>
    <section class='security-settings'>
      <section class='card'><div class='actions'>{tabs_html}</div></section>
      <section class='card security-score-card'><div><span class='badge'>Protect your PulseSoc identity</span><h2>Secure your PulseSoc account</h2><p class='muted'>Security can be improved over time. Regular PulseSoc users are not forced to provide ID.</p><div class='security-score-meter'><i></i></div></div><aside><p class='metric'>{int(data['score'])}</p><strong>{clean_html(data['label'])}</strong><p class='muted'>{clean_html(data['trust_level'])}</p></aside></section>
      <section class='security-grid'>
        <article class='security-item'><h3>Email</h3><p>{clean_html(data['email'] or 'Not added')}</p><p class='muted'>{'Verified' if data['email_verified'] else 'Not verified'}</p><button data-security-action='verify-email'>Verify email</button></article>
        <article class='security-item'><h3>Phone</h3><p>{clean_html(data['phone'] or 'Not added')}</p><p class='muted'>{'Verified' if data['phone_verified'] else 'Not verified'}</p><button data-security-action='verify-phone'>Verify phone</button></article>
        <article class='security-item'><h3>Two-factor</h3><p>{'Enabled' if data['two_factor_enabled'] else 'Not enabled'}</p><button data-security-action='2fa-enable'>Enable 2FA</button></article>
        <article class='security-item'><h3>Recovery email</h3><p>{clean_html(data['recovery_email'] or 'Not added')}</p><a class='button' href='/pulse/settings/recovery'>Add recovery email</a></article>
        <article class='security-item'><h3>Recovery phone</h3><p>{clean_html(data['recovery_phone'] or 'Not added')}</p><a class='button' href='/pulse/settings/recovery'>Add recovery phone</a></article>
        <article class='security-item'><h3>Recovery codes</h3><p>{'Saved' if data['recovery_codes_ready'] else 'Not generated'}</p><button data-security-action='recovery-codes'>Generate codes</button></article>
        <article class='security-item'><h3>Trusted devices</h3><p>{int(data['trusted_devices_count'])} trusted devices</p><a class='button' href='/pulse/settings/devices'>Manage devices</a></article>
        <article class='security-item'><h3>Active sessions</h3><p>{int(data['active_sessions_count'])} active sessions</p><button data-security-action='signout-all'>Sign out all devices</button></article>
        <article class='security-item'><h3>Recent alerts</h3><p>{int(data['suspicious_alerts'])} suspicious alerts</p><a class='button' href='/api/account/security-events'>View events</a></article>
        <article class='security-item'><h3>Sensitive actions</h3><p class='muted'>Email, phone, password, payment, payout, delete, and admin actions require reauthentication.</p><button data-security-action='reauth'>Reauthenticate</button></article>
        {account_delete_card}
      </section>
    </section>
    """
    script = """
    document.addEventListener('click',async e=>{const action=e.target.closest('[data-security-action]')?.dataset.securityAction;if(!action)return;if(action==='signout-all'&&!confirm('Sign out of PulseSoc on every device?'))return;e.target.disabled=true;const endpoints={'verify-email':'/api/account/verify-email','verify-phone':'/api/account/verify-phone','2fa-enable':'/api/account/2fa/enable','recovery-codes':'/api/account/recovery-codes/generate','reauth':'/api/account/reauthenticate','signout-all':'/api/account/sessions/revoke-all'};try{const d=await pulseApi(endpoints[action],{method:'POST',body:JSON.stringify({})});toast(d.message||'Security updated.');if(action==='signout-all')setTimeout(()=>location.href='/login',700);else if(action!=='reauth')setTimeout(()=>location.reload(),500)}catch(err){toast(err.message)}finally{e.target.disabled=false}});
    """
    return pulse_social_shell("Account Security", "Security score, trust profile, recovery options, trusted devices, sessions, and recent security events.", main, "", script)


