@webhook_app.route("/api/account/verify-email", methods=["POST"])
def api_account_verify_email():
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); cur = conn.cursor()
    cur.execute("INSERT INTO user_verifications (user_id, verification_type, status, provider, created_at, updated_at) VALUES (?, 'email', 'pending', 'email', ?, ?)", (user["user_id"], now, now))
    cur.execute("INSERT INTO user_security_events (user_id, event_type, ip_hash, user_agent_hash, device_label, created_at) VALUES (?, 'email_verification_requested', ?, ?, ?, ?)", (user["user_id"], client_ip_hash(), hashlib.sha256((request.headers.get('User-Agent') or '').encode()).hexdigest()[:32], "Browser", now))
    conn.commit(); conn.close()
    return jsonify({"ok": True, "message": "Email verification is queued."})


