@webhook_app.route("/api/account/2fa/enable", methods=["POST"])
def api_account_2fa_enable():
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); cur = conn.cursor()
    cur.execute("UPDATE users SET two_factor_enabled=1, updated_at=? WHERE user_id=?", (now, user["user_id"]))
    cur.execute("INSERT INTO user_security_events (user_id, event_type, ip_hash, user_agent_hash, device_label, created_at) VALUES (?, 'two_factor_enabled', ?, ?, ?, ?)", (user["user_id"], client_ip_hash(), hashlib.sha256((request.headers.get('User-Agent') or '').encode()).hexdigest()[:32], "Browser", now))
    conn.commit(); conn.close()
    return jsonify({"ok": True, "message": "Two-factor protection is enabled for sensitive actions."})


@webhook_app.route("/api/account/2fa/disable", methods=["POST"])
def api_account_2fa_disable():
    user = api_account_user()
