@webhook_app.route("/pulse/teachers", methods=["GET"])
def pulse_teachers_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_teacher_applications WHERE user_id=? ORDER BY id DESC LIMIT 1", (user["user_id"],))
    latest_app = dict(cur.fetchone() or {})
    cur.execute("SELECT * FROM pulse_teacher_profiles WHERE status='approved' ORDER BY id DESC LIMIT 30")
    teachers = [dict(row) for row in cur.fetchall()]
    conn.close()
    cats = ["Digital Safety", "Scam Prevention", "Wallet Safety", "AI Tools", "Creator Skills", "Business Basics", "Crypto Education", "Cybersecurity Basics", "Roast Battle Performance"]
    cat_options = "".join(f"<option>{clean_html(c)}</option>" for c in cats)
    status_panel = ""
    if latest_app:
        status_panel = f"<section class='card teacher-status'><h2>Application Status</h2><p class='metric'>{clean_html(latest_app.get('status') or 'submitted')}</p><p class='muted'>Completeness {int(latest_app.get('completeness') or 0)}% · Safety {int(latest_app.get('safety_score') or 0)}</p><a class='button primary' href='/pulse/teacher/dashboard'>Open Educator Dashboard</a></section>"
    teacher_html = "".join(f"<article class='card'><h2>{clean_html(t.get('display_name') or 'PulseSoc Educator')}</h2><p>{clean_html(t.get('bio') or '')}</p><p><span class='pill'>{clean_html(t.get('expertise') or 'Education')}</span> <span class='pill'>{clean_html(t.get('teacher_level') or 'Approved Educator')}</span> <span class='pill'>Safety {int(t.get('safety_score') or 0)}</span></p><div class='actions'><a class='button primary' href='/pulse/teachers/{int(t.get('user_id') or 0)}'>View Profile</a><button data-teacher-message='{int(t.get('user_id') or 0)}'>Message</button></div></article>" for t in teachers)
    main = f"""
    <style>
    .teacher-application{{display:grid;gap:14px;min-width:0;overflow-wrap:break-word;word-break:normal;white-space:normal}}.teacher-application section{{border:1px solid rgba(110,223,246,.14);border-radius:18px;padding:14px;background:rgba(255,255,255,.035);min-width:0;overflow:hidden;overflow-wrap:break-word;word-break:normal;white-space:normal}}
    .teacher-application .two{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;min-width:0}}.teacher-application label{{display:grid;gap:6px;color:var(--muted);font-weight:800;min-width:0;overflow-wrap:break-word;word-break:normal;white-space:normal}}.teacher-application label input,.teacher-application label select,.teacher-application label textarea{{color:var(--text);min-width:0;max-width:100%;overflow-wrap:break-word;word-break:normal;white-space:normal}}
    .teacher-application input[type=file]{{position:static!important;width:100%!important;height:auto!important;opacity:1!important;pointer-events:auto!important;clip:auto!important;clip-path:none!important;overflow:visible!important;white-space:normal!important;border:1px dashed rgba(110,223,246,.28);background:rgba(5,11,20,.55);padding:12px;aspect-ratio:auto}}
    .teacher-application .check-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;min-width:0}}.teacher-application .check-grid label{{display:flex;gap:8px;align-items:flex-start;white-space:normal;min-width:0}}
    .teacher-status{{border-color:rgba(54,229,143,.35)!important}}@media(max-width:767px){{body:has(.teacher-application) .pulse-fab{{bottom:calc(env(safe-area-inset-bottom) + 112px)}}.teacher-application,.teacher-application section,.teacher-application .two,.teacher-application .check-grid{{display:grid!important;grid-template-columns:1fr!important;width:100%!important;max-width:100%!important;min-width:0!important;gap:10px}}.teacher-application section{{padding:12px}}.teacher-application textarea{{min-height:110px}}.teacher-application button,.teacher-application .button{{width:100%;white-space:normal}}}}
    </style>
    {status_panel}
    <form class='card teacher-application' id='teacherApplicationForm' enctype='multipart/form-data'>
      <h2>Educator Application</h2><p class='muted'>PulseSoc educators are reviewed for trust, clarity, learner safety, and educational quality before full dashboard tools unlock.</p>
      <section><h3>Basic Info</h3><div class='two'><label>Educator display name<input name='teacher_display_name' required value='{clean_html(user.get('display_name') or user.get('username') or '')}'></label><label>Legal name/private<input name='legal_name' required></label><label>Email<input name='email' type='email' required value='{clean_html(user.get('email') or '')}'></label><label>Phone optional<input name='phone'></label><label>Country<input name='country' required></label><label>Languages spoken<input name='languages' placeholder='English, Haitian Creole, French'></label><label>Timezone<input name='timezone' placeholder='America/New_York'></label></div></section>
      <section><h3>Teaching Profile</h3><div class='two'><label>Teaching category<select name='teaching_category'>{cat_options}</select></label><label>Skill level taught<select name='skill_level'><option>Beginner</option><option>Intermediate</option><option>Advanced</option><option>Mixed</option></select></label><label>Teaching style<input name='teaching_style' placeholder='Calm, tactical, workshop, cohort...'></label><label>Years of experience<input name='years_experience'></label><label>Audience type<input name='audience_type' placeholder='Beginners, creators, sellers, builders...'></label><label>Sample lesson title<input name='sample_lesson_title' required></label></div><label>Sample lesson description<textarea name='sample_lesson_description' required></textarea></label><label>Why should students trust you?<textarea name='trust_reason' required></textarea></label></section>
      <section><h3>Safety + Compliance</h3><div class='check-grid'><label><input type='checkbox' name='no_financial_advice' required> I will not present lessons as financial advice.</label><label><input type='checkbox' name='no_guaranteed_profits' required> I will not promise guaranteed profits.</label><label><input type='checkbox' name='no_scam_promotion' required> I will not promote scams or deceptive products.</label><label><input type='checkbox' name='no_income_claims' required> I will not make misleading income claims.</label></div><label>How do you keep learners safe?<textarea name='learner_safety_plan' required></textarea></label></section>
      <section><h3>Credentials</h3><div class='two'><label>Certificates optional<input type='file' name='certificate' accept='.jpg,.jpeg,.png,.webp,.pdf'></label><label>Resume / CV optional<input type='file' name='resume' accept='.jpg,.jpeg,.png,.webp,.pdf'></label><label>Portfolio proof optional<input type='file' name='portfolio' accept='.jpg,.jpeg,.png,.webp,.pdf'></label><label>Website optional<input name='website'></label></div><label>Social links optional<textarea name='social_links'></textarea></label></section>
      <section><h3>Verification</h3><div class='two'><label>ID upload optional/required for paid educators<input type='file' name='id_document' accept='.jpg,.jpeg,.png,.webp,.pdf'></label><label>Selfie verification optional/required for paid educators<input type='file' name='selfie' accept='.jpg,.jpeg,.png,.webp,image/*' capture='user'></label></div><label><input type='checkbox' name='teacher_agreement' required> I agree to the educator standards, safety rules, and review process.</label></section>
      <section><button class='primary' id='teacherSubmitBtn'>Submit Educator Application</button><p id='teacherApplyError' class='muted'></p></section>
    </form>
    <section class='grid'>{teacher_html or '<article class="card"><h2>Educators are warming up.</h2><p>Apply to teach digital safety, scam prevention, AI tools, cybersecurity, creator skills, or crypto education.</p></article>'}</section>
    """
    script = """
    document.getElementById('teacherApplicationForm').addEventListener('submit',async e=>{
      e.preventDefault();const form=e.currentTarget,btn=document.getElementById('teacherSubmitBtn'),err=document.getElementById('teacherApplyError');btn.disabled=true;btn.textContent='Submitting...';err.textContent='';
      try{const fd=new FormData(form);const payload={};fd.forEach((v,k)=>{if(v instanceof File){return} payload[k]=v==='on'?true:v});
        const res=await pulseApi('/api/pulse/teachers/apply',{method:'POST',body:JSON.stringify(payload)});
        const appId=res.application_id;for(const key of ['certificate','resume','portfolio','id_document','selfie']){const f=form.elements[key]?.files?.[0];if(f&&appId){const dfd=new FormData();dfd.append('file',f);dfd.append('document_type',key);dfd.append('application_id',appId);const r=await fetch('/api/pulse/teachers/documents/upload',{method:'POST',credentials:'same-origin',body:dfd});const d=await r.json();if(!r.ok||d.ok===false)throw new Error(d.message||'Document upload failed.')}}toast('Educator application submitted.');location.href='/pulse/teacher/dashboard';}
      catch(ex){console.error('Educator application failed',ex);err.textContent=ex.message;toast(ex.message)}finally{btn.disabled=false;btn.textContent='Submit Educator Application'}
    });
    document.addEventListener('click',async e=>{const b=e.target.closest('[data-teacher-message]');if(!b)return;try{const d=await pulseApi('/api/pulse/messages/start',{method:'POST',body:JSON.stringify({user_id:b.dataset.teacherMessage})});location.href=d.next_url}catch(err){toast(err.message)}});
    """
    return pulse_social_shell("Educators", "Trusted educator onboarding, approval, courses, lessons, live classes, and safe learning tools.", main, "", script)


@webhook_app.route("/pulse/topic/<topic>", methods=["GET"])
def pulse_topic_page(topic):
    return pulse_page_html(f"PulseSoc Topic #{topic}", request.args.get("feed") or "for_you", topic=topic)


@webhook_app.route("/pulse/messages/<int:conversation_id>", methods=["GET"])
def pulse_message_thread_page(conversation_id):
    try:
        from pulse_communications_v2 import flags as comm_v2_flags
        if comm_v2_flags.is_enabled() and request.args.get("legacy") not in {"1", "true", "yes"}:
            user = require_account()
            if not user:
                return redirect(url_for("login_page", next=request.path))
            try:
                from services import command_center_client

                ai_enabled = bool(command_center_client.is_enabled() and command_center_client.ai_enabled())
            except Exception:
                ai_enabled = False
            return render_template(
                "pulse_messages_v2.html",
                enabled=True,
                current_user=user,
                ai_enabled=ai_enabled,
                initial_conversation_id=int(conversation_id or 0),
            )
    except Exception:
        logging.exception("PULSE_COMMUNICATIONS_V2_DEEP_LINK_FALLBACK conversation_id=%s", conversation_id)
    return pulse_communications_page(str(conversation_id))
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_conversation_participants WHERE conversation_id=? AND user_id=? LIMIT 1", (conversation_id, user["user_id"]))
    participant = dict(cur.fetchone() or {})
    if not participant:
        target_user_id = int(conversation_id or 0)
        if target_user_id and target_user_id != int(user["user_id"]):
            result, status = pulse_start_conversation(cur, user["user_id"], target_user_id=target_user_id)
            if result.get("ok"):
                conn.commit(); conn.close()
                return redirect(result["next_url"])
            conn.close()
            return pulse_social_shell("PulseSoc Message", result.get("message") or "This PulseSoc member is not available for messaging.", "<section class='card'><a class='button primary' href='/pulse/messages'>Back to Messenger</a></section>"), status
        conn.close()
        return pulse_social_shell("PulseSoc Message", "This conversation was not found or is not available to your account.", "<section class='card'><a class='button primary' href='/pulse/messages'>Back to Messenger</a></section>")
    cur.execute("SELECT * FROM pulse_conversations WHERE id=? LIMIT 1", (conversation_id,))
    conversation = dict(cur.fetchone() or {})
    conversation_type = conversation.get("conversation_type") or "direct"
    cur.execute("SELECT user_id FROM pulse_conversation_participants WHERE conversation_id=? AND user_id!=? LIMIT 1", (conversation_id, user["user_id"]))
    other_id = int(dict(cur.fetchone() or {}).get("user_id") or 0)
    if conversation_type == "direct":
        other = pulse_identity_for_user(cur, other_id)
        other_name = clean_html(other.get("name") or "PulseSoc user") + pulse_premium_mark_html(other.get("premium_mark"))
        avatar = f"<img src='{clean_html(other.get('avatar_url'))}' alt=''>" if other.get("avatar_url") else clean_html((other.get("name") or "P")[:1])
        subtitle = "PulseSoc Messenger"
    else:
        cur.execute("SELECT COUNT(*) AS total FROM pulse_conversation_participants WHERE conversation_id=?", (conversation_id,))
        participant_count = int(dict(cur.fetchone() or {}).get("total") or 0)
        label = conversation.get("title") or "Group Chat"
        other_name = clean_html(label)
        avatar = f"<img src='{clean_html(conversation.get('avatar_url'))}' alt=''>" if conversation.get("avatar_url") else clean_html((label or "G")[:1])
        subtitle = f"{participant_count} members · {clean_html(conversation_type.replace('_', ' '))}"
    cur.execute("SELECT * FROM pulse_messages WHERE conversation_id=? AND deleted_at IS NULL " + PULSE_VISIBLE_MESSAGE_FILTER + " ORDER BY id ASC LIMIT 200", (conversation_id,))
    messages = [dict(row) for row in cur.fetchall()]
    conn.close()
    message_html = "".join(
        f"<article class='msg {'mine' if int(m.get('sender_user_id') or 0)==int(user['user_id']) else 'theirs'}'>"
        f"{pulse_message_media_html(m)}"
        f"{'<p>'+clean_html(m.get('body') or '')+'</p>' if (m.get('body') or '').strip() and (m.get('message_type') or 'text') not in {'post_share','reel_share','group_share','marketplace_share','live_share'} else ''}"
        f"<small>{smart_time_html(m.get('created_at'), clean_html(m.get('delivery_status') or m.get('status') or 'sent'))}</small></article>"
        for m in messages
    )
    main = f"""
    <style>
    .messenger-screen{{height:min(82dvh,820px);display:grid;grid-template-rows:auto minmax(0,1fr) auto;border-radius:22px;overflow:hidden;padding:0}}
    .messenger-top{{position:relative;z-index:8;display:grid;gap:10px;padding:calc(12px + env(safe-area-inset-top)) 14px 12px;background:rgba(7,17,31,.94);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.08);pointer-events:auto}}
    .messenger-handle{{width:46px;height:5px;border-radius:999px;background:rgba(242,251,255,.32);margin:0 auto;pointer-events:none}}
    .messenger-head{{display:flex;align-items:center;justify-content:space-between;gap:10px;pointer-events:auto;position:relative;z-index:9}}
    .messenger-tabs{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;position:relative;z-index:10;pointer-events:auto}}
    .messenger-tabs a,.messenger-more,.messenger-close{{pointer-events:auto;position:relative;z-index:11}}
    .messenger-tabs a{{min-height:42px;border-radius:999px;text-decoration:none;display:grid;place-items:center;border:1px solid rgba(110,223,246,.2);font-weight:950;background:rgba(255,255,255,.05)}}
    .messenger-tabs .active{{color:#06101b;background:linear-gradient(135deg,var(--green),var(--cyan));border:0}}
    .message-list{{min-height:0;overflow:auto;padding:14px;display:grid;align-content:end;gap:10px;scroll-behavior:smooth}}
    .msg{{max-width:min(78%,520px);border:1px solid rgba(255,255,255,.08);border-radius:18px;padding:10px 12px;background:rgba(255,255,255,.06);box-shadow:0 14px 42px rgba(0,0,0,.18)}}
    .msg.mine{{justify-self:end;color:#06101b;background:linear-gradient(135deg,#6edff6,#77a7ff)}}.msg.theirs{{justify-self:start}}
    .msg p{{margin:4px 0;color:inherit}}.msg small{{display:block;margin-top:5px;opacity:.72;color:inherit}}
    .message-media{{display:block;width:min(280px,70vw);max-height:360px;object-fit:cover;border-radius:16px;background:#020817;border:1px solid rgba(255,255,255,.1)}}
    .message-audio{{width:min(280px,70vw);height:38px}}.voice-bubble{{display:grid;gap:8px;min-width:min(280px,70vw);padding:10px;border-radius:16px;background:rgba(5,11,20,.24);border:1px solid rgba(255,255,255,.1)}}.waveform{{height:28px;border-radius:999px;background:repeating-linear-gradient(90deg,rgba(110,223,246,.82) 0 3px,transparent 3px 9px);mask-image:linear-gradient(90deg,transparent,black 8%,black 92%,transparent);opacity:.82}}
    .share-card{{display:grid;gap:4px;min-width:min(260px,68vw);padding:12px;border-radius:16px;background:rgba(5,11,20,.28);text-decoration:none;color:inherit;border:1px solid rgba(255,255,255,.12)}}
    .message-composer{{position:sticky;bottom:0;z-index:12;display:grid;grid-template-columns:46px 46px minmax(0,1fr) 48px;gap:8px;padding:10px 12px calc(12px + env(safe-area-inset-bottom));background:rgba(5,11,20,.94);backdrop-filter:blur(18px);border-top:1px solid rgba(255,255,255,.08);pointer-events:auto}}
    .message-composer button{{width:46px;min-width:46px;padding:0;border-radius:50%}}.message-composer input{{min-height:46px;border-radius:999px}}
    .attachment-sheet{{position:fixed;left:12px;right:12px;bottom:calc(76px + env(safe-area-inset-bottom));z-index:80;display:none;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding:12px;border:1px solid rgba(110,223,246,.24);border-radius:22px;background:rgba(8,15,28,.96);backdrop-filter:blur(20px);box-shadow:0 28px 90px rgba(0,0,0,.48)}}
    .attachment-sheet.open{{display:grid}}.attachment-sheet button,.attachment-sheet a{{min-height:46px;border-radius:14px;white-space:normal}}
    .safety-backdrop{{position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,.48);backdrop-filter:blur(7px);pointer-events:auto}}.safety-backdrop[hidden]{{display:none}}
    .safety-menu{{position:absolute;right:0;top:48px;z-index:9999;display:grid;gap:6px;min-width:260px;padding:8px;border:1px solid rgba(110,223,246,.22);border-radius:18px;background:rgba(8,15,28,.98);box-shadow:0 20px 70px rgba(0,0,0,.45);pointer-events:auto}}
    .safety-menu[hidden]{{display:none}}.safety-menu button{{width:100%;justify-content:flex-start;background:rgba(255,255,255,.045)}}.safety-menu-title{{padding:8px 10px 4px;font-weight:950}}.safety-menu-section{{display:grid;gap:6px;padding:6px;border-top:1px solid rgba(255,255,255,.08)}}.safety-menu-section:first-of-type{{border-top:0}}.safety-menu small{{padding:8px 10px 0;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em;font-weight:850}}
    @media(max-width:900px){{body:has(.messenger-screen){{overflow:hidden}}body:has(.messenger-screen) .wrap{{padding:0}}body:has(.messenger-screen) .layout{{display:block}}body:has(.messenger-screen) .layout>aside,body:has(.messenger-screen) .wrap>section.card{{display:none}}.messenger-screen{{position:fixed;inset:0;z-index:200;height:100dvh;max-height:100dvh;border-radius:0;margin:0;border:0}}.messenger-tabs a{{font-size:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}.messenger-tabs a::after{{font-size:12px}}.messenger-tabs a:nth-child(1)::after{{content:'Chats'}}.messenger-tabs a:nth-child(2)::after{{content:'Rooms'}}.messenger-tabs a:nth-child(3)::after{{content:'Groups'}}.safety-menu{{position:fixed;left:0;right:0;top:auto;bottom:0;min-width:0;width:100%;border-radius:26px 26px 0 0;padding:12px 12px calc(14px + env(safe-area-inset-bottom));animation:messengerSheetIn .22s cubic-bezier(.18,.9,.2,1)}}.safety-menu::before{{content:'';display:block;width:46px;height:5px;border-radius:999px;background:rgba(242,251,255,.36);margin:2px auto 10px}}.mobile-bottom-nav,.pulse-fab{{display:none!important}}}}@keyframes messengerSheetIn{{from{{transform:translateY(18px);opacity:.86}}to{{transform:translateY(0);opacity:1}}}}
    </style>
    <section class='card messenger-screen'>
      <header class='messenger-top'>
        <div class='messenger-handle'></div>
        <div class='messenger-head'><div class='person'><span class='avatar'>{avatar}</span><div><strong>{other_name}</strong><p class='muted'>{subtitle}</p></div></div><div class='private-chat-tools'><button class='messenger-more' id='safetyMenuBtn' type='button' aria-haspopup='dialog' aria-expanded='false'>⋯</button><a class='button messenger-close' href='/pulse/messages'>Close</a><div class='safety-backdrop' id='safetyBackdrop' hidden></div><div class='safety-menu' id='safetyMenu' hidden><div class='safety-menu-title'>Messenger Options</div><div class='safety-menu-section'><button type='button'>Mute Notifications</button><button type='button'>Search in Chat</button><button type='button'>Pinned Messages</button></div><small>Safety & Privacy</small><div class='safety-menu-section'><button type='button'>Report a Problem</button><button type='button'>Blocked Users</button><button type='button'>Restricted Users</button></div></div></div></div>
        <nav class='messenger-tabs'><a href='/pulse/messages'>Conversations</a><a class='active' href='/pulse/messages/{conversation_id}'>Chat Room</a><a href='/pulse/messages#group-chat'>Group Chat</a></nav>
      </header>
      <section class='message-list' id='messages'>{message_html or '<article class="msg theirs"><p>No messages yet. Start the conversation with text, media, or a PulseSoc share.</p></article>'}</section>
      <form class='message-composer' id='replyForm'><button id='attachBtn' type='button'>+</button><a class='button' href='/pulse/camera?target=message&conversation_id={conversation_id}' aria-label='Camera'>📷</a><input id='replyBody' placeholder='Message...' autocomplete='off'><button class='primary' id='replyBtn'>➤</button></form>
    </section>
    <section class='attachment-sheet' id='attachmentSheet'><a class='button' href='/pulse/camera?target=message&conversation_id={conversation_id}'>Take Photo</a><a class='button' href='/pulse/camera/video?target=message&conversation_id={conversation_id}'>Record Video</a><button type='button' data-pick-media='image/*'>Upload Photo</button><button type='button' data-pick-media='video/*'>Upload Video</button><button type='button' data-pick-media='image/gif'>Upload GIF</button><button type='button' data-pick-media='audio/*' data-voice='1'>Voice Note</button><button type='button' data-pick-media='audio/*'>Audio Clip</button><button type='button' data-pick-media='.pdf,.txt,.doc,.docx'>File</button><button type='button' data-share-kind='post_share'>Share PulseSoc Post</button><button type='button' data-share-kind='reel_share'>Share Reel</button><button type='button' data-share-kind='marketplace_share'>Share Marketplace Item</button></section><input id='messageMediaFile' type='file' accept='image/*,video/*,audio/*,.pdf,.txt,.doc,.docx' hidden>
    """
    script = f"""
    const list=document.getElementById('messages'),form=document.getElementById('replyForm'),input=document.getElementById('replyBody'),sheet=document.getElementById('attachmentSheet'),file=document.getElementById('messageMediaFile'),safety=document.getElementById('safetyMenu'),safetyBackdrop=document.getElementById('safetyBackdrop'),safetyBtn=document.getElementById('safetyMenuBtn');list.scrollTop=list.scrollHeight;
    function setSafetyMenu(open){{safety.hidden=!open;safetyBackdrop.hidden=!open;safetyBtn.setAttribute('aria-expanded',open?'true':'false')}}
    safetyBtn.addEventListener('click',()=>setSafetyMenu(safety.hidden));
    safetyBackdrop.addEventListener('click',()=>setSafetyMenu(false));
    document.addEventListener('keydown',e=>{{if(e.key==='Escape')setSafetyMenu(false)}});
    document.getElementById('attachBtn').addEventListener('click',()=>sheet.classList.toggle('open'));
    let voiceUpload=false;document.querySelectorAll('[data-pick-media]').forEach(b=>b.addEventListener('click',()=>{{file.accept=b.dataset.pickMedia;voiceUpload=b.dataset.voice==='1';file.click();sheet.classList.remove('open')}}));
    file.addEventListener('change',async()=>{{const chosen=file.files[0];if(!chosen)return;try{{const fd=new FormData();fd.append('file',chosen);fd.append('conversation_id','{conversation_id}');if(voiceUpload)fd.append('voice','1');const r=await fetch('/api/pulse/messages/upload',{{method:'POST',credentials:'same-origin',body:fd}});const d=await r.json();if(!r.ok||d.ok===false)throw new Error(d.message||'Upload failed.');await pulseApi('/api/pulse/messages/send',{{method:'POST',body:JSON.stringify({{conversation_id:{conversation_id},message_type:d.message_type,media_url:d.media_url,thumbnail_url:d.thumbnail_url,file_size:d.file_size||0,body:input.value||chosen.name}})}});location.reload();}}catch(err){{toast(err.message)}}finally{{file.value='';voiceUpload=false}}}});
    document.querySelectorAll('[data-share-kind]').forEach(b=>b.addEventListener('click',async()=>{{const url=prompt('Paste the PulseSoc link to share');if(!url)return;try{{await pulseApi('/api/pulse/messages/send',{{method:'POST',body:JSON.stringify({{conversation_id:{conversation_id},message_type:b.dataset.shareKind,media_url:url,body:'Shared from PulseSoc'}})}});location.reload();}}catch(err){{toast(err.message)}}}}));
    form.addEventListener('submit',async e=>{{e.preventDefault();try{{await pulseApi('/api/pulse/messages/send',{{method:'POST',body:JSON.stringify({{conversation_id:{conversation_id},body:input.value,message_type:'text'}})}});location.reload()}}catch(err){{toast(err.message)}}}});
    """
    return pulse_social_shell("PulseSoc Messenger", "Reply quickly and safely inside the PulseSoc social layer.", main, "", script)


@webhook_app.route("/pulse/groups/<group_slug>", methods=["GET"])
def pulse_group_detail_page(group_slug):
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    if clean_html(group_slug).strip().lower() == "bigboss":
        return pulse_social_shell("PulseSoc Group", "This group was not found.", "<section class='card'><a class='button primary' href='/pulse/groups'>Back to Groups</a></section>"), 404
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_groups WHERE (slug=? OR id=?) AND COALESCE(status,'active') NOT IN ('deleted','removed') LIMIT 1", (clean_html(group_slug), safe_int(group_slug, 0)))
    group = dict(cur.fetchone() or {})
    if not group:
        conn.close()
        return pulse_social_shell("PulseSoc Group", "This group was not found.", "<section class='card'><a class='button primary' href='/pulse/groups'>Back to Groups</a></section>"), 404
    group_id = int(group.get("id") or 0)
    cur.execute("SELECT COUNT(*) AS total FROM pulse_group_members WHERE group_id=?", (group_id,))
    members = int(dict(cur.fetchone() or {}).get("total") or 0)
    cur.execute(
        """
        SELECT gp.*, COALESCE(u.display_name,u.username,'PulseSoc Member') AS author
        FROM pulse_group_posts gp
        LEFT JOIN users u ON u.user_id=gp.user_id
        WHERE gp.group_id=?
          AND gp.deleted_at IS NULL
          AND COALESCE(gp.status,'published') NOT IN ('deleted','removed')
        ORDER BY CASE WHEN gp.pinned_at IS NOT NULL AND gp.pinned_at!='' THEN 0 ELSE 1 END,
                 gp.pinned_at DESC,
                 gp.id DESC LIMIT 50
        """,
        (group_id,),
    )
    posts = [dict(row) for row in cur.fetchall()]
    post_cards = []
    groups_advanced = GROUPS_ADVANCED_MODE
    current_role = ""
    cur.execute("SELECT role FROM pulse_group_members WHERE group_id=? AND user_id=? LIMIT 1", (group_id, user["user_id"]))
    current_role = dict(cur.fetchone() or {}).get("role") or ""
    can_delete_group = pulse_group_can_delete_group(group, user, current_role)
    for p in posts:
        post_id = int(p.get("id") or 0)
        ident = pulse_identity_for_user(cur, p.get("user_id"))
        stats = pulse_group_post_stats(cur, p.get("id"), user["user_id"])
        can_delete = pulse_group_can_delete_post({**p, **group, "member_role": current_role, "owner_user_id": group.get("owner_user_id"), "group_status": group.get("status"), "group_type": group.get("group_type")}, user)
        cur.execute(
            """
            SELECT * FROM pulse_group_post_comments
            WHERE group_post_id=? AND deleted_at IS NULL AND COALESCE(status,'visible')='visible'
            ORDER BY id DESC LIMIT 3
            """,
            (int(p.get("id") or 0),),
        )
        previews = [pulse_group_comment_payload(cur, row, user["user_id"]) for row in cur.fetchall()]
        preview_html = "".join(
            f"<div class='group-comment' data-comment-id='{c['id']}'><strong>{clean_html(c['author_name'])}{pulse_premium_mark_html(c.get('premium_mark'))}</strong><p>{clean_html(c['body'])}</p><small>{smart_time_html(c.get('created_at'))}</small>{'<button data-group-comment-delete=\"'+str(c['id'])+'\">Delete</button>' if c.get('can_delete') else ''}<button data-group-comment-report='{c['id']}'>Report</button></div>"
            for c in reversed(previews)
        )
        if not groups_advanced:
            preview_html = ""
        media_html = ""
        media_url = pulse_media_url(p.get("media_url") or "")
        media_type = clean_html(p.get("media_type") or "")
        thumbnail_url = pulse_media_url(p.get("thumbnail_url") or "")
        if not media_url:
            cur.execute(
                """
                SELECT media_url, thumbnail_url, media_type
                FROM pulse_group_post_media
                WHERE group_post_id=?
                ORDER BY id ASC LIMIT 1
                """,
                (int(p.get("id") or 0),),
            )
            media_row = dict(cur.fetchone() or {})
            media_url = pulse_media_url(media_row.get("media_url") or "")
            thumbnail_url = pulse_media_url(media_row.get("thumbnail_url") or "")
            media_type = clean_html(media_row.get("media_type") or media_type)
        if media_url and media_type == "video":
            media_html = f"<div class='group-media-frame'><video controls playsinline preload='metadata' poster='{clean_html(thumbnail_url)}' data-group-media='{post_id}' onerror=\"window.reportGroupMediaFailure&&window.reportGroupMediaFailure({post_id},'{clean_html(media_url)}')\"><source src='{clean_html(media_url)}'></video></div>"
        elif media_url:
            media_html = f"<button class='group-media-frame' type='button' data-media-fullscreen='{clean_html(media_url)}'><img src='{clean_html(media_url)}' alt='Group post media' loading='lazy' data-group-media='{post_id}' onerror=\"window.reportGroupMediaFailure&&window.reportGroupMediaFailure({post_id},'{clean_html(media_url)}');this.closest('.group-media-frame').classList.add('is-broken');this.replaceWith(document.createTextNode('Media could not load.'))\"></button>"
        if not groups_advanced:
            media_html = ""
        reaction_buttons = "".join(
            f"<button class='group-reaction-chip {'primary' if stats.get('my_reaction') == key else ''}' data-group-react='{post_id}' data-reaction='{key}'>{label} <span data-reaction-count='{post_id}:{key}'>{int(stats['reactions'].get(key) or 0)}</span></button>"
            for key, label in [("fire", "Fire"), ("smart", "Smart"), ("scam_alert", "Scam Alert"), ("whale", "Whale"), ("bullish", "Bullish"), ("bearish", "Bearish")]
        )
        if not groups_advanced:
            reaction_buttons = ""
        is_pinned = bool(p.get("pinned_at"))
        moderator_controls = ""
        if groups_advanced and pulse_group_role_allows_moderation(current_role):
            moderator_controls = f"<button data-group-remove-user='{int(p.get('user_id') or 0)}'>Remove User From Group</button><button data-group-post-pin='{post_id}'>{'Unpin Post' if is_pinned else 'Pin Post'}</button>"
        delete_control = f"<button data-group-post-delete='{post_id}'>Delete Post</button>" if can_delete else ""
        report_control = f"<button data-group-report-post='{post_id}'>Report Post</button>" if groups_advanced else ""
        menu_html = f"<details class='group-post-menu'><summary>...</summary><div>{report_control}{delete_control}{moderator_controls}</div></details>" if (groups_advanced or delete_control) else ""
        author_avatar = f"<img src='{clean_html(ident.get('avatar_url'))}' alt=''>" if ident.get("avatar_url") else clean_html((ident.get("name") or "P")[:1])
        pinned_badge = "<span class='pill pinned-pill'>Pinned</span> " if is_pinned else ""
        interaction_html = (
            f"<div class='group-reaction-row'>{reaction_buttons}</div><div class='group-comments' data-comments-for='{post_id}'>{preview_html}</div><form class='group-comment-form' data-group-comment-form='{post_id}'><input name='body' placeholder='Write a comment...' autocomplete='off'><button class='primary'>Comment</button></form>"
            if groups_advanced
            else "<p class='muted'>Group interactions are temporarily paused while this area is stabilized.</p>"
        )
        post_cards.append(
            f"<article class='card group-post-card' data-group-post='{post_id}'><div class='group-post-head'><div class='person'><span class='avatar'>{author_avatar}</span><div><strong>{clean_html(ident.get('name') or p.get('author') or 'PulseSoc Member')}{pulse_premium_mark_html(ident.get('premium_mark'))}</strong><p class='muted'>{clean_html(ident.get('primary_label') or ident.get('rank') or 'Member')} <span class='time-dot'>•</span> {smart_time_html(p.get('created_at'))}</p></div></div>{menu_html}</div>"
        f"<p>{clean_html(p.get('body') or p.get('content') or '')}</p>{media_html}<p class='group-post-meta'>{pinned_badge}<span class='pill'>{clean_html(p.get('post_type') or 'text')}</span> <span class='pill'>{clean_html(p.get('moderation_status') or 'approved')}</span> <span class='pill'><span data-comment-count='{post_id}'>{stats['comment_count']}</span> comments</span></p>"
            f"{interaction_html}</article>"
        )
    post_html = "".join(post_cards)
    conn.close()
    slug = clean_html(group.get("slug") or str(group_id))
    style = "<style>.group-post-head{display:flex;justify-content:space-between;gap:10px;align-items:start;min-width:0}.group-post-menu{position:relative;flex:0 0 auto;z-index:20}.group-post-menu summary{list-style:none;cursor:pointer;border:1px solid var(--line);border-radius:10px;padding:8px 12px;font-weight:950}.group-post-menu div{position:absolute;right:0;z-index:999;display:grid;gap:6px;min-width:min(260px,calc(100vw - 28px));max-width:calc(100vw - 28px);padding:8px;border:1px solid var(--line);border-radius:14px;background:#081323;box-shadow:0 20px 60px rgba(0,0,0,.42)}.group-post-menu button{width:100%;justify-content:flex-start;white-space:normal}.group-media-frame{display:block;width:100%;margin-top:12px;padding:0;border:0;border-radius:18px;overflow:hidden;background:linear-gradient(135deg,rgba(110,223,246,.09),rgba(255,255,255,.035));box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}.group-media-frame img,.group-media-frame video{display:block;width:100%;max-height:540px;object-fit:cover;background:#050b14}.group-media-frame.is-broken{padding:18px;border:1px dashed rgba(255,255,255,.18);color:var(--muted);text-align:center}.pinned-pill{background:rgba(255,209,102,.14);border-color:rgba(255,209,102,.38)}.group-reaction-row{display:flex;gap:7px;overflow-x:auto;padding:6px 0;max-width:100%;scrollbar-width:thin}.group-reaction-chip{min-height:38px;font-size:13px;padding:7px 10px;flex:0 0 auto}.group-comments{display:grid;gap:8px;margin-top:8px}.group-comment{border-left:2px solid rgba(110,223,246,.3);padding:7px 9px;background:rgba(255,255,255,.035);border-radius:10px}.group-comment p{margin:3px 0}.group-comment-form{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin-top:10px}.group-comment-form input{min-height:42px;border-radius:999px}.group-community-actions{display:grid;grid-template-columns:1fr;gap:12px;margin-top:12px}.group-community-actions button,.group-community-actions .button{width:100%;min-width:0}.group-meta-pills,.group-post-meta{display:flex;gap:6px;flex-wrap:wrap}.group-composer-actions{display:grid;grid-template-columns:1fr;gap:10px}.group-post-card{overflow:hidden}.group-report-modal{position:fixed;inset:0;z-index:1000;display:none;place-items:end center;background:rgba(0,0,0,.45);backdrop-filter:blur(8px);padding:14px}.group-report-modal.open{display:grid}.group-report-sheet{width:min(520px,100%);border:1px solid var(--line);border-radius:22px;background:#071321;padding:16px;box-shadow:0 28px 90px rgba(0,0,0,.5)}.group-danger-zone{border-color:rgba(255,107,122,.38);background:linear-gradient(180deg,rgba(255,107,122,.08),rgba(17,29,50,.88))}@media(min-width:768px){.group-community-actions,.group-composer-actions{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.group-comment-form{grid-template-columns:1fr}.group-post-head{align-items:center}.group-post-menu div{position:fixed;right:12px;left:12px;top:auto;bottom:calc(110px + env(safe-area-inset-bottom));border-radius:22px}.group-reaction-chip{flex:0 0 auto}.group-media-frame img,.group-media-frame video{max-height:70dvh;object-fit:contain}}</style>"
    delete_group_html = f"<section class='card group-danger-zone'><h2>Owner Controls</h2><p class='muted'>Delete hides this group, posts, and community chat while preserving audit history.</p><button data-delete-group-id='{group_id}'>Delete Group</button></section>" if (groups_advanced and can_delete_group) else ""
    action_html = f"<button class='primary' data-join-group-id='{group_id}'>Join Group</button><button data-leave-group-id='{group_id}'>Leave</button>"
    if groups_advanced:
        action_html = f"<button class='primary' data-join-group-id='{group_id}'>Join Group</button><button data-open-group-chat-id='{group_id}'>Open Group Chat</button><button data-invite-group-id='{group_id}'>Invite</button><button data-report-group-id='{group_id}'>Report</button><button data-leave-group-id='{group_id}'>Leave</button>"
    composer_html = f"<section class='card'><h2>Share With Group</h2><textarea id='groupPostBody' placeholder='Share an update, lesson, warning, question, photo, or video caption.'></textarea><label>Attach photo or video<input id='groupMediaFile' type='file' accept='image/*,video/*'></label><div class='group-composer-actions'><a class='button' href='/pulse/camera/photo?target=group&group={slug}'>Take Photo</a><a class='button' href='/pulse/camera/video?target=group&group={slug}'>Record Video</a><button class='primary' id='groupPostBtn'>Post</button></div></section>" if groups_advanced else "<section class='card'><h2>Groups Stabilization</h2><p class='muted'>Advanced posting, media, invites, moderation, and chat controls are temporarily paused. Group browsing, creation, joining, and leaving remain available.</p></section>"
    modal_html = f"<section class='group-report-modal' id='groupReportModal'><div class='group-report-sheet'><h2 id='groupReportTitle'>Report Post</h2><select id='groupReportReason'><option value='spam'>Spam</option><option value='harassment'>Harassment</option><option value='scam'>Scam</option><option value='impersonation'>Impersonation</option><option value='misleading financial claims'>Misleading financial claims</option><option value='nudity'>Nudity</option><option value='violence'>Violence</option><option value='misinformation'>Misinformation</option><option value='illegal'>Illegal</option><option value='other'>Other</option></select><textarea id='groupReportNotes' placeholder='Add context for moderators'></textarea><div class='actions'><button type='button' id='cancelGroupReport'>Cancel</button><button class='primary' type='button' id='submitGroupReport'>Submit Report</button></div></div></section><section class='group-report-modal' id='groupInviteModal'><div class='group-report-sheet'><h2>Invite to Group</h2><form id='groupInviteSearch'><input name='q' placeholder='Search by name or public PulseSoc ID'><button class='primary'>Search</button></form><div class='messenger-search-results' id='groupInviteResults'></div><button type='button' id='copyGroupInvite'>Copy Invite Link</button><button type='button' id='cancelGroupInvite'>Close</button></div></section>" if groups_advanced else ""
    main = f"{style}<section class='card' data-group-shell='{group_id}'><h2>{clean_html(group.get('name'))}</h2><p>{clean_html(group.get('description') or '')}</p><p class='group-meta-pills'><span class='pill'>{clean_html(group.get('category') or 'Community')}</span> <span class='pill'>{clean_html(group.get('group_type') or 'public')}</span> <span class='pill'><span data-group-member-count>{members}</span> members</span> <span class='pill'>{clean_html(group.get('trust_level') or 'standard')}</span></p><div class='group-community-actions'>{action_html}</div></section><section class='card'><h2>Rules</h2><p>{clean_html(group.get('rules') or 'Keep it safe, educational, and scam-free.')}</p></section>{delete_group_html}{composer_html}<section>{post_html or '<article class=\"card\"><p>No group posts yet.</p></article>'}</section>{modal_html}"
    script = f"""
    const groupSlug={json.dumps(slug)};
    let pendingReportPostId=null;
    let reportMode='post';
    const reportModal=document.getElementById('groupReportModal');
    const inviteModal=document.getElementById('groupInviteModal');
    function gEsc(v){{return String(v||'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}
    function groupTime(ts){{return window.CoinPilotTime?window.CoinPilotTime.element(ts):gEsc(ts||'Recently')}}
    function renderGroupComment(c){{return `<div class="group-comment" data-comment-id="${{c.id}}"><strong>${{gEsc(c.author_name||'PulseSoc Member')}}</strong><p>${{gEsc(c.body||'')}}</p><small>${{groupTime(c.created_at)}}</small>${{c.can_delete?`<button data-group-comment-delete="${{c.id}}">Delete</button>`:''}}<button data-group-comment-report="${{c.id}}">Report</button></div>`}}
    function updateReactions(postId,data){{Object.entries(data.reactions||{{}}).forEach(([k,v])=>{{document.querySelectorAll(`[data-reaction-count="${{postId}}:${{k}}"]`).forEach(n=>n.textContent=v)}});document.querySelectorAll(`[data-group-react="${{postId}}"]`).forEach(b=>b.classList.toggle('primary',b.dataset.reaction===(data.my_reaction||'')))}}
    function closeMenus(el){{el?.closest('details')?.removeAttribute('open')}}
    function setLoading(btn,on,label){{if(!btn)return;btn.disabled=on;if(on){{btn.dataset.originalText=btn.textContent;btn.textContent=label||'Working...'}}else if(btn.dataset.originalText){{btn.textContent=btn.dataset.originalText;delete btn.dataset.originalText}}}}
    function updateMemberCount(n){{document.querySelectorAll('[data-group-member-count]').forEach(el=>el.textContent=n)}}
    window.reportGroupMediaFailure=(postId,url)=>{{fetch('/api/pulse/groups/media-failure',{{method:'POST',credentials:'same-origin',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{post_id:postId,media_url:url,page:location.pathname}})}}).catch(()=>{{}})}};
    document.addEventListener('keydown',e=>{{if(e.key==='Escape'){{document.querySelectorAll('.group-post-menu[open]').forEach(d=>d.removeAttribute('open'));reportModal?.classList.remove('open');inviteModal?.classList.remove('open')}}}});
    document.addEventListener('click',e=>{{if(!e.target.closest('.group-post-menu'))document.querySelectorAll('.group-post-menu[open]').forEach(d=>d.removeAttribute('open'))}});
    document.getElementById('cancelGroupReport')?.addEventListener('click',()=>{{reportModal?.classList.remove('open');pendingReportPostId=null;reportMode='post'}});
    document.getElementById('submitGroupReport')?.addEventListener('click',async e=>{{const btn=e.currentTarget;setLoading(btn,true,'Submitting...');try{{const payload={{reason:document.getElementById('groupReportReason').value,notes:document.getElementById('groupReportNotes').value}};if(reportMode==='group')await pulseApi(`/api/pulse/groups/{group_id}/report`,{{method:'POST',body:JSON.stringify(payload)}});else await pulseApi(`/api/pulse/groups/posts/${{pendingReportPostId}}/report`,{{method:'POST',body:JSON.stringify(payload)}});reportModal?.classList.remove('open');toast('Report submitted.');pendingReportPostId=null;reportMode='post';document.getElementById('groupReportNotes').value='';}}catch(err){{console.error('Group action failed',err);toast(err.message)}}finally{{setLoading(btn,false)}}}});
    document.getElementById('cancelGroupInvite')?.addEventListener('click',()=>inviteModal?.classList.remove('open'));
    document.getElementById('copyGroupInvite')?.addEventListener('click',async()=>{{try{{const d=await pulseApi(`/api/pulse/groups/{group_id}/invite-link`,{{method:'POST',body:JSON.stringify({{}})}});await navigator.clipboard.writeText(d.invite_url).catch(()=>{{}});toast('Invite link copied.')}}catch(err){{toast(err.message)}}}});
    document.getElementById('groupInviteSearch')?.addEventListener('submit',async e=>{{e.preventDefault();const q=e.target.q.value.trim();if(!q)return;const box=document.getElementById('groupInviteResults');box.innerHTML='<p class="muted">Searching...</p>';try{{const r=await fetch('/api/pulse/users/search?q='+encodeURIComponent(q),{{credentials:'same-origin',cache:'no-store'}});const d=await r.json();if(!r.ok||d.ok===false)throw new Error(d.message||'Search failed.');box.innerHTML=(d.users||[]).map(u=>`<div class="messenger-user-result"><span class="avatar">${{u.avatar_url?`<img src="${{gEsc(u.avatar_url)}}" alt="">`:gEsc((u.display_name||'P').slice(0,1))}}</span><div><strong>${{gEsc(u.display_name||'PulseSoc user')}}</strong><p class="muted">${{gEsc(u.public_pulse_id||'')}}</p></div><button data-send-group-invite="${{u.id}}" ${{u.is_self?'disabled':''}}>Invite</button></div>`).join('')||'<p class="muted">No users found.</p>';}}catch(err){{box.innerHTML=`<p class="muted">${{gEsc(err.message)}}</p>`}}}});
    document.addEventListener('click',async e=>{{const full=e.target.closest('[data-media-fullscreen]');if(full){{window.open(full.dataset.mediaFullscreen,'_blank','noopener');return}}const jid=e.target.closest('[data-join-group-id]'),lid=e.target.closest('[data-leave-group-id]'),rid=e.target.closest('[data-report-group-id]'),invid=e.target.closest('[data-invite-group-id]'),gcid=e.target.closest('[data-open-group-chat-id]'),deleteGroup=e.target.closest('[data-delete-group-id]'),inviteUser=e.target.closest('[data-send-group-invite]');const j=e.target.closest('[data-join-group]'),l=e.target.closest('[data-leave-group]'),r=e.target.closest('[data-report-group]'),inv=e.target.closest('[data-invite-group]'),gr=e.target.closest('[data-group-react]'),rp=e.target.closest('[data-group-report-post]'),rm=e.target.closest('[data-group-remove-user]'),pin=e.target.closest('[data-group-post-pin]'),cd=e.target.closest('[data-group-comment-delete]'),cr=e.target.closest('[data-group-comment-report]'),pd=e.target.closest('[data-group-post-delete]'),gc=e.target.closest('[data-open-group-chat]');try{{if(deleteGroup){{if(!confirm('Delete this group? This will hide the group and its posts.'))return;setLoading(deleteGroup,true,'Deleting...');const d=await pulseApi(`/api/pulse/groups/${{deleteGroup.dataset.deleteGroupId}}/delete`,{{method:'POST',body:JSON.stringify({{reason:'owner_delete'}})}});toast(d.message||'Group deleted.');location.href=d.next_url||'/pulse/groups';return}} if(jid){{setLoading(jid,true);const d=await pulseApi(`/api/pulse/groups/${{jid.dataset.joinGroupId}}/join`,{{method:'POST',body:JSON.stringify({{}})}});if(d.member_count!==undefined)updateMemberCount(d.member_count);toast(d.message||'Joined group.');setLoading(jid,false);return}} if(lid){{setLoading(lid,true);const d=await pulseApi(`/api/pulse/groups/${{lid.dataset.leaveGroupId}}/leave`,{{method:'POST',body:JSON.stringify({{}})}});if(d.member_count!==undefined)updateMemberCount(d.member_count);toast(d.message||'Left group.');setLoading(lid,false);return}} if(gcid){{setLoading(gcid,true);const d=await pulseApi(`/api/pulse/groups/${{gcid.dataset.openGroupChatId}}/chat/open`,{{method:'POST',body:JSON.stringify({{}})}});location.href=d.next_url||('/pulse/messages/'+d.conversation_id);return}} if(invid){{inviteModal?.classList.add('open');return}} if(rid){{reportMode='group';pendingReportPostId=null;document.getElementById('groupReportTitle').textContent='Report Group';reportModal?.classList.add('open');return}} if(inviteUser){{setLoading(inviteUser,true,'Sending...');await pulseApi(`/api/pulse/groups/{group_id}/invite`,{{method:'POST',body:JSON.stringify({{invitee_user_id:inviteUser.dataset.sendGroupInvite}})}});toast('Invite sent.');setLoading(inviteUser,false);return}} if(j){{setLoading(j,true);const d=await pulseApi(`/api/pulse/groups/${{encodeURIComponent(j.dataset.joinGroup)}}/join`,{{method:'POST',body:JSON.stringify({{}})}});if(d.member_count!==undefined)updateMemberCount(d.member_count);toast(d.message||'Joined group.');setLoading(j,false)}} if(l){{setLoading(l,true);const d=await pulseApi(`/api/pulse/groups/${{encodeURIComponent(l.dataset.leaveGroup)}}/leave`,{{method:'POST',body:JSON.stringify({{}})}});if(d.member_count!==undefined)updateMemberCount(d.member_count);toast(d.message||'Left group.');setLoading(l,false)}} if(inv){{const url=location.origin+'/pulse/groups/'+encodeURIComponent(inv.dataset.inviteGroup);if(navigator.share){{navigator.share({{title:'Join this PulseSoc Group',url}}).catch(()=>{{}})}}else{{await navigator.clipboard.writeText(url).catch(()=>{{}});toast('Group invite link ready.')}}}} if(gc){{setLoading(gc,true);const d=await pulseApi(`/api/pulse/groups/${{encodeURIComponent(gc.dataset.openGroupChat)}}/chat/open`,{{method:'POST',body:JSON.stringify({{}})}});location.href=d.next_url||('/pulse/messages/'+d.conversation_id)}} if(r){{await pulseApi('/api/pulse/groups/report',{{method:'POST',body:JSON.stringify({{group_slug:r.dataset.reportGroup,reason:'Needs review'}})}});toast('Group report sent.')}} if(gr){{setLoading(gr,true);const d=await pulseApi(`/api/pulse/groups/posts/${{gr.dataset.groupReact}}/react`,{{method:'POST',body:JSON.stringify({{reaction_type:gr.dataset.reaction}})}});updateReactions(gr.dataset.groupReact,d);toast(d.message||'Reaction updated.');setLoading(gr,false)}} if(rp){{reportMode='post';document.getElementById('groupReportTitle').textContent='Report Post';pendingReportPostId=rp.dataset.groupReportPost;reportModal?.classList.add('open');closeMenus(rp);}} if(rm){{if(!confirm('Remove this user from the group?'))return;setLoading(rm,true);const d=await pulseApi(`/api/pulse/groups/posts/${{rm.closest('[data-group-post]')?.dataset.groupPost||0}}/remove-user`,{{method:'POST',body:JSON.stringify({{user_id:rm.dataset.groupRemoveUser}})}});toast(d.message||'User removed from group.');closeMenus(rm);setLoading(rm,false)}} if(pin){{setLoading(pin,true);const d=await pulseApi(`/api/pulse/groups/posts/${{pin.dataset.groupPostPin}}/pin`,{{method:'POST',body:JSON.stringify({{}})}});toast(d.message||'Pin updated.');const post=pin.closest('[data-group-post]');let badge=post?.querySelector('.pinned-pill');if(d.pinned&&!badge)post?.querySelector('.group-post-meta')?.insertAdjacentHTML('afterbegin','<span class="pill pinned-pill">Pinned</span> ');if(!d.pinned)badge?.remove();pin.textContent=d.pinned?'Unpin Post':'Pin Post';closeMenus(pin);setLoading(pin,false)}} if(cd){{setLoading(cd,true);await pulseApi(`/api/pulse/groups/comments/${{cd.dataset.groupCommentDelete}}/delete`,{{method:'POST',body:JSON.stringify({{}})}});cd.closest('[data-comment-id]')?.remove();toast('Comment deleted.')}} if(cr){{await pulseApi(`/api/pulse/groups/comments/${{cr.dataset.groupCommentReport}}/report`,{{method:'POST',body:JSON.stringify({{reason:'Needs review'}})}});toast('Comment report sent.')}} if(pd){{if(!confirm('Delete this group post?'))return;const post=pd.closest('[data-group-post]');setLoading(pd,true);const d=await pulseApi(`/api/pulse/groups/posts/${{pd.dataset.groupPostDelete}}/delete`,{{method:'POST',body:JSON.stringify({{reason:pd.dataset.deleteReason||'owner_delete'}})}});post?.animate([{{opacity:1,transform:'scale(1)'}},{{opacity:0,transform:'scale(.98)'}}],{{duration:180,easing:'ease'}}).onfinish=()=>post.remove();toast(d.message||'Group post deleted.');closeMenus(pd)}}}}catch(err){{console.error('Group action failed',err);toast(err.message)}}}});
    document.querySelectorAll('[data-group-comment-form]').forEach(form=>form.addEventListener('submit',async e=>{{e.preventDefault();const input=form.querySelector('input[name=body]');try{{const postId=form.dataset.groupCommentForm;const d=await pulseApi(`/api/pulse/groups/posts/${{postId}}/comments`,{{method:'POST',body:JSON.stringify({{body:input.value}})}});form.previousElementSibling?.insertAdjacentHTML('beforeend',renderGroupComment(d.comment));document.querySelectorAll(`[data-comment-count="${{postId}}"]`).forEach(n=>n.textContent=Number(n.textContent||0)+1);input.value='';toast('Comment posted.')}}catch(err){{toast(err.message)}}}}));
    document.getElementById('groupPostBtn')?.addEventListener('click',async()=>{{try{{const fd=new FormData();fd.append('body',document.getElementById('groupPostBody').value);const file=document.getElementById('groupMediaFile').files[0];if(file)fd.append('media',file);const r=await fetch('/api/pulse/groups/{slug}/posts',{{method:'POST',credentials:'same-origin',body:fd}});const d=await r.json();if(!r.ok||d.ok===false)throw new Error(d.message||'Could not post.');location.reload()}}catch(err){{toast(err.message)}}}});
    let groupLastEventId=0;
    function applyGroupLiveEvents(events){{(events||[]).forEach(ev=>{{const p=ev.payload||{{}};if(Number(p.group_id||0)!=={group_id})return;if(ev.event_type==='group_post_reacted')updateReactions(p.post_id,p);if(ev.event_type==='group_post_comment_created'){{const box=document.querySelector(`[data-comments-for="${{p.post_id}}"]`);if(box&&p.comment&&!box.querySelector(`[data-comment-id="${{p.comment.id}}"]`))box.insertAdjacentHTML('beforeend',renderGroupComment(p.comment));document.querySelectorAll(`[data-comment-count="${{p.post_id}}"]`).forEach(n=>n.textContent=p.comment_count||Number(n.textContent||0)+1)}}if(ev.event_type==='group_post_comment_deleted'){{document.querySelector(`[data-comment-id="${{p.comment_id}}"]`)?.remove();document.querySelectorAll(`[data-comment-count="${{p.post_id}}"]`).forEach(n=>n.textContent=p.comment_count||Math.max(0,Number(n.textContent||0)-1))}}if(ev.event_type==='group_post_updated'&&p.status==='deleted')document.querySelector(`[data-group-post="${{p.post_id}}"]`)?.remove();groupLastEventId=Math.max(groupLastEventId,Number(ev.id||0));}})}}
    async function pollGroupLive(){{try{{const d=await pulseApi(`/api/pulse/live?since_id=${{groupLastEventId}}`);applyGroupLiveEvents(d.events||[]);groupLastEventId=d.latest_event_id||groupLastEventId}}catch(_ ){{}}}}
    setInterval(()=>{{if(!document.hidden)pollGroupLive()}},3500)
    """
    return pulse_social_shell(group.get("name") or "PulseSoc Group", "A user-created community with posts, members, rules, and safety reporting.", main, "", script)


@webhook_app.route("/pulse/@<path:profile_key>", methods=["GET"])
@webhook_app.route("/pulse/u/<path:profile_key>", methods=["GET"])
@webhook_app.route("/pulse/id/<path:profile_key>", methods=["GET"])
@webhook_app.route("/pulse/profile/<path:profile_key>", methods=["GET"])
def pulse_profile_page(profile_key):
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    target_user_id = pulse_user_id_from_public(cur, profile_key)
    conn.close()
    if not target_user_id:
        return pulse_profile_not_found_page(profile_key)
    return pulse_profile_page_for_user(target_user_id)


def pulse_profile_page_for_user(target_user_id):
    init_db()
    viewer = require_account()
    if not viewer:
        return redirect(url_for("login_page", next=request.path))
    target_user_id = int(target_user_id or 0)
    if not target_user_id:
        return pulse_profile_not_found_page("")
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT user_id FROM users WHERE user_id=? LIMIT 1", (target_user_id,))
    if not cur.fetchone():
        conn.close()
        return pulse_profile_not_found_page(str(target_user_id))
    ident = pulse_identity_for_user(cur, target_user_id)
    cur.execute("SELECT COUNT(*) AS total FROM pulse_posts WHERE user_id=? AND deleted_at IS NULL", (target_user_id,))
    post_count = int(dict(cur.fetchone() or {}).get("total") or 0)
    cur.execute("SELECT COUNT(*) AS total FROM pulse_follows WHERE followed_user_id=?", (target_user_id,))
    follower_count = int(dict(cur.fetchone() or {}).get("total") or 0)
    cur.execute("SELECT COUNT(*) AS total FROM pulse_follows WHERE follower_user_id=?", (target_user_id,))
    following_count = int(dict(cur.fetchone() or {}).get("total") or 0)
    cur.execute("SELECT COUNT(*) AS total FROM pulse_group_members WHERE user_id=?", (target_user_id,))
    group_count = int(dict(cur.fetchone() or {}).get("total") or 0)
    cur.execute("SELECT * FROM marketplace_listings WHERE seller_user_id=? AND status='active' ORDER BY id DESC LIMIT 6", (target_user_id,))
    listings = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT * FROM teacher_profiles WHERE user_id=? LIMIT 1", (target_user_id,))
    teacher = dict(cur.fetchone() or {})
    cur.execute(
        """
        SELECT b.badge_key, b.label, b.description
        FROM pulse_user_badges ub
        JOIN pulse_badges b ON b.badge_key=ub.badge_key
        WHERE ub.user_id=? AND COALESCE(b.active,1)=1
        ORDER BY ub.id ASC
        """,
        (target_user_id,),
    )
    earned_badges = [dict(row) for row in cur.fetchall()]
    cur.execute(
        "SELECT badge_key, label, description FROM pulse_badges WHERE COALESCE(active,1)=1 ORDER BY id ASC"
    )
    badge_catalog = [dict(row) for row in cur.fetchall()]
    conn.close()
    listing_html = "".join(f"<article class='card'><h3>{clean_html(l.get('title'))}</h3><p>{clean_html(l.get('description') or '')}</p></article>" for l in listings)
    is_owner = int(target_user_id or 0) == int(viewer["user_id"])
    badge_priority = {"verified": 0, "founder": 1, "creator": 2, "vip": 3, "premium_verified_star": 4, "premium_verified_check": 4}
    earned_badges.sort(key=lambda badge: (badge_priority.get(str(badge.get("badge_key") or ""), 50), str(badge.get("label") or "")))
    top_badges = earned_badges[:5]
    badge_html = "".join(
        f"<span class='profile-role-badge' title='{clean_html(badge.get('description') or '')}'>{clean_html(badge.get('label') or 'Badge')}</span>"
        for badge in top_badges
    )
    earned_keys = {str(badge.get("badge_key") or "") for badge in earned_badges}
    all_badges_html = "".join(
        f"<article class='profile-badge-row {'earned' if str(badge.get('badge_key') or '') in earned_keys else 'locked'}'><span class='profile-badge-icon'>{'✓' if str(badge.get('badge_key') or '') in earned_keys else '◇'}</span><div><strong>{clean_html(badge.get('label') or 'PulseSoc badge')}</strong><p>{clean_html(badge.get('description') or 'PulseSoc community badge.')}</p><small>{'Earned' if str(badge.get('badge_key') or '') in earned_keys else 'Locked'}</small></div></article>"
        for badge in badge_catalog
    )
    premium_html = pulse_premium_mark_html(ident.get("premium_mark"))
    if is_owner:
        action_html = "<a class='button primary' href='/pulse/profile/edit'>Edit Profile</a><button type='button' data-share-profile>Share Profile</button><a class='button' href='/account'>Settings</a>"
        more_tools_html = "<a href='/pulse/profile/edit'>Profile Controls</a><a href='/account'>Account</a><a href='/privacy-center'>Privacy</a><a href='/pulse/teachers'>Teacher Status</a><a href='/pulse/marketplace'>Marketplace</a><a href='/pulse/music'>PulseSoc Music</a><a href='/pulse/creator/dashboard'>Creator Tools</a><a href='/pulse/live'>Livestream Studio</a><a href='/arena'>Arena Call Signs</a>"
    else:
        action_html = f"<button class='primary profile-action-primary' data-follow-public='{clean_html(ident['public_player_id'])}'><span aria-hidden='true'>＋</span> Follow</button><button class='profile-action-message' data-message-public='{clean_html(ident['public_player_id'])}'><span aria-hidden='true'>◇</span> Message</button><button class='profile-action-more' type='button' data-profile-more-toggle aria-label='More actions' aria-expanded='false'>•••</button>"
        more_tools_html = f"<button class='profile-sheet-action' data-friend-public='{clean_html(ident['public_player_id'])}'><span class='profile-sheet-icon' aria-hidden='true'>＋</span><span><strong>Add Friend</strong><small>Send a connection request</small></span></button><button class='profile-sheet-action' data-share-profile><span class='profile-sheet-icon' aria-hidden='true'>↗</span><span><strong>Share Profile</strong><small>Send this profile securely</small></span></button><div class='profile-sheet-divider' role='separator'></div><button class='profile-sheet-action profile-sheet-safety' data-open-report-profile><span class='profile-sheet-icon' aria-hidden='true'>!</span><span><strong>Report Profile</strong><small>Alert the PulseSoc safety team</small></span></button><button class='profile-sheet-action profile-sheet-danger' data-open-block-profile><span class='profile-sheet-icon' aria-hidden='true'>⊘</span><span><strong>Block User</strong><small>Stop contact and hide their activity</small></span></button>"
    avatar_html = f"<img src='{clean_html(ident.get('avatar_url'))}' alt=''>" if ident.get("avatar_url") else clean_html(ident["name"][:1])
    cover_style = f" style=\"background-image:linear-gradient(135deg,rgba(5,11,20,.38),rgba(5,11,20,.22)),url('{clean_html(ident.get('banner_url'))}');background-size:cover;background-position:center\"" if ident.get("banner_url") else ""
    main = f"""
    <style>
    .pulse-profile-page{{display:grid;gap:12px;min-width:0}}.pulse-profile-page>.card{{margin:0}}
    .pulse-profile-card{{padding:0;overflow:hidden;border-radius:20px;border-color:rgba(92,224,241,.28);background:linear-gradient(155deg,rgba(10,25,43,.96),rgba(4,12,24,.98));box-shadow:0 24px 80px rgba(0,0,0,.34),0 0 40px rgba(54,229,143,.06)}}.pulse-profile-cover{{height:clamp(170px,26vw,280px);position:relative;background:radial-gradient(circle at 20% 20%,rgba(54,229,143,.2),transparent 28%),radial-gradient(circle at 82% 14%,rgba(110,223,246,.28),transparent 30%),linear-gradient(135deg,#071625,#102441)}}.pulse-profile-cover:after{{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(110deg,transparent 35%,rgba(110,223,246,.08),transparent 64%),repeating-linear-gradient(90deg,transparent 0 72px,rgba(110,223,246,.035) 73px);mask-image:linear-gradient(to bottom,#000,transparent)}}
    .pulse-profile-identity{{display:grid;grid-template-columns:132px minmax(0,1fr);gap:18px;align-items:end;padding:0 20px 18px;margin-top:-66px}}.pulse-profile-avatar{{width:124px;height:124px;border-radius:32px;border:4px solid #071321;box-shadow:0 18px 55px rgba(0,0,0,.42),0 0 34px rgba(110,223,246,.2)}}
    .pulse-profile-copy{{min-width:0}}.pulse-profile-copy h1{{margin:0 0 5px;font-size:clamp(30px,5vw,48px)}}.pulse-profile-handle{{margin:0;color:#8fc9d8;font-weight:850}}.pulse-profile-bio{{margin:8px 0;color:#e8f7fb}}
    .profile-badges{{display:flex;gap:6px;flex-wrap:wrap}}.profile-role-badge{{display:inline-flex;border:1px solid rgba(110,223,246,.2);border-radius:999px;padding:5px 9px;background:rgba(110,223,246,.08);font-size:12px;font-weight:900;color:#dffaff}}
    .profile-badges-more{{border:0;background:transparent;color:#6edff6;padding:4px 2px;min-height:28px}}
    .pulse-profile-stats{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding:0 20px 14px}}.pulse-profile-stat{{text-align:center;border:1px solid rgba(255,255,255,.09);border-radius:14px;padding:10px 5px;background:rgba(255,255,255,.04);font-size:12px;color:#9fb5c0}}.pulse-profile-stat strong{{display:block;font-size:21px;color:#f5fcff}}
    .pulse-profile-actions{{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 48px;gap:8px;padding:0 20px 18px}}.pulse-profile-actions>*{{width:100%;min-width:0}}.profile-action-primary,.profile-action-message{{min-height:48px}}.profile-action-more{{width:48px!important;min-width:48px;border-radius:14px;padding:0;font-size:19px;letter-spacing:2px}}
    .pulse-profile-more{{position:fixed;inset:0;z-index:1750;display:none;place-items:end center;padding:16px;background:rgba(1,6,14,.72);backdrop-filter:blur(10px)}}.pulse-profile-more.open{{display:grid}}.pulse-profile-more:before{{content:"";position:absolute;inset:0}}.pulse-profile-more-inner{{position:relative;width:min(560px,100%);display:grid;gap:7px;border:1px solid rgba(110,223,246,.28);border-radius:22px;background:linear-gradient(165deg,#0b1b2d,#06101d);padding:12px;box-shadow:0 28px 100px rgba(0,0,0,.62),0 0 42px rgba(110,223,246,.1)}}.profile-sheet-head{{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:5px 4px 10px}}.profile-sheet-head span{{display:grid}}.profile-sheet-head small{{color:#8da7b4}}.profile-sheet-close{{width:40px!important;min-width:40px!important;height:40px!important;min-height:40px!important;border-radius:999px!important;padding:0!important}}.profile-sheet-action{{display:grid!important;grid-template-columns:42px minmax(0,1fr);gap:11px;align-items:center;text-align:left;min-height:58px!important;padding:8px 10px!important;border-color:rgba(255,255,255,.09)!important;background:rgba(255,255,255,.04)!important}}.profile-sheet-action>span:last-child{{display:grid}}.profile-sheet-action small{{font-weight:650;color:#8fa8b5}}.profile-sheet-icon{{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:rgba(110,223,246,.1);color:#7ae9fa;font-size:18px}}.profile-sheet-divider{{height:1px;background:rgba(255,255,255,.08);margin:4px}}.profile-sheet-safety .profile-sheet-icon{{color:#ffd166;background:rgba(255,209,102,.1)}}.profile-sheet-danger{{color:#ffc5cf!important;border-color:rgba(255,91,116,.18)!important}}.profile-sheet-danger .profile-sheet-icon{{color:#ff7188;background:rgba(255,91,116,.12)}}
    .pulse-profile-tabs{{display:flex;gap:4px;overflow-x:auto;padding:6px;border:1px solid rgba(110,223,246,.14);border-radius:16px;background:rgba(9,20,35,.88);scrollbar-width:none}}.pulse-profile-tabs a{{flex:1 0 auto;min-width:82px;padding:10px 12px;border-radius:11px;text-align:center;text-decoration:none;font-weight:900;color:#a9c5ce}}.pulse-profile-tabs a.active{{background:linear-gradient(135deg,rgba(54,229,143,.2),rgba(110,223,246,.18));color:#fff}}
    .pulse-profile-feed-card{{padding:10px;overflow-anchor:none}}.pulse-profile-feed-card h2{{margin:3px 4px 10px}}.pulse-profile-feed-frame{{display:block;width:100%;min-height:760px;border:0;border-radius:14px;background:#071321;overflow-anchor:none}}
    .pulse-profile-about-grid{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.pulse-profile-secondary details summary{{cursor:pointer;font-weight:950}}.pulse-profile-secondary .profile-tool-links{{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin-top:12px}}.profile-tool-links a{{text-decoration:none}}
    .profile-badges-modal,.profile-safety-modal{{position:fixed;inset:0;z-index:1800;display:none;place-items:end center;background:rgba(1,6,14,.72);backdrop-filter:blur(10px);padding:16px}}.profile-badges-modal.open,.profile-safety-modal.open{{display:grid}}.profile-badges-sheet,.profile-safety-sheet{{width:min(680px,100%);max-height:min(82dvh,760px);overflow:auto;border:1px solid rgba(110,223,246,.22);border-radius:24px;background:#071321;padding:16px;box-shadow:0 28px 100px rgba(0,0,0,.55)}}.profile-badges-head,.profile-safety-head{{display:grid;grid-template-columns:minmax(0,1fr) 42px;gap:12px;align-items:center;position:sticky;top:-16px;background:#071321;padding:10px 0;z-index:2}}.profile-badges-head h2,.profile-safety-head h2{{margin:0}}.profile-badges-head button,.profile-safety-head button{{width:42px!important;min-width:42px!important;height:42px!important;min-height:42px!important;padding:0!important;border-radius:999px}}.profile-badges-list,.profile-report-reasons{{display:grid;gap:8px}}.profile-badge-row{{display:grid;grid-template-columns:42px minmax(0,1fr);gap:10px;border:1px solid rgba(255,255,255,.09);border-radius:14px;padding:10px;background:rgba(255,255,255,.04)}}.profile-badge-row.locked{{opacity:.56}}.profile-badge-icon{{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(54,229,143,.24),rgba(110,223,246,.22));font-size:20px;font-weight:950}}.profile-badge-row p,.profile-badge-row small{{margin:2px 0}}.profile-report-reason{{display:grid;grid-template-columns:24px minmax(0,1fr);gap:10px;align-items:center;min-height:48px;border:1px solid rgba(255,255,255,.09);border-radius:13px;padding:9px 11px;background:rgba(255,255,255,.035);font-weight:850}}.profile-report-reason input{{width:20px;height:20px;margin:0;accent-color:#36e58f}}.profile-safety-copy{{color:#a8bbc6;margin:0 0 12px}}.profile-safety-actions{{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}}.profile-danger-confirm{{background:#ff5b74!important;color:#16040a!important;border:0!important}}body.profile-sheet-open{{overflow:hidden}}
    @media(max-width:900px){{body:has(.pulse-profile-page) .layout>aside{{display:none}}body:has(.pulse-profile-page) .layout{{display:block}}body:has(.pulse-profile-page) .pulse-fab{{display:none!important}}}}
    @media(max-width:620px){{body:has(.pulse-profile-page) .wrap{{padding-left:8px;padding-right:8px}}.pulse-profile-page{{gap:8px}}.pulse-profile-card{{border-radius:16px}}.pulse-profile-cover{{height:116px}}.pulse-profile-identity{{grid-template-columns:78px minmax(0,1fr);gap:10px;align-items:start;padding:0 12px 10px;margin-top:-39px;text-align:left;justify-items:stretch}}.pulse-profile-avatar{{width:78px;height:78px;border-radius:22px;border-width:3px}}.pulse-profile-copy{{padding-top:32px}}.pulse-profile-copy h1{{font-size:24px;line-height:1;margin-bottom:4px}}.pulse-profile-handle{{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}.pulse-profile-bio{{font-size:13px;line-height:1.3;margin:5px 0}}.profile-role-badge{{font-size:10px;padding:4px 7px}}.profile-role-badge:nth-of-type(n+4){{display:none}}.profile-badges-more{{font-size:11px;min-height:24px}}.pulse-profile-stats{{padding:0 10px 10px;gap:5px}}.pulse-profile-stat{{padding:8px 2px;font-size:10px;border-radius:10px;background:rgba(255,255,255,.035)}}.pulse-profile-stat strong{{font-size:18px}}.pulse-profile-actions{{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 44px;padding:0 10px 11px;gap:6px}}.pulse-profile-actions>*{{min-height:44px;padding:7px 5px;font-size:12px;border-radius:11px;white-space:nowrap}}.profile-action-more{{width:44px!important;min-width:44px!important}}.pulse-profile-more{{padding:0;align-items:end}}.pulse-profile-more-inner{{border-radius:24px 24px 0 0;padding:12px 12px calc(16px + env(safe-area-inset-bottom))}}.pulse-profile-tabs{{margin:0;border-radius:12px;padding:4px}}.pulse-profile-tabs a{{min-width:70px;padding:9px 10px;font-size:12px}}.pulse-profile-feed-card{{padding:4px;border:0;background:transparent;box-shadow:none}}.pulse-profile-feed-card h2{{display:none}}.pulse-profile-feed-frame{{min-height:820px;border-radius:12px}}.pulse-profile-about-grid{{grid-template-columns:1fr}}.profile-badges-modal,.profile-safety-modal{{padding:0;align-items:end}}.profile-badges-sheet,.profile-safety-sheet{{border-radius:24px 24px 0 0;max-height:84dvh;padding-bottom:calc(18px + env(safe-area-inset-bottom))}}}}
    </style>
    <div class='pulse-profile-page' data-pulse-profile-page data-profile-owner='{'1' if is_owner else '0'}'>
      <section class='card pulse-profile-card'>
        <div class='pulse-profile-cover'{cover_style}></div>
        <div class='pulse-profile-identity'>
          <span class='avatar pulse-profile-avatar'>{avatar_html}</span>
          <div class='pulse-profile-copy'>
            <h1>{clean_html(ident['name'])}{premium_html}</h1>
            <p class='pulse-profile-handle'>@{clean_html(ident.get('username') or ident['public_player_id'])}</p>
            <p class='pulse-profile-bio'>{clean_html(ident.get('bio') or 'No bio yet.')}</p>
            <div class='profile-badges'>{badge_html or '<span class="profile-role-badge">' + clean_html(ident.get('primary_label') or ident.get('rank') or 'Member') + '</span>'}<button class='profile-badges-more' type='button' data-open-profile-badges>View All Badges</button></div>
          </div>
        </div>
        <div class='pulse-profile-stats' aria-label='Profile statistics'>
          <span class='pulse-profile-stat'><strong>{post_count}</strong>Posts</span><span class='pulse-profile-stat'><strong>{follower_count}</strong>Followers</span><span class='pulse-profile-stat'><strong>{following_count}</strong>Following</span><span class='pulse-profile-stat'><strong>{group_count}</strong>Groups</span>
        </div>
        <div class='pulse-profile-actions'>{action_html}</div>
      </section>
      <nav class='pulse-profile-tabs' aria-label='Profile content'><a class='active' href='#profilePosts'>Posts</a><a href='/pulse/reels?creator={clean_html(ident['public_player_id'])}'>Reels</a><a href='/pulse/videos?creator={clean_html(ident['public_player_id'])}'>Videos</a><a href='/pulse?profile={clean_html(ident['public_player_id'])}&topic=photo'>Photos</a><a href='#profileAbout'>About</a></nav>
      <section class='card pulse-profile-feed-card' id='profilePosts'><h2>Posts</h2><iframe class='pulse-profile-feed-frame' title='{clean_html(ident['name'])} posts' src='/pulse?profile={clean_html(ident['public_player_id'])}&embed=profile' loading='eager'></iframe></section>
      <section class='pulse-profile-about-grid' id='profileAbout'>
        <article class='card'><h2>About</h2><p>{clean_html(ident.get('bio') or 'This creator has not added a bio yet.')}</p><p class='muted'>{post_count} posts · {follower_count} followers · {group_count} groups</p></article>
        <article class='card'><h2>Creator Activity</h2><p>{clean_html((teacher.get('category') or 'Community member'))} · {clean_html((teacher.get('verification_status') or 'No teacher status'))}</p><p>{len(listings)} active marketplace listing{'s' if len(listings) != 1 else ''}.</p></article>
      </section>
      <section class='card pulse-profile-secondary'><details><summary>{'Settings and creator tools' if is_owner else 'More profile options'}</summary><div class='profile-tool-links'>{more_tools_html}</div></details></section>
    </div>
    <div class='pulse-profile-more' data-profile-more aria-hidden='true'><div class='pulse-profile-more-inner'><header class='profile-sheet-head'><span><strong>{clean_html(ident['name'])}</strong><small>Profile actions</small></span><button class='profile-sheet-close' type='button' data-close-profile-more aria-label='Close profile actions'>×</button></header>{more_tools_html}</div></div>
    <section class='profile-badges-modal' data-profile-badges-modal aria-hidden='true' role='dialog' aria-modal='true' aria-label='All profile badges'><div class='profile-badges-sheet'><header class='profile-badges-head'><div><h2>All Badges</h2><small>{len(earned_badges)} earned</small></div><button type='button' data-close-profile-badges aria-label='Close badges'>×</button></header><div class='profile-badges-list'>{all_badges_html or '<p>No badges are available yet.</p>'}</div></div></section>
    <section class='profile-safety-modal' data-profile-report-modal aria-hidden='true' role='dialog' aria-modal='true' aria-label='Report profile'><form class='profile-safety-sheet' data-profile-report-form><header class='profile-safety-head'><div><h2>Report Profile</h2><small>Private and confidential</small></div><button type='button' data-close-profile-report aria-label='Close report profile'>×</button></header><p class='profile-safety-copy'>Choose the issue that best describes this account. PulseSoc reviews reports without telling the reported user who submitted them.</p><div class='profile-report-reasons'><label class='profile-report-reason'><input type='radio' name='reason' value='Spam or misleading activity' required><span>Spam or misleading activity</span></label><label class='profile-report-reason'><input type='radio' name='reason' value='Harassment or bullying'><span>Harassment or bullying</span></label><label class='profile-report-reason'><input type='radio' name='reason' value='Scam, fraud, or impersonation'><span>Scam, fraud, or impersonation</span></label><label class='profile-report-reason'><input type='radio' name='reason' value='Hateful or inappropriate content'><span>Hateful or inappropriate content</span></label><label class='profile-report-reason'><input type='radio' name='reason' value='Other safety concern'><span>Other safety concern</span></label></div><div class='profile-safety-actions'><button type='button' data-close-profile-report>Cancel</button><button class='primary' type='submit'>Submit Report</button></div></form></section>
    <section class='profile-safety-modal' data-profile-block-modal aria-hidden='true' role='dialog' aria-modal='true' aria-label='Block user'><div class='profile-safety-sheet'><header class='profile-safety-head'><div><h2>Block {clean_html(ident['name'])}?</h2><small>Immediate privacy protection</small></div><button type='button' data-close-profile-block aria-label='Close block user'>×</button></header><p class='profile-safety-copy'>They will no longer be able to message or interact with you, and their activity will be hidden from your PulseSoc experience. You can manage blocked accounts later in Privacy.</p><div class='profile-safety-actions'><button type='button' data-close-profile-block>Cancel</button><button class='profile-danger-confirm' type='button' data-confirm-block-profile data-public-player-id='{clean_html(ident['public_player_id'])}'>Block User</button></div></div></section>
    """
    script = """
    const badgeModal=document.querySelector('[data-profile-badges-modal]');
    const profileMore=document.querySelector('[data-profile-more]');
    const reportModal=document.querySelector('[data-profile-report-modal]');
    const blockModal=document.querySelector('[data-profile-block-modal]');
    const setBadgeModal=open=>{badgeModal?.classList.toggle('open',open);badgeModal?.setAttribute('aria-hidden',open?'false':'true')};
    const syncProfileSheetLock=()=>document.body.classList.toggle('profile-sheet-open',!!document.querySelector('.pulse-profile-more.open,.profile-safety-modal.open,.profile-badges-modal.open'));
    const setProfileModal=(modal,open)=>{modal?.classList.toggle('open',open);modal?.setAttribute('aria-hidden',open?'false':'true');syncProfileSheetLock()};
    const setProfileMore=open=>{profileMore?.classList.toggle('open',open);profileMore?.setAttribute('aria-hidden',open?'false':'true');const toggle=document.querySelector('[data-profile-more-toggle]');toggle?.setAttribute('aria-expanded',open?'true':'false');syncProfileSheetLock()};
    const closeProfileSheets=()=>{setProfileMore(false);setProfileModal(reportModal,false);setProfileModal(blockModal,false);setBadgeModal(false);syncProfileSheetLock()};
    function hydrateProfileFeedFrame(frame){try{const doc=frame.contentDocument;if(!doc)return;if(!doc.getElementById('pulseProfileEmbedStyles')){doc.documentElement.classList.add('profile-feed-embed');const style=doc.createElement('style');style.id='pulseProfileEmbedStyles';style.textContent=`body>header,.pulse-desktop-rail,.mobile-topbar,.mobile-bottom-nav,.pulse-fab,.pulse-status-home-shell,.pulse-home-status-rail,.pulse-status-rail,.pulse-publisher-card,#pulseComposer,#tabs,#newPulsesBanner,#loadMore,.pulse-desktop-intel,.layout>aside,html.profile-feed-embed body .pulse-desktop-center .pulse-home-hero.hero.card{display:none!important}.wrap,.pulse-shell{width:100%!important;max-width:100%!important;padding:0!important;margin:0!important}.pulse-desktop-layout,.pulse-desktop-center,.layout,.layout>div,#feed{display:block!important;width:100%!important;max-width:100%!important;margin:0!important;padding:0!important}.feed>.post-card-modern{margin:0 0 10px!important}body{background:transparent!important}.card{box-shadow:none!important}`;doc.head.appendChild(style)}const resize=()=>{frame.style.height=Math.max(720,doc.documentElement.scrollHeight+8)+'px'};resize();if(!frame.dataset.resizeBound&&window.ResizeObserver){frame.dataset.resizeBound='1';new ResizeObserver(resize).observe(doc.body)}}catch(_){}}
    document.querySelectorAll('.pulse-profile-feed-frame').forEach(frame=>{frame.addEventListener('load',()=>hydrateProfileFeedFrame(frame));setTimeout(()=>hydrateProfileFeedFrame(frame),0)});
    document.addEventListener('click',async e=>{const follow=e.target.closest('[data-follow-public]'),friend=e.target.closest('[data-friend-public]'),msg=e.target.closest('[data-message-public]'),share=e.target.closest('[data-share-profile]');if(e.target.closest('[data-open-profile-badges]')){setBadgeModal(true);syncProfileSheetLock();return}if(e.target.closest('[data-close-profile-badges]')||e.target===badgeModal){setBadgeModal(false);syncProfileSheetLock();return}if(e.target.closest('[data-profile-more-toggle]')){setProfileMore(true);return}if(e.target.closest('[data-close-profile-more]')||e.target===profileMore){setProfileMore(false);return}if(e.target.closest('[data-open-report-profile]')){setProfileMore(false);setProfileModal(reportModal,true);return}if(e.target.closest('[data-close-profile-report]')||e.target===reportModal){setProfileModal(reportModal,false);return}if(e.target.closest('[data-open-block-profile]')){setProfileMore(false);setProfileModal(blockModal,true);return}if(e.target.closest('[data-close-profile-block]')||e.target===blockModal){setProfileModal(blockModal,false);return}const confirmBlock=e.target.closest('[data-confirm-block-profile]');try{if(confirmBlock){confirmBlock.disabled=true;confirmBlock.textContent='Blocking...';await pulseApi('/api/pulse/block',{method:'POST',body:JSON.stringify({public_player_id:confirmBlock.dataset.publicPlayerId,reason:'Blocked from profile safety controls'})});setProfileModal(blockModal,false);toast('User blocked. Their activity is now hidden.');setTimeout(()=>location.href='/pulse',700);return}if(share){if(navigator.share)await navigator.share({title:document.title,url:location.href});else{await navigator.clipboard.writeText(location.href);toast('Profile link copied.')}setProfileMore(false);return}if(follow){follow.disabled=true;follow.textContent='Following';await pulseApi('/api/pulse/follow',{method:'POST',body:JSON.stringify({public_player_id:follow.dataset.followPublic})});toast('Followed.')} if(friend){friend.disabled=true;await pulseApi('/api/pulse/friends/request',{method:'POST',body:JSON.stringify({public_player_id:friend.dataset.friendPublic})});friend.querySelector('strong').textContent='Request Sent';toast('Friend request sent.');setProfileMore(false)} if(msg){const d=await pulseApi('/api/pulse/messages/start',{method:'POST',body:JSON.stringify({public_player_id:msg.dataset.messagePublic})});location.href=d.next_url}}catch(err){if(follow){follow.disabled=false;follow.textContent='Follow'}if(confirmBlock){confirmBlock.disabled=false;confirmBlock.textContent='Block User'}toast(err.message)}})
    document.querySelector('[data-profile-report-form]')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const reason=new FormData(form).get('reason');if(!reason)return;const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Sending...';try{await pulseApi('/api/pulse/report',{method:'POST',body:JSON.stringify({target_type:'user',target_id:__TARGET_USER_ID__,reason:String(reason)})});setProfileModal(reportModal,false);form.reset();toast('Report submitted. PulseSoc Safety will review it.')}catch(err){toast(err.message)}finally{submit.disabled=false;submit.textContent='Submit Report'}});
    document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfileSheets()});
    window.addEventListener('pagehide',closeProfileSheets,{once:true});
    """
    script = script.replace("__TARGET_USER_ID__", str(target_user_id))
    return pulse_social_shell(f"{ident['name']} Profile", "PulseSoc social identity hub with posts, followers, groups, marketplace, teacher status, and safe messaging. Arena call signs stay in battle areas.", main, "", script, show_intro=False)


@webhook_app.route("/pulse/post/<int:post_id>", methods=["GET"])
def pulse_post_page(post_id):
    init_db()
    user = require_account()
    post = pulse_feed_engine.get_post(post_id, viewer_user_id=(user or {}).get("user_id"), include_private=bool(user))
    if not post:
        return Response("PulseSoc post not found.", status=404)
    is_public_indexable = post.get("visibility") == "public" and post.get("moderation_status") == "approved"
    title = post.get("title") or (post.get("body") or "PulseSoc Post")[:72]
    description = post.get("ai_summary") or (post.get("body") or "Community post on PulseSoc.")[:155]
    media = (post.get("media") or [{}])[0]
    image = media.get("thumbnail_url") or media.get("media_url") or "/static/brand/pulsesoc-logo-20260606.png"
    comments = pulse_feed_engine.list_comments(post_id).get("comments", [])
    comment_html = "".join(f"<div class='comment'><strong>{clean_html(c.get('author',{}).get('display_name') or 'PulseSoc user')}{pulse_premium_mark_html(c.get('author',{}).get('premium_mark'))}</strong><p>{clean_html(c.get('body') or '')}</p><small>{smart_time_html(c.get('created_at'))}</small></div>" for c in comments)
    media_html = ""
    for item in post.get("media") or []:
        media_id = clean_html(item.get("id") or "")
        media_url = clean_html(item.get("media_url") or "")
        thumb_url = clean_html(item.get("thumbnail_url") or item.get("media_url") or "")
        mime_type = clean_html(item.get("mime_type") or "")
        width = safe_int(item.get("width"), 0)
        height = safe_int(item.get("height"), 0)
        ratio = float(item.get("aspect_ratio") or 0) if item.get("aspect_ratio") else (float(width) / float(height) if width and height else 0)
        orient = clean_html(item.get("orientation") or ("square" if ratio and abs(ratio - 1) < 0.08 else "landscape" if ratio and ratio > 1 else "portrait" if ratio else "unknown"))
        dims = f" width='{width}' height='{height}'" if width and height else ""
        is_video_item = item.get("media_type") == "video"
        poster_url = clean_html(item.get("poster_url") or "")
        backdrop_url = poster_url if poster_url and not re.search(r"\.(mp4|webm|mov|m4v)(\?|#|$)", poster_url, re.I) else ""
        backdrop_style = f" style=\"--media-ratio:{ratio};--media-backdrop:url('{backdrop_url}');\"" if ratio else f" style=\"--media-backdrop:url('{backdrop_url}');\""
        cinematic_layers = "<div class='pulse-media-backdrop' aria-hidden='true'></div><div class='pulse-media-soft-glow' aria-hidden='true'></div><div class='pulse-media-color-orb' aria-hidden='true'></div><div class='pulse-media-depth-layer' aria-hidden='true'></div><div class='pulse-media-aura' aria-hidden='true'></div><div class='pulse-media-vignette' aria-hidden='true'></div>"
        fallback = f"<div class='pulse-media-fallback'><div><strong>Media could not load.</strong><span>Tap to retry. Trace media-{media_id or 'unknown'}</span><br><button type='button' onclick='location.reload()'>Retry</button></div></div>"
        if is_video_item:
            poster_attr = f" poster='{poster_url}'" if poster_url else ""
            type_attr = f" type='{mime_type}'" if mime_type else ""
            media_html += f"<div class='pulse-media-wrap pulse-cinematic-media-shell pulse-media-galaxy-shell pulse-media-ambient-shell is-{orient}' data-media-id='{media_id}' data-media-url='{media_url}' data-media-mime='{mime_type}' data-media-backdrop='{backdrop_url}'{backdrop_style}>{cinematic_layers}<video controls playsinline preload='metadata'{poster_attr}{dims} onerror=\"this.style.visibility='hidden';this.closest('.pulse-media-wrap').classList.add('is-broken');console.warn('PulseSoc media failed',this.closest('.pulse-media-wrap').dataset)\"><source src='{media_url}'{type_attr}></video>{fallback}</div>"
        else:
            media_html += f"<div class='pulse-media-wrap pulse-cinematic-media-shell pulse-media-galaxy-shell pulse-media-ambient-shell is-{orient}' data-media-id='{media_id}' data-media-url='{media_url}' data-media-backdrop='{backdrop_url}'{backdrop_style}>{cinematic_layers}<img src='{thumb_url}' data-full-src='{media_url}' alt='PulseSoc media' loading='lazy' decoding='async'{dims} onerror=\"if(this.dataset.fullSrc&&this.src!==new URL(this.dataset.fullSrc,location.origin).href){{this.src=this.dataset.fullSrc}}else{{this.style.visibility='hidden';this.closest('.pulse-media-wrap').classList.add('is-broken');console.warn('PulseSoc media failed',this.closest('.pulse-media-wrap').dataset)}}\">{fallback}</div>"
    counts = post.get("reaction_counts") or {}
    reaction_icons = {"fire": "🔥", "smart": "🧠", "scam_alert": "🚨", "whale": "🐋", "bullish": "📈", "bearish": "📉", "funny": "😂", "elite": "👑"}
    reaction_buttons = "".join(
        f"<button class='reaction-pill {'active' if post.get('viewer_reaction') == key else ''}' data-react='{clean_html(key)}'><span>{icon}</span> <b>{int(counts.get(key) or 0)}</b></button>"
        for key, icon in reaction_icons.items()
    )
    tags_html = "".join(f"<a class='tag' href='/pulse/topic/{clean_html(tag)}'>#{clean_html(tag)}</a>" for tag in post.get("tags") or [])
    author_public_id = (post.get("author") or {}).get("public_player_id") or ""
    author_profile_url = f"/pulse/profile/{clean_html(author_public_id)}" if author_public_id else "/pulse/profile"
    author = post.get("author") or {}
    author_label = author.get("primary_label") or author.get("rank") or (author.get("badges") or ["Member"])[0]
    author_mark = pulse_premium_mark_html(author.get("premium_mark"))
    return Response(f"""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><title>{clean_html(title)} | PulseSoc</title><meta name='description' content='{clean_html(description)}'><meta name='robots' content='{"index,follow,max-image-preview:large" if is_public_indexable else "noindex,nofollow"}'><link rel='canonical' href='https://pulsesoc.com/pulse/post/{post_id}'><meta property='og:title' content='{clean_html(title)}'><meta property='og:description' content='{clean_html(description)}'><meta property='og:image' content='{clean_html(image)}'><meta name='twitter:card' content='summary_large_image'><style>:root{{color-scheme:dark;--line:rgba(110,223,246,.22);--muted:#9fb5c0;--cyan:#6edff6;--green:#36e58f}}*{{box-sizing:border-box}}html,body{{max-width:100%;overflow-x:hidden}}body{{margin:0;background:radial-gradient(circle at 12% 0,rgba(110,223,246,.18),transparent 28rem),linear-gradient(145deg,#050b14,#081421);color:#f2fbff;font-family:Inter,system-ui,sans-serif}}.wrap{{width:min(100% - 28px,900px);margin:auto;padding:max(20px,env(safe-area-inset-top)) 0 calc(98px + env(safe-area-inset-bottom))}}.card{{border:1px solid var(--line);border-radius:16px;background:rgba(13,22,39,.9);padding:14px;margin:12px 0;box-shadow:0 20px 70px rgba(0,0,0,.24);position:relative;overflow:hidden}}a{{color:var(--cyan)}}p,.muted,small{{color:var(--muted);line-height:1.55}}.smart-time{{font-size:.82rem;color:rgba(217,247,255,.62);white-space:nowrap}}.time-dot{{opacity:.42;margin:0 4px}}h1{{font-size:clamp(30px,7vw,56px);line-height:1;margin:8px 0 12px}}img,video{{width:100%;max-height:min(74vh,760px);object-fit:contain;border-radius:12px;background:#020817;border:1px solid rgba(255,255,255,.08)}}.pulse-media-wrap{{position:relative;isolation:isolate;overflow:hidden;border-radius:14px;background:radial-gradient(circle at 50% 20%,rgba(110,223,246,.14),transparent 32%),#020817;border:1px solid rgba(110,223,246,.18);margin:12px 0;box-shadow:0 18px 70px rgba(0,0,0,.34),0 0 46px rgba(54,229,143,.08)}}.pulse-cinematic-media-shell:before,.pulse-cinematic-media-shell:after,.pulse-media-backdrop,.pulse-media-depth-layer,.pulse-media-aura{{position:absolute;inset:0;pointer-events:none}}.pulse-media-backdrop{{z-index:0;inset:-12%;background-image:var(--media-backdrop);background-size:cover;background-position:center;filter:blur(34px) saturate(1.32) brightness(.62);opacity:.86;transform:scale(1.08)}}.pulse-media-depth-layer{{z-index:1;background:radial-gradient(circle at var(--pulse-media-x,50%) var(--pulse-media-y,42%),rgba(var(--pulse-media-rgb,110,223,246),.3),transparent 35%),radial-gradient(circle at 12% 18%,rgba(54,229,143,.16),transparent 36%),radial-gradient(circle at 86% 80%,rgba(166,88,255,.15),transparent 38%),linear-gradient(180deg,rgba(2,8,17,.18),rgba(2,8,17,.58));mix-blend-mode:screen;opacity:.74}}.pulse-media-aura{{z-index:2;border-radius:inherit;box-shadow:inset 0 0 54px rgba(var(--pulse-media-rgb,110,223,246),.16),inset 0 -34px 72px rgba(0,0,0,.28),0 0 52px rgba(var(--pulse-media-rgb,110,223,246),.1);background:linear-gradient(115deg,transparent 10%,rgba(255,255,255,.06) 48%,transparent 62%);opacity:.8}}.pulse-cinematic-media-shell:before{{content:"";z-index:3;background:radial-gradient(1px 1px at 18% 22%,rgba(110,223,246,.55),transparent),radial-gradient(1px 1px at 77% 26%,rgba(54,229,143,.45),transparent),radial-gradient(1px 1px at 66% 72%,rgba(166,88,255,.42),transparent);background-size:150px 150px,190px 190px,230px 230px;opacity:.28}}.pulse-cinematic-media-shell:after{{content:"";z-index:4;border-radius:inherit;background:linear-gradient(180deg,rgba(255,255,255,.06),transparent 22%,transparent 76%,rgba(0,0,0,.18));box-shadow:inset 0 0 0 1px rgba(255,255,255,.045)}}.pulse-media-wrap img,.pulse-media-wrap video{{position:relative;z-index:5;display:block;border:0;width:100%;height:auto;object-fit:contain;object-position:center;background:transparent!important;filter:drop-shadow(0 18px 44px rgba(0,0,0,.42))}}.pulse-media-fallback{{position:absolute;z-index:7;inset:0;display:none;place-items:center;text-align:center;padding:18px;background:linear-gradient(145deg,rgba(8,19,35,.92),rgba(4,9,17,.96));color:#dffcff}}.pulse-media-fallback strong{{display:block;margin-bottom:5px}}.pulse-media-wrap.is-broken .pulse-media-fallback{{display:grid}}button,.button,input{{min-height:42px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.06);color:#f2fbff;padding:9px 12px;font-weight:900;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:7px}}.primary{{background:linear-gradient(135deg,var(--green),var(--cyan));color:#06101b;border:0}}.actions,.tags{{display:flex;gap:8px;flex-wrap:wrap}}.pulse-post-actions-old,.pulse-action-wall,.reaction-stack{{display:none!important}}.tag{{font-size:12px;border:1px solid rgba(110,223,246,.2);border-radius:999px;padding:5px 9px;text-decoration:none}}.author{{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}}.badge{{display:inline-flex;border:1px solid rgba(255,255,255,.12);border-radius:999px;padding:5px 9px;color:#dffcff;background:rgba(110,223,246,.08)}}.menu-btn{{width:38px;height:38px;min-height:38px;border-radius:999px;padding:0;font-size:20px}}.post-sheet{{display:none;position:fixed;left:12px;right:12px;bottom:calc(110px + env(safe-area-inset-bottom));z-index:20;border:1px solid var(--line);border-radius:18px;background:#071321;padding:10px;box-shadow:0 24px 80px rgba(0,0,0,.5)}}.post-sheet.open{{display:grid;gap:7px}}.post-sheet .button,.post-sheet button{{width:100%;justify-content:flex-start}}.reactions{{display:flex;gap:6px;overflow-x:auto;flex-wrap:nowrap;scrollbar-width:none}}.reaction-pill{{flex:0 0 auto;min-height:34px;border-radius:999px;padding:6px 10px;font-size:13px}}.reaction-pill.active{{background:rgba(54,229,143,.18);border-color:rgba(54,229,143,.5);box-shadow:0 0 24px rgba(54,229,143,.15)}}.comment{{border-radius:12px;padding:8px 10px;background:rgba(255,255,255,.04);margin:7px 0}}.comment p{{margin:3px 0}}.comment-box{{display:grid;grid-template-columns:minmax(0,1fr) 42px;gap:7px;align-items:center}}.comment-box input{{border-radius:999px;min-height:40px}}.comment-box button{{width:42px;min-height:40px;border-radius:999px;padding:0}}@media(max-width:720px){{.wrap{{width:100%;padding:max(24px,env(safe-area-inset-top)) 10px calc(160px + env(safe-area-inset-bottom))}}.actions{{overflow-x:auto;flex-wrap:nowrap}}.actions .button,.actions button{{white-space:nowrap}}}}</style></head><body><main class='wrap'><nav class='actions'><a class='button' href='/pulse'>Back to PulseSoc</a><a class='button' href='/pulse/my-posts'>My Posts</a><a class='button' href='/pulse#create'>Create</a><button id='shareBtn' type='button'>Share</button></nav><article class='card'><div class='author'><p><strong>{clean_html(author.get('display_name') or 'PulseSoc creator')}{author_mark}</strong><br><span class='badge'>{clean_html(author_label or 'Member')}</span><br><small>{smart_time_html(post.get('created_at'))}</small></p><button class='menu-btn' id='moreBtn' type='button'>⋯</button></div><h1>{clean_html(title)}</h1><p>{clean_html(post.get('body') or '')}</p>{media_html}<div class='tags'>{tags_html}</div><p class='muted'>Type: {clean_html(post.get('post_type') or 'post')} · Status: {clean_html(post.get('moderation_status') or 'approved')} · Risk score: {int(post.get('risk_score') or 0)}</p><div class='reactions'>{reaction_buttons}</div><p>{PULSE_DISCLAIMER}</p></article><section class='card'><h2>Comments</h2><div id='comments'>{comment_html or '<p>No comments yet.</p>'}</div><form class='comment-box' id='commentForm'><input name='body' placeholder='Write a comment...'><button class='primary'>➤</button></form></section><section class='post-sheet' id='postSheet'><a class='button primary' href='/pulse/post/{post_id}'>View post</a><a class='button' href='{author_profile_url}'>View profile</a><button id='sheetShare' type='button'>Share</button><a class='button' href='/pulse/my-posts'>My Posts</a></section></main><script src='/static/js/time.js'></script><script src='/static/js/pulse_media_renderer.js?v=global-media-ui-20260628g'></script><script>async function api(url,opts={{}}){{const r=await fetch(url,{{credentials:'same-origin',cache:'no-store',headers:{{'Content-Type':'application/json',...(opts.headers||{{}})}},...opts}});const d=await r.json().catch(()=>({{}}));if(!r.ok||d.ok===false)throw new Error(d.error||d.message||'Request failed.');return d}}const share=async()=>{{const url=location.href;if(navigator.share){{await navigator.share({{title:document.title,url}}).catch(()=>{{}})}}else{{await navigator.clipboard.writeText(url).catch(()=>{{}});alert('Post link copied.')}}}};document.getElementById('shareBtn').addEventListener('click',share);document.getElementById('sheetShare').addEventListener('click',share);document.getElementById('moreBtn').addEventListener('click',()=>document.getElementById('postSheet').classList.toggle('open'));document.querySelectorAll('[data-react]').forEach(btn=>btn.addEventListener('click',async()=>{{try{{await api('/api/pulse/posts/{post_id}/react',{{method:'POST',body:JSON.stringify({{reaction_type:btn.dataset.react}})}});btn.classList.add('active')}}catch(e){{alert(e.message)}}}}));document.getElementById('commentForm').addEventListener('submit',async e=>{{e.preventDefault();const input=e.target.body;if(!input.value.trim())return;try{{await api('/api/pulse/posts/{post_id}/comments',{{method:'POST',body:JSON.stringify({{body:input.value}})}});location.reload()}}catch(err){{alert(err.message)}}}});window.CoinPilotTime?.hydrate(document);window.PulseMediaRenderer?.hydrate(document);</script></body></html>""")


def pulse_attach_video_detail_links(posts):
    """Attach validated internal watch URLs to feed video posts."""
    video_posts = []
    for post in posts or []:
        media_items = list(post.get("media") or [])
        primary = media_items[0] if media_items else {}
        media_type = str(primary.get("media_type") or primary.get("type") or primary.get("mime_type") or "").lower()
        media_url = str(primary.get("playback_url") or primary.get("media_url") or primary.get("url") or "")
        is_video = "video" in media_type or bool(re.search(r"\.(mp4|mov|webm|m4v|m3u8)(?:\?|$)", media_url, re.I))
        if is_video:
            video_posts.append((post, primary))
    if not video_posts:
        return posts

    post_ids = [safe_int(post.get("id"), 0) for post, _media in video_posts if safe_int(post.get("id"), 0)]
    if not post_ids:
        return posts
    placeholders = ",".join(["?"] * len(post_ids))
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        f"SELECT id, source_id FROM pulse_videos WHERE source_type='feed_video' AND source_id IN ({placeholders}) AND COALESCE(status,'active')='active'",
        tuple(str(post_id) for post_id in post_ids),
    )
    indexed = {safe_int(row["source_id"], 0): safe_int(row["id"], 0) for row in cur.fetchall()}
    missing = [post_id for post_id in post_ids if post_id not in indexed]
    source_rows = {}
    if missing:
        missing_placeholders = ",".join(["?"] * len(missing))
        cur.execute(
            f"SELECT id, user_id, title, body, visibility FROM pulse_posts WHERE id IN ({missing_placeholders}) AND deleted_at IS NULL",
            tuple(missing),
        )
        source_rows = {safe_int(row["id"], 0): dict(row) for row in cur.fetchall()}
    conn.close()

    for post, primary in video_posts:
        post_id = safe_int(post.get("id"), 0)
        video_id = indexed.get(post_id, 0)
        if not video_id:
            source = source_rows.get(post_id) or {}
            try:
                indexed_row = pulse_video_index_upsert(
                    source.get("user_id"),
                    "feed_video",
                    post_id,
                    media_id=safe_int(primary.get("id") or primary.get("media_id"), 0),
                    title=source.get("title") or post.get("title") or "",
                    description=source.get("body") or post.get("body") or "",
                    visibility=source.get("visibility") or post.get("visibility") or "public",
                    media=primary,
                )
                video_id = safe_int((indexed_row or {}).get("id"), 0)
            except Exception as exc:
                logging.warning("PULSE_FEED_VIDEO_LINK_RECOVERY_FAILED post_id=%s error=%s", post_id, exc.__class__.__name__)
        if not video_id:
            continue
        route = f"/pulse/videos/{video_id}"
        post["video_id"] = video_id
        post["video_permalink"] = route
        for item in post.get("media") or []:
            item_type = str(item.get("media_type") or item.get("type") or item.get("mime_type") or "").lower()
            item_url = str(item.get("playback_url") or item.get("media_url") or item.get("url") or "")
            if "video" in item_type or re.search(r"\.(mp4|mov|webm|m4v|m3u8)(?:\?|$)", item_url, re.I):
                item["video_id"] = video_id
                item["video_permalink"] = route
    return posts


@webhook_app.route("/api/pulse/feed", methods=["GET"])
def api_pulse_feed():
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    pulse_mark_online(user["user_id"], "feed_poll", "/pulse")
    feed = request.args.get("tab") or request.args.get("feed") or "for_you"
    try:
        result = pulse_feed_engine.list_feed(user["user_id"], feed, request.args.get("topic") or "", request.args.get("profile") or "", request.args.get("limit") or 20, request.args.get("offset") or 0)
        pulse_attach_video_detail_links(result.get("posts") or [])
        result.setdefault("intelligence", {})
        if isinstance(result.get("intelligence"), dict):
            result["intelligence"]["status_activity"] = pulse_status_discovery_signal(user["user_id"])
    except Exception as exc:
        logging.exception("PULSE_FEED_FAILED user_id=%s feed=%s error=%s", user["user_id"], feed, exc)
        result = {
            "ok": True,
            "feed": pulse_feed_engine.normalize_feed(feed),
            "topic": request.args.get("topic") or "",
            "posts": [],
            "next_offset": 0,
            "has_more": False,
            "message": "PulseSoc is warming up. Create the first post.",
            "intelligence": pulse_feed_engine.safe_intelligence_panel(request.args.get("topic") or ""),
        }
        result["intelligence"]["status_activity"] = {"active_statuses": 0, "unseen_statuses": 0, "live_creators": 0, "engagement_signal": 0, "ranking_weight": "fallback"}
    response = jsonify(result)
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


def pulse_daily_mentor_reply(user_message, prompt_id="wallet-safety-reflection"):
    message = clean_html(user_message or "")[:1600]
    lower = message.lower()
    safety_tags = ["daily_reflection", "mentor"]
    if any(word in lower for word in ["scam", "fake", "support", "wallet", "seed", "link", "airdrop", "dm"]):
        safety_tags.extend(["scam_awareness", "wallet_safety"])
    if any(word in lower for word in ["buy", "sell", "profit", "guarantee", "pump", "moon", "signal"]):
        safety_tags.append("financial_advice_boundary")
    if "help me answer" in lower:
        ai_reply = (
            "Start with the moment, the pressure you felt, and the warning sign you noticed. "
            "A strong answer could be: I almost trusted a message because it looked official, but I paused when it asked me to connect my wallet. "
            "What detail made it feel believable?"
        )
    elif "support" in lower or "link" in lower:
        ai_reply = (
            "That is a common trap. The warning sign was urgency mixed with a link that wanted wallet access. "
            "Next time, pause, verify the domain from an official source, and never connect a wallet from a support DM. "
            "What made the link feel believable in the moment?"
        )
    elif "seed" in lower or "phrase" in lower or "private key" in lower:
        ai_reply = (
            "You caught one of the biggest red flags: no real support team needs a seed phrase or private key. "
            "The practical habit is simple: treat any seed phrase request as theft, close the page, and verify from a clean browser tab. "
            "What helped you stop before sharing it?"
        )
    elif "profit" in lower or "guarantee" in lower or "buy" in lower or "sell" in lower:
        ai_reply = (
            "I cannot give buy, sell, or profit instructions, but I can help you evaluate risk. "
            "Guaranteed returns, secret groups, pressure to act quickly, and withdrawal tests are major warning signs. "
            "What evidence did you check before trusting the offer?"
        )
    else:
        ai_reply = (
            "That reflection matters. The safest pattern is to slow down when a message creates urgency, asks for wallet access, or makes trust feel automatic. "
            "Write down the warning sign you noticed, then make one rule you will use next time. "
            "What is the one habit you want future-you to remember?"
        )
    suggested = (
        "PulseSoc Daily Mentor reflection: I am learning to pause before trusting crypto links, DMs, or urgent wallet requests. "
        "My safety habit is to verify the domain, avoid seed phrase requests, and slow down before connecting a wallet. "
        "#ScamShield #WalletSafety"
    )
    return ai_reply, suggested, sorted(set(safety_tags))


@webhook_app.route("/api/pulse/daily-mentor/respond", methods=["POST"])
def api_pulse_daily_mentor_respond():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required.", "trace_id": secrets.token_hex(6)}), 401
    payload = request.get_json(silent=True) or {}
    trace_id = secrets.token_hex(6)
    prompt_id = clean_html(payload.get("prompt_id") or "wallet-safety-reflection")[:120]
    user_message = clean_html(payload.get("user_message") or "")[:1600]
    conversation_id = safe_int(payload.get("conversation_id"), 0)
    if not user_message:
        return jsonify({"ok": False, "message": "Share your answer first.", "trace_id": trace_id}), 400
    try:
        now = datetime.utcnow().isoformat(timespec="seconds")
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        if conversation_id:
            cur.execute("SELECT id FROM pulse_daily_mentor_conversations WHERE id=? AND user_id=? AND status='active'", (conversation_id, int(user["user_id"])))
            if not cur.fetchone():
                conversation_id = 0
        if not conversation_id:
            title = "PulseSoc Daily Mentor"
            cur.execute(
                """
                INSERT INTO pulse_daily_mentor_conversations (user_id, prompt_id, title, status, created_at, updated_at)
                VALUES (?, ?, ?, 'active', ?, ?)
                """,
                (int(user["user_id"]), prompt_id, title, now, now),
            )
            conversation_id = int(cur.lastrowid)
        cur.execute(
            """
            INSERT INTO pulse_daily_mentor_messages (conversation_id, sender_type, body, metadata_json, created_at)
            VALUES (?, 'user', ?, ?, ?)
            """,
            (conversation_id, user_message, json.dumps({"prompt_id": prompt_id}), now),
        )
        ai_reply, suggested_post_text, safety_tags = pulse_daily_mentor_reply(user_message, prompt_id)
        cur.execute(
            """
            INSERT INTO pulse_daily_mentor_messages (conversation_id, sender_type, body, metadata_json, created_at)
            VALUES (?, 'ai', ?, ?, ?)
            """,
            (conversation_id, ai_reply, json.dumps({"safety_tags": safety_tags, "not_financial_advice": True}), now),
        )
        cur.execute("UPDATE pulse_daily_mentor_conversations SET updated_at=? WHERE id=?", (now, conversation_id))
        conn.commit()
        conn.close()
        return jsonify(
            {
                "ok": True,
                "trace_id": trace_id,
                "conversation_id": conversation_id,
                "ai_reply": ai_reply,
                "suggested_post_text": suggested_post_text,
                "safety_tags": safety_tags,
            }
        )
    except Exception as exc:
        logging.exception("PULSE_DAILY_MENTOR_FAILED trace_id=%s user_id=%s error=%s", trace_id, user.get("user_id"), exc)
        return jsonify({"ok": False, "message": "PulseSoc Daily Mentor could not reply.", "trace_id": trace_id}), 500


