PULSE_VIDEO_SOURCE_TYPES = {"feed_video", "reel", "live", "replay"}


def pulse_video_index_upsert(owner_user_id, source_type, source_id, media_id=0, title="", description="", visibility="public", media=None):
    """Keep a lightweight playback index without moving or duplicating media."""
    source_type = str(source_type or "").strip().lower()
    if source_type not in PULSE_VIDEO_SOURCE_TYPES:
        return None
    source_id = str(source_id or "").strip()
    if not source_id:
        return None
    media_id = safe_int(media_id, 0)
    resolved = dict(media or {})
    if media_id and not resolved:
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
        media_row = dict(cur.fetchone() or {})
        conn.close()
        resolved = media_service.resolve_media(media_row) if media_row else {}
    media_type = str(resolved.get("media_type") or resolved.get("type") or "").lower()
    if source_type in {"feed_video", "reel"} and media_type and media_type != "video":
        return None
    width = safe_int(resolved.get("width"), 0)
    height = safe_int(resolved.get("height"), 0)
    orientation = "portrait" if height > width else "landscape" if width > height else "square" if width else "unknown"
    mux_playback_id = str(resolved.get("mux_playback_id") or "").strip()
    playback_url = str(resolved.get("playback_url") or resolved.get("mux_hls_url") or "").strip()
    if mux_playback_id:
        playback_url = f"https://stream.mux.com/{mux_playback_id}.m3u8"
    mux_status = str(resolved.get("mux_status") or "").strip().lower()
    processing_status = str(resolved.get("processing_status") or "").strip().lower()
    if not processing_status:
        processing_status = "ready" if playback_url and (not mux_status or mux_status in {"ready", "asset_ready", "available"}) else "processing"
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO pulse_videos
        (owner_user_id, source_type, source_id, media_id, title, description, thumbnail_url, media_url, playback_url,
         mux_asset_id, mux_playback_id, mux_status, processing_status, duration_seconds, width, height, orientation,
         visibility, status, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
        ON CONFLICT(source_type, source_id) DO UPDATE SET
          media_id=excluded.media_id, title=excluded.title, description=excluded.description,
          thumbnail_url=excluded.thumbnail_url, media_url=excluded.media_url, playback_url=excluded.playback_url,
          mux_asset_id=excluded.mux_asset_id, mux_playback_id=excluded.mux_playback_id, mux_status=excluded.mux_status,
          processing_status=excluded.processing_status, duration_seconds=excluded.duration_seconds, width=excluded.width,
          height=excluded.height, orientation=excluded.orientation, visibility=excluded.visibility, status='active',
          updated_at=excluded.updated_at
        """,
        (
            safe_int(owner_user_id, 0), source_type, source_id, media_id or None, clean_html(title or "")[:180],
            clean_html(description or "")[:3000], resolved.get("poster_url") or resolved.get("thumbnail_url") or "",
            resolved.get("media_url") or resolved.get("valid_url") or "", playback_url,
            resolved.get("mux_asset_id") or "", mux_playback_id, mux_status or "processing", processing_status,
            float(resolved.get("duration_seconds") or resolved.get("duration") or 0), width, height, orientation,
            visibility if visibility in {"public", "followers", "private"} else "public", now, now,
        ),
    )
    cur.execute("SELECT * FROM pulse_videos WHERE source_type=? AND source_id=? LIMIT 1", (source_type, source_id))
    row = dict(cur.fetchone() or {})
    conn.commit()
    conn.close()
    return row or None


def pulse_video_payload(row):
    row = dict(row or {})
    mux_playback_id = str(row.get("mux_playback_id") or "").strip()
    if mux_playback_id:
        row["playback_url"] = f"https://stream.mux.com/{mux_playback_id}.m3u8"
    row["id"] = safe_int(row.get("id"), 0)
    row["owner_user_id"] = safe_int(row.get("owner_user_id"), 0)
    row["media_id"] = safe_int(row.get("media_id"), 0)
    row["view_count"] = safe_int(row.get("view_count"), 0)
    row["duration_seconds"] = float(row.get("duration_seconds") or 0)
    row["ready"] = str(row.get("processing_status") or "").lower() == "ready" or str(row.get("mux_status") or "").lower() in {"ready", "asset_ready", "available"}
    row["tags"] = str(row.get("tags") or "")
    row["category"] = str(row.get("category") or "")
    row["source_url"] = f"/pulse/reels/{row.get('source_id')}" if row.get("source_type") == "reel" else f"/pulse/post/{row.get('source_id')}" if row.get("source_type") == "feed_video" else pulse_live_watch_url(row.get("source_id"))
    row["permalink"] = f"/pulse/videos/{row.get('id')}"
    return row


def pulse_video_hydrate_attached_music(cur, videos):
    """Attach approved PulseSoc Music metadata to video payloads without exposing private storage."""
    hydrated = []
    for video in videos or []:
        item = dict(video or {})
        candidates = [("video", safe_int(item.get("id"), 0))]
        source_type = str(item.get("source_type") or "")
        source_id = safe_int(item.get("source_id"), 0)
        if source_type == "feed_video" and source_id:
            candidates.append(("post", source_id))
        if source_type == "reel" and source_id:
            candidates.append(("reel", source_id))
        music_row = None
        for content_type, content_id in candidates:
            if not content_id:
                continue
            try:
                cur.execute(
                    """
                    SELECT pcm.content_type, pcm.content_id, pcm.audio_track_id, pcm.title, pcm.artist, pcm.source,
                           pcm.license_snapshot_json, pcm.created_at, pcm.audio_start_time, pcm.audio_volume, pcm.original_audio_muted,
                           at.audio_url AS current_audio_url,
                           at.duration_seconds AS current_duration_seconds
                    FROM pulse_content_music pcm
                    JOIN pulse_audio_tracks at ON CAST(at.id AS TEXT)=CAST(pcm.audio_track_id AS TEXT)
                    WHERE pcm.content_type=? AND pcm.content_id=?
                      AND COALESCE(at.safety_status,'approved')='approved'
                      AND COALESCE(at.active,1)=1
                      AND COALESCE(at.approved_by_admin,0)=1
                      AND COALESCE(at.commercial_use_allowed,0)=1
                      AND COALESCE(at.remix_edit_allowed,0)=1
                      AND COALESCE(at.removed_at,'')=''
                      AND COALESCE(at.audio_url,'')!=''
                    ORDER BY pcm.created_at DESC
                    LIMIT 1
                    """,
                    (content_type, content_id),
                )
                music_row = dict(cur.fetchone() or {})
            except Exception:
                music_row = None
            if music_row:
                break
        if music_row:
            try:
                snapshot = json.loads(music_row.get("license_snapshot_json") or "{}")
            except Exception:
                snapshot = {}
            audio_url = pulse_media_url(music_row.get("current_audio_url") or snapshot.get("audio_url") or snapshot.get("preview_url") or "")
            if audio_url:
                def music_text(value, fallback, limit):
                    return str(value or fallback or "").replace("\x00", "").strip()[:limit]
                duration = int(float(music_row.get("current_duration_seconds") or snapshot.get("duration_seconds") or snapshot.get("duration") or 0) or 0)
                start_time = float(music_row.get("audio_start_time") or snapshot.get("audio_start_time") or snapshot.get("start_seconds") or 0)
                volume = max(0.0, min(float(music_row.get("audio_volume") or snapshot.get("volume") or snapshot.get("audio_volume") or 1), 1.0))
                music = {
                    "audio_id": str(music_row.get("audio_track_id") or snapshot.get("track_id") or ""),
                    "track_id": str(music_row.get("audio_track_id") or snapshot.get("track_id") or ""),
                    "title": music_text(music_row.get("title") or snapshot.get("title"), "Approved track", 180),
                    "artist": music_text(music_row.get("artist") or snapshot.get("artist"), "PulseSoc Music", 180),
                    "attached_audio_url": audio_url,
                    "audio_url": audio_url,
                    "preview_url": audio_url,
                    "duration_seconds": duration,
                    "audio_duration": duration,
                    "audio_start_time": max(0.0, start_time),
                    "audio_volume": volume,
                    "original_audio_muted": True,
                    "source": music_text(music_row.get("source") or snapshot.get("source"), "PulseSoc", 120),
                    "is_creator_safe": True,
                }
                item["music"] = music
                item.update(
                    {
                        "audio_id": music["audio_id"],
                        "music_id": music["track_id"],
                        "attached_audio_url": audio_url,
                        "audio_title": music["title"],
                        "audio_artist": music["artist"],
                        "audio_duration": duration,
                        "audio_start_time": music["audio_start_time"],
                        "audio_volume": volume,
                        "original_audio_muted": True,
                    }
                )
        hydrated.append(item)
    return hydrated


def pulse_video_playback_is_renderable(video):
    item = dict(video or {})
    if pulse_video_state(item) != "ready":
        return True
    playback = str(item.get("playback_url") or item.get("media_url") or "").strip()
    if not playback:
        return False
    if playback.startswith(("/static/", "/uploads/")):
        return pulse_media_exists(playback)
    return True


def pulse_video_processing_is_stale(video, minutes=10):
    item = dict(video or {})
    status = str(item.get("processing_status") or "").strip().lower()
    mux_status = str(item.get("mux_status") or "").strip().lower()
    if status in {"ready", "failed", "error"} or mux_status in {"ready", "asset_ready", "available", "failed", "errored", "error"}:
        return False
    stamp = item.get("updated_at") or item.get("created_at") or ""
    try:
        parsed = datetime.fromisoformat(str(stamp).replace("Z", "+00:00"))
        if parsed.tzinfo is not None:
            parsed = parsed.replace(tzinfo=None)
        return (datetime.utcnow() - parsed).total_seconds() >= int(minutes) * 60
    except Exception:
        return False


def pulse_video_recover_from_media(cur, video, *, force=False):
    """Use the durable uploaded file when Mux never finishes producing playback."""
    item = dict(video or {})
    media_id = safe_int(item.get("media_id"), 0)
    if not media_id:
        return item, False
    current_state = pulse_video_state(pulse_video_payload(item))
    if current_state == "ready" and (item.get("playback_url") or item.get("media_url")):
        return item, False
    if not force and not pulse_video_processing_is_stale(item):
        return item, False
    try:
        cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
        media_row = dict(cur.fetchone() or {})
    except Exception:
        media_row = {}
    if not media_row:
        return item, False
    resolved = media_service.resolve_media(media_row, check_remote=False)
    if str(resolved.get("media_type") or "").lower() != "video":
        return item, False
    playback_url = clean_html(
        resolved.get("playback_url") or resolved.get("valid_url") or resolved.get("media_url") or ""
    )[:1000]
    if not playback_url or resolved.get("is_available") is False:
        return item, False
    now = datetime.utcnow().isoformat(timespec="seconds")
    mux_playback_id = clean_html(resolved.get("mux_playback_id") or item.get("mux_playback_id") or "")[:180]
    mux_status = clean_html(resolved.get("mux_status") or item.get("mux_status") or "fallback_ready")[:80]
    media_url = clean_html(resolved.get("media_url") or item.get("media_url") or playback_url)[:1000]
    thumbnail_url = clean_html(resolved.get("poster_url") or resolved.get("thumbnail_url") or item.get("thumbnail_url") or "")[:1000]
    processing_status = "ready"
    cur.execute(
        """
        UPDATE pulse_videos
        SET playback_url=?, media_url=COALESCE(NULLIF(?, ''), media_url),
            thumbnail_url=COALESCE(NULLIF(?, ''), thumbnail_url),
            mux_playback_id=COALESCE(NULLIF(?, ''), mux_playback_id),
            mux_status=?, processing_status=?, updated_at=?,
            db_ready_update_at=COALESCE(db_ready_update_at, ?)
        WHERE id=?
        """,
        (
            playback_url,
            media_url,
            thumbnail_url,
            mux_playback_id,
            mux_status,
            processing_status,
            now,
            now,
            safe_int(item.get("id"), 0),
        ),
    )
    try:
        cur.execute(
            """
            UPDATE chat_media_uploads
            SET playback_url=COALESCE(NULLIF(?, ''), playback_url),
                processing_status='ready',
                db_ready_update_at=COALESCE(db_ready_update_at, ?),
                updated_at=?
            WHERE id=?
            """,
            (playback_url, now, now, media_id),
        )
    except Exception:
        pass
    item.update(
        {
            "playback_url": playback_url,
            "media_url": media_url or item.get("media_url") or playback_url,
            "thumbnail_url": thumbnail_url or item.get("thumbnail_url") or "",
            "mux_playback_id": mux_playback_id or item.get("mux_playback_id") or "",
            "mux_status": mux_status,
            "processing_status": processing_status,
            "updated_at": now,
            "db_ready_update_at": item.get("db_ready_update_at") or now,
        }
    )
    return item, True


def pulse_video_duration_label(seconds):
    try:
        seconds = int(float(seconds or 0))
    except Exception:
        seconds = 0
    if seconds <= 0:
        return "0:00"
    hours, rem = divmod(seconds, 3600)
    minutes, secs = divmod(rem, 60)
    return f"{hours}:{minutes:02d}:{secs:02d}" if hours else f"{minutes}:{secs:02d}"


def pulse_video_state(video):
    status = str((video or {}).get("processing_status") or "").strip().lower()
    mux_status = str((video or {}).get("mux_status") or "").strip().lower()
    if status in {"failed", "error"} or mux_status in {"failed", "errored", "error"}:
        return "failed"
    if (video or {}).get("ready") and ((video or {}).get("playback_url") or (video or {}).get("media_url")):
        return "ready"
    if mux_status in {"ready", "asset_ready", "available"} and ((video or {}).get("playback_url") or (video or {}).get("media_url")):
        return "ready"
    return "processing"


def pulse_video_direct_reaction_counts(cur, video_id):
    cur.execute(
        """
        SELECT reaction_type, COUNT(*) AS total
        FROM pulse_video_reactions
        WHERE video_id=?
        GROUP BY reaction_type
        """,
        (safe_int(video_id, 0),),
    )
    return {str(r["reaction_type"] or "like"): safe_int(r["total"], 0) for r in cur.fetchall()}


def pulse_video_direct_reaction_payload(cur, video_id, viewer_user_id):
    counts = pulse_video_direct_reaction_counts(cur, video_id)
    cur.execute(
        "SELECT reaction_type FROM pulse_video_reactions WHERE video_id=? AND user_id=? LIMIT 1",
        (safe_int(video_id, 0), safe_int(viewer_user_id, 0)),
    )
    return counts, (dict(cur.fetchone() or {}).get("reaction_type") or "")


def pulse_video_direct_comments(cur, video_id, limit=20):
    cur.execute(
        """
        SELECT c.*, COALESCE(NULLIF(u.display_name,''), NULLIF(u.full_name,''), NULLIF(u.username,''), 'PulseSoc user') AS author_name,
               COALESCE(u.avatar_thumbnail_url, u.avatar_url, '') AS author_avatar_url
        FROM pulse_video_comments c
        LEFT JOIN users u ON u.user_id=c.user_id
        WHERE c.video_id=? AND c.deleted_at IS NULL AND COALESCE(c.moderation_status,'approved')!='blocked'
        ORDER BY c.created_at DESC
        LIMIT ?
        """,
        (safe_int(video_id, 0), safe_int(limit, 20)),
    )
    return [dict(r) for r in cur.fetchall()]


def pulse_video_not_found_response(trace_id, status_code=404):
    logging.warning("PULSE_VIDEO_DETAIL_NOT_FOUND trace_id=%s path=%s", trace_id, request.path)
    main = f"""
    <style>.layout:has(.pulse-video-detail-page){{grid-template-columns:1fr}}.layout:has(.pulse-video-detail-page)>aside{{display:none}}</style>
    <section class='card pulse-video-detail-page'>
      <span class='pill'>Trace {clean_html(trace_id)}</span>
      <h2>Video not found</h2>
      <p>This PulseSoc video is deleted, private, or no longer available.</p>
      <div class='actions'><a class='button primary' href='/pulse/videos'>Back to Videos</a><a class='button' href='/pulse'>PulseSoc Home</a></div>
    </section>
    """
    response = pulse_social_shell("Video not found", "This video is not available.", main, "", "")
    response.status_code = int(status_code)
    return response


@webhook_app.route("/pulse/videos", methods=["GET"])
def pulse_videos_page():
    init_db()
    user = require_account()
    if not user:
        return redirect(url_for("login_page", next=request.path))
    tabs = [("all", "For You"), ("following", "Following"), ("trending", "Trending"), ("new", "New Creators"), ("ai", "AI Picks"), ("local", "Local")]
    categories = ["All", "Entertainment", "Education", "News", "Gaming", "Sports", "Music", "Tech", "Lifestyle"]
    tab_html = "".join(f"<button type='button' data-video-tab='{key}' class='{'active' if key == 'all' else ''}'>{label}</button>" for key, label in tabs)
    category_html = "".join(f"<button type='button' data-video-category='{clean_html(cat.lower())}' class='{'active' if cat == 'All' else ''}'>{clean_html(cat)}</button>" for cat in categories)
    mobile_avatar = f"<img src='{clean_html(user.get('avatar_url') or user.get('avatar_thumbnail_url') or '')}' alt='Profile'>" if (user.get("avatar_url") or user.get("avatar_thumbnail_url")) else clean_html((user.get("display_name") or user.get("username") or "P")[:1])
