        include_preview_comments = str(request.args.get("include_comments") or request.args.get("comments") or "").strip().lower() in {"1", "true", "yes", "on"}
        payload = pulse_reel_feed_payload(
            viewer_user_id=user["user_id"],
            category=request.args.get("category") or "",
            limit=safe_int(request.args.get("limit"), 8),
            offset=safe_int(request.args.get("offset"), 0),
            lane=request.args.get("tab") or request.args.get("lane") or request.args.get("feed") or "for_you",
            focus_live_id=safe_int(request.args.get("live"), 0),
            include_preview_comments=include_preview_comments,
        )
        pulse_mark_online(user["user_id"], "reels", request.path)
