@webhook_app.route("/api/reels/audio", methods=["GET"])
@webhook_app.route("/api/pulse/reels/sounds", methods=["GET"])
def api_pulse_reels_sounds():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    query = clean_html(request.args.get("q") or "")[:120].strip()
    category = clean_html(request.args.get("category") or "")[:80].strip()
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    params = []
    where = """
    WHERE COALESCE(at.safety_status,'approved')='approved'
      AND COALESCE(at.active,1)=1
      AND COALESCE(at.approved_by_admin,0)=1
      AND COALESCE(at.commercial_use_allowed,0)=1
      AND COALESCE(at.remix_edit_allowed,0)=1
      AND COALESCE(at.license_type,'') NOT IN ('noncommercial','cc-by-nc','no-derivatives','cc-by-nd')
      AND (COALESCE(at.proof_url,'')!='' OR COALESCE(at.proof_file,'')!='' OR COALESCE(at.source_provider,'')='original_pulse_sound')
    """
    if query:
        where += " AND (lower(COALESCE(at.title,'')) LIKE ? OR lower(COALESCE(at.artist,'')) LIKE ?)"
        like = f"%{query.lower()}%"
        params.extend([like, like])
    if category and category.lower() == "saved":
        where += " AND (ss.id IS NOT NULL OR pss.id IS NOT NULL)"
    elif category:
        where += " AND lower(COALESCE(ts.category,at.source_type,''))=lower(?)"
        params.append(category)
    cur.execute(
        f"""
        SELECT at.*, COALESCE(ts.trend_score, at.trend_score, 0) AS live_trend_score,
               COALESCE(ts.usage_count, at.usage_count, 0) AS live_usage_count,
               COALESCE(ts.category, at.source_type, 'Trending') AS live_category,
               CASE WHEN ss.id IS NULL AND pss.id IS NULL THEN 0 ELSE 1 END AS saved
        FROM pulse_audio_tracks at
        LEFT JOIN pulse_trending_sounds ts ON ts.audio_track_id=at.id
        LEFT JOIN pulse_reel_sound_saves ss ON ss.audio_track_id=at.id AND ss.user_id=?
        LEFT JOIN pulse_saved_sounds pss ON pss.audio_track_id=at.id AND pss.user_id=?
        {where}
        ORDER BY live_trend_score DESC, live_usage_count DESC, at.created_at DESC
        LIMIT 40
        """,
        [user["user_id"], user["user_id"], *params],
    )
    sounds = []
    for row in cur.fetchall():
        item = dict(row)
        sounds.append({
            "id": int(item.get("id") or 0),
            "track_id": int(item.get("id") or 0),
            "title": item.get("title") or "PulseSoc sound",
            "artist": item.get("artist") or "CoinPilotXAI",
            "audio_url": item.get("audio_url") or "",
            "duration": float(item.get("duration_seconds") or 0),
            "waveform": item.get("waveform_json") or "",
            "bpm": int(item.get("bpm") or 0),
            "usage_count": int(item.get("live_usage_count") or 0),
            "trend_score": int(item.get("live_trend_score") or 0),
            "category": item.get("live_category") or "Trending",
            "mood": item.get("mood") or "",
            "genre": item.get("genre") or "",
            "source": item.get("source_provider") or item.get("source_type") or "",
            "license_type": item.get("license_type") or "",
            "commercial_use_allowed": bool(item.get("commercial_use_allowed")),
            "remix_edit_allowed": bool(item.get("remix_edit_allowed")),
            "attribution_required": bool(item.get("attribution_required")),
            "approved_by_admin": bool(item.get("approved_by_admin")),
            "saved": bool(item.get("saved")),
        })
    conn.close()
    return jsonify({"ok": True, "sounds": sounds})


@webhook_app.route("/api/pulse/reels/sounds/save", methods=["POST"])
def api_pulse_reels_sound_save():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    payload = request.get_json(silent=True) or {}
    track_id = safe_int(payload.get("track_id") or payload.get("audio_track_id") or payload.get("sound_id"), 0)
    if not track_id:
        return api_error("Choose a sound to save.", 400)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute(
        """
        SELECT id FROM pulse_audio_tracks
        WHERE id=?
          AND COALESCE(safety_status,'approved')='approved'
          AND COALESCE(active,1)=1
          AND COALESCE(approved_by_admin,0)=1
          AND COALESCE(commercial_use_allowed,0)=1
          AND COALESCE(remix_edit_allowed,0)=1
        LIMIT 1
        """,
        (track_id,),
    )
    if not cur.fetchone():
        conn.close()
        return api_error("Sound not found.", 404)
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("INSERT OR IGNORE INTO pulse_reel_sound_saves (user_id, audio_track_id, created_at) VALUES (?, ?, ?)", (user["user_id"], track_id, now))
    cur.execute("INSERT OR IGNORE INTO pulse_saved_sounds (user_id, audio_track_id, created_at) VALUES (?, ?, ?)", (user["user_id"], track_id, now))
    conn.commit(); conn.close()
    return jsonify({"ok": True, "message": "Sound saved.", "track_id": track_id})


@webhook_app.route("/api/pulse/reels/sounds/upload", methods=["POST"])
def api_pulse_reels_sound_upload():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    upload = request.files.get("file")
    if not upload or not upload.filename:
        return api_error("Choose an audio file.", 400)
    filename = secure_filename(upload.filename or "")
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    if ext not in {"mp3", "m4a", "aac", "wav"}:
        return api_error("Upload MP3, WAV, M4A, or AAC audio.", 400)
    if upload.mimetype and not (upload.mimetype.startswith("audio/") or upload.mimetype in {"video/webm", "application/ogg"}):
        return api_error("That file does not look like an audio track.", 400)
    rights_confirmed = request.form.get("rights_confirmed") in {"1", "true", "on", "yes"}
    if not rights_confirmed:
        return api_error("Confirm that you own this music or have the legal right to upload it.", 400)
    result, status = media_service.save_upload(user["user_id"], upload, context_type="pulse_sound", context_id="reels")
    if not result.get("ok"):
        return jsonify(result), status
    media = result.get("media") or {}
    title = clean_html(request.form.get("title") or filename.rsplit(".", 1)[0] or "Original PulseSoc Sound")[:120]
    artist = clean_html(request.form.get("artist") or user.get("display_name") or user.get("username") or "PulseSoc Creator")[:120]
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO pulse_audio_tracks
        (title, artist, uploader_user_id, audio_url, duration_seconds, waveform_json, bpm, usage_count, trend_score, source_type, safety_status,
         source_provider, license_type, commercial_use_allowed, remix_edit_allowed, attribution_required, proof_url, approved_by_admin, active,
         rights_confirmed, rights_confirmed_at, rights_statement, created_at, updated_at)
        VALUES (?, ?, ?, ?, 0, ?, 0, 0, 0, 'uploaded', 'pending',
                'user_upload_pending_rights', 'pending admin review', 0, 0, 0, '', 0, 0,
                1, ?, 'I confirm that I own this music or have the legal right to upload it.', ?, ?)
        """,
        (title, artist, user["user_id"], media.get("media_url") or "", json.dumps([0.22, 0.48, 0.35, 0.68, 0.44, 0.58, 0.26, 0.52]), now, now, now),
    )
    track_id = int(cur.lastrowid)
    cur.execute("INSERT OR IGNORE INTO pulse_saved_sounds (user_id, audio_track_id, created_at) VALUES (?, ?, ?)", (user["user_id"], track_id, now))
    cur.execute("INSERT OR IGNORE INTO pulse_reel_sound_saves (user_id, audio_track_id, created_at) VALUES (?, ?, ?)", (user["user_id"], track_id, now))
    conn.commit(); conn.close()
    sound = {"id": track_id, "track_id": track_id, "title": title, "artist": artist, "audio_url": media.get("media_url") or "", "duration": 0, "category": "Pending review", "approved_by_admin": False, "active": False}
    return jsonify({"ok": True, "success": True, "message": "Sound uploaded for admin rights review.", "track_id": track_id, "sound": sound, "media_url": media.get("media_url") or "", "status_id": "", "media": media})


@webhook_app.route("/api/reels", methods=["POST"])
@webhook_app.route("/api/pulse/reels/create", methods=["POST"])
def api_pulse_reels_create():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or {}
    trace_id = secrets.token_hex(6)
    try:
        caption = clean_html(payload.get("caption") or payload.get("body") or "")[:2200]
        title = clean_html(payload.get("title") or "PulseSoc Reel")[:140]
        category = clean_html(payload.get("category") or "Community")[:80]
        raw_media_ids = payload.get("media_ids") or []
        if not isinstance(raw_media_ids, list):
            raw_media_ids = [raw_media_ids]
        if payload.get("media_id"):
            raw_media_ids = [payload.get("media_id"), *list(raw_media_ids if isinstance(raw_media_ids, list) else [raw_media_ids])]
        media_ids = []
        for candidate in raw_media_ids:
            media_id = safe_int(candidate, 0)
            if media_id and media_id not in media_ids:
                media_ids.append(media_id)
        if not media_ids:
            return jsonify({"ok": False, "success": False, "message": "Choose a video before publishing your Reel.", "trace_id": trace_id}), 400
        media_conn = db()
        media_conn.row_factory = sqlite3.Row
        media_cur = media_conn.cursor()
        media_cur.execute(
            """
            SELECT * FROM chat_media_uploads
            WHERE id=? AND uploader_user_id=? AND COALESCE(moderation_status,'approved')!='blocked'
            LIMIT 1
            """,
            (media_ids[0], user["user_id"]),
        )
        media_row = dict(media_cur.fetchone() or {})
        media_conn.close()
        if not media_row:
            return jsonify({"ok": False, "success": False, "message": "Uploaded Reel video was not found. Upload again and retry.", "trace_id": trace_id}), 404
        resolved_media = media_service.resolve_media(media_row)
        media_type = (resolved_media.get("media_type") or media_row.get("media_type") or payload.get("post_type") or "video").lower()
        if media_type != "video":
            return jsonify({"ok": False, "success": False, "message": "Reels require an MP4, MOV, or WEBM video.", "trace_id": trace_id}), 400
        playback_url = resolved_media.get("playback_url") or payload.get("playback_url") or resolved_media.get("valid_url") or resolved_media.get("media_url") or ""
        media_url = resolved_media.get("media_url") or payload.get("media_url") or ""
        mux_status = (resolved_media.get("mux_status") or payload.get("mux_status") or "").lower()
        processing_status = resolved_media.get("processing_status") or media_row.get("processing_status") or ""
        if media_type == "video" and resolved_media.get("mux_playback_id") and mux_status and mux_status not in {"ready", "asset_ready", "available"}:
            processing_status = "mux_processing"
        if media_type == "video" and not processing_status:
            processing_status = "ready" if not mux_status or mux_status in {"ready", "asset_ready", "available"} else "mux_processing"
        audio_track_id = safe_int(payload.get("audio_track_id") or payload.get("sound_id") or payload.get("music_track_id"), 0)
        try:
            sound_start = max(0.0, float(payload.get("sound_start_seconds") or payload.get("audio_start_seconds") or 0))
            sound_end = max(0.0, float(payload.get("sound_end_seconds") or payload.get("audio_end_seconds") or 0))
            audio_volume = min(1.0, max(0.0, float(payload.get("audio_volume") if payload.get("audio_volume") is not None else 1)))
        except (TypeError, ValueError):
            return jsonify({"ok": False, "success": False, "message": "Use valid audio timing and volume values.", "trace_id": trace_id}), 400
        if sound_end and sound_end <= sound_start:
            return jsonify({"ok": False, "success": False, "message": "Audio end time must be after its start time.", "trace_id": trace_id}), 400
        music_payload = {}
        if audio_track_id:
            music_payload = music_service.attach_music_payload(str(audio_track_id))
            if not music_payload.get("is_creator_safe"):
                return jsonify({
                    "ok": False,
                    "success": False,
                    "message": music_payload.get("message") or "That music track is not approved for PulseSoc use.",
                    "trace_id": trace_id,
                }), 400
        tags = payload.get("tags") or ai_social_engine.suggest_hashtags(caption, category)
        if isinstance(tags, str):
            tags = [item.lstrip("#") for item in re.split(r"[\s,]+", tags) if item.strip()]
        if not isinstance(tags, list):
            tags = []
        tags = [clean_html(str(item)).lstrip("#")[:60] for item in tags if clean_html(str(item))][:10]
        safety = ai_moderation_core.moderate_text(caption or title, "reel")
        if safety.get("status") == "blocked":
            return jsonify({"ok": False, "message": "This Reel needs changes before publishing.", "trace_id": trace_id}), 400
        share_to_feed = bool(payload.get("share_to_feed"))
        reel_visibility = (payload.get("visibility") or payload.get("privacy") or "public") if share_to_feed else "reel_only"
        result = pulse_feed_engine.create_post(user["user_id"], caption, payload.get("post_type") or media_type or "video", title, tags=tags, visibility=reel_visibility, media_ids=media_ids)
        if not result.get("ok"):
            return jsonify({**result, "trace_id": trace_id}), 400
        post_id = int(result.get("post_id") or 0)
        score = reel_ranking_engine.score_reel({"risk_score": safety.get("risk_score"), "educational_value": 65, "created_at": datetime.utcnow().isoformat(timespec="seconds")})
        now = datetime.utcnow().isoformat(timespec="seconds")
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO pulse_reels
            (post_id, user_id, category, caption, video_url, poster_url, ai_tags_json, safety_score, educational_value, reel_score, processing_status, transcoding_status, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
            ON CONFLICT(post_id) DO UPDATE SET category=excluded.category, caption=excluded.caption, video_url=excluded.video_url, poster_url=excluded.poster_url, ai_tags_json=excluded.ai_tags_json, safety_score=excluded.safety_score, educational_value=excluded.educational_value, reel_score=excluded.reel_score, processing_status=excluded.processing_status, transcoding_status=excluded.transcoding_status, updated_at=excluded.updated_at
            """,
            (post_id, user["user_id"], category, caption, playback_url or media_url, resolved_media.get("poster_url") or resolved_media.get("thumbnail_url") or "", json.dumps(tags[:10]), score["safety_score"], score["educational_score"], score["reel_score"], processing_status or "ready", mux_status or processing_status or "ready", now, now),
        )
        reel_id = int(cur.lastrowid or 0)
        if not reel_id:
            cur.execute("SELECT id FROM pulse_reels WHERE post_id=? LIMIT 1", (post_id,))
            reel_id = safe_int((cur.fetchone() or [0])[0], post_id)
        if audio_track_id:
            cur.execute(
                """
                SELECT title FROM pulse_audio_tracks
                WHERE id=?
                  AND COALESCE(safety_status,'approved')='approved'
                  AND COALESCE(active,1)=1
                  AND COALESCE(approved_by_admin,0)=1
                  AND COALESCE(commercial_use_allowed,0)=1
                  AND COALESCE(remix_edit_allowed,0)=1
                LIMIT 1
                """,
                (audio_track_id,),
            )
            track = dict(cur.fetchone() or {})
            if track:
                cur.execute("UPDATE pulse_reels SET audio_track_id=?, sound_title=?, sound_start_seconds=?, sound_end_seconds=? WHERE id=?", (audio_track_id, track.get("title") or "", sound_start, sound_end, reel_id))
                cur.execute(
                    """
                    INSERT INTO pulse_reel_audio
                    (reel_id, audio_track_id, start_seconds, end_seconds, volume, created_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT(reel_id, audio_track_id) DO UPDATE SET
                        start_seconds=excluded.start_seconds,
                        end_seconds=excluded.end_seconds,
                        volume=excluded.volume,
                        created_at=excluded.created_at
                    """,
                    (reel_id, audio_track_id, sound_start, sound_end, audio_volume, now),
                )
                attach_result = pulse_attach_music_to_content(cur, content_type="reel", content_id=reel_id, track_id=audio_track_id, user_id=user["user_id"], start_seconds=sound_start, volume=audio_volume)
                if not attach_result.get("ok"):
                    logging.warning("PULSE_REEL_MUSIC_ATTACH_BLOCKED user_id=%s reel_id=%s track_id=%s reason=%s", user["user_id"], reel_id, audio_track_id, attach_result.get("message"))
                if share_to_feed and post_id:
                    feed_attach = pulse_attach_music_to_content(cur, content_type="post", content_id=post_id, track_id=audio_track_id, user_id=user["user_id"], start_seconds=sound_start, volume=audio_volume)
                    if not feed_attach.get("ok"):
                        logging.warning("PULSE_REEL_FEED_MUSIC_ATTACH_BLOCKED user_id=%s reel_id=%s post_id=%s track_id=%s reason=%s", user["user_id"], reel_id, post_id, audio_track_id, feed_attach.get("message"))
                    video_attach = pulse_attach_music_to_content(cur, content_type="video", content_id=post_id, track_id=audio_track_id, user_id=user["user_id"], start_seconds=sound_start, volume=audio_volume)
                    if not video_attach.get("ok"):
                        logging.warning("PULSE_REEL_FEED_VIDEO_MUSIC_ATTACH_BLOCKED user_id=%s reel_id=%s post_id=%s track_id=%s reason=%s", user["user_id"], reel_id, post_id, audio_track_id, video_attach.get("message"))
                cur.execute("UPDATE pulse_trending_sounds SET usage_count=COALESCE(usage_count,0)+1, trend_score=COALESCE(trend_score,0)+1, updated_at=? WHERE audio_track_id=?", (now, audio_track_id))
        conn.commit()
        conn.close()
        try:
            pulse_video_index_upsert(
                user["user_id"], "reel", reel_id, media_ids[0], title, caption,
                payload.get("visibility") or payload.get("privacy") or "public", media=resolved_media,
            )
        except Exception:
            logging.exception("PULSE_REELS_VIDEO_INDEX_NONCRITICAL_FAILED trace_id=%s user_id=%s reel_id=%s", trace_id, user["user_id"], reel_id)
        try:
            reel = pulse_reel_payload(reel_id=reel_id, viewer_user_id=user["user_id"])
        except Exception:
            logging.exception("PULSE_REELS_PAYLOAD_NONCRITICAL_FAILED trace_id=%s user_id=%s reel_id=%s", trace_id, user["user_id"], reel_id)
            reel = {"id": reel_id, "reel_id": reel_id, "post_id": post_id, "caption": caption, "title": title, "processing_status": processing_status or "ready"}
        logging.info(
            "PULSE_REELS_CREATE_FINAL_STEP trace_id=%s user_id=%s media_id=%s post_id=%s reel_id=%s mux_status=%s processing_status=%s",
            trace_id,
            user["user_id"],
            media_ids[0],
            post_id,
            reel_id,
            mux_status or "",
            processing_status or "",
        )
        pulse_emit_event("pulse_reel_created", {"reel_id": reel_id, "post_id": post_id, "reel": reel}, user["user_id"], post_id)
        return jsonify({
            "ok": True,
            "success": True,
            "data": {"reel": reel},
            "reel": reel,
            "reel_id": reel_id,
            "post_id": post_id,
            "media_id": media_ids[0],
            "media_url": media_url,
            "playback_url": playback_url,
            "mux_asset_id": resolved_media.get("mux_asset_id") or "",
            "mux_playback_id": resolved_media.get("mux_playback_id") or "",
            "mux_status": mux_status or "",
            "processing_status": processing_status or "ready",
            "next_url": f"/pulse/reels/{reel_id}",
        })
    except Exception as exc:
        logging.exception("PULSE_REELS_CREATE_FAILED trace_id=%s user_id=%s error=%s", trace_id, user.get("user_id"), exc)
        return jsonify({"ok": False, "message": "Reel could not be created.", "trace_id": trace_id}), 500


@webhook_app.route("/api/pulse/reels/react", methods=["POST"])
def api_pulse_reels_react():
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or {}
    reel = pulse_reel_payload(reel_id=safe_int(payload.get("reel_id"), 0), post_id=safe_int(payload.get("post_id"), 0), viewer_user_id=user["user_id"])
    if not reel:
        return jsonify({"ok": False, "message": "Reel not found."}), 404
    if reel.get("reactions_disabled") and not reel.get("can_manage"):
        return jsonify({"ok": False, "message": "Reactions are disabled for this Reel."}), 403
    result, status = pulse_feed_engine.react(user["user_id"], reel["post_id"], payload.get("reaction_type") or "fire")
    if result.get("ok"):
        if not result.get("removed"):
            conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
            pulse_notify_post_owner(
                cur,
                reel["post_id"],
                user,
                "reel_like",
                "New Reel reaction",
                f"{pulse_actor_display_name(user)} reacted to your PulseSoc Reel.",
                entity_type="reel",
                entity_id=reel.get("reel_id"),
                deep_link=f"/pulse/reels/{reel.get('reel_id')}",
                metadata={"reaction_type": result.get("reaction_type") or payload.get("reaction_type") or ""},
            )
            conn.commit(); conn.close()
        pulse_emit_event("pulse_reel_reaction_updated", {**result, "reel_id": reel.get("reel_id")}, user["user_id"], reel["post_id"])
    return jsonify(result), status


