@webhook_app.route("/api/pulse/reels/<int:reel_id>/view", methods=["POST"])
def api_pulse_reel_view(reel_id):
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    reel = pulse_reel_payload(reel_id=reel_id, viewer_user_id=user["user_id"])
    if not reel:
        return jsonify({"ok": False, "message": "Reel not found."}), 404
    payload = request.get_json(silent=True) or {}
    watch_ms = max(0, safe_int(payload.get("watch_ms"), 0))
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute(
        "UPDATE pulse_reels SET replay_count=COALESCE(replay_count,0)+1, watch_duration_ms=COALESCE(watch_duration_ms,0)+?, updated_at=? WHERE id=?",
        (watch_ms, now, reel_id),
    )
    cur.execute(
        "UPDATE pulse_posts SET view_count=COALESCE(view_count,0)+1, updated_at=? WHERE id=?",
        (now, int(reel.get("post_id") or 0)),
    )
    cur.execute("SELECT COALESCE(replay_count,0) AS views FROM pulse_reels WHERE id=? LIMIT 1", (reel_id,))
    views = safe_int(dict(cur.fetchone() or {}).get("views"), 0)
    conn.commit(); conn.close()
    return jsonify({"ok": True, "reel_id": reel_id, "view_count": views})


