@webhook_app.route("/api/reels/<int:reel_id>", methods=["PATCH", "DELETE"])
@webhook_app.route("/api/pulse/reels/<int:reel_id>", methods=["PATCH", "DELETE"])
def api_pulse_reel_manage(reel_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    trace_id = secrets.token_hex(6)
    reel = pulse_reel_payload(reel_id=reel_id, viewer_user_id=user["user_id"])
    if not reel:
        return api_error("Reel not found.", 404, trace_id)
    if not reel.get("can_manage"):
        return api_error("Only the Reel owner can manage this Reel.", 403, trace_id)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    if request.method == "DELETE":
        try:
            cur.execute("UPDATE pulse_reels SET status='deleted', updated_at=? WHERE id=? AND user_id=?", (now, reel_id, user["user_id"]))
            cur.execute("UPDATE pulse_posts SET status='deleted', deleted_at=?, updated_at=? WHERE id=? AND user_id=?", (now, now, int(reel["post_id"]), user["user_id"]))
            conn.commit()
        except Exception as exc:
            conn.rollback()
            logging.exception("PULSE_REEL_DELETE_FAILED trace_id=%s user_id=%s reel_id=%s error=%s", trace_id, user.get("user_id"), reel_id, exc)
            return api_error("Reel could not be deleted.", 500, trace_id)
        finally:
            conn.close()
        pulse_emit_event("pulse_reel_deleted", {"reel_id": reel_id, "post_id": int(reel["post_id"]), "trace_id": trace_id}, user["user_id"], int(reel["post_id"]))
        return jsonify({"ok": True, "message": "Reel deleted.", "reel_id": reel_id, "trace_id": trace_id})
    payload = request.get_json(silent=True) or {}
    title = clean_html(payload.get("title") or reel.get("title") or "PulseSoc Reel")[:140]
    caption = clean_html(payload.get("description") or payload.get("caption") or payload.get("body") or reel.get("caption") or reel.get("body") or "")[:2200]
    category = clean_html(payload.get("category") or reel.get("category") or "Community")[:80]
    raw_tags = payload.get("hashtags") if "hashtags" in payload else payload.get("tags")
    if isinstance(raw_tags, str):
        tags = [re.sub(r"[^A-Za-z0-9_]", "", tag.strip().lstrip("#"))[:40] for tag in re.split(r"[\s,]+", raw_tags) if tag.strip()]
    elif isinstance(raw_tags, list):
        tags = [re.sub(r"[^A-Za-z0-9_]", "", clean_html(str(tag)).strip().lstrip("#"))[:40] for tag in raw_tags if str(tag).strip()]
    else:
        tags = reel.get("ai_tags") or reel.get("tags") or []
    tags = [tag for tag in tags if tag][:20]
    visibility = clean_html(payload.get("visibility") or reel.get("visibility") or "public")[:40]
    if visibility not in {"public", "followers", "private", "reel_only"}:
        conn.close()
        return api_error("Choose a valid Reel visibility.", 400, trace_id)
    comments_disabled = 1 if bool(payload.get("comments_disabled", reel.get("comments_disabled"))) else 0
    reactions_disabled = 1 if bool(payload.get("reactions_disabled", reel.get("reactions_disabled"))) else 0
    try:
        cur.execute(
            "UPDATE pulse_posts SET title=?, body=?, tags_json=?, visibility=?, updated_at=? WHERE id=? AND user_id=?",
            (title, caption, json.dumps(tags[:20]), visibility, now, int(reel["post_id"]), user["user_id"]),
        )
        cur.execute(
            "UPDATE pulse_reels SET category=?, caption=?, ai_tags_json=?, comments_disabled=?, reactions_disabled=?, updated_at=? WHERE id=? AND user_id=?",
            (category, caption, json.dumps(tags[:20]), comments_disabled, reactions_disabled, now, reel_id, user["user_id"]),
        )
        conn.commit()
    except Exception as exc:
        conn.rollback()
        logging.exception("PULSE_REEL_UPDATE_FAILED trace_id=%s user_id=%s reel_id=%s error=%s", trace_id, user.get("user_id"), reel_id, exc)
        return api_error("Reel could not be updated.", 500, trace_id)
    finally:
        conn.close()
    updated = pulse_reel_payload(reel_id=reel_id, viewer_user_id=user["user_id"])
    pulse_emit_event("pulse_reel_updated", {"reel_id": reel_id, "post_id": int(reel["post_id"]), "reel": updated}, user["user_id"], int(reel["post_id"]))
    return jsonify({"ok": True, "message": "Reel updated.", "reel": updated, "trace_id": trace_id})


@webhook_app.route("/api/pulse/reels/<int:reel_id>/pin", methods=["POST"])
def api_pulse_reel_pin(reel_id):
    init_db()
