@webhook_app.route("/api/pulse/reels/comments/<int:comment_id>/react", methods=["POST"])
def api_pulse_reel_comment_react(comment_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    payload = request.get_json(silent=True) or {}
    reaction_type = clean_html(payload.get("reaction_type") or "like")[:40] or "like"
    comment = pulse_feed_engine.get_comment(comment_id)
    if not comment:
        return api_error("Comment not found.", 404)
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT id FROM pulse_comment_reactions WHERE comment_id=? AND user_id=? LIMIT 1", (comment_id, user["user_id"]))
    existing = cur.fetchone()
    removed = False
    now = datetime.utcnow().isoformat(timespec="seconds")
    if existing:
        cur.execute("DELETE FROM pulse_comment_reactions WHERE id=? AND user_id=?", (existing["id"], user["user_id"]))
        removed = True
    else:
        cur.execute("INSERT OR REPLACE INTO pulse_comment_reactions (comment_id, user_id, reaction_type, created_at) VALUES (?, ?, ?, ?)", (comment_id, user["user_id"], reaction_type, now))
        owner_id = safe_int(comment.get("user_id"), 0)
        if owner_id and owner_id != safe_int(user["user_id"]):
            notify_user(
                cur,
                owner_id,
                "reel_comment_like",
                "New comment reaction",
                f"{pulse_actor_display_name(user)} liked your Reel comment.",
                target_url=f"/pulse/reels?comment={comment_id}",
                actor_user_id=user["user_id"],
                entity_type="reel_comment",
                entity_id=str(comment_id),
                metadata={"post_id": comment.get("post_id"), "comment_id": comment_id, "reaction_type": reaction_type},
            )
    cur.execute("SELECT reaction_type, COUNT(*) AS total FROM pulse_comment_reactions WHERE comment_id=? GROUP BY reaction_type", (comment_id,))
    counts = {dict(row).get("reaction_type") or "like": safe_int(dict(row).get("total"), 0) for row in cur.fetchall()}
    conn.commit()
    conn.close()
    pulse_emit_event("pulse_reel_comment_reaction_updated", {"comment_id": comment_id, "removed": removed, "reaction_counts": counts}, user["user_id"], safe_int(comment.get("post_id"), 0))
    return jsonify({"ok": True, "comment_id": comment_id, "removed": removed, "reaction_type": reaction_type, "reaction_counts": counts, "like_count": safe_int(counts.get("like"), 0)})


@webhook_app.route("/api/pulse/reels/comments/<int:comment_id>", methods=["PATCH", "DELETE"])
def api_pulse_reel_comment_manage(comment_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    trace_id = secrets.token_hex(6)
    comment = pulse_feed_engine.get_comment(comment_id)
    if not comment:
        return api_error("Comment not found.", 404, trace_id)
    post_id = safe_int(comment.get("post_id"), 0)
