@webhook_app.route("/api/reels/<int:reel_id>/audio", methods=["POST"])
@webhook_app.route("/api/pulse/reels/<int:reel_id>/audio", methods=["POST"])
def api_pulse_reel_audio_manage(reel_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    reel = pulse_reel_payload(reel_id=reel_id, viewer_user_id=user["user_id"])
    if not reel:
        return api_error("Reel not found.", 404)
    if not reel.get("can_manage"):
        return api_error("Only the Reel owner can change its audio.", 403)
    payload = request.get_json(silent=True) or {}
    track_id = safe_int(payload.get("audio_track_id") or payload.get("track_id"), 0)
    try:
        start_seconds = max(0.0, float(payload.get("start_seconds") or 0))
        end_seconds = max(0.0, float(payload.get("end_seconds") or 0))
        volume = min(1.0, max(0.0, float(payload.get("volume") if payload.get("volume") is not None else 1)))
    except (TypeError, ValueError):
        return api_error("Use valid audio timing and volume values.", 400)
    if end_seconds and end_seconds <= start_seconds:
        return api_error("Audio end time must be after its start time.", 400)
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        cur.execute("DELETE FROM pulse_reel_audio WHERE reel_id=?", (reel_id,))
        cur.execute("DELETE FROM pulse_content_music WHERE content_type='reel' AND content_id=?", (reel_id,))
        post_id = safe_int(reel.get("post_id"), 0)
        if post_id:
            cur.execute("DELETE FROM pulse_content_music WHERE content_type IN ('post','video') AND content_id=?", (post_id,))
        if not track_id:
            cur.execute("UPDATE pulse_reels SET audio_track_id=NULL, sound_title='Original audio', sound_start_seconds=0, sound_end_seconds=0, updated_at=? WHERE id=? AND user_id=?", (now, reel_id, user["user_id"]))
            conn.commit()
            return jsonify({"ok": True, "message": "Original Reel audio selected.", "audio": {"track_id": 0, "title": "Original audio", "volume": volume}})
        music_payload = music_service.attach_music_payload(str(track_id))
        if not music_payload.get("is_creator_safe"):
            conn.rollback()
            return api_error(music_payload.get("message") or "That audio is not approved for Reel use.", 400)
        cur.execute(
            """
            SELECT * FROM pulse_audio_tracks
            WHERE id=? AND COALESCE(safety_status,'approved')='approved' AND COALESCE(active,1)=1
              AND COALESCE(approved_by_admin,0)=1 AND COALESCE(commercial_use_allowed,0)=1
              AND COALESCE(remix_edit_allowed,0)=1 LIMIT 1
            """,
            (track_id,),
        )
        track = dict(cur.fetchone() or {})
        if not track:
            conn.rollback()
            return api_error("That audio track is unavailable for Reel use.", 400)
        cur.execute(
            "INSERT INTO pulse_reel_audio (reel_id, audio_track_id, start_seconds, end_seconds, volume, created_at) VALUES (?, ?, ?, ?, ?, ?)",
            (reel_id, track_id, start_seconds, end_seconds, volume, now),
        )
        cur.execute(
            "UPDATE pulse_reels SET audio_track_id=?, sound_title=?, sound_start_seconds=?, sound_end_seconds=?, updated_at=? WHERE id=? AND user_id=?",
            (track_id, track.get("title") or "", start_seconds, end_seconds, now, reel_id, user["user_id"]),
        )
        attached = pulse_attach_music_to_content(cur, content_type="reel", content_id=reel_id, track_id=track_id, user_id=user["user_id"], start_seconds=start_seconds, volume=volume)
        if not attached.get("ok"):
            conn.rollback()
            return api_error(attached.get("message") or "Audio could not be attached.", 400)
        if post_id:
            feed_attached = pulse_attach_music_to_content(cur, content_type="post", content_id=post_id, track_id=track_id, user_id=user["user_id"], start_seconds=start_seconds, volume=volume)
            if not feed_attached.get("ok"):
                conn.rollback()
                return api_error(feed_attached.get("message") or "Feed audio could not be attached.", 400)
            video_attached = pulse_attach_music_to_content(cur, content_type="video", content_id=post_id, track_id=track_id, user_id=user["user_id"], start_seconds=start_seconds, volume=volume)
            if not video_attached.get("ok"):
                conn.rollback()
                return api_error(video_attached.get("message") or "Video audio could not be attached.", 400)
        conn.commit()
    except Exception:
        conn.rollback()
        logging.exception("PULSE_REEL_AUDIO_UPDATE_FAILED user_id=%s reel_id=%s", user.get("user_id"), reel_id)
        return api_error("Reel audio could not be updated.", 500)
    finally:
        conn.close()
    pulse_emit_event("pulse_reel_audio_updated", {"reel_id": reel_id, "track_id": track_id}, user["user_id"], int(reel.get("post_id") or 0))
    return jsonify({"ok": True, "message": "Reel audio updated.", "audio": {"track_id": track_id, "title": track.get("title") or "", "artist": track.get("artist") or "", "start_seconds": start_seconds, "end_seconds": end_seconds, "volume": volume}})


@webhook_app.route("/api/pulse/posts/<int:post_id>", methods=["GET", "PATCH", "DELETE"])
def api_pulse_post(post_id):
    init_db()
    user = api_account_user()
    if not user:
        return jsonify({"ok": False, "message": "Login required."}), 401
    if request.method == "PATCH":
        trace_id = secrets.token_hex(6)
        payload = request.get_json(silent=True) or {}
        body = clean_html(payload.get("body") or "")[:5000]
        title = clean_html(payload.get("title") or "")[:180]
        visibility = clean_html(payload.get("visibility") or "public")[:40]
        if visibility not in {"public", "followers", "private"}:
            visibility = "public"
        conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
        cur.execute("SELECT user_id FROM pulse_posts WHERE id=? AND deleted_at IS NULL LIMIT 1", (post_id,))
        post = dict(cur.fetchone() or {})
        if not post:
            conn.close()
            return api_error("Post not found.", 404, trace_id)
        if int(post.get("user_id") or 0) != int(user["user_id"]) and not pulse_group_user_is_admin(user):
            conn.close()
            return api_error("You can only edit your own PulseSoc posts.", 403, trace_id)
        if not body and not title:
            conn.close()
            return api_error("Add text before saving the edit.", 400, trace_id)
        now = datetime.utcnow().isoformat(timespec="seconds")
        cur.execute(
            "UPDATE pulse_posts SET body=?, title=?, visibility=?, updated_at=? WHERE id=?",
            (body, title, visibility, now, post_id),
        )
        conn.commit(); conn.close()
        pulse_emit_event("post_updated", {"post_id": post_id}, user["user_id"], post_id)
        return jsonify({"ok": True, "message": "Post updated.", "post_id": post_id})
    if request.method == "DELETE":
        return pulse_delete_post_common(post_id, user)
    post = pulse_feed_engine.get_post(post_id, viewer_user_id=user["user_id"], include_private=True)
    if not post:
        return jsonify({"ok": False, "message": "Post not found."}), 404
    return jsonify({"ok": True, "post": post, "comments": pulse_feed_engine.list_comments(post_id).get("comments", [])})


def pulse_delete_post_common(post_id, user):
    trace_id = secrets.token_hex(6)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM pulse_posts WHERE id=? AND deleted_at IS NULL LIMIT 1", (post_id,))
        post = dict(cur.fetchone() or {})
        if not post:
            conn.close()
            return api_error("Post not found.", 404, trace_id)
        owner_id = int(post.get("user_id") or 0)
        if owner_id != int(user["user_id"]) and not pulse_group_user_is_admin(user):
            conn.close()
            return api_error("You cannot delete this post.", 403, trace_id)
        now = datetime.utcnow().isoformat(timespec="seconds")
        cur.execute("UPDATE pulse_posts SET deleted_at=?, updated_at=?, moderation_status=COALESCE(moderation_status,'approved') WHERE id=?", (now, now, post_id))
        for table, column in [
            ("pulse_reactions", "post_id"),
            ("pulse_comments", "post_id"),
            ("pulse_reports", "target_id"),
            ("pulse_post_saves", "post_id"),
        ]:
            try:
                if table == "pulse_reports":
                    cur.execute(f"UPDATE {table} SET status='closed' WHERE target_type='post' AND {column}=?", (post_id,))
                elif "deleted_at" in table_columns(cur, table):
                    cur.execute(f"UPDATE {table} SET deleted_at=? WHERE {column}=?", (now, post_id))
                else:
                    cur.execute(f"DELETE FROM {table} WHERE {column}=?", (post_id,))
            except Exception:
                pass
        try:
            cur.execute("UPDATE chat_media_uploads SET deleted_at=? WHERE context_type IN ('pulse','pulse_post') AND context_id=?", (now, str(post_id)))
        except Exception:
            pass
        conn.commit(); conn.close()
        pulse_emit_event("pulse_post_deleted", {"post_id": post_id, "deleted": True}, user["user_id"], post_id)
        pulse_emit_event("post_deleted", {"post_id": post_id, "deleted": True}, user["user_id"], post_id)
        return jsonify({"ok": True, "message": "Post deleted.", "post_id": post_id})
    except Exception as exc:
        conn.rollback(); conn.close()
        logging.exception("PULSE_POST_DELETE_FAILED trace_id=%s post_id=%s user_id=%s", trace_id, post_id, user.get("user_id"))
        return api_error("Post could not be deleted. The team can trace this safely.", 500, trace_id, error_type=exc.__class__.__name__)


