PULSE_SAVED_TYPES = {"post", "reel", "status", "live_replay", "marketplace", "room", "group", "teacher", "comment", "thread", "video", "image", "learning"}


def pulse_saved_slug(name):
    value = re.sub(r"[^a-z0-9]+", "-", str(name or "saved").strip().lower()).strip("-")
    return value[:80] or "saved"


def ensure_pulse_saved_collection(cur, user_id, name="Favorites"):
    now = datetime.utcnow().isoformat(timespec="seconds")
    slug = pulse_saved_slug(name)
    cur.execute("SELECT id FROM pulse_saved_collections WHERE user_id=? AND slug=? LIMIT 1", (int(user_id), slug))
    row = cur.fetchone()
    if row:
        return int(row["id"] if isinstance(row, sqlite3.Row) else row[0])
    cur.execute(
        "INSERT INTO pulse_saved_collections (user_id, name, slug, description, is_default, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (int(user_id), clean_html(name)[:120], slug, "Default saved space" if slug == "favorites" else "", 1 if slug == "favorites" else 0, now, now),
    )
    return int(cur.lastrowid)


def pulse_saved_snapshot(cur, content_type, content_id, payload=None):
    payload = payload or {}
    content_type = clean_html(content_type)[:40]
    content_id = clean_html(str(content_id or ""))[:80]
    title = clean_html(payload.get("title") or "")[:220]
    preview = clean_html(payload.get("preview_text") or payload.get("description") or payload.get("body") or "")[:700]
    source_url = clean_html(payload.get("source_url") or "")[:500]
    thumbnail_url = clean_html(payload.get("thumbnail_url") or "")[:800]
    media_url = clean_html(payload.get("media_url") or "")[:800]
    if content_type == "post" and content_id:
        cur.execute("SELECT id, post_type, title, body, media_ids_json FROM pulse_posts WHERE id=? AND deleted_at IS NULL LIMIT 1", (safe_int(content_id, 0),))
        post = cur.fetchone()
        if post:
            title = title or clean_html(post["title"] or f"PulseSoc {post['post_type'] or 'post'}")[:220]
            preview = preview or clean_html(post["body"] or "")[:700]
            source_url = source_url or f"/pulse/post/{post['id']}"
    elif content_type == "reel" and content_id:
        cur.execute("SELECT r.id, r.post_id, r.caption, p.title, p.body FROM pulse_reels r LEFT JOIN pulse_posts p ON p.id=r.post_id WHERE r.id=? LIMIT 1", (safe_int(content_id, 0),))
        reel = cur.fetchone()
        if reel:
            title = title or clean_html(reel["title"] or "PulseSoc Reel")[:220]
            preview = preview or clean_html(reel["caption"] or reel["body"] or "")[:700]
            source_url = source_url or f"/pulse/reels?reel={reel['id']}"
    elif content_type == "status" and content_id:
        cur.execute("SELECT id, status_type, body FROM pulse_status WHERE id=? LIMIT 1", (safe_int(content_id, 0),))
        status = cur.fetchone()
        if status:
            title = title or clean_html(status["body"] or f"{status['status_type'] or 'PulseSoc'} Status")[:220]
            preview = preview or clean_html(status["status_type"] or "PulseSoc Status")[:700]
            source_url = source_url or f"/pulse/status?status_id={status['id']}"
    elif content_type == "video" and content_id:
        cur.execute("SELECT id, source_type, source_id, title, description, thumbnail_url, playback_url, media_url FROM pulse_videos WHERE id=? AND COALESCE(status,'active')='active' LIMIT 1", (safe_int(content_id, 0),))
        video = cur.fetchone()
        if video:
            title = title or clean_html(video["title"] or "PulseSoc Video")[:220]
            preview = preview or clean_html(video["description"] or "")[:700]
            thumbnail_url = thumbnail_url or clean_html(video["thumbnail_url"] or "")[:800]
            media_url = media_url or clean_html(video["playback_url"] or video["media_url"] or "")[:800]
            source_url = source_url or f"/pulse/videos/{video['id']}"
    return {
        "title": title or content_type.replace("_", " ").title(),
        "preview_text": preview,
        "thumbnail_url": thumbnail_url,
        "media_url": media_url,
        "source_url": source_url or "/pulse",
    }


def pulse_saved_items_query(cur, user_id, *, collection_id=0, content_type="", q="", limit=80):
    where = ["i.user_id=?"]
    params = [int(user_id)]
    if collection_id:
        where.append("i.collection_id=?")
        params.append(int(collection_id))
    if content_type and content_type != "all":
        where.append("i.content_type=?")
        params.append(clean_html(content_type)[:40])
    if q:
        where.append("(i.title LIKE ? OR i.preview_text LIKE ?)")
        params.extend([f"%{q}%", f"%{q}%"])
    cur.execute(
        f"""
        SELECT i.*, c.name AS collection_name
        FROM pulse_saved_items i
        LEFT JOIN pulse_saved_collections c ON c.id=i.collection_id AND c.user_id=i.user_id
        WHERE {' AND '.join(where)}
        ORDER BY i.updated_at DESC, i.id DESC
        LIMIT ?
        """,
        (*params, int(limit)),
    )
    return [dict(row) for row in cur.fetchall()]


@webhook_app.route("/api/pulse/posts/<int:post_id>/save", methods=["POST"])
def api_pulse_post_save(post_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    trace_id = secrets.token_hex(6)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_posts WHERE id=? AND deleted_at IS NULL LIMIT 1", (post_id,))
    post = cur.fetchone()
    if not post:
        conn.close()
        return api_error("Post not found.", 404, trace_id)
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("SELECT id FROM pulse_post_saves WHERE post_id=? AND user_id=? LIMIT 1", (post_id, user["user_id"]))
    existing = cur.fetchone()
    if existing:
        cur.execute("DELETE FROM pulse_post_saves WHERE post_id=? AND user_id=?", (post_id, user["user_id"]))
        cur.execute("DELETE FROM pulse_saved_items WHERE user_id=? AND content_type='post' AND content_id=?", (user["user_id"], str(post_id)))
        saved = False
    else:
        cur.execute("INSERT INTO pulse_post_saves (post_id, user_id, collection_name, created_at) VALUES (?, ?, 'Saved', ?)", (post_id, user["user_id"], now))
        collection_id = ensure_pulse_saved_collection(cur, user["user_id"])
        title = clean_html(post["title"] or f"PulseSoc {post['post_type'] or 'post'}")[:220]
        preview = clean_html(post["body"] or "")[:700]
        cur.execute(
            """
            INSERT INTO pulse_saved_items
            (user_id, collection_id, content_type, content_id, title, preview_text, thumbnail_url, media_url, source_url, metadata_json, created_at, updated_at)
            VALUES (?, ?, 'post', ?, ?, ?, '', '', ?, ?, ?, ?)
            ON CONFLICT(user_id, content_type, content_id) DO UPDATE SET collection_id=excluded.collection_id, title=excluded.title, preview_text=excluded.preview_text, updated_at=excluded.updated_at
            """,
            (user["user_id"], collection_id, str(post_id), title, preview, f"/pulse/post/{post_id}", json.dumps({"post_type": post["post_type"] or "post"}), now, now),
        )
        saved = True
        pulse_notify_post_owner(
            cur,
            post_id,
            user,
            "video_save" if (post["post_type"] or "") == "video" else "save",
            "PulseSoc saved",
            f"{pulse_actor_display_name(user)} saved your PulseSoc post.",
            metadata={"source": "api_pulse_post_save", "content_type": post["post_type"] or "post"},
        )
    conn.commit(); conn.close()
    return jsonify({"ok": True, "saved": saved, "message": "Post saved." if saved else "Post removed from saved."})


@webhook_app.route("/api/pulse/saved/collections", methods=["GET", "POST"])
def api_pulse_saved_collections():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    if request.method == "POST":
        payload = request.get_json(silent=True) or {}
        name = clean_html(payload.get("name") or "New Collection")[:120]
        if len(name.strip()) < 2:
            conn.close()
            return api_error("Collection name must be at least 2 characters.", 400)
        collection_id = ensure_pulse_saved_collection(cur, user["user_id"], name)
        conn.commit()
    else:
        ensure_pulse_saved_collection(cur, user["user_id"])
        conn.commit()
        collection_id = 0
    cur.execute(
        """
        SELECT c.*, (SELECT COUNT(*) FROM pulse_saved_items i WHERE i.collection_id=c.id AND i.user_id=c.user_id) AS item_count
        FROM pulse_saved_collections c
        WHERE c.user_id=?
        ORDER BY c.is_default DESC, c.updated_at DESC, c.name
        """,
        (user["user_id"],),
    )
    collections = [dict(row) for row in cur.fetchall()]
    conn.close()
    return jsonify({"ok": True, "collections": collections, "collection_id": collection_id})


@webhook_app.route("/api/pulse/saved/collections/<int:collection_id>", methods=["PATCH", "DELETE"])
def api_pulse_saved_collection_detail(collection_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM pulse_saved_collections WHERE id=? AND user_id=? LIMIT 1", (collection_id, user["user_id"]))
    row = cur.fetchone()
    if not row:
        conn.close()
        return api_error("Collection not found.", 404)
    if request.method == "DELETE":
        fallback_id = ensure_pulse_saved_collection(cur, user["user_id"])
        if int(row["is_default"] or 0):
            conn.close()
            return api_error("Default collection cannot be deleted.", 400)
        cur.execute("UPDATE pulse_saved_items SET collection_id=?, updated_at=? WHERE collection_id=? AND user_id=?", (fallback_id, datetime.utcnow().isoformat(timespec="seconds"), collection_id, user["user_id"]))
        cur.execute("DELETE FROM pulse_saved_collections WHERE id=? AND user_id=?", (collection_id, user["user_id"]))
        conn.commit(); conn.close()
        return jsonify({"ok": True, "message": "Collection deleted."})
    payload = request.get_json(silent=True) or {}
    name = clean_html(payload.get("name") or row["name"])[:120]
    if len(name.strip()) < 2:
        conn.close()
        return api_error("Collection name must be at least 2 characters.", 400)
    slug = pulse_saved_slug(name)
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("UPDATE pulse_saved_collections SET name=?, slug=?, updated_at=? WHERE id=? AND user_id=?", (name, slug, now, collection_id, user["user_id"]))
    conn.commit(); conn.close()
    return jsonify({"ok": True, "message": "Collection updated.", "collection_id": collection_id})


@webhook_app.route("/api/pulse/saved", methods=["GET", "POST"])
def api_pulse_saved_items():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    if request.method == "POST":
        payload = request.get_json(silent=True) or {}
        content_type = clean_html(payload.get("content_type") or payload.get("type") or "post")[:40]
        content_id = clean_html(str(payload.get("content_id") or payload.get("id") or ""))[:80]
        if content_type not in PULSE_SAVED_TYPES:
            conn.close()
            return api_error("That content type cannot be saved yet.", 400, error="unsupported_content_type")
        if not content_id:
            conn.close()
            return api_error("Saved item is missing a content ID.", 400)
        collection_id = safe_int(payload.get("collection_id"), 0) or ensure_pulse_saved_collection(cur, user["user_id"])
        cur.execute("SELECT id FROM pulse_saved_collections WHERE id=? AND user_id=? LIMIT 1", (collection_id, user["user_id"]))
        if not cur.fetchone():
            collection_id = ensure_pulse_saved_collection(cur, user["user_id"])
        snapshot = pulse_saved_snapshot(cur, content_type, content_id, payload)
        now = datetime.utcnow().isoformat(timespec="seconds")
        cur.execute(
            """
            INSERT INTO pulse_saved_items
            (user_id, collection_id, content_type, content_id, title, preview_text, thumbnail_url, media_url, source_url, metadata_json, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(user_id, content_type, content_id) DO UPDATE SET collection_id=excluded.collection_id, title=excluded.title, preview_text=excluded.preview_text, thumbnail_url=excluded.thumbnail_url, media_url=excluded.media_url, source_url=excluded.source_url, updated_at=excluded.updated_at
            """,
            (user["user_id"], collection_id, content_type, content_id, snapshot["title"], snapshot["preview_text"], snapshot["thumbnail_url"], snapshot["media_url"], snapshot["source_url"], json.dumps(payload, default=str)[:5000], now, now),
        )
        conn.commit()
    else:
        ensure_pulse_saved_collection(cur, user["user_id"])
        conn.commit()
    collection_id = safe_int(request.args.get("collection_id"), 0)
    content_type = clean_html(request.args.get("type") or "all")[:40]
    q = clean_html(request.args.get("q") or "")[:120]
    items = pulse_saved_items_query(cur, user["user_id"], collection_id=collection_id, content_type=content_type, q=q)
    cur.execute("SELECT * FROM pulse_saved_collections WHERE user_id=? ORDER BY is_default DESC, name", (user["user_id"],))
    collections = [dict(row) for row in cur.fetchall()]
    conn.close()
    return jsonify({"ok": True, "items": items, "collections": collections, "message": "Saved." if request.method == "POST" else ""})


