        following = True
        notify_user(
            cur,
            target_id,
            "follow",
            "New follower",
            f"{pulse_actor_display_name(user)} followed you on PulseSoc.",
            f"/pulse/profile/{user.get('public_player_id') or user['user_id']}",
            actor_user_id=user["user_id"],
            entity_type="profile",
            entity_id=str(user["user_id"]),
            metadata={"source": "api_pulse_follows_toggle"},
        )
