@webhook_app.route("/api/pulse/communications/conversations/<path:conversation_ref>/messages", methods=["GET"])
def api_pulse_communications_conversation_messages(conversation_ref):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_comm_error("Login required.", 401, reason="login_required", endpoint=request.path)
    trace_id = secrets.token_hex(6)
    source, conversation_id = pulse_comm_ref(conversation_ref)
    if source != "room" and not conversation_id:
        return pulse_comm_error("Conversation not found.", 404, trace_id, reason="conversation_not_found", endpoint=request.path)
    try:
        if source == "legacy":
            payload, status = pulse_comm_legacy_messages(user, conversation_id, limit=safe_int(request.args.get("limit"), 80), after_id=safe_int(request.args.get("since_id") or request.args.get("after_id"), 0))
            payload["trace_id"] = trace_id
            payload.setdefault("endpoint", request.path)
            return jsonify(payload), status
        conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
        ensure_pulse_messenger_schema(cur, conn)
        if source == "room":
            result, room_status = pulse_get_or_create_room_conversation(cur, user["user_id"], room_key=conversation_id)
            if not result.get("ok"):
                result["trace_id"] = trace_id
                result["endpoint"] = request.path
                result.setdefault("reason", "room_lookup_failed")
                conn.rollback(); conn.close()
                return jsonify(result), room_status
            conversation_id = safe_int(result.get("conversation_id"), 0)
        payload, status = pulse_comm_pulse_messages(cur, user, conversation_id, limit=safe_int(request.args.get("limit"), 80), before_id=safe_int(request.args.get("before_id"), 0))
        payload["trace_id"] = trace_id
        payload.setdefault("endpoint", request.path)
        if source == "room" and payload.get("conversation"):
            payload["conversation"]["room_id"] = conversation_ref.replace("room-", "", 1)
        conn.commit(); conn.close()
        return jsonify(payload), status
    except Exception as exc:
        logging.exception("PULSE_COMM_MESSAGES_FAILED trace_id=%s user_id=%s conversation_ref=%s", trace_id, user.get("user_id"), conversation_ref)
        return pulse_comm_error("Messages could not load.", 500, trace_id, reason="query_failure", endpoint=request.path, error_type=exc.__class__.__name__)


@webhook_app.route("/api/pulse/communications/conversations/<path:conversation_ref>/messages", methods=["POST"])
def api_pulse_communications_send_message(conversation_ref):
    init_db()
    user = api_account_user()
    if not user:
        return pulse_comm_error("Login required.", 401, reason="login_required", endpoint=request.path)
    payload = request.get_json(silent=True) or {}
    body = clean_html(payload.get("message") or payload.get("body") or payload.get("content") or "")[:2000].strip()
    if not body:
        return pulse_comm_error("Write a message before sending.", 400, reason="empty_message", endpoint=request.path)
    trace_id = secrets.token_hex(6)
    source, conversation_id = pulse_comm_ref(conversation_ref)
    if source != "room" and not conversation_id:
        return pulse_comm_error("Conversation not found.", 404, trace_id, reason="conversation_not_found", endpoint=request.path)
    try:
        if source == "legacy":
            result, status = chat_realtime_service.send_message(user["user_id"], conversation_id, body)
            result["trace_id"] = trace_id
            result.setdefault("endpoint", request.path)
            if result.get("ok"):
                conn = db(); cur = conn.cursor()
                cur.execute("SELECT user_id FROM conversation_members WHERE conversation_id=? AND user_id!=?", (conversation_id, user["user_id"]))
                recipient_ids = [int(row["user_id"]) for row in cur.fetchall()]
                conn.close()
                pulse_finalize_legacy_message_delivery(result, user, conversation_id, recipient_ids, body, "text", trace_id)
                event = {"conversation_id": conversation_id, "message_id": result.get("message_id"), "target_user_ids": recipient_ids}
                pulse_emit_event("message_created", event, user["user_id"], conversation_id)
                pulse_emit_event("conversation_updated", event, user["user_id"], conversation_id)
            return jsonify(result), status
        conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
        ensure_pulse_messenger_schema(cur, conn)
        if source == "room":
            result, room_status = pulse_get_or_create_room_conversation(cur, user["user_id"], room_key=conversation_id)
            if not result.get("ok"):
                result["trace_id"] = trace_id
                result["endpoint"] = request.path
                result.setdefault("reason", "room_lookup_failed")
                conn.rollback(); conn.close()
                return jsonify(result), room_status
            conversation_id = safe_int(result.get("conversation_id"), 0)
        conversation, state = pulse_comm_conversation_access(cur, user["user_id"], conversation_id)
        if state == "missing":
            conn.close()
            return pulse_comm_error("Conversation not found.", 404, trace_id, reason="conversation_not_found", endpoint=request.path)
        if state == "forbidden":
            conn.close()
            return pulse_comm_error("You do not have access to this chat.", 403, trace_id, reason="permission_denied", endpoint=request.path)
        result, status = pulse_send_conversation_message(cur, user, conversation_id, body, payload.get("message_type") or "text", payload.get("media_url") or "", payload.get("thumbnail_url") or "", payload.get("media_metadata") if isinstance(payload.get("media_metadata"), dict) else {}, safe_int(payload.get("reply_to_id"), 0), safe_int(payload.get("file_size"), 0), float(payload.get("duration") or payload.get("duration_seconds") or 0), payload.get("client_message_id") or payload.get("local_id") or "", payload.get("local_created_at") or "")
        result["trace_id"] = trace_id
        result.setdefault("endpoint", request.path)
        if result.get("ok"):
            conn.commit()
        else:
            conn.rollback()
        conn.close()
        if result.get("ok"):
            pulse_finalize_message_delivery(result, user, trace_id)
            event = {"conversation_id": conversation_id, "message": result.get("data"), "message_id": result.get("message_id")}
            pulse_emit_event(result.get("event_name") or "message_created", event, user["user_id"], conversation_id)
            pulse_emit_event("conversation_updated", event, user["user_id"], conversation_id)
        return jsonify(result), status
    except Exception as exc:
        logging.exception("PULSE_COMM_SEND_FAILED trace_id=%s user_id=%s conversation_ref=%s", trace_id, user.get("user_id"), conversation_ref)
        return pulse_comm_error("Message could not be sent.", 500, trace_id, reason="query_failure", endpoint=request.path, error_type=exc.__class__.__name__)


