@webhook_app.route("/api/payments/orders/<int:transaction_id>", methods=["GET"])
@webhook_app.route("/api/pulse/payments/orders/<int:transaction_id>", methods=["GET"])
def api_payments_order_verify(transaction_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    if ios_native_app_request():
        return ios_paid_digital_unavailable_response(api=True)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM creator_transactions
        WHERE id=? AND (buyer_user_id=? OR seller_user_id=?)
        LIMIT 1
        """,
        (int(transaction_id), int(user["user_id"]), int(user["user_id"])),
    )
    order = dict(cur.fetchone() or {})
    if not order:
        cur.execute(
            """
            SELECT * FROM seller_transactions
            WHERE id=? AND (buyer_user_id=? OR seller_user_id=?)
            LIMIT 1
            """,
            (int(transaction_id), int(user["user_id"]), int(user["user_id"])),
        )
        order = dict(cur.fetchone() or {})
    conn.close()
    if not order:
        return api_error("Order not found.", 404)
    status = str(order.get("status") or "pending").lower()
    safe_status = "paid" if status in {"paid", "checkout_completed"} else "refunded" if "refund" in status else "failed" if "failed" in status else "canceled" if "cancel" in status else "pending"
    return jsonify({"ok": True, "order": order, "payment_status": safe_status, "fulfilled": safe_status == "paid"})


