def pulse_admin_user_row(cur, user_id):
    cur.execute(
        """
        SELECT u.*, upp.trust_score, upp.current_level, upp.can_go_live, upp.can_sell, upp.can_teach,
               upp.can_create_groups, upp.can_upload_video, upp.max_video_duration, upp.max_upload_mb,
               upp.posting_limit_per_day, upp.messaging_restricted, upp.posting_restricted, upp.moderation_status,
               la.status AS livestream_status, u.premium_status, u.premium_expires_at, u.lifetime_premium,
               u.premium_glow_manual_grant, u.premium_mark_override, u.premium_mark_type
        FROM users u
        LEFT JOIN user_privilege_profiles upp ON upp.user_id=u.user_id
        LEFT JOIN livestream_access la ON la.user_id=u.user_id
        WHERE u.user_id=?
        LIMIT 1
        """,
        (int(user_id or 0),),
    )
    row = cur.fetchone()
    return dict(row) if row else None


def pulse_admin_all_badges(cur):
    cur.execute("SELECT badge_key, label FROM pulse_badges WHERE COALESCE(active,1)=1 ORDER BY label")
    return [dict(row) for row in cur.fetchall()]


def pulse_admin_all_privileges(cur):
    cur.execute("SELECT privilege_key, label FROM pulse_privileges WHERE COALESCE(active,1)=1 ORDER BY label")
    return [dict(row) for row in cur.fetchall()]


def pulse_admin_user_badges(cur, user_id):
    cur.execute("SELECT badge_key FROM pulse_user_badges WHERE user_id=?", (int(user_id or 0),))
    return {str(dict(row).get("badge_key") or "") for row in cur.fetchall()}


def pulse_admin_user_privileges(cur, user_id):
    cur.execute("SELECT privilege_key FROM pulse_user_privileges WHERE user_id=? AND COALESCE(enabled,1)=1", (int(user_id or 0),))
    return {str(dict(row).get("privilege_key") or "") for row in cur.fetchall()}


def pulse_admin_grant_all(conn, user_id, admin_id=0):
    cur = conn.cursor()
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute(
        "UPDATE users SET lifetime_premium=1, premium_glow_manual_grant=1, premium_mark_override=1, premium_status='lifetime', premium_mark_type=COALESCE(NULLIF(premium_mark_type,''),'star'), updated_at=? WHERE user_id=?",
        (now, int(user_id)),
    )
    cur.execute(
        """
        INSERT INTO user_privilege_profiles
        (user_id, trust_score, current_level, can_go_live, can_sell, can_teach, can_create_groups, can_upload_video,
         can_create_space, can_host_room, can_use_creator_filters, max_video_duration, max_upload_mb,
         posting_limit_per_day, messaging_restricted, posting_restricted, moderation_status, manual_override, updated_by, created_at, updated_at)
        VALUES (?, 100, 'Platform Ambassador', 1, 1, 1, 1, 1, 1, 1, 1, 3600, 1024, 9999, 0, 0, 'clear', 1, ?, ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET
            trust_score=100, current_level='Platform Ambassador', can_go_live=1, can_sell=1, can_teach=1,
            can_create_groups=1, can_upload_video=1, can_create_space=1, can_host_room=1,
            can_use_creator_filters=1, max_video_duration=3600, max_upload_mb=1024,
            posting_limit_per_day=9999, messaging_restricted=0, posting_restricted=0,
            moderation_status='clear', manual_override=1, updated_by=excluded.updated_by, updated_at=excluded.updated_at
        """,
        (int(user_id), int(admin_id or 0), now, now),
    )
    cur.execute(
        "INSERT INTO livestream_access (user_id, status, referral_count, approved_by, suspended_reason, created_at, updated_at) VALUES (?, 'approved', 30, ?, '', ?, ?) ON CONFLICT(user_id) DO UPDATE SET status='approved', referral_count=30, approved_by=excluded.approved_by, suspended_reason='', updated_at=excluded.updated_at",
        (int(user_id), int(admin_id or 0), now, now),
    )
    cur.execute(
        "INSERT INTO livestream_eligibility (user_id, status, referral_count, approved_by, suspended_reason, created_at, updated_at) VALUES (?, 'approved', 30, ?, '', ?, ?) ON CONFLICT(user_id) DO UPDATE SET status='approved', referral_count=30, approved_by=excluded.approved_by, suspended_reason='', updated_at=excluded.updated_at",
        (int(user_id), int(admin_id or 0), now, now),
    )
    for row in cur.execute("SELECT badge_key FROM pulse_badges WHERE COALESCE(active,1)=1").fetchall():
        cur.execute("INSERT OR IGNORE INTO pulse_user_badges (user_id, badge_key, granted_by, created_at) VALUES (?, ?, ?, ?)", (int(user_id), row[0], int(admin_id or 0), now))
    for row in cur.execute("SELECT privilege_key FROM pulse_privileges WHERE COALESCE(active,1)=1").fetchall():
        cur.execute("INSERT INTO pulse_user_privileges (user_id, privilege_key, enabled, granted_by, created_at, updated_at) VALUES (?, ?, 1, ?, ?, ?) ON CONFLICT(user_id, privilege_key) DO UPDATE SET enabled=1, granted_by=excluded.granted_by, updated_at=excluded.updated_at", (int(user_id), row[0], int(admin_id or 0), now, now))
    for vtype in ["identity_verified", "creator_verified", "teacher_verified", "seller_verified", "community_verified", "arena_verified", "safety_verified"]:
        cur.execute(
            "INSERT INTO verification_requests (user_id, verification_type, status, notes, reviewed_by, created_at, reviewed_at) VALUES (?, ?, 'approved', 'Manual PulseSoc control center grant', ?, ?, ?)",
            (int(user_id), vtype, int(admin_id or 0), now, now),
        )
    conn.commit()


def pulse_admin_remove_all(conn, user_id, admin_id=0):
    cur = conn.cursor()
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute(
        "UPDATE users SET lifetime_premium=0, premium_glow_manual_grant=0, premium_mark_override=0, premium_status=CASE WHEN lower(COALESCE(subscription_status,'')) IN ('active','trialing') THEN subscription_status ELSE 'inactive' END, updated_at=? WHERE user_id=?",
        (now, int(user_id)),
    )
    cur.execute("DELETE FROM pulse_user_badges WHERE user_id=?", (int(user_id),))
    cur.execute("UPDATE pulse_user_privileges SET enabled=0, updated_at=?, granted_by=? WHERE user_id=?", (now, int(admin_id or 0), int(user_id)))
    cur.execute(
        """
        INSERT INTO user_privilege_profiles
        (user_id, trust_score, current_level, can_go_live, can_sell, can_teach, can_create_groups, can_upload_video,
         can_create_space, can_host_room, can_use_creator_filters, max_video_duration, max_upload_mb,
         posting_limit_per_day, messaging_restricted, posting_restricted, moderation_status, manual_override, updated_by, created_at, updated_at)
        VALUES (?, 0, 'New User', 0, 0, 0, 0, 0, 0, 0, 0, 45, 25, 5, 1, 1, 'restricted', 1, ?, ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET
            trust_score=0, current_level='New User', can_go_live=0, can_sell=0, can_teach=0,
            can_create_groups=0, can_upload_video=0, can_create_space=0, can_host_room=0,
            can_use_creator_filters=0, max_video_duration=45, max_upload_mb=25, posting_limit_per_day=5,
            messaging_restricted=1, posting_restricted=1, moderation_status='restricted',
            manual_override=1, updated_by=excluded.updated_by, updated_at=excluded.updated_at
        """,
        (int(user_id), int(admin_id or 0), now, now),
    )
    conn.commit()


@webhook_app.route("/admin/pulse-users", methods=["GET"])
def admin_pulse_users_page():
    admin, denied = require_owner_admin_page()
    if denied:
        return denied
    q = (request.args.get("q") or "").strip()
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    rows = []
    query_error = ""
    try:
        if db_service.IS_POSTGRES:
            cur.execute("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='users'")
            user_columns = {str(_migration_row_value(r, "column_name", 0)) for r in cur.fetchall()}
        else:
            user_columns = {str(r[1]) for r in cur.execute("PRAGMA table_info(users)").fetchall()}
        display_expr = "u.display_name" if "display_name" in user_columns else ("u.full_name" if "full_name" in user_columns else "u.username")
        avatar_expr = "u.avatar_url" if "avatar_url" in user_columns else "''"
        status_expr = "u.status" if "status" in user_columns else "'active'"
        last_active_expr = "u.last_login" if "last_login" in user_columns else ("u.last_seen_at" if "last_seen_at" in user_columns else "u.created_at")
        badges_expr = (
            "(SELECT STRING_AGG(COALESCE(b.label, ub.badge_key), ', ') FROM pulse_user_badges ub LEFT JOIN pulse_badges b ON b.badge_key=ub.badge_key WHERE ub.user_id=u.user_id)"
            if db_service.IS_POSTGRES
            else "(SELECT GROUP_CONCAT(COALESCE(b.label, ub.badge_key), ', ') FROM pulse_user_badges ub LEFT JOIN pulse_badges b ON b.badge_key=ub.badge_key WHERE ub.user_id=u.user_id)"
        )
        params = []
        where = ""
        if q:
            like = f"%{q.lower()}%"
            where = f"""
            WHERE lower(COALESCE({display_expr},'')) LIKE ? OR lower(COALESCE(u.username,'')) LIKE ?
               OR lower(COALESCE(u.email,'')) LIKE ? OR CAST(u.user_id AS TEXT)=?
               OR lower(COALESCE(ap.public_player_id,'')) LIKE ?
            """
            params = [like, like, like, q, like]
        cur.execute(
            f"""
            SELECT u.user_id, u.email, u.username, {display_expr} AS display_name, {avatar_expr} AS avatar_url, {status_expr} AS status,
                   u.created_at, {last_active_expr} AS last_active, COALESCE(ap.public_player_id,'') AS public_player_id,
                   COALESCE(upp.trust_score,0) AS trust_score, COALESCE(upp.current_level,'New User') AS current_level,
                   COALESCE(la.status,'locked') AS live_status, COALESCE({badges_expr}, '') AS badges
            FROM users u
            LEFT JOIN arena_profiles ap ON ap.user_id=u.user_id
            LEFT JOIN user_privilege_profiles upp ON upp.user_id=u.user_id
            LEFT JOIN livestream_access la ON la.user_id=u.user_id
            {where}
            ORDER BY COALESCE(upp.trust_score,0) DESC, u.user_id DESC
            LIMIT 120
            """,
            params,
        )
        rows = [dict(row) for row in cur.fetchall()]
    except Exception as exc:
        query_error = str(exc)
        logging.exception("ADMIN_PULSE_USERS_QUERY_FAILED q=%s error=%s", q, exc)
        try:
            conn.rollback()
        except Exception:
            pass
        try:
            cur.execute(
                """
                SELECT u.user_id, u.email, u.username,
                       COALESCE(u.display_name,u.full_name,u.username,'PulseSoc Member') AS display_name,
                       COALESCE(u.avatar_url,'') AS avatar_url, 'active' AS status, u.created_at, u.created_at AS last_active,
                       '' AS public_player_id, 0 AS trust_score, 'New User' AS current_level, 'locked' AS live_status, '' AS badges
                FROM users u
                ORDER BY u.user_id DESC
                LIMIT 120
                """
            )
            rows = [dict(row) for row in cur.fetchall()]
        except Exception as fallback_exc:
            logging.exception("ADMIN_PULSE_USERS_FALLBACK_FAILED error=%s", fallback_exc)
            rows = []
            query_error = f"{query_error} | fallback: {fallback_exc}"
    conn.close()
    table = "".join(
        f"<tr><td>{('<img src=\"'+clean_html(r.get('avatar_url') or '')+'\" style=\"width:34px;height:34px;border-radius:999px;object-fit:cover\">') if r.get('avatar_url') else '•'}</td><td><strong>{clean_html(r.get('display_name') or 'User')}</strong><br><small>{clean_html(r.get('email') or '')}</small></td><td>{clean_html(r.get('username') or '')}</td><td>{clean_html(r.get('status') or 'active')}</td><td>{int(r.get('trust_score') or 0)}</td><td>{clean_html(r.get('current_level') or '')}</td><td>{clean_html(r.get('live_status') or '')}</td><td>{clean_html(r.get('badges') or 'No badges')}</td><td><a class='button' href='/admin/pulse-users/{int(r.get('user_id') or 0)}'>Manage</a></td></tr>"
        for r in rows
    )
    body = f"""
    <h1>PulseSoc Users</h1>
    <p class='muted'>Owner-only manual control for PulseSoc privileges, badges, roles, verification, livestream, marketplace, teacher, posting, and trust status.</p>
    {"<section class='card'><h2>Safe Mode</h2><p class='muted'>PulseSoc user data loaded with a fallback because the primary query failed: " + clean_html(query_error) + "</p><a class='button' href='/admin/pulse-users-health'>Open Health Diagnostics</a></section>" if query_error else ""}
    <form class='card' method='get'><input name='q' value='{clean_html(q)}' placeholder='Search display name, username, email, user ID, or PulseSoc profile ID'><button class='button'>Search</button></form>
    <div class='card'><table><tr><th>Avatar</th><th>User</th><th>Username</th><th>Status</th><th>Trust</th><th>Level</th><th>Live</th><th>Badges</th><th>Action</th></tr>{table or '<tr><td colspan=9>No PulseSoc users found.</td></tr>'}</table></div>
    <p><a class='button' href='/admin/pulse-users-health'>PulseSoc Users Health</a></p>
    """
    return admin_page_html("PulseSoc Users", body, admin)


@webhook_app.route("/admin/pulse-users-health", methods=["GET"])
def admin_pulse_users_health_page():
    admin, denied = require_owner_admin_page()
    if denied:
        return denied
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    tables = [
        "users", "arena_profiles", "user_privilege_profiles", "pulse_badges", "pulse_user_badges",
        "pulse_privileges", "pulse_user_privileges", "livestream_access", "admin_audit_logs",
    ]
    rows = []
    for table in tables:
        exists = migration_table_exists(cur, table)
        columns = sorted(migration_table_columns(cur, table)) if exists else []
        rows.append(
            f"<tr><td>{clean_html(table)}</td><td>{'Yes' if exists else 'No'}</td><td>{clean_html(', '.join(columns[:18]) or 'No columns found')}</td></tr>"
        )
    user_count = "0"
    latest_actions = []
    latest_error = ""
    try:
        cur.execute("SELECT COUNT(*) AS total FROM users")
        user_count = str(int(dict(cur.fetchone() or {}).get("total") or 0))
    except Exception as exc:
        latest_error = str(exc)
    try:
        cur.execute(
            """
            SELECT action, target_type, target_id, metadata, created_at
            FROM admin_audit_logs
            WHERE action LIKE 'pulse_user_%' OR action LIKE 'premium_%' OR target_type LIKE 'pulse%'
            ORDER BY id DESC
            LIMIT 8
            """
        )
        latest_actions = [dict(row) for row in cur.fetchall()]
    except Exception as exc:
        latest_error = latest_error or str(exc)
    action_rows = "".join(
        f"<tr><td>{clean_html(a.get('created_at') or '')}</td><td>{clean_html(a.get('action') or '')}</td><td>{clean_html(a.get('target_type') or '')}</td><td>{clean_html(a.get('target_id') or '')}</td></tr>"
        for a in latest_actions
    )
    premium_columns = sorted(migration_table_columns(cur, "users")) if migration_table_exists(cur, "users") else []
    required_premium_columns = {"premium_status", "premium_expires_at", "lifetime_premium", "premium_glow_manual_grant", "premium_mark_override", "premium_mark_type"}
    conn.close()
    body = f"""
    <h1>PulseSoc Users Health</h1>
    <p class='muted'>Owner-only diagnostics for PulseSoc user control, badges, privileges, and premium identity.</p>
    <section class='grid'>
      <article class='card'><h2>Users</h2><p class='metric'>{clean_html(user_count)}</p><p class='muted'>Total user rows visible to the app.</p></article>
      <article class='card'><h2>Premium Mark Fields</h2><p>{'Available' if required_premium_columns <= set(premium_columns) else 'Needs migration'}</p><p class='muted'>Required fields: {clean_html(', '.join(sorted(required_premium_columns)))}</p></article>
      <article class='card'><h2>Latest Query Error</h2><p class='muted'>{clean_html(latest_error or 'None in this local health check.')}</p></article>
    </section>
    <section class='card'><h2>Table Diagnostics</h2><table><tr><th>Table</th><th>Exists</th><th>Columns</th></tr>{''.join(rows)}</table></section>
    <section class='card'><h2>Latest PulseSoc User Actions</h2><table><tr><th>Time</th><th>Action</th><th>Target Type</th><th>Target</th></tr>{action_rows or '<tr><td colspan=4>No recent PulseSoc user actions.</td></tr>'}</table></section>
    <p><a class='button primary' href='/admin/pulse-users'>Back to PulseSoc Users</a></p>
    """
    return admin_page_html("PulseSoc Users Health", body, admin)


@webhook_app.route("/admin/pulse-users/<int:user_id>", methods=["GET", "POST"])
def admin_pulse_user_detail_page(user_id):
    admin, denied = require_owner_admin_page()
    if denied:
        return denied
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    message = ""
    before = pulse_admin_user_row(cur, user_id) or {}
    if request.method == "POST":
        action = request.form.get("action") or "save"
        if action == "grant_all":
            pulse_admin_grant_all(conn, user_id, admin.get("id"))
            message = "All PulseSoc privileges and badges granted."
        elif action == "remove_all":
            pulse_admin_remove_all(conn, user_id, admin.get("id"))
            message = "All PulseSoc privileges and badges removed."
        elif action in {"grant_premium_glow", "remove_premium_glow", "premium_glow_star", "premium_glow_check", "grant_lifetime_premium", "revoke_lifetime_premium"}:
            now = datetime.utcnow().isoformat(timespec="seconds")
            if action == "grant_lifetime_premium":
                cur.execute("UPDATE users SET lifetime_premium=1, premium_status='lifetime', premium_mark_type=COALESCE(NULLIF(premium_mark_type,''),'star'), updated_at=? WHERE user_id=?", (now, user_id))
                message = "Lifetime Premium granted."
            elif action == "revoke_lifetime_premium":
                cur.execute("UPDATE users SET lifetime_premium=0, premium_status=CASE WHEN lower(COALESCE(subscription_status,'')) IN ('active','trialing') THEN subscription_status ELSE 'inactive' END, updated_at=? WHERE user_id=?", (now, user_id))
                message = "Lifetime Premium revoked."
            elif action in {"grant_premium_glow", "premium_glow_star"}:
                cur.execute("UPDATE users SET premium_glow_manual_grant=1, premium_mark_override=1, premium_mark_type='star', updated_at=? WHERE user_id=?", (now, user_id))
                message = "Premium Glow Star granted."
            elif action == "premium_glow_check":
                cur.execute("UPDATE users SET premium_glow_manual_grant=1, premium_mark_override=1, premium_mark_type='check', updated_at=? WHERE user_id=?", (now, user_id))
                message = "Premium Glow Check granted."
            else:
                cur.execute("UPDATE users SET premium_glow_manual_grant=0, premium_mark_override=0, updated_at=? WHERE user_id=?", (now, user_id))
                message = "Premium Glow removed."
            conn.commit()
        elif action in {"grant_all_badges", "remove_all_badges", "grant_all_privileges", "remove_all_privileges"}:
            now = datetime.utcnow().isoformat(timespec="seconds")
            if action == "grant_all_badges":
                for row in cur.execute("SELECT badge_key FROM pulse_badges WHERE COALESCE(active,1)=1").fetchall():
                    cur.execute("INSERT OR IGNORE INTO pulse_user_badges (user_id, badge_key, granted_by, created_at) VALUES (?, ?, ?, ?)", (user_id, row[0], admin.get("id"), now))
            elif action == "remove_all_badges":
                cur.execute("DELETE FROM pulse_user_badges WHERE user_id=?", (user_id,))
            elif action == "grant_all_privileges":
                for row in cur.execute("SELECT privilege_key FROM pulse_privileges WHERE COALESCE(active,1)=1").fetchall():
                    cur.execute("INSERT INTO pulse_user_privileges (user_id, privilege_key, enabled, granted_by, created_at, updated_at) VALUES (?, ?, 1, ?, ?, ?) ON CONFLICT(user_id, privilege_key) DO UPDATE SET enabled=1, granted_by=excluded.granted_by, updated_at=excluded.updated_at", (user_id, row[0], admin.get("id"), now, now))
            else:
                cur.execute("UPDATE pulse_user_privileges SET enabled=0, granted_by=?, updated_at=? WHERE user_id=?", (admin.get("id"), now, user_id))
            conn.commit()
            message = action.replace("_", " ").title() + " complete."
        elif action in {"verify", "make_creator", "make_teacher", "make_seller", "unlock_livestream", "suspend_pulse", "restore_pulse", "reset_trust", "trust_100"}:
            now = datetime.utcnow().isoformat(timespec="seconds")
            if action == "verify":
                cur.execute("INSERT INTO verification_requests (user_id, verification_type, status, notes, reviewed_by, created_at, reviewed_at) VALUES (?, 'identity_verified', 'approved', 'Manual verification', ?, ?, ?)", (user_id, admin.get("id"), now, now))
                cur.execute("INSERT OR IGNORE INTO pulse_user_badges (user_id, badge_key, granted_by, created_at) VALUES (?, 'verified', ?, ?)", (user_id, admin.get("id"), now))
            elif action == "make_creator":
                cur.execute("INSERT OR IGNORE INTO pulse_user_badges (user_id, badge_key, granted_by, created_at) VALUES (?, 'creator', ?, ?)", (user_id, admin.get("id"), now))
                cur.execute("INSERT INTO pulse_user_privileges (user_id, privilege_key, enabled, granted_by, created_at, updated_at) VALUES (?, 'can_use_creator_filters', 1, ?, ?, ?) ON CONFLICT(user_id, privilege_key) DO UPDATE SET enabled=1, updated_at=excluded.updated_at", (user_id, admin.get("id"), now, now))
            elif action == "make_teacher":
                cur.execute("INSERT OR IGNORE INTO pulse_user_badges (user_id, badge_key, granted_by, created_at) VALUES (?, 'teacher', ?, ?)", (user_id, admin.get("id"), now))
                cur.execute("INSERT INTO pulse_user_privileges (user_id, privilege_key, enabled, granted_by, created_at, updated_at) VALUES (?, 'can_teach', 1, ?, ?, ?) ON CONFLICT(user_id, privilege_key) DO UPDATE SET enabled=1, updated_at=excluded.updated_at", (user_id, admin.get("id"), now, now))
            elif action == "make_seller":
                cur.execute("INSERT OR IGNORE INTO pulse_user_badges (user_id, badge_key, granted_by, created_at) VALUES (?, 'marketplace_seller', ?, ?)", (user_id, admin.get("id"), now))
                cur.execute("INSERT INTO pulse_user_privileges (user_id, privilege_key, enabled, granted_by, created_at, updated_at) VALUES (?, 'can_sell_marketplace', 1, ?, ?, ?) ON CONFLICT(user_id, privilege_key) DO UPDATE SET enabled=1, updated_at=excluded.updated_at", (user_id, admin.get("id"), now, now))
            elif action == "unlock_livestream":
                cur.execute("INSERT INTO livestream_access (user_id, status, referral_count, approved_by, suspended_reason, created_at, updated_at) VALUES (?, 'approved', 30, ?, '', ?, ?) ON CONFLICT(user_id) DO UPDATE SET status='approved', referral_count=30, suspended_reason='', updated_at=excluded.updated_at", (user_id, admin.get("id"), now, now))
            elif action == "suspend_pulse":
                cur.execute("UPDATE user_privilege_profiles SET posting_restricted=1, messaging_restricted=1, moderation_status='suspended', updated_at=? WHERE user_id=?", (now, user_id))
            elif action == "restore_pulse":
                cur.execute("UPDATE user_privilege_profiles SET posting_restricted=0, messaging_restricted=0, moderation_status='clear', updated_at=? WHERE user_id=?", (now, user_id))
            elif action == "reset_trust":
                cur.execute("UPDATE user_privilege_profiles SET trust_score=0, current_level='New User', updated_at=? WHERE user_id=?", (now, user_id))
            elif action == "trust_100":
                cur.execute("UPDATE user_privilege_profiles SET trust_score=100, current_level='Platform Ambassador', updated_at=? WHERE user_id=?", (now, user_id))
            conn.commit()
            message = action.replace("_", " ").title() + " complete."
        elif action in {"remove_avatar", "remove_cover"}:
            now = datetime.utcnow().isoformat(timespec="seconds")
            if action == "remove_avatar":
                cur.execute("UPDATE users SET avatar_url=NULL, avatar_thumbnail_url=NULL, avatar_filter=NULL, updated_at=? WHERE user_id=?", (now, user_id))
                message = "Avatar removed."
            else:
                cur.execute("UPDATE users SET cover_url=NULL, banner_url=NULL, cover_filter=NULL, updated_at=? WHERE user_id=?", (now, user_id))
                message = "Cover removed."
            conn.commit()
        else:
            now = datetime.utcnow().isoformat(timespec="seconds")
            display_name = clean_html(request.form.get("display_name") or "")[:120]
            username = clean_html(request.form.get("username") or "")[:80]
            avatar_url = clean_html(request.form.get("avatar_url") or "")[:600]
            cover_url = clean_html(request.form.get("cover_url") or "")[:600]
            bio = clean_html(request.form.get("bio") or "")[:1000]
            trust_score = max(0, min(100, int(request.form.get("trust_score") or 0)))
            level = clean_html(request.form.get("current_level") or "New User")[:80]
            live_status = clean_html(request.form.get("livestream_status") or "locked")[:40]
            cur.execute("UPDATE users SET display_name=?, username=?, avatar_url=?, cover_url=?, banner_url=?, bio=?, updated_at=? WHERE user_id=?", (display_name, username, avatar_url, cover_url, cover_url, bio, now, user_id))
            cur.execute(
                "INSERT INTO user_privilege_profiles (user_id, trust_score, current_level, created_at, updated_at, manual_override, updated_by) VALUES (?, ?, ?, ?, ?, 1, ?) ON CONFLICT(user_id) DO UPDATE SET trust_score=excluded.trust_score, current_level=excluded.current_level, updated_at=excluded.updated_at, manual_override=1, updated_by=excluded.updated_by",
                (user_id, trust_score, level, now, now, admin.get("id")),
            )
            cur.execute("INSERT INTO livestream_access (user_id, status, referral_count, approved_by, suspended_reason, created_at, updated_at) VALUES (?, ?, 0, ?, '', ?, ?) ON CONFLICT(user_id) DO UPDATE SET status=excluded.status, updated_at=excluded.updated_at", (user_id, live_status, admin.get("id"), now, now))
            conn.commit()
            message = "PulseSoc user profile saved."
        after = pulse_admin_user_row(cur, user_id) or {}
        log_admin_audit(admin.get("id"), f"pulse_user_{action}", "user", str(user_id), {"before": before, "after": after})
    row = pulse_admin_user_row(cur, user_id)
    if not row:
        conn.close()
        return admin_page_html("PulseSoc User Not Found", "<h1>User not found</h1><p class='muted'>No matching user exists.</p>", admin), 404
    badges = pulse_admin_all_badges(cur)
    privileges = pulse_admin_all_privileges(cur)
    user_badges = pulse_admin_user_badges(cur, user_id)
    user_privileges = pulse_admin_user_privileges(cur, user_id)
    cur.execute("SELECT action, metadata, created_at FROM admin_audit_logs WHERE target_type='user' AND target_id=? ORDER BY id DESC LIMIT 30", (str(user_id),))
    audit = [dict(r) for r in cur.fetchall()]
    conn.close()
    badge_grid = "".join(f"<span class='pill'>{'✓ ' if b['badge_key'] in user_badges else ''}{clean_html(b['label'])}</span>" for b in badges)
    privilege_grid = "".join(f"<span class='pill'>{'✓ ' if p['privilege_key'] in user_privileges else ''}{clean_html(p['label'])}</span>" for p in privileges)
    quick_actions = "".join(f"<button name='action' value='{key}'>{label}</button>" for key, label in [
        ("grant_all", "Grant All Privileges"), ("remove_all", "Remove All Privileges"), ("grant_all_badges", "Grant All Badges"),
        ("remove_all_badges", "Remove All Badges"), ("grant_all_privileges", "Grant All Privileges Only"),
        ("remove_all_privileges", "Remove All Privileges Only"), ("verify", "Verify User"), ("make_creator", "Make Creator"),
        ("make_teacher", "Make Teacher"), ("make_seller", "Make Seller"), ("unlock_livestream", "Unlock Livestream"),
        ("grant_lifetime_premium", "Grant Lifetime Premium"), ("revoke_lifetime_premium", "Revoke Lifetime Premium"),
        ("grant_premium_glow", "Grant Premium Glow"), ("remove_premium_glow", "Remove Premium Glow"),
        ("premium_glow_star", "Choose Star"), ("premium_glow_check", "Choose Check"),
        ("suspend_pulse", "Suspend PulseSoc Access"), ("restore_pulse", "Restore PulseSoc Access"), ("reset_trust", "Reset Trust Score"),
        ("trust_100", "Set Trust Score to 100"),
    ])
    audit_rows = "".join(f"<tr><td>{clean_html(a.get('action') or '')}</td><td>{clean_html(a.get('created_at') or '')}</td><td><pre>{clean_html(a.get('metadata') or '')}</pre></td></tr>" for a in audit)
    avatar_preview = f"<img src='{clean_html(row.get('avatar_url') or '')}' style='width:96px;height:96px;border-radius:24px;object-fit:cover'>" if row.get("avatar_url") else "<span class='pill'>No avatar</span>"
    cover_preview = f"<img src='{clean_html(row.get('cover_url') or row.get('banner_url') or '')}' style='width:100%;max-height:160px;border-radius:18px;object-fit:cover'>" if (row.get("cover_url") or row.get("banner_url")) else "<span class='pill'>No cover</span>"
    body = f"""
    <h1>PulseSoc User Control: {clean_html(row.get('display_name') or row.get('email') or str(user_id))}</h1>
    <p class='muted'>{clean_html(message)}</p>
    <div class='grid'>
      <section class='card'><h2>Status</h2><p><span class='pill'>Trust {int(row.get('trust_score') or 0)}</span> <span class='pill'>{clean_html(row.get('current_level') or 'New User')}</span> <span class='pill'>Live {clean_html(row.get('livestream_status') or 'locked')}</span> <span class='pill'>Premium {clean_html(row.get('premium_status') or 'inactive')}</span> <span class='pill'>Glow {'on' if row.get('premium_glow_manual_grant') else 'off'} · {clean_html(row.get('premium_mark_type') or 'star')}</span></p><p><a class='button' href='/pulse/profile'>View User Profile</a> <a class='button' href='/pulse?profile={user_id}'>View User Posts</a> <a class='button' href='/pulse/messages'>View User Messages</a> <a class='button' href='/admin/audit-logs'>View Audit Log</a></p></section>
      <section class='card'><h2>Badges</h2>{badge_grid}</section>
      <section class='card'><h2>Privileges</h2>{privilege_grid}</section>
    </div>
    <form class='card' method='post'><h2>Profile Media Review</h2><div class='grid'><div><h3>Avatar</h3>{avatar_preview}<button name='action' value='remove_avatar'>Remove Avatar</button></div><div><h3>Cover</h3>{cover_preview}<button name='action' value='remove_cover'>Remove Cover</button></div></div></form>
    <form class='card' method='post'><h2>Edit Profile And Limits</h2>
      <input name='display_name' value='{clean_html(row.get('display_name') or '')}' placeholder='Display name'>
      <input name='username' value='{clean_html(row.get('username') or '')}' placeholder='Username'>
      <input name='avatar_url' value='{clean_html(row.get('avatar_url') or '')}' placeholder='Avatar URL'>
      <input name='cover_url' value='{clean_html(row.get('cover_url') or row.get('banner_url') or '')}' placeholder='Cover URL'>
      <textarea name='bio' placeholder='Bio'>{clean_html(row.get('bio') or '')}</textarea>
      <input name='trust_score' value='{int(row.get('trust_score') or 0)}' placeholder='Trust score'>
      <input name='current_level' value='{clean_html(row.get('current_level') or 'New User')}' placeholder='Level'>
      <select name='livestream_status'><option>{clean_html(row.get('livestream_status') or 'locked')}</option><option>locked</option><option>progress</option><option>eligible</option><option>approved</option><option>suspended</option></select>
      <button class='button primary' name='action' value='save'>Save Manual Changes</button>
    </form>
    <form class='card' method='post'><h2>Owner Quick Actions</h2><div class='actions'>{quick_actions}</div></form>
    <section class='card'><h2>Audit History</h2><table><tr><th>Action</th><th>Time</th><th>Metadata</th></tr>{audit_rows or '<tr><td colspan=3>No audit entries yet.</td></tr>'}</table></section>
    """
    return admin_page_html("PulseSoc User Control", body, admin)


@webhook_app.route("/admin/monetization", methods=["GET"])
def admin_monetization_page():
    admin, denied = require_admin_page("monetization.manage")
    if denied:
        return denied
    init_db()
    try:
        conn = db()
        conn.row_factory = sqlite3.Row
        summary = monetization_engine.admin_summary(conn)
        try:
            candidates = creator_monetization_engine.creator_candidates(12)
        except Exception as exc:
            logging.exception("ADMIN_MONETIZATION_CREATOR_CANDIDATES_FAILED error=%s", exc)
            candidates = []
        slot = ad_policy_engine.contextual_slot("pulse")
        cur = conn.cursor()
        safe_counts = {}
        for key, query in {
            "revenue_events": "SELECT COUNT(*) AS total FROM monetization_events",
            "premium_users": "SELECT COUNT(*) AS total FROM users WHERE premium_status IN ('active','trialing') OR COALESCE(lifetime_premium,0)=1",
            "trial_users": "SELECT COUNT(*) AS total FROM subscriptions WHERE status='trialing'",
            "upgrade_clicks": "SELECT COUNT(*) AS total FROM monetization_events WHERE event_type='upgrade_click'",
            "sponsor_slots": "SELECT COUNT(*) AS total FROM sponsor_slots",
            "ad_reviews": "SELECT COUNT(*) AS total FROM ad_reviews WHERE status='pending'",
            "marketplace_listings": "SELECT COUNT(*) AS total FROM marketplace_listings",
            "teacher_courses": "SELECT COUNT(*) AS total FROM pulse_courses",
            "enterprise_leads": "SELECT COUNT(*) AS total FROM enterprise_leads",
            "creator_payouts": "SELECT COUNT(*) AS total FROM creator_payouts_placeholder",
            "marketplace_orders": "SELECT COUNT(*) AS total FROM marketplace_orders_placeholder",
            "teacher_earnings": "SELECT COUNT(*) AS total FROM teacher_earnings_placeholder",
        }.items():
            try:
                cur.execute(query)
                safe_counts[key] = int(dict(cur.fetchone() or {}).get("total") or 0)
            except Exception:
                safe_counts[key] = 0
        conn.close()
        layer_parts = []
        for layer in summary.get("revenue_layers", []):
            layer_items = "".join("<li>{}</li>".format(clean_html(i)) for i in layer.get("items", []))
            layer_parts.append(f"<article class='card'><h2>{clean_html(layer.get('layer') or '')}</h2><ul>{layer_items}</ul></article>")
        layers = "".join(layer_parts)
        creator_rows = "".join(f"<tr><td>{c.get('user_id')}</td><td>{clean_html(c.get('display_name') or '')}</td><td>{int(c.get('posts') or 0)}</td><td>{clean_html(c.get('verification_status') or '')}</td></tr>" for c in candidates)
        all_counts = {**{k: v for k, v in summary.items() if isinstance(v, int)}, **safe_counts}
        cards = "".join(f"<div class='card'><h2>{clean_html(k.replace('_',' ').title())}</h2><p style='font-size:32px;font-weight:900'>{v}</p></div>" for k, v in all_counts.items())
        config = {
            "stripe": "Configured" if STRIPE_SECRET_KEY else "Not configured yet",
            "google_ads": "Configured" if os.getenv("GOOGLE_ADS_CONVERSION_ID") or os.getenv("GOOGLE_ADS_ID") else "Not configured yet",
            "marketplace": "Payment release locked until compliance review",
            "teacher_earnings": "Earnings release locked until compliance review",
        }
        body = f"<h1>Monetization Control</h1><p class='muted'>Trust-first monetization: Premium, creator tools, courses, marketplace products, sponsorship controls, and enterprise leads. Empty providers show setup states instead of crashing.</p><p><a class='button' href='/admin/monetization-health'>Open Monetization Health</a> <a class='button' href='/admin/payments-health'>Payments Health</a> <a class='button' href='/admin/sponsorships'>Sponsorships</a></p><div class='grid'>{cards}</div><section class='grid'>{layers}</section><div class='card'><h2>Provider Setup</h2><pre>{clean_html(json.dumps(config, indent=2))}</pre></div><div class='card'><h2>Safe Sponsor Slot</h2><pre>{clean_html(json.dumps(slot, indent=2))}</pre></div><div class='card'><h2>Creator Candidates</h2><table><tr><th>User</th><th>Public Name</th><th>Posts</th><th>Status</th></tr>{creator_rows or '<tr><td colspan=4>No candidates yet.</td></tr>'}</table></div>"
    except Exception as exc:
        logging.exception("ADMIN_MONETIZATION_PAGE_FAILED error=%s", exc)
        body = f"<h1>Monetization Control</h1><div class='card'><h2>Monetization diagnostics needed</h2><p class='muted'>The page recovered safely instead of showing a raw error.</p><p>{clean_html(str(exc))}</p><a class='button' href='/admin/monetization-health'>Open Monetization Health</a></div>"
    return admin_page_html("Monetization", body, admin)


@webhook_app.route("/admin/monetization-health", methods=["GET"])
def admin_monetization_health_page():
    admin, denied = require_admin_page("monetization.manage")
    if denied:
        return denied
    init_db()
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    tables = ["monetization_events", "sponsor_slots", "ad_reviews", "enterprise_leads", "creator_payouts_placeholder", "marketplace_orders_placeholder", "teacher_earnings_placeholder", "creator_profiles", "creator_revenue_events"]
    table_rows = []
    for table in tables:
        try:
            if db_service.IS_POSTGRES:
                cur.execute("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name=%s", (table,))
                exists = bool(cur.fetchone())
            else:
                cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table,))
                exists = bool(cur.fetchone())
            count = 0
            if exists:
                cur.execute(f"SELECT COUNT(*) AS total FROM {table}")
                count = int(dict(cur.fetchone() or {}).get("total") or 0)
            table_rows.append({"table": table, "exists": exists, "rows": count})
        except Exception as exc:
            table_rows.append({"table": table, "exists": False, "rows": 0, "error": str(exc)})
    diagnostics = {
        "stripe_key_configured": bool(STRIPE_SECRET_KEY),
        "stripe_webhook_configured": bool(STRIPE_WEBHOOK_SECRET),
        "stripe_price_ids_configured": bool(os.getenv("STRIPE_PRO_PRICE_ID") or os.getenv("STRIPE_PRICE_ID")),
        "google_ads_configured": bool(os.getenv("GOOGLE_ADS_CONVERSION_ID") or os.getenv("GOOGLE_ADS_ID")),
        "tables": table_rows,
    }
    conn.close()
    body = f"<h1>Monetization Health</h1><p class='muted'>No secrets are shown here. Missing providers display setup states instead of crashing admin.</p><div class='card'><pre>{clean_html(json.dumps(diagnostics, indent=2, default=str))}</pre></div>"
    return admin_page_html("Monetization Health", body, admin)


@webhook_app.route("/admin/payments-health", methods=["GET"])
@webhook_app.route("/admin/stripe-health", methods=["GET"])
def admin_payments_health_page():
    admin, denied = require_admin_page("monetization.manage")
    if denied:
        return denied
    init_db()
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    counts = {}
    for key, sql in {
        "subscriptions": "SELECT COUNT(*) AS total FROM subscriptions",
        "active_subscriptions": "SELECT COUNT(*) AS total FROM subscriptions WHERE status IN ('active','trialing')",
        "payment_records": "SELECT COUNT(*) AS total FROM payment_records",
        "checkout_attempts": "SELECT COUNT(*) AS total FROM checkout_attempts",
    }.items():
        try:
            cur.execute(sql)
            counts[key] = int(dict(cur.fetchone() or {}).get("total") or 0)
        except Exception:
            counts[key] = 0
    conn.close()
    diagnostics = {
        "stripe_key_configured": bool(STRIPE_SECRET_KEY),
        "stripe_webhook_configured": bool(STRIPE_WEBHOOK_SECRET),
        "pro_price_configured": bool(os.getenv("STRIPE_PRO_PRICE_ID") or os.getenv("STRIPE_PRICE_ID")),
        "publishable_key_configured": bool(STRIPE_PUBLISHABLE_KEY),
        "status": "ready" if STRIPE_SECRET_KEY and STRIPE_WEBHOOK_SECRET else "setup_required",
        "counts": counts,
    }
    body = f"<h1>Payments Health</h1><p class='muted'>No secrets are exposed. Missing Stripe setup shows as setup required, never a crash.</p><section class='card'><pre>{clean_html(json.dumps(diagnostics, indent=2, default=str))}</pre></section>"
    return admin_page_html("Payments Health", body, admin)


@webhook_app.route("/admin/payments", methods=["GET", "POST"])
def admin_payments_page():
    admin, denied = require_admin_page("monetization.manage")
    if denied:
        return denied
    init_db()
    creator_summary = creator_economy_service.payment_summary()
    provider = payment_provider.provider_status()
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    counts = {}
    for key, sql in {
        "total_volume_cents": "SELECT COALESCE(SUM(amount_cents),0) AS total FROM seller_transactions WHERE status IN ('paid','checkout_completed','succeeded')",
        "fees_cents": "SELECT COALESCE(SUM(platform_fee_cents),0) AS total FROM seller_transactions WHERE status IN ('paid','checkout_completed','succeeded')",
        "merchant_transactions": "SELECT COUNT(*) AS total FROM seller_transactions WHERE seller_type='merchant'",
        "teacher_transactions": "SELECT COUNT(*) AS total FROM seller_transactions WHERE seller_type='teacher'",
        "failed_payments": "SELECT COUNT(*) AS total FROM seller_transactions WHERE status LIKE '%failed%' OR status LIKE 'blocked%'",
        "accounts_missing_onboarding": "SELECT COUNT(*) AS total FROM seller_payout_accounts WHERE COALESCE(payouts_enabled,0)=0 OR onboarding_status!='complete'",
    }.items():
        try:
            cur.execute(sql)
            counts[key] = int(dict(cur.fetchone() or {}).get("total") or 0)
        except Exception:
            counts[key] = 0
    cur.execute("SELECT t.*, COALESCE(b.display_name,b.username,'Buyer') AS buyer_name, COALESCE(s.display_name,s.username,'Seller') AS seller_name FROM seller_transactions t LEFT JOIN users b ON b.user_id=t.buyer_user_id LEFT JOIN users s ON s.user_id=t.seller_user_id ORDER BY t.id DESC LIMIT 100")
    transactions = [dict(row) for row in cur.fetchall()]
    cur.execute("SELECT * FROM seller_payout_accounts ORDER BY updated_at DESC, id DESC LIMIT 80")
    accounts = [dict(row) for row in cur.fetchall()]
    conn.close()
    cards = "".join(
        f"<div class='card'><h2>{clean_html(k.replace('_',' ').title())}</h2><p class='metric'>{(f'${v/100:.2f}' if k.endswith('_cents') else v)}</p></div>"
        for k, v in counts.items()
    )
    tx_rows = "".join(f"<tr><td>{t.get('id')}</td><td>{clean_html(t.get('buyer_name') or '')}</td><td>{clean_html(t.get('seller_name') or '')}</td><td>{clean_html(t.get('seller_type') or '')}</td><td>{clean_html(t.get('item_type') or '')} #{int(t.get('item_id') or 0)}</td><td>{(int(t.get('amount_cents') or 0)/100):.2f} {clean_html(t.get('currency') or 'USD')}</td><td>{(int(t.get('platform_fee_cents') or 0)/100):.2f}</td><td>{clean_html(t.get('status') or '')}</td></tr>" for t in transactions)
    acct_rows = "".join(f"<tr><td>{a.get('id')}</td><td>{int(a.get('user_id') or 0)}</td><td>{clean_html(a.get('seller_type') or '')}</td><td>{clean_html(a.get('onboarding_status') or '')}</td><td>{'yes' if a.get('charges_enabled') else 'no'}</td><td>{'yes' if a.get('payouts_enabled') else 'no'}</td><td>{clean_html(a.get('connected_account_id') or '')}</td></tr>" for a in accounts)
    core = creator_summary.get("summary") or {}
    core_cards = "".join(
        f"<div class='card'><h2>{clean_html(k.replace('_',' ').title())}</h2><p class='metric'>{(f'${int(v or 0)/100:.2f}' if k.endswith('_cents') else int(v or 0))}</p></div>"
        for k, v in core.items()
    )
    ledger_rows = "".join(f"<tr><td>{t.get('id')}</td><td>{clean_html(t.get('item_type') or '')}</td><td>{int(t.get('buyer_user_id') or 0)}</td><td>{int(t.get('seller_user_id') or 0)}</td><td>${int(t.get('gross_amount_cents') or 0)/100:.2f}</td><td>${int(t.get('platform_fee_cents') or 0)/100:.2f}</td><td>{clean_html(t.get('status') or '')}</td><td>{clean_html(t.get('trace_id') or '')}</td></tr>" for t in (creator_summary.get("transactions") or []))
    wallet_rows = "".join(f"<tr><td>{w.get('id')}</td><td>{int(w.get('user_id') or 0)}</td><td>{clean_html(w.get('wallet_type') or '')}</td><td>${int(w.get('pending_balance_cents') or 0)/100:.2f}</td><td>${int(w.get('available_balance_cents') or 0)/100:.2f}</td><td>${int(w.get('lifetime_fees_cents') or 0)/100:.2f}</td><td>{clean_html(w.get('status') or '')}</td></tr>" for w in (creator_summary.get("wallets") or []))
    body = f"""
    <h1>Payments Command Center</h1><p class='muted'>Stripe Connect-style marketplace payments backed by internal wallets, append-only ledger entries, webhook idempotency, entitlements, and audit logs.</p>
    <section class='card'><h2>Treasury Modules</h2><p class='muted'>Platform fee revenue now flows into the CoinPilotXAI treasury ledger and settlement system.</p><div class='actions'><a class='button primary' href='/admin/treasury'>Treasury</a><a class='button' href='/admin/platform-revenue'>Platform Revenue</a><a class='button' href='/admin/creator-payouts'>Creator Payouts</a><a class='button' href='/admin/fee-ledger'>Fee Ledger</a><a class='button' href='/admin/escrow'>Escrow</a><a class='button' href='/admin/settlements'>Settlement Engine</a><a class='button' href='/admin/stripe-connect'>Stripe Connect</a><a class='button' href='/admin/tax-center'>Tax Center</a><a class='button' href='/admin/revenue-analytics'>Revenue Analytics</a><a class='button' href='/admin/financial-audit'>Financial Audit</a><a class='button' href='/admin/refunds'>Refund Center</a><a class='button' href='/admin/disputes'>Dispute Resolution</a></div></section>
    <section class='card'><h2>Provider Status</h2><pre>{clean_html(json.dumps(provider, indent=2, default=str))}</pre></section>
    <section class='grid'>{core_cards}</section>
    <section class='card'><h2>Creator Economy Ledger Transactions</h2><table class='table'><tr><th>ID</th><th>Item</th><th>Buyer</th><th>Seller</th><th>Gross</th><th>Fee</th><th>Status</th><th>Trace</th></tr>{ledger_rows or '<tr><td colspan=8>No creator economy transactions yet.</td></tr>'}</table></section>
    <section class='card'><h2>Wallet Balances</h2><table class='table'><tr><th>ID</th><th>User</th><th>Wallet</th><th>Pending</th><th>Available</th><th>Fees</th><th>Status</th></tr>{wallet_rows or '<tr><td colspan=7>No wallets yet.</td></tr>'}</table></section>
    <h2>Legacy Seller Transaction Compatibility</h2>
    <section class='grid'>{cards}</section>
    <section class='card'><h2>Seller Transactions</h2><table class='table'><tr><th>ID</th><th>Buyer</th><th>Seller</th><th>Type</th><th>Item</th><th>Gross</th><th>Fee</th><th>Status</th></tr>{tx_rows or '<tr><td colspan=8>No seller transactions yet.</td></tr>'}</table></section>
    <section class='card'><h2>Payout Accounts</h2><table class='table'><tr><th>ID</th><th>User</th><th>Seller Type</th><th>Onboarding</th><th>Charges</th><th>Payouts</th><th>Stripe Account</th></tr>{acct_rows or '<tr><td colspan=7>No payout accounts yet.</td></tr>'}</table></section>
    """
    return admin_page_html("Payments", body, admin)


@webhook_app.route("/admin/payments-command-center", methods=["GET"])
def admin_payments_command_center_page():
    admin, denied = require_admin_page("monetization.manage")
    if denied:
        return denied
    init_db()
    data = platform_treasury_service.treasury_summary()
    provider = payment_provider.provider_status()
    summary = data.get("summary") or {}

    def dollars(value):
        return f"${int(value or 0) / 100:,.2f}"

    wallets = data.get("wallets") or []
    treasury_transactions = data.get("treasury_transactions") or []
    fee_ledger = data.get("fee_ledger") or []
    payout_queue = data.get("payout_queue") or []
    escrow_holds = data.get("escrow_holds") or []
    creator_balances = data.get("creator_balances") or []
    treasury_balance_cents = sum(int(w.get("available_balance_cents") or 0) + int(w.get("pending_balance_cents") or 0) for w in wallets)
    refund_exposure_cents = sum(int(w.get("lifetime_refunds_cents") or 0) for w in wallets)
    escrow_held_cents = sum(int(e.get("amount_cents") or 0) for e in escrow_holds if str(e.get("status") or "").lower() in {"held", "pending", "active"})
    active_stripe_accounts = 0
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) AS total FROM seller_payout_accounts WHERE COALESCE(charges_enabled,0)=1 OR COALESCE(payouts_enabled,0)=1")
        active_stripe_accounts = int(dict(cur.fetchone() or {}).get("total") or 0)
    except Exception:
        active_stripe_accounts = 0
    conn.close()

    kpis = [
        ("Total Platform Revenue", dollars(summary.get("total_platform_revenue_cents")), "Platform fee revenue recorded in treasury."),
        ("Today Revenue", dollars(summary.get("today_revenue_cents")), "Current UTC-day fee intake."),
        ("Pending Payouts", dollars(summary.get("pending_payouts_cents")), "Seller funds queued or awaiting release."),
        ("Treasury Balance", dollars(treasury_balance_cents), "Available plus pending platform wallet balance."),
        ("Gross Creator Volume", dollars(summary.get("creator_sales_volume_cents")), "Total creator economy sales volume."),
        ("Premium Subscription Revenue", dollars(summary.get("premium_revenue_cents")), "Premium and subscription revenue."),
        ("Refund Exposure", dollars(refund_exposure_cents), "Refunded/reversal amount tracked by treasury."),
        ("Escrow Held", dollars(escrow_held_cents), "Funds currently held before settlement."),
        ("Active Stripe Accounts", active_stripe_accounts, "Connected payout accounts with activity enabled."),
        ("Failed Payouts", int(summary.get("failed_payouts") or 0), "Payout failures requiring operator review."),
    ]
    kpi_html = "".join(
        f"<article class='pay-kpi'><span>{clean_html(label)}</span><strong>{clean_html(str(value))}</strong><p>{clean_html(note)}</p></article>"
        for label, value, note in kpis
    )

    stream_items = []
    for tx in treasury_transactions[:8]:
        stream_items.append({
            "kind": "Treasury",
            "title": f"{tx.get('transaction_type') or 'transaction'} · {tx.get('seller_type') or 'seller'}",
            "amount": int(tx.get("platform_fee_cents") or tx.get("gross_amount_cents") or 0),
            "status": tx.get("status") or "recorded",
            "time": tx.get("created_at") or "",
            "trace": tx.get("trace_id") or "",
        })
    for payout in payout_queue[:5]:
        stream_items.append({
            "kind": "Payout",
            "title": f"{payout.get('seller_type') or 'creator'} payout queued",
            "amount": int(payout.get("amount_cents") or 0),
            "status": payout.get("status") or "queued",
            "time": payout.get("created_at") or payout.get("scheduled_for") or "",
            "trace": payout.get("trace_id") or "",
        })
    for fee in fee_ledger[:5]:
        stream_items.append({
            "kind": "Fee",
            "title": f"{fee.get('fee_type') or 'platform fee'} collected",
            "amount": int(fee.get("amount_cents") or 0),
            "status": fee.get("status") or "posted",
            "time": fee.get("created_at") or "",
            "trace": fee.get("trace_id") or "",
        })
    stream_items = sorted(stream_items, key=lambda item: item.get("time") or "", reverse=True)[:14]
    stream_html = "".join(
        f"<div class='finance-event'><span class='event-kind'>{clean_html(item['kind'])}</span><div><strong>{clean_html(item['title'])}</strong><p>{dollars(item['amount'])} · {clean_html(item['status'])} · {smart_time_html(item.get('time'))}</p></div><code>{clean_html(item.get('trace') or 'trace-ready')}</code></div>"
        for item in stream_items
    ) or "<p class='muted'>No financial movement yet. The command stream will populate as checkout, fee, payout, refund, and escrow events arrive.</p>"

    top_creators = sorted(creator_balances, key=lambda c: int(c.get("lifetime_net_cents") or 0), reverse=True)[:6]
    creator_rows = "".join(
        f"<tr><td>{int(c.get('user_id') or 0)}</td><td>{clean_html(c.get('seller_type') or '')}</td><td>{dollars(c.get('lifetime_gross_cents'))}</td><td>{dollars(c.get('lifetime_fees_cents'))}</td><td>{dollars(c.get('available_balance_cents'))}</td><td>{'Frozen' if c.get('frozen') else 'Clear'}</td></tr>"
        for c in top_creators
    )
    risk_notes = [
        ("Payout Risk Detection", "Clear" if not summary.get("failed_payouts") else "Review needed", f"{int(summary.get('failed_payouts') or 0)} failed payout signals."),
        ("Refund Activity", "Stable" if int(summary.get("refund_rate_bps") or 0) < 500 else "Elevated", f"{int(summary.get('refund_rate_bps') or 0) / 100:.2f}% refund rate."),
        ("Revenue Acceleration", "Learning", "Trend forecasting activates as daily revenue samples accumulate."),
        ("Creator Monetization Signals", "Active", f"{len(creator_balances)} creator balance records tracked."),
    ]
    insight_html = "".join(
        f"<article class='pay-insight'><span>{clean_html(label)}</span><strong>{clean_html(status)}</strong><p>{clean_html(note)}</p></article>"
        for label, status, note in risk_notes
    )
    quick_actions = [
        ("Open Treasury", "/admin/treasury"),
        ("Open Revenue Analytics", "/admin/revenue-analytics"),
        ("Open Fee Ledger", "/admin/fee-ledger"),
        ("Open Stripe Connect", "/admin/stripe-connect"),
        ("Open Escrow", "/admin/escrow"),
        ("Open Refund Center", "/admin/refunds"),
        ("Open Creator Payouts", "/admin/creator-payouts"),
        ("Open Disputes", "/admin/disputes"),
        ("Open Tax Center", "/admin/tax-center"),
    ]
    quick_html = "".join(f"<a class='button' href='{href}'>{clean_html(label)}</a>" for label, href in quick_actions)
    provider_status = provider.get("status") or ("ready" if provider.get("stripe_secret_configured") else "setup_required")
    body = f"""
    <style>
    .payments-hero{{position:relative;overflow:hidden;border:1px solid rgba(110,223,246,.22);border-radius:28px;padding:26px;background:radial-gradient(circle at 12% 0,rgba(54,229,143,.22),transparent 34%),radial-gradient(circle at 86% 12%,rgba(110,223,246,.18),transparent 30%),linear-gradient(135deg,rgba(8,16,32,.98),rgba(4,9,18,.98));box-shadow:0 26px 90px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.08)}}
    .payments-hero h1{{font-size:clamp(38px,6vw,76px);line-height:.96;margin:8px 0}}.payments-hero p{{max-width:900px}}
    .pay-pulse{{height:10px;border-radius:999px;background:linear-gradient(90deg,#36e58f,#6edff6,#ffd166,#9b5cff);box-shadow:0 0 36px rgba(110,223,246,.35);margin-top:18px;animation:payFlow 6s ease-in-out infinite}}
    .pay-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:16px 0}}.pay-kpi,.pay-insight{{border:1px solid rgba(110,223,246,.18);border-radius:20px;background:linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.025));padding:16px;box-shadow:0 18px 54px rgba(0,0,0,.24),inset 0 1px 0 rgba(255,255,255,.07)}}.pay-kpi span,.pay-insight span{{display:block;color:#9fb5c0;font-size:.84rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em}}.pay-kpi strong{{display:block;font-size:clamp(24px,4vw,36px);margin:8px 0;color:#f4fdff}}.pay-insight strong{{display:block;font-size:1.35rem;margin:8px 0;color:#b9fff0}}.pay-kpi p,.pay-insight p{{margin:0;color:#9fb5c0}}
    .treasury-flow{{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;align-items:stretch}}.flow-step{{position:relative;border:1px solid rgba(255,255,255,.12);border-radius:18px;background:rgba(255,255,255,.055);padding:13px;min-height:108px}}.flow-step:after{{content:'→';position:absolute;right:-12px;top:42%;color:#6edff6;font-weight:950}}.flow-step:last-child:after{{display:none}}.flow-step strong{{display:block;color:#f4fdff}}.flow-step span{{display:block;color:#9fb5c0;font-size:.9rem;margin-top:6px}}
    .finance-event{{display:grid;grid-template-columns:86px minmax(0,1fr) auto;gap:10px;align-items:center;border:1px solid rgba(255,255,255,.09);border-radius:16px;background:rgba(255,255,255,.045);padding:10px;margin:8px 0}}.event-kind{{display:inline-flex;justify-content:center;border-radius:999px;border:1px solid rgba(110,223,246,.24);padding:5px 8px;color:#b9f7ff;font-weight:900}}.finance-event p{{margin:3px 0 0}}.finance-event code{{color:#ffd166;white-space:nowrap}}
    @keyframes payFlow{{0%,100%{{filter:saturate(1);transform:translateY(0)}}50%{{filter:saturate(1.35);transform:translateY(-1px)}}}}
    @media(max-width:820px){{.treasury-flow{{grid-template-columns:1fr 1fr}}.flow-step:after{{display:none}}.finance-event{{grid-template-columns:1fr}}.finance-event code{{white-space:normal}}}}
    </style>
    <section class='payments-hero'><span class='pill'>Financial Operating Hub · {clean_html(str(provider_status))}</span><h1>Payments Command Center</h1><p class='muted'>Monitor platform revenue, creator payouts, treasury health, subscriptions, and creator economy flow in realtime.</p><div class='pay-pulse'></div></section>
    <section class='pay-grid'>{kpi_html}</section>
    <section class='card'><h2>Creator Economy Flow</h2><div class='treasury-flow'><div class='flow-step'><strong>Customer payment</strong><span>Stripe checkout confirms trusted payment.</span></div><div class='flow-step'><strong>Platform fee</strong><span>CoinPilotXAI fee is calculated from active rules.</span></div><div class='flow-step'><strong>Creator allocation</strong><span>Seller net moves to pending balance.</span></div><div class='flow-step'><strong>Treasury allocation</strong><span>Fee revenue posts to platform wallet and fee ledger.</span></div><div class='flow-step'><strong>Escrow</strong><span>Risk and fulfillment windows hold funds safely.</span></div><div class='flow-step'><strong>Settlement payout</strong><span>Eligible funds release to connected accounts.</span></div></div></section>
    <section class='grid'><div class='card'><h2>Live Financial Stream</h2>{stream_html}</div><div class='card'><h2>AI Financial Intelligence</h2><section class='pay-grid'>{insight_html}</section></div></section>
    <section class='card'><h2>Quick Actions</h2><div class='actions'>{quick_html}</div></section>
    <section class='card table-wrap'><h2>Top Creator Balances</h2><table class='table'><tr><th>User</th><th>Seller</th><th>Gross</th><th>Fees</th><th>Available</th><th>Status</th></tr>{creator_rows or '<tr><td colspan=6>No creator balances yet.</td></tr>'}</table></section>
    <section class='card'><h2>Provider Snapshot</h2><pre>{clean_html(json.dumps(provider, indent=2, default=str))}</pre></section>
    """
    return admin_page_html("Payments Command Center", body, admin)


