def backend_command_safe_scalar(query, params=(), default=0):
    """Return a single admin metric without exposing query/database details."""
    conn = None
    try:
        conn = db()
        cur = conn.cursor()
        cur.execute(query, params)
        row = cur.fetchone()
        if row is None:
            return default
        if isinstance(row, sqlite3.Row):
            value = row[0]
        elif isinstance(row, (tuple, list)):
            value = row[0]
        else:
            value = row
        return int(value or 0)
    except Exception as exc:
        logging.info("BACKEND_COMMAND_METRIC_SKIPPED error=%s", str(exc)[:160])
        return default
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass


def backend_command_live_metrics():
    now = datetime.utcnow()
    day = (now - timedelta(days=1)).isoformat(timespec="seconds")
    today = now.strftime("%Y-%m-%dT00:00:00")
    metric_queries = {
        "account": [
            ("Users", "users", "SELECT COUNT(*) FROM users"),
            ("New today", "today", "SELECT COUNT(*) FROM users WHERE created_at>=?", (today,)),
            ("Suspended/restricted", "restricted", "SELECT COUNT(*) FROM users WHERE lower(COALESCE(status,'')) IN ('restricted','suspended','banned')"),
            ("Verification pending", "review", "SELECT COUNT(*) FROM verification_requests WHERE lower(COALESCE(status,'')) IN ('submitted','in_review','needs_more_info')"),
        ],
        "network": [
            ("Queued alerts", "queue", "SELECT COUNT(*) FROM push_delivery_jobs WHERE status IN ('pending','retry_ready','queued')"),
            ("Failed delivery", "failed", "SELECT COUNT(*) FROM notification_delivery_logs WHERE status IN ('failed','not_configured','rate_limited') AND created_at>=?", (day,)),
            ("Delivered 24h", "sent", "SELECT COUNT(*) FROM notification_delivery_logs WHERE status IN ('sent','created','delivered') AND created_at>=?", (day,)),
            ("Active devices", "devices", "SELECT COUNT(*) FROM user_device_tokens WHERE COALESCE(enabled,1)=1 AND revoked_at IS NULL"),
        ],
        "creator": [
            ("Posts today", "posts", "SELECT COUNT(*) FROM pulse_posts WHERE created_at>=? AND deleted_at IS NULL", (today,)),
            ("Reels active", "reels", "SELECT COUNT(*) FROM pulse_reels WHERE COALESCE(status,'active')='active'"),
            ("Videos active", "videos", "SELECT COUNT(*) FROM pulse_videos WHERE COALESCE(status,'active')='active'"),
            ("Mod queue", "review", "SELECT COUNT(*) FROM moderation_cases WHERE status IN ('open','reviewing')"),
        ],
        "moderation": [
            ("Open reports", "reports", "SELECT COUNT(*) FROM moderation_cases WHERE status IN ('open','reviewing')"),
            ("Security events", "security", "SELECT COUNT(*) FROM command_center_security_events WHERE created_at>=?", (day,)),
            ("Scam reports", "scam", "SELECT COUNT(*) FROM pulse_reports WHERE COALESCE(status,'open')='open'"),
            ("Chat reports", "chat", "SELECT COUNT(*) FROM chat_reports WHERE COALESCE(status,'open')='open'"),
        ],
        "ads": [
            ("Pending review", "review", "SELECT COUNT(*) FROM pulse_ad_creatives WHERE lower(COALESCE(moderation_status,status,'')) IN ('pending','submitted','in_review')"),
            ("Approved today", "approved", "SELECT COUNT(*) FROM pulse_ad_review_board WHERE decision='approved' AND reviewed_at>=?", (today,)),
            ("Rejected today", "rejected", "SELECT COUNT(*) FROM pulse_ad_review_board WHERE decision='rejected' AND reviewed_at>=?", (today,)),
            ("Wallet cents", "wallet", "SELECT COALESCE(SUM(available_balance_cents),0) FROM pulse_ad_wallets"),
        ],
        "economy": [
            ("Payments 24h", "payments", "SELECT COUNT(*) FROM payment_records WHERE created_at>=?", (day,)),
            ("Failed payments", "failed", "SELECT COUNT(*) FROM payment_records WHERE lower(COALESCE(status,'')) IN ('failed','canceled','requires_payment_method')"),
            ("Ad spend cents", "spend", "SELECT COALESCE(SUM(amount_cents),0) FROM pulse_ad_wallet_transactions WHERE transaction_type='spend' AND created_at>=?", (day,)),
            ("Refund events", "refunds", "SELECT COUNT(*) FROM pulse_ad_refunds WHERE created_at>=?", (day,)),
        ],
        "media": [
            ("Music approved", "music", "SELECT COUNT(*) FROM audio_tracks WHERE lower(COALESCE(review_status,status,''))='approved'"),
            ("Music review", "review", "SELECT COUNT(*) FROM audio_tracks WHERE lower(COALESCE(review_status,status,'')) IN ('pending','submitted','in_review')"),
            ("Music reports", "reports", "SELECT COUNT(*) FROM pulse_music_reports WHERE COALESCE(status,'open')='open'"),
            ("Storage uploads", "uploads", "SELECT COUNT(*) FROM chat_media_uploads WHERE created_at>=?", (day,)),
        ],
        "ai": [
            ("AI events", "events", "SELECT COUNT(*) FROM command_center_ai_events WHERE created_at>=?", (day,)),
            ("AI failures", "failed", "SELECT COUNT(*) FROM command_center_ai_events WHERE status='failed' AND created_at>=?", (day,)),
            ("Usage logs", "usage", "SELECT COUNT(*) FROM ai_usage_logs WHERE created_at>=?", (day,)),
            ("Safety blocks", "blocks", "SELECT COUNT(*) FROM command_center_security_events WHERE event_type IN ('phishing_link','scam_keyword') AND created_at>=?", (day,)),
        ],
        "system": [
            ("Workers jobs", "jobs", "SELECT COUNT(*) FROM push_delivery_jobs WHERE created_at>=?", (day,)),
            ("Feature flags", "flags", "SELECT COUNT(*) FROM feature_flags"),
            ("Audit 24h", "audit", "SELECT COUNT(*) FROM admin_audit_logs WHERE created_at>=?", (day,)),
            ("Health snapshots", "health", "SELECT COUNT(*) FROM system_health_snapshots WHERE created_at>=?", (day,)),
        ],
        "launch": [
            ("Features", "features", "SELECT COUNT(*) FROM backend_feature_registry"),
            ("Critical gaps", "gaps", "SELECT COUNT(*) FROM backend_feature_registry WHERE launch_critical=1 AND status!='active'"),
            ("QA reports", "qa", "SELECT COUNT(*) FROM backend_management_audit_events WHERE action LIKE '%qa%'"),
            ("Audit events", "audit", "SELECT COUNT(*) FROM backend_management_audit_events"),
        ],
        "controls": [
            ("Feature flags", "flags", "SELECT COUNT(*) FROM feature_flags"),
            ("Ad settings", "ads", "SELECT COUNT(*) FROM pulse_ad_platform_settings"),
            ("Provider skips", "skips", "SELECT COUNT(*) FROM notification_delivery_logs WHERE status IN ('skipped','not_configured') AND created_at>=?", (day,)),
            ("Risky actions", "audit", "SELECT COUNT(*) FROM admin_audit_logs WHERE action LIKE '%kill%' OR action LIKE '%disable%'"),
        ],
        "audit": [
            ("Admin audit", "admin", "SELECT COUNT(*) FROM admin_audit_logs"),
            ("Payment audit", "payment", "SELECT COUNT(*) FROM payment_audit_logs"),
            ("Ads audit", "ads", "SELECT COUNT(*) FROM pulse_ad_audit_logs"),
            ("Account audit", "account", "SELECT COUNT(*) FROM account_audit_logs"),
        ],
    }
    output = {}
    for module, rows in metric_queries.items():
        items = []
        for label, key, query, *maybe_params in rows:
            params = maybe_params[0] if maybe_params else ()
            items.append({"label": label, "key": key, "value": backend_command_safe_scalar(query, params)})
        output[module] = items
    return output


