@webhook_app.route("/admin/command-center/<module_key>", methods=["GET"])
def admin_backend_management_module_page(module_key):
    admin, denied = require_admin_page("command_center.view")
    if denied:
        return denied
    module_key = clean_html(str(module_key or "").strip().lower())[:80]
    modules = backend_management_registry.REQUIRED_MODULES
    if module_key not in modules:
        return redirect("/admin/command-center")
    query = clean_html(request.args.get("q") or "").lower()[:80]
    status_filter = clean_html(request.args.get("status") or "all").lower()[:40]
    risk_filter = clean_html(request.args.get("risk") or "all").lower()[:40]
    all_module_features = [item for item in backend_management_registry.visible_features(admin, admin_has_permission) if item.get("category") == module_key]
    features = []
    for item in all_module_features:
        haystack = " ".join(str(item.get(key) or "") for key in ("feature_key", "display_name", "owner", "backend_service", "notes")).lower()
        if query and query not in haystack:
            continue
        if status_filter != "all" and str(item.get("status") or "") != status_filter:
            continue
        if risk_filter != "all" and str(item.get("risk_level") or "") != risk_filter:
            continue
        features.append(item)
    blueprint = backend_management_registry.module_blueprint(module_key)
    metrics = backend_command_metric_html(backend_command_live_metrics().get(module_key, []))
    rows = []
    for item in features:
        risk = str(item.get("risk_level") or "low")
        state = "READY" if item.get("status") == "active" and item.get("manageable_from_backend") else "PARTIAL" if item.get("status") == "partial" else "WARNING"
        rows.append(
            "<tr>"
            f"<td><strong>{clean_html(item.get('display_name') or '')}</strong><br><small>{clean_html(item.get('feature_key') or '')}</small></td>"
            f"<td><span class='pill'>{clean_html(state)}</span> <span class='pill'>{clean_html(risk)}</span></td>"
            f"<td>{clean_html(item.get('owner') or '')}<br><small>{clean_html(item.get('backend_service') or '')}</small></td>"
            f"<td>{clean_html(item.get('audit_log_table') or '')}</td>"
            f"<td><a class='button' href='{clean_html(item.get('route') or '/admin/command-center')}'>Manage</a></td>"
            "</tr>"
        )
    module_summary = next((item for item in backend_management_registry.category_summary(all_module_features) if item.get("category") == module_key), {})
    action_chips = "".join(f"<span class='pill'>{clean_html(action)}</span> " for action in (blueprint.get("actions") or []))
    body = f"""
    <style>
      .module-search{{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:8px;align-items:end}}
      .ops-metrics{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:10px 0}}
      .ops-metric{{border:1px solid rgba(110,223,246,.16);border-radius:12px;background:rgba(255,255,255,.045);padding:8px;min-width:0}}
      .ops-metric strong{{display:block;font-size:22px;color:#f4fdff;line-height:1}}
      .ops-metric span{{display:block;color:#9fb5c0;font-size:12px}}
      @media(max-width:760px){{.module-search{{grid-template-columns:1fr}}.ops-metrics{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}
    </style>
    <h1>{clean_html(modules[module_key])}</h1>
    <p class='muted'>Only features your admin role can manage are shown. Admin-only and moderator-only features stay server-side hidden from unauthorized roles.</p>
    <section class='card'>
      <h2>Operating Blueprint</h2>
      <div class='ops-metrics'>{metrics}</div>
      <p><strong>Managed at:</strong> {clean_html(blueprint.get('surface') or '')}</p>
      <p><strong>Operators:</strong> {clean_html(blueprint.get('operators') or '')}</p>
      <p><strong>Visible state:</strong> {clean_html(blueprint.get('visible_state') or '')}</p>
      <p><strong>Actions:</strong> {action_chips}</p>
      <p class='muted'><strong>Failure behavior:</strong> {clean_html(blueprint.get('failure_behavior') or '')}</p>
    </section>
    <section class='grid'>
      <div class='card'><h2>Readiness</h2><p class='metric'>{int(module_summary.get('readiness_score') or 0)}%</p></div>
      <div class='card'><h2>Managed Features</h2><p class='metric'>{int(module_summary.get('manageable') or 0)}</p></div>
      <div class='card'><h2>Gaps</h2><p class='metric'>{int(module_summary.get('gaps') or 0)}</p></div>
      <div class='card'><h2>Risk</h2><p class='metric'>{clean_html(module_summary.get('risk_level') or 'low')}</p></div>
    </section>
    <section class='card'>
      <h2>Feature Inventory</h2>
      <form class='module-search' method='get'>
        <label>Search<input name='q' value='{clean_html(query)}' placeholder='feature, owner, service'></label>
        <label>Status<select name='status'><option value='all'>All</option><option value='active'>Active</option><option value='partial'>Partial</option><option value='planned'>Planned</option><option value='blocked'>Blocked</option></select></label>
        <label>Risk<select name='risk'><option value='all'>All</option><option value='critical'>Critical</option><option value='high'>High</option><option value='medium'>Medium</option><option value='low'>Low</option></select></label>
        <button class='button'>Filter</button>
      </form>
      <table><tr><th>Feature</th><th>State</th><th>Owner</th><th>Audit</th><th>Manage</th></tr>{''.join(rows) or '<tr><td colspan="5">No features visible for this role.</td></tr>'}</table>
    </section>
    <p><a class='button' href='/admin/command-center'>Back to Backend Command Center</a></p>
    """
    return admin_page_html(modules[module_key], body, admin)


