def _admin_network_section_by_key(state, section_key):
    normalized = str(section_key or "").replace("-", "_")
    for section in state.get("sections") or []:
        section_id = str(section.get("key") or "")
        if section_id == section_key or section_id == normalized or section_id.replace("_", "-") == section_key:
            return section
    return None


