def _admin_creator_metric_cards(metrics):
    labels = [
        ("posts_total", "Posts"),
        ("posts_in_review", "Posts In Review"),
        ("reels_total", "Reels"),
        ("reels_processing", "Reels Processing"),
        ("videos_total", "Videos"),
        ("videos_processing", "Videos Processing"),
        ("statuses_total", "Statuses"),
        ("statuses_active", "Active Statuses"),
        ("live_total", "Live Records"),
        ("live_active", "Live/Scheduled"),
        ("moderation_queue", "Moderation Queue"),
        ("media_processing", "Media Processing"),
        ("creator_health_score", "Creator Health"),
        ("media_health_score", "Media Health"),
        ("live_health_score", "Live Health"),
    ]
    cards = []
    for key, label in labels:
        value = int(metrics.get(key) or 0)
        suffix = "%" if key.endswith("_score") else ""
        cards.append(f"<article class='card'><h2>{clean_html(label)}</h2><p class='metric'>{value}{suffix}</p></article>")
    return "".join(cards)


