def _admin_economy_money(cents):
    try:
        return f"${int(cents or 0) / 100:,.2f}"
    except Exception:
        return "$0.00"


def _admin_economy_metric_cards(metrics):
    labels = [
        ("wallets", "Wallets", ""),
        ("transactions", "Transactions", ""),
        ("orders", "Orders", ""),
        ("sellers", "Sellers", ""),
        ("products", "Products", ""),
        ("subscriptions", "Subscriptions", ""),
        ("wallet_balance_cents", "Wallet Balance", "$"),
        ("platform_revenue_cents", "Revenue Signals", "$"),
        ("payout_queue", "Payout Queue", ""),
        ("refund_queue", "Refund Queue", ""),
        ("chargeback_queue", "Chargebacks", ""),
        ("payment_failures", "Payment Failures", ""),
        ("payment_health", "Payment Health", "%"),
        ("fraud_risk", "Fraud Risk", "%"),
    ]
    cards = []
    for key, label, kind in labels:
        raw = metrics.get(key) or 0
        value = _admin_economy_money(raw) if kind == "$" else f"{int(raw)}{kind}"
        cards.append(f"<article class='card'><h2>{clean_html(label)}</h2><p class='metric'>{clean_html(value)}</p></article>")
    return "".join(cards)


