def _serialize_direct_mux_media(row):
    item = dict(row or {})
    playback_id = clean_html(item.get("mux_playback_id") or "")[:180]
    playback_url = item.get("playback_url") or (media_service.mux_playback_urls(playback_id).get("hls_url") if playback_id else "")
    return {
        "id": safe_int(item.get("id"), 0),
        "media_id": safe_int(item.get("id"), 0),
        "media_type": "video",
        "mime_type": clean_html(item.get("mime_type") or "video/mp4")[:120],
        "file_size_bytes": safe_int(item.get("file_size_bytes"), 0),
        "original_filename": clean_html(item.get("original_filename") or "")[:220],
        "storage_provider": clean_html(item.get("storage_provider") or "mux")[:40],
        "mux_upload_id": clean_html(item.get("mux_upload_id") or "")[:180],
        "mux_asset_id": clean_html(item.get("mux_asset_id") or "")[:180],
        "mux_playback_id": playback_id,
        "mux_status": clean_html(item.get("mux_status") or "waiting_upload")[:80],
        "processing_status": clean_html(item.get("processing_status") or "mux_uploading")[:80],
        "playback_url": clean_html(playback_url or "")[:1000],
        "media_url": clean_html(playback_url or item.get("media_url") or "")[:1000],
        "thumbnail_url": clean_html(item.get("thumbnail_url") or "")[:1000],
        "poster_url": clean_html(item.get("poster_url") or item.get("thumbnail_url") or "")[:1000],
        "is_available": bool(playback_url) or str(item.get("processing_status") or "").startswith("mux_"),
    }


@webhook_app.route("/api/pulse/media/mux/direct-upload", methods=["POST"])
def api_pulse_media_mux_direct_upload():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401, error="login_required")
    trace_id = secrets.token_hex(6)
    payload = request.get_json(silent=True) or {}
    filename = clean_html(payload.get("filename") or "pulse-video.mp4")[:220]
    lowered_name = filename.lower()
    mime_type = clean_html(payload.get("mime_type") or payload.get("type") or "")[:120].lower()
    file_size = safe_int(payload.get("size"), 0)
    context_type = clean_html(payload.get("context_type") or "pulse_video")[:80]
    context_id = clean_html(payload.get("context_id") or "direct_mux")[:120]
    origin = clean_html(payload.get("origin") or request.headers.get("Origin") or request.host_url.rstrip("/"))[:300]
    ext = lowered_name.rsplit(".", 1)[-1] if "." in lowered_name else ""
    if ext not in {"mp4", "mov", "webm", "m4v"} and not mime_type.startswith("video/"):
        return api_error("Direct upload is only available for MP4, MOV, or WEBM videos.", 400, trace_id, error="unsupported_video_type")
    max_gb = float(os.getenv("MEDIA_DIRECT_UPLOAD_MAX_VIDEO_GB", "25"))
    max_bytes = int(max_gb * 1024 * 1024 * 1024)
    if file_size and file_size > max_bytes:
        return api_error(f"Video is too large. Direct uploads can be up to {max_gb:g} GB.", 413, trace_id, error="file_too_large", max_upload_gb=max_gb)
    if not media_service.mux_diagnostics().get("configured"):
        return api_error("Large video uploads need Mux configured before publishing.", 503, trace_id, error="mux_not_configured")
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO chat_media_uploads
            (uploader_user_id, context_type, context_id, original_filename, stored_filename,
             media_url, thumbnail_url, media_type, mime_type, file_size_bytes,
             storage_provider, mux_status, processing_status, moderation_status, trace_id, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, '', '', 'video', ?, ?, 'mux', 'waiting_upload', 'mux_uploading', 'approved', ?, ?, ?)
            """,
            (int(user["user_id"]), context_type, context_id, filename, filename, mime_type or "video/mp4", file_size, trace_id, now, now),
        )
        media_id = int(cur.lastrowid)
        direct = media_service.create_mux_direct_upload(
            media_id=media_id,
            filename=filename,
            mime_type=mime_type,
            file_size=file_size,
            origin=origin,
            context_type=context_type,
            trace_id=trace_id,
        )
        if not direct.get("ok"):
            cur.execute(
                "UPDATE chat_media_uploads SET mux_status='direct_upload_failed', processing_status='mux_failed', error_message=?, updated_at=? WHERE id=?",
                ((direct.get("message") or "Mux direct upload could not be created.")[:1000], now, media_id),
            )
            conn.commit()
            conn.close()
            return api_error(direct.get("message") or "Mux direct upload could not be created.", 502, trace_id, error="mux_direct_upload_failed", mux_status=direct.get("status") or "")
        cur.execute(
            "UPDATE chat_media_uploads SET mux_upload_id=?, mux_status=?, updated_at=? WHERE id=?",
            (clean_html(direct.get("upload_id") or "")[:180], clean_html(direct.get("status") or "waiting")[:80], now, media_id),
        )
        cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
        media = _serialize_direct_mux_media(cur.fetchone())
        conn.commit()
        conn.close()
        logging.info(
            "PULSE_MUX_DIRECT_UPLOAD_READY trace_id=%s user_id=%s media_id=%s mux_upload_id=%s file_size=%s context_type=%s",
            trace_id,
            user.get("user_id"),
            media_id,
            direct.get("upload_id") or "",
            file_size,
            context_type,
        )
        return jsonify({
            "ok": True,
            "success": True,
            "direct_upload": True,
            "provider": "mux",
            "upload_url": direct.get("upload_url") or "",
            "upload_id": direct.get("upload_id") or "",
            "media_id": media_id,
            "media": media,
            "message": "Large video upload is ready.",
            "trace_id": trace_id,
        })
    except Exception as exc:
        logging.exception("PULSE_MUX_DIRECT_UPLOAD_ROUTE_FAILED trace_id=%s user_id=%s error=%s", trace_id, user.get("user_id"), exc)
        try:
            conn.rollback(); conn.close()
        except Exception:
            pass
        return api_error("Large video upload could not be prepared. Please retry.", 500, trace_id, error="mux_direct_upload_prepare_failed")


@webhook_app.route("/api/pulse/media/mux/direct-upload/complete", methods=["POST"])
def api_pulse_media_mux_direct_upload_complete():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401, error="login_required")
    trace_id = secrets.token_hex(6)
    payload = request.get_json(silent=True) or {}
    media_id = safe_int(payload.get("media_id"), 0)
    upload_id = clean_html(payload.get("upload_id") or "")[:180]
    if media_id <= 0 or not upload_id:
        return api_error("Direct upload completion is missing media details.", 400, trace_id, error="missing_direct_upload_details")
    now = datetime.utcnow().isoformat(timespec="seconds")
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
    row = cur.fetchone()
    if not row:
        conn.close()
        return api_error("Uploaded media was not found.", 404, trace_id, error="media_not_found")
    if safe_int(row["uploader_user_id"], 0) != int(user["user_id"]):
        conn.close()
        return api_error("You do not have access to this upload.", 403, trace_id, error="forbidden")
    mux_upload = media_service.get_mux_direct_upload(upload_id)
    asset_id = clean_html(mux_upload.get("asset_id") or row["mux_asset_id"] or "")[:180]
    mux_status = clean_html(mux_upload.get("upload_status") or row["mux_status"] or "uploaded")[:80]
    playback_id = clean_html(row["mux_playback_id"] or "")[:180]
    playback_url = clean_html(row["playback_url"] or "")[:1000]
    if asset_id:
        mux_asset = media_service.get_mux_asset(asset_id)
        playback_id = clean_html(mux_asset.get("playback_id") or playback_id or "")[:180]
        mux_status = clean_html(mux_asset.get("mux_status") or mux_status or "preparing")[:80]
        playback_url = clean_html(media_service.mux_playback_urls(playback_id).get("hls_url") if playback_id else playback_url)[:1000]
    processing_status = "ready" if playback_id and mux_status in {"ready", "asset_ready", "available"} else "mux_processing"
    cur.execute(
        """
        UPDATE chat_media_uploads
        SET mux_upload_id=?, mux_asset_id=COALESCE(NULLIF(?, ''), mux_asset_id),
            mux_playback_id=COALESCE(NULLIF(?, ''), mux_playback_id),
            mux_status=?, playback_url=COALESCE(NULLIF(?, ''), playback_url),
            playback_mime_type=CASE WHEN ? != '' THEN 'application/vnd.apple.mpegurl' ELSE playback_mime_type END,
            processing_status=?, is_available=1,
            upload_complete_at=COALESCE(upload_complete_at, ?),
            mux_asset_created_at=COALESCE(mux_asset_created_at, CASE WHEN ? != '' THEN ? ELSE NULL END),
            mux_ready_at=CASE WHEN ?='ready' THEN COALESCE(mux_ready_at, ?) ELSE mux_ready_at END,
            db_ready_update_at=CASE WHEN ?='ready' THEN COALESCE(db_ready_update_at, ?) ELSE db_ready_update_at END,
            updated_at=?
        WHERE id=?
        """,
        (upload_id, asset_id, playback_id, mux_status or "preparing", playback_url, playback_url, processing_status, now, asset_id, now, processing_status, now, processing_status, now, now, media_id),
    )
    cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
    media = _serialize_direct_mux_media(cur.fetchone())
    conn.commit()
    conn.close()
    logging.info(
        "PULSE_MUX_DIRECT_UPLOAD_COMPLETE trace_id=%s user_id=%s media_id=%s mux_upload_id=%s mux_asset_id=%s mux_playback_id=%s mux_status=%s",
        trace_id,
        user.get("user_id"),
        media_id,
        upload_id,
        asset_id,
        playback_id,
        mux_status,
    )
    return jsonify({"ok": True, "success": True, "direct_upload": True, "media": media, "media_id": media_id, "mux_status": mux_status, "processing_status": processing_status, "playback_url": playback_url, "message": "Video uploaded. Processing playback.", "trace_id": trace_id})


def pulse_sync_video_processing_rows(cur, media_id, row, *, webhook_received_at=""):
    now = datetime.utcnow().isoformat(timespec="seconds")
    playback_id = clean_html(row.get("mux_playback_id") or "")[:180]
    playback_url = clean_html(row.get("playback_url") or (media_service.mux_playback_urls(playback_id).get("hls_url") if playback_id else ""))[:1000]
    mux_status = clean_html(row.get("mux_status") or "")[:80]
    processing_status = clean_html(row.get("processing_status") or ("ready" if playback_id and mux_status in {"ready", "asset_ready", "available"} else "mux_processing"))[:80]
    update_pairs = {
        "processing_status": processing_status,
        "transcoding_status": mux_status or processing_status,
        "mux_ready_at": row.get("mux_ready_at") or (now if processing_status == "ready" else ""),
        "webhook_received_at": webhook_received_at or row.get("webhook_received_at") or "",
        "db_ready_update_at": row.get("db_ready_update_at") or (now if processing_status == "ready" else ""),
        "updated_at": now,
    }
    for table in ("pulse_reels", "pulse_videos"):
        try:
            columns = table_columns(cur, table)
            assignments = []
            values = []
            for key, value in update_pairs.items():
                if key in columns and value != "":
                    assignments.append(f"{key}=?")
                    values.append(value)
            if table == "pulse_reels":
                if "video_url" in columns and playback_url:
                    assignments.append("video_url=?"); values.append(playback_url)
                where = "post_id IN (SELECT context_id FROM chat_media_uploads WHERE id=? AND context_id GLOB '[0-9]*') OR id IN (SELECT context_id FROM chat_media_uploads WHERE id=? AND context_id GLOB '[0-9]*')"
                values.extend([media_id, media_id])
            else:
                if "playback_url" in columns and playback_url:
                    assignments.append("playback_url=?"); values.append(playback_url)
                if "mux_playback_id" in columns and playback_id:
                    assignments.append("mux_playback_id=?"); values.append(playback_id)
                where = "media_id=? OR source_id=CAST(? AS TEXT)"
                values.extend([media_id, media_id])
            if assignments:
                cur.execute(f"UPDATE {table} SET {', '.join(assignments)} WHERE {where}", values)
        except Exception:
            logging.exception("PULSE_MEDIA_PROCESSING_ROW_SYNC_FAILED table=%s media_id=%s", table, media_id)


@webhook_app.route("/api/pulse/media/<int:media_id>/status", methods=["GET"])
def api_pulse_media_status(media_id):
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
    cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
    row = dict(cur.fetchone() or {})
    if not row:
        conn.close()
        return api_error("Media not found.", 404)
    if int(row.get("uploader_user_id") or 0) != int(user["user_id"]) and not user_is_super_user(user):
        conn.close()
        return api_error("You do not have access to this media.", 403)
    mux_asset_id = clean_html(row.get("mux_asset_id") or "")[:180]
    if mux_asset_id and row.get("processing_status") == "mux_processing":
        mux_asset = media_service.get_mux_asset(mux_asset_id)
        playback_id = clean_html(mux_asset.get("playback_id") or row.get("mux_playback_id") or "")[:180]
        mux_status = clean_html(mux_asset.get("mux_status") or row.get("mux_status") or "preparing")[:80]
        processing_status = "ready" if playback_id and mux_status in {"ready", "asset_ready", "available"} else "mux_processing"
        playback_url = clean_html(media_service.mux_playback_urls(playback_id).get("hls_url") if playback_id else row.get("playback_url") or "")[:1000]
        cur.execute(
            """
            UPDATE chat_media_uploads
            SET mux_playback_id=COALESCE(NULLIF(?, ''), mux_playback_id), mux_status=?, playback_url=COALESCE(NULLIF(?, ''), playback_url),
                playback_mime_type=CASE WHEN ? != '' THEN 'application/vnd.apple.mpegurl' ELSE playback_mime_type END,
                processing_status=?, mux_ready_at=CASE WHEN ?='ready' THEN COALESCE(mux_ready_at, ?) ELSE mux_ready_at END,
                db_ready_update_at=CASE WHEN ?='ready' THEN COALESCE(db_ready_update_at, ?) ELSE db_ready_update_at END,
                updated_at=?
            WHERE id=?
            """,
            (playback_id, mux_status, playback_url, playback_url, processing_status, processing_status, datetime.utcnow().isoformat(timespec="seconds"), processing_status, datetime.utcnow().isoformat(timespec="seconds"), datetime.utcnow().isoformat(timespec="seconds"), media_id),
        )
        cur.execute("SELECT * FROM chat_media_uploads WHERE id=? LIMIT 1", (media_id,))
        row = dict(cur.fetchone() or row)
        pulse_sync_video_processing_rows(cur, media_id, row)
        conn.commit()
    conn.close()
    media = media_service.resolve_media(row, check_remote=False)
    return jsonify({"ok": True, "media_id": media_id, "media": media, "processing_status": media.get("processing_status") or row.get("processing_status") or "", "mux_status": media.get("mux_status") or row.get("mux_status") or "", "playback_url": media.get("playback_url") or ""})


