@webhook_app.route("/api/pulse/media/upload", methods=["POST"])
def api_pulse_media_upload():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    trace_id = secrets.token_hex(6)
    context_type = request.form.get("context_type") or "pulse_camera"
    context_id = request.form.get("context_id") or request.form.get("group") or request.form.get("target") or ""
    logging.info(
        "PULSE_MEDIA_UPLOAD_ROUTE_HIT trace_id=%s user_id=%s context_type=%s context_id=%s content_length=%s content_type=%s storage_provider=%s mux_configured=%s ffmpeg_present=%s",
        trace_id,
        user.get("user_id"),
        context_type,
        context_id,
        request.content_length or 0,
        request.content_type or "",
        media_storage.provider(),
        media_service.mux_diagnostics().get("configured"),
        bool(shutil.which("ffmpeg")),
    )
    file = request.files.get("file")
    if file:
        file.stream.seek(0, os.SEEK_END)
        size = file.stream.tell()
        file.stream.seek(0)
        logging.info(
            "PULSE_MEDIA_UPLOAD_START trace_id=%s user_id=%s filename=%s mime_type=%s size=%s",
            trace_id,
            user.get("user_id"),
            clean_html(file.filename or "")[:180],
            clean_html(file.mimetype or "")[:120],
            size,
        )
        check = camera_filter_engine.validate_media(file.filename or "", file.mimetype or "", size)
        if not check.get("ok"):
            message = check.get("message") or "Media could not be validated."
            logging.warning(
                "PULSE_MEDIA_UPLOAD_VALIDATION_REJECTED trace_id=%s user_id=%s message=%s",
                trace_id,
                user.get("user_id"),
                message,
            )
            return jsonify({"ok": False, "success": False, "message": message, "error": "media_validation_failed", "trace_id": trace_id}), 400
    try:
        result, status = upload_progress_service.stage_upload(
            user["user_id"],
            file,
            context_type=context_type,
            context_id=context_id,
        )
    except Exception as exc:
        logging.exception("PULSE_MEDIA_UPLOAD_ROUTE_FAILED trace_id=%s user_id=%s error=%s", trace_id, user.get("user_id"), exc)
        return jsonify({
            "ok": False,
            "success": False,
            "message": "Upload could not be saved. Please retry with a smaller MP4, MOV, WEBM, or image.",
            "error": "upload_save_failed",
            "trace_id": trace_id,
        }), 500
    result["success"] = bool(result.get("ok"))
    result["trace_id"] = result.get("trace_id") or trace_id
    if result.get("ok") and result.get("media"):
        result["media"]["filter_name"] = clean_html(request.form.get("filter_name") or "")[:80]
        result["status_id"] = ""
        result["media_url"] = result["media"].get("valid_url") or result["media"].get("media_url") or ""
        result["message"] = result.get("message") or "Media uploaded and verified."
        try:
            media = result.get("media") or {}
            now = datetime.utcnow().isoformat(timespec="seconds")
            conn = db()
            cur = conn.cursor()
            cur.execute(
                """
                INSERT INTO pulse_media_assets
                (media_id, owner_user_id, storage_provider, storage_key, public_url, thumbnail_url, poster_url, media_type, mime_type, width, height, aspect_ratio, processing_status, mux_asset_id, mux_playback_id, mux_status, playback_url, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    safe_int(media.get("id"), 0),
                    int(user["user_id"]),
                    clean_html(media.get("storage_provider") or media_storage.provider())[:40],
                    clean_html(media.get("storage_key") or "")[:600],
                    clean_html(media.get("valid_url") or media.get("media_url") or "")[:1000],
                    clean_html(media.get("thumbnail_url") or "")[:1000],
                    clean_html(media.get("poster_url") or media.get("thumbnail_url") or "")[:1000],
                    clean_html(media.get("media_type") or "")[:40],
                    clean_html(media.get("mime_type") or "")[:120],
                    safe_int(media.get("width"), 0),
                    safe_int(media.get("height"), 0),
                    float(media.get("aspect_ratio") or 0),
                    clean_html(media.get("processing_status") or "ready")[:80],
                    clean_html(media.get("mux_asset_id") or "")[:180],
                    clean_html(media.get("mux_playback_id") or "")[:180],
                    clean_html(media.get("mux_status") or "")[:80],
                    clean_html(media.get("playback_url") or "")[:1000],
                    now,
                    now,
                ),
            )
            if (request.form.get("context_type") or "").startswith("pulse_camera"):
                cur.execute(
                    """
                    INSERT INTO pulse_camera_captures (user_id, media_id, target, mode, filter_name, effect_key, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        int(user["user_id"]),
                        safe_int(media.get("id"), 0),
                        clean_html(request.form.get("target") or "")[:80],
                        clean_html(request.form.get("mode") or "")[:40],
                        clean_html(request.form.get("filter_name") or "")[:80],
                        clean_html(request.form.get("effect_key") or "")[:80],
                        now,
                    ),
                )
            conn.commit()
            conn.close()
        except Exception:
            logging.exception("PULSE_MEDIA_ASSET_INDEX_FAILED trace_id=%s user_id=%s", result.get("trace_id"), user.get("user_id"))
        logging.info(
            "PULSE_MEDIA_UPLOAD_COMPLETE trace_id=%s user_id=%s media_id=%s media_url=%s status=%s",
            result.get("trace_id"),
            user.get("user_id"),
            (result.get("media") or {}).get("id"),
            result.get("media_url") or "",
            status,
        )
    else:
        result["error"] = result.get("error") or "upload_failed"
        logging.warning(
            "PULSE_MEDIA_UPLOAD_INCOMPLETE trace_id=%s user_id=%s status=%s message=%s",
            result.get("trace_id"),
            user.get("user_id"),
            status,
            result.get("message") or "",
        )
    log_product_event(user["user_id"], "pulse_media_upload", {"ok": result.get("ok"), "target": request.form.get("target") or "", "context_type": context_type})
    response = jsonify(result)
    response.headers["Content-Type"] = "application/json"
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response, status


