@webhook_app.route("/api/pulse/media/<int:media_id>/stream", methods=["GET", "HEAD"])
def api_pulse_media_stream(media_id):
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, media_type, mime_type, media_url, public_url, cdn_url, storage_provider,
               storage_key, object_key, playback_storage_key, playback_mime_type,
               moderation_status, is_available
        FROM chat_media_uploads
        WHERE id=? LIMIT 1
        """,
        (int(media_id),),
    )
    media = dict(cur.fetchone() or {})
    try:
        g.rows_returned = int(getattr(g, "rows_returned", 0) or 0) + (1 if media else 0)
    except Exception:
        pass
    conn.close()
    if not media:
        return Response("Media not found.", status=404)
    if str(media.get("moderation_status") or "").lower() == "blocked":
        return Response("Media unavailable.", status=403)
    media_type = str(media.get("media_type") or "").lower()
    if media_type not in {"video", "audio"}:
        return redirect(media_service.resolve_media(media).get("media_url") or "/static/img/media-unavailable.svg", code=302)
    provider = str(media.get("storage_provider") or "").lower()
    storage_key = media.get("playback_storage_key") or media.get("storage_key") or media.get("object_key") or ""
    mime_type = (
        media.get("playback_mime_type")
        or media.get("mime_type")
        or mimetypes.guess_type(str(media.get("media_url") or storage_key))[0]
        or "application/octet-stream"
    )
    if provider not in {"r2", "s3"} or not storage_key:
        local_url = media_service.resolve_media(media).get("media_url") or ""
        local_path = media_service.local_path_for_url(local_url)
        if local_path and os.path.exists(local_path):
            return send_file(local_path, mimetype=mime_type, conditional=True)
        return Response("Media object not found.", status=404)
    max_chunk = max(256 * 1024, min(safe_int(os.getenv("PULSE_MEDIA_STREAM_MAX_CHUNK_BYTES"), 2 * 1024 * 1024), 8 * 1024 * 1024))
    request_range = request.headers.get("Range") or ""
    try:
        r2_start = time.perf_counter()
        head = media_storage.head_object(storage_key)
        g.r2_duration_ms = int(getattr(g, "r2_duration_ms", 0) or 0) + int((time.perf_counter() - r2_start) * 1000)
    except Exception as exc:
        try:
            g.r2_duration_ms = int(getattr(g, "r2_duration_ms", 0) or 0) + int((time.perf_counter() - r2_start) * 1000)
        except Exception:
            pass
        logging.exception("PULSE_MEDIA_STREAM_HEAD_FAILED media_id=%s provider=%s key=%s error=%s", media_id, provider, storage_key, exc)
        return Response("Media object could not be loaded.", status=502)
    total_size = safe_int(head.get("ContentLength"), 0)
    content_type = head.get("ContentType") or mime_type
    start = 0
    end = max(0, min(total_size - 1, max_chunk - 1)) if total_size else max_chunk - 1
    range_requested = False
    if request_range.lower().startswith("bytes="):
        range_requested = True
        spec = request_range.split("=", 1)[1].split(",", 1)[0].strip()
        left, _, right = spec.partition("-")
        try:
            if left:
                start = max(0, int(left))
                requested_end = int(right) if right else start + max_chunk - 1
                end = min(requested_end, start + max_chunk - 1)
            elif right and total_size:
                suffix = max(1, int(right))
                start = max(0, total_size - suffix)
                end = total_size - 1
        except Exception:
            return Response("Invalid range.", status=416, headers={"Accept-Ranges": "bytes", "Content-Range": f"bytes */{total_size}" if total_size else "bytes */*"})
    if total_size:
        if start >= total_size:
            return Response("Range not satisfiable.", status=416, headers={"Accept-Ranges": "bytes", "Content-Range": f"bytes */{total_size}"})
        end = min(end, total_size - 1)
    byte_range = f"bytes={start}-{end}"
    status_code = 206 if range_requested or total_size == 0 or (end - start + 1) < total_size else 200
    headers = {
        "Accept-Ranges": "bytes",
        "Cache-Control": "public, max-age=3600",
        "Content-Type": content_type,
    }
    content_length = max(0, end - start + 1)
    headers["Content-Length"] = str(content_length)
    if status_code == 206:
        headers["Content-Range"] = f"bytes {start}-{end}/{total_size}" if total_size else f"bytes {start}-{end}/*"
    if request.method == "HEAD":
        logging.info("PULSE_MEDIA_STREAM_HEAD media_id=%s provider=%s key=%s total_size=%s content_type=%s", media_id, provider, storage_key, total_size, content_type)
        return Response(status=status_code, headers=headers)
    try:
        r2_start = time.perf_counter()
        obj = media_storage.get_object(storage_key, byte_range=byte_range)
        g.r2_duration_ms = int(getattr(g, "r2_duration_ms", 0) or 0) + int((time.perf_counter() - r2_start) * 1000)
    except Exception as exc:
        try:
            g.r2_duration_ms = int(getattr(g, "r2_duration_ms", 0) or 0) + int((time.perf_counter() - r2_start) * 1000)
        except Exception:
            pass
        logging.exception("PULSE_MEDIA_STREAM_FAILED media_id=%s provider=%s key=%s range=%s error=%s", media_id, provider, storage_key, byte_range, exc)
        return Response("Media object could not be loaded.", status=502)
    body = obj.get("Body")
    if obj.get("ContentRange"):
        headers["Content-Range"] = obj.get("ContentRange")
    if obj.get("ContentLength") is not None:
        headers["Content-Length"] = str(obj.get("ContentLength"))
    logging.info("PULSE_MEDIA_STREAM_RANGE media_id=%s provider=%s key=%s range=%s status=%s bytes=%s total_size=%s", media_id, provider, storage_key, byte_range, status_code, headers.get("Content-Length"), total_size)
    return Response(body.iter_chunks(chunk_size=1024 * 256), status=status_code, headers=headers, direct_passthrough=True)


