def _profile_media_from_upload(user_id, media_id):
    if not safe_int(media_id, 0):
        return {}
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        SELECT *
        FROM chat_media_uploads
        WHERE id=? AND uploader_user_id=? AND media_type IN ('image','gif')
        LIMIT 1
        """,
        (safe_int(media_id, 0), int(user_id)),
    )
    row = cur.fetchone()
    conn.close()
    if not row:
        return {}
    return media_service.resolve_media(dict(row))


def _profile_media_is_cdn_safe(url):
    if media_storage.provider() not in {"r2", "s3"}:
        return bool(url)
    base = (os.getenv("R2_PUBLIC_BASE_URL") or "").rstrip("/")
    return bool(base and str(url or "").startswith(base + "/"))


def _profile_image_upload_signature_allowed(file_storage):
    stream = getattr(file_storage, "stream", None)
    if not stream:
        return False
    try:
        pos = stream.tell()
    except Exception:
        pos = 0
    head = stream.read(32)
    stream.seek(pos)
    return bool(
        head.startswith(b"\xff\xd8\xff")
        or head.startswith(b"\x89PNG\r\n\x1a\n")
        or (head.startswith(b"RIFF") and b"WEBP" in head[:16])
    )


def _profile_cache_busted_url(url, version=None):
    url = clean_html(url or "")[:1000]
    if not url:
        return ""
    cache_version = str(version or int(datetime.utcnow().timestamp())).replace(":", "").replace(".", "").replace("-", "")
    cache_sep = "&" if "?" in url else "?"
    return f"{url}{cache_sep}v={cache_version}"


def _profile_media_payload_url(user_id, payload, media_id_key, url_key, thumbnail_key="thumbnail_url"):
    media_id = safe_int(payload.get(media_id_key) or request.form.get(media_id_key), 0)
    resolved = _profile_media_from_upload(user_id, media_id)
    if not resolved:
        raw_url = clean_html(payload.get(url_key) or request.form.get(url_key) or "")[:1000]
        if raw_url:
            resolved = media_service.resolve_media({"media_url": raw_url, "thumbnail_url": payload.get(thumbnail_key) or request.form.get(thumbnail_key) or ""})
    if not resolved:
        return "", "", {}
    media_url = clean_html(resolved.get("valid_url") or resolved.get("media_url") or "")[:1000]
    thumbnail_url = clean_html(resolved.get("thumbnail_url") or media_url)[:1000]
    return media_url, thumbnail_url, resolved


@webhook_app.route("/api/pulse/profile/avatar", methods=["POST"])
def api_pulse_profile_avatar():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    payload = request.get_json(silent=True) or {}
    result = {"media": {}}
    avatar_url, avatar_thumbnail_url, payload_media = _profile_media_payload_url(user["user_id"], payload, "media_id", "media_url")
    if not avatar_url:
        file_storage = request.files.get("avatar")
        filename = (getattr(file_storage, "filename", "") or "").lower()
        ext = filename.rsplit(".", 1)[-1] if "." in filename else ""
        if ext not in {"jpg", "jpeg", "png", "webp"}:
            return api_error("Upload a jpg, png, or webp profile picture.", 400)
        if file_storage and file_storage.mimetype and not file_storage.mimetype.lower().startswith("image/"):
            return api_error("That profile picture type is not supported.", 400)
        if not _profile_image_upload_signature_allowed(file_storage):
            return api_error("That profile picture file is not a valid image.", 400)
        result, status = media_service.save_upload(user["user_id"], file_storage, context_type="pulse_avatar", context_id=str(user["user_id"]))
        if not result.get("ok"):
            return jsonify(result), status
        uploaded_media = result.get("media") or {}
        resolved = media_service.resolve_media(uploaded_media)
        avatar_url = clean_html(resolved.get("valid_url") or resolved.get("media_url") or uploaded_media.get("media_url") or "")[:1000]
        avatar_thumbnail_url = clean_html(resolved.get("thumbnail_url") or avatar_url)[:1000]
        payload_media = resolved
    if not _profile_media_is_cdn_safe(avatar_url):
        return api_error("Profile picture was not saved to durable CDN media. Please upload again.", 502)
    avatar_filter = clean_html(payload.get("filter_name") or request.form.get("filter_name") or "")[:80]
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("SELECT * FROM users WHERE user_id=? LIMIT 1", (user["user_id"],))
    before_profile = dashboard_account_command_center.profile_snapshot(dict(cur.fetchone() or user))
    cur.execute(
        "UPDATE users SET avatar_url=?, avatar_thumbnail_url=?, avatar_filter=?, updated_at=? WHERE user_id=?",
        (avatar_url, avatar_thumbnail_url or avatar_url, avatar_filter, now, user["user_id"]),
    )
    if cur.rowcount != 1:
        conn.rollback()
        conn.close()
        return api_error("Profile picture could not be saved. Please retry.", 500)
    conn.commit()
    cur.execute("SELECT * FROM users WHERE user_id=? LIMIT 1", (user["user_id"],))
    saved = dict(cur.fetchone() or {})
    dashboard_account_command_center.record_profile_audit(
        conn,
        user_id=int(user["user_id"]),
        actor_user_id=int(user["user_id"]),
        action="profile_avatar_updated",
        before=before_profile,
        after=dashboard_account_command_center.profile_snapshot(saved),
        ip_hash=client_ip_hash(),
        user_agent_hash=hashlib.sha256((request.headers.get("User-Agent") or "").encode()).hexdigest()[:32],
    )
    conn.commit()
    conn.close()
    saved_url = clean_html(saved.get("avatar_url") or "")[:1000]
    if saved_url != avatar_url:
        return api_error("Profile picture save did not persist. Please retry.", 500)
    cache_busted = _profile_cache_busted_url(saved_url)
    pulse_emit_event("profile_updated", {"avatar_url": saved_url, "message": "A PulseSoc profile picture changed."}, user["user_id"], 0)
    thumbnail_url = clean_html(saved.get("avatar_thumbnail_url") or avatar_thumbnail_url or saved_url)[:1000]
    thumbnail_cache_busted = _profile_cache_busted_url(thumbnail_url) if thumbnail_url else cache_busted
    media_response = result.get("media") or payload_media
    return jsonify({
        "ok": True,
        "message": "Profile picture updated.",
        "avatar_url": saved_url,
        "avatar_url_cache_busted": cache_busted,
        "avatar_thumbnail_url": thumbnail_url,
        "thumbnail_url": thumbnail_url,
        "thumbnail_url_cache_busted": thumbnail_cache_busted,
        "media": media_response,
    })


@webhook_app.route("/api/pulse/profile/cover", methods=["POST"])
def api_pulse_profile_cover():
    init_db()
    user = api_account_user()
    if not user:
        return api_error("Login required.", 401)
    payload = request.get_json(silent=True) or {}
    result = {"media": {}}
    cover_url, cover_thumbnail_url, payload_media = _profile_media_payload_url(user["user_id"], payload, "media_id", "media_url")
    if not cover_url:
        file_storage = request.files.get("cover")
        filename = (getattr(file_storage, "filename", "") or "").lower()
        ext = filename.rsplit(".", 1)[-1] if "." in filename else ""
        if ext not in {"jpg", "jpeg", "png", "webp"}:
            return api_error("Upload a jpg, png, or webp cover picture.", 400)
        if file_storage and file_storage.mimetype and not file_storage.mimetype.lower().startswith("image/"):
            return api_error("That cover picture type is not supported.", 400)
        if not _profile_image_upload_signature_allowed(file_storage):
            return api_error("That cover picture file is not a valid image.", 400)
        result, status = media_service.save_upload(user["user_id"], file_storage, context_type="pulse_cover", context_id=str(user["user_id"]))
        if not result.get("ok"):
            return jsonify(result), status
        uploaded_media = result.get("media") or {}
        resolved = media_service.resolve_media(uploaded_media)
        cover_url = clean_html(resolved.get("valid_url") or resolved.get("media_url") or uploaded_media.get("media_url") or "")[:1000]
        cover_thumbnail_url = clean_html(resolved.get("thumbnail_url") or cover_url)[:1000]
        payload_media = resolved
    if not _profile_media_is_cdn_safe(cover_url):
        return api_error("Cover photo was not saved to durable CDN media. Please upload again.", 502)
    cover_filter = clean_html(payload.get("filter_name") or request.form.get("filter_name") or "")[:80]
    cover_position = clean_html(payload.get("cover_position") or request.form.get("cover_position") or "center")[:80]
    conn = db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    now = datetime.utcnow().isoformat(timespec="seconds")
    cur.execute("SELECT * FROM users WHERE user_id=? LIMIT 1", (user["user_id"],))
    before_profile = dashboard_account_command_center.profile_snapshot(dict(cur.fetchone() or user))
    cur.execute(
        "UPDATE users SET cover_url=?, banner_url=?, cover_position=?, cover_filter=?, updated_at=? WHERE user_id=?",
        (cover_url, cover_url, cover_position, cover_filter, now, user["user_id"]),
    )
    if cur.rowcount != 1:
        conn.rollback()
        conn.close()
        return api_error("Cover photo could not be saved. Please retry.", 500)
    conn.commit()
    cur.execute("SELECT * FROM users WHERE user_id=? LIMIT 1", (user["user_id"],))
    saved = dict(cur.fetchone() or {})
    dashboard_account_command_center.record_profile_audit(
        conn,
        user_id=int(user["user_id"]),
        actor_user_id=int(user["user_id"]),
        action="profile_cover_updated",
        before=before_profile,
        after=dashboard_account_command_center.profile_snapshot(saved),
        ip_hash=client_ip_hash(),
        user_agent_hash=hashlib.sha256((request.headers.get("User-Agent") or "").encode()).hexdigest()[:32],
    )
    conn.commit()
    conn.close()
    saved_url = clean_html(saved.get("cover_url") or saved.get("banner_url") or "")[:1000]
    if saved_url != cover_url:
        return api_error("Cover photo save did not persist. Please retry.", 500)
    cache_busted = _profile_cache_busted_url(saved_url)
    pulse_emit_event("profile_updated", {"cover_url": saved_url, "message": "A PulseSoc cover photo changed."}, user["user_id"], 0)
    media_response = result.get("media") or payload_media
    thumbnail_url = clean_html(cover_thumbnail_url or saved_url)[:1000]
    return jsonify({
        "ok": True,
        "message": "Cover photo updated.",
        "cover_url": saved_url,
        "cover_url_cache_busted": cache_busted,
        "banner_url": saved_url,
        "thumbnail_url": thumbnail_url,
        "thumbnail_url_cache_busted": _profile_cache_busted_url(thumbnail_url) if thumbnail_url else cache_busted,
        "cover_position": saved.get("cover_position") or cover_position,
        "media": media_response,
    })


