def stripe_event_processed(event_id):
    if not event_id:
        return False
    conn = db()
    cur = conn.cursor()
    cur.execute("SELECT id FROM stripe_events WHERE stripe_event_id=? AND status='processed' LIMIT 1", (event_id,))
    row = cur.fetchone()
    conn.close()
    return bool(row)


def record_stripe_event(event, status="processed", user_id=None, error_message=""):
    event = event or {}
    event_id = event.get("id") or ""
    if not event_id:
        return
    event_type = event.get("type") or ""
    stripe_object = ((event.get("data") or {}).get("object") or {})
    payload_summary = json.dumps({
        "object_id": stripe_object.get("id"),
        "customer": stripe_object.get("customer"),
        "subscription": stripe_object.get("subscription") or stripe_object.get("id") if event_type.startswith("customer.subscription") else stripe_object.get("subscription"),
        "payment_status": stripe_object.get("payment_status"),
        "amount": stripe_object.get("amount_total") or stripe_object.get("amount_paid"),
    })[:2000]
    now = datetime.now().isoformat()
    conn = db()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO stripe_events (stripe_event_id, event_id, event_type, user_id, status, error_message, payload_summary, payload_json, created_at, processed_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(stripe_event_id) DO UPDATE SET
            user_id=COALESCE(excluded.user_id, stripe_events.user_id),
            event_id=COALESCE(excluded.event_id, stripe_events.event_id),
            status=excluded.status,
            error_message=excluded.error_message,
            payload_summary=excluded.payload_summary,
            payload_json=excluded.payload_json,
            processed_at=excluded.processed_at
        """,
        (event_id, event_id, event_type, user_id, status, error_message[:500], payload_summary, json.dumps(event, default=str)[:12000], now, now if status == "processed" else ""),
    )
    conn.commit()
    conn.close()


def record_payment_record(user_id, stripe_event_id="", stripe_session_id="", stripe_customer_id="", stripe_subscription_id="", invoice_id="", payment_intent_id="", amount=None, currency="usd", status="succeeded", payment_type="stripe", manual=False, metadata=None, stripe_payload=None, email_sent=False, pro_activated_at=""):
    if not user_id:
        return
    if amount is None and status == "succeeded" and payment_type == "stripe":
        amount = 14.99
    conn = db()
    cur = conn.cursor()
    if stripe_event_id:
        cur.execute(
            "SELECT id FROM payment_records WHERE stripe_event_id=? AND status=? LIMIT 1",
            (stripe_event_id, status),
        )
        existing = cur.fetchone()
        if existing:
            conn.close()
            logging.info("PAYMENT_RECORD_CREATED skipped_duplicate user_id=%s stripe_event_id=%s status=%s", user_id, stripe_event_id, status)
            return existing[0]
    if invoice_id:
        cur.execute(
            "SELECT id FROM payment_records WHERE invoice_id=? AND status=? LIMIT 1",
            (invoice_id, status),
        )
        existing = cur.fetchone()
        if existing:
            conn.close()
            logging.info("PAYMENT_RECORD_CREATED skipped_duplicate user_id=%s invoice_id=%s status=%s", user_id, invoice_id, status)
            return existing[0]
    if payment_intent_id:
        cur.execute(
            "SELECT id FROM payment_records WHERE payment_intent_id=? AND status=? LIMIT 1",
            (payment_intent_id, status),
        )
        existing = cur.fetchone()
        if existing:
            conn.close()
            logging.info("PAYMENT_RECORD_CREATED skipped_duplicate user_id=%s payment_intent_id=%s status=%s", user_id, payment_intent_id, status)
            return existing[0]
    cur.execute(
        """
        INSERT INTO payment_records
        (user_id, stripe_event_id, stripe_session_id, stripe_customer_id, stripe_subscription_id, invoice_id, payment_intent_id, amount, currency, status, payment_type, manual, metadata, stripe_payload, email_sent, pro_activated_at, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            user_id,
            stripe_event_id or "",
            stripe_session_id or "",
            stripe_customer_id or "",
            stripe_subscription_id or "",
            invoice_id or "",
            payment_intent_id or "",
            amount,
            (currency or "usd").upper(),
            status,
            payment_type,
            1 if manual else 0,
            json.dumps(metadata or {})[:4000],
            json.dumps(stripe_payload or {})[:8000],
            1 if email_sent else 0,
            pro_activated_at or "",
            datetime.now().isoformat(),
        ),
    )
    payment_record_id = cur.lastrowid
    cur.execute(
        """
        INSERT INTO transactions
        (user_id, stripe_event_id, stripe_customer_id, stripe_subscription_id, amount, currency, status, transaction_type, manual, metadata, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            user_id,
            stripe_event_id or "",
            stripe_customer_id or "",
            stripe_subscription_id or "",
            amount,
            (currency or "usd").upper(),
            status,
            payment_type,
            1 if manual else 0,
            json.dumps(metadata or {})[:4000],
            datetime.now().isoformat(),
        ),
    )
    conn.commit()
    conn.close()
    logging.info(
        "PAYMENT_RECORD_CREATED user_id=%s stripe_event_id=%s session_id=%s invoice_id=%s amount=%s currency=%s status=%s",
        user_id,
        stripe_event_id,
        stripe_session_id,
        invoice_id,
        amount,
        currency,
        status,
    )
    logging.info(
        "STRIPE_PAYMENT_RECORD_CREATED payment_record_id=%s user_id=%s stripe_event_id=%s customer_id=%s subscription_id=%s amount=%s",
        payment_record_id,
        user_id,
        stripe_event_id,
        stripe_customer_id,
        stripe_subscription_id,
        amount,
    )
    logging.info("ADMIN_TRANSACTION_SYNCED user_id=%s payment_record_id=%s amount=%s currency=%s status=%s", user_id, payment_record_id, amount, currency, status)
    return payment_record_id


def record_unmatched_payment(event, stripe_object, reason):
    event = event or {}
    stripe_object = stripe_object or {}
    customer_details = stripe_object.get("customer_details") or {}
    customer_email = (
        customer_details.get("email")
        or stripe_object.get("customer_email")
        or stripe_object.get("customer_email_address")
        or stripe_object.get("email")
        or ""
    )
    amount = stripe_object.get("amount_total") or stripe_object.get("amount_paid")
    amount = amount / 100 if amount else None
    conn = db()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO unmatched_payments
        (stripe_event_id, event_type, stripe_object_id, customer_id, customer_email, amount, currency, reason, payload_summary, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            event.get("id") or "",
            event.get("type") or "",
            stripe_object.get("id") or "",
            stripe_object.get("customer") or "",
            customer_email,
            amount,
            (stripe_object.get("currency") or "usd").upper(),
            reason[:500],
            json.dumps({
                "client_reference_id": stripe_object.get("client_reference_id"),
                "metadata": stripe_object.get("metadata") or {},
                "subscription": stripe_object.get("subscription"),
                "payment_status": stripe_object.get("payment_status"),
            })[:2000],
            datetime.now().isoformat(),
        ),
    )
    conn.commit()
    conn.close()
    logging.warning("Stripe payment received but no matching PulseSoc account found. event_id=%s object_id=%s reason=%s", event.get("id"), stripe_object.get("id"), reason)


def stripe_subscription_price_details(subscription):
    subscription = subscription or {}
    prices = []
    for item in ((subscription.get("items") or {}).get("data") or []):
        price = item.get("price") or {}
        if price.get("id"):
            prices.append({"price_id": price.get("id") or "", "product_id": price.get("product") or ""})
    return prices


def stripe_subscription_includes_founder(subscription):
    metadata = (subscription or {}).get("metadata") or {}
    if metadata.get("plan_key") == "founder_premium":
        return True
    return any(item.get("price_id") == STRIPE_FOUNDER_PRICE_ID for item in stripe_subscription_price_details(subscription))


def stripe_checkout_session_is_founder(session):
    session = session or {}
    metadata = session.get("metadata") or {}
    return metadata.get("plan") == "founder_premium" or metadata.get("plan_key") == "founder_premium" or metadata.get("price_id") == STRIPE_FOUNDER_PRICE_ID


def first_stripe_subscription_price(subscription):
    details = stripe_subscription_price_details(subscription)
    return details[0] if details else {"price_id": STRIPE_FOUNDER_PRICE_ID, "product_id": ""}


def founder_user_from_stripe_object(stripe_object, subscription=None):
    stripe_object = stripe_object or {}
    metadata = stripe_object.get("metadata") or {}
    subscription_metadata = (subscription or {}).get("metadata") or {}
    return find_user_by_stripe(
        customer_id=stripe_object.get("customer") or (subscription or {}).get("customer") or "",
        subscription_id=stripe_object.get("subscription") or (subscription or {}).get("id") or "",
        metadata_user_id=metadata.get("user_id") or subscription_metadata.get("user_id") or stripe_object.get("client_reference_id") or metadata.get("client_reference_id"),
        customer_email=(stripe_object.get("customer_details") or {}).get("email") or stripe_object.get("customer_email") or metadata.get("email") or subscription_metadata.get("email"),
    )


def activate_founder_from_stripe_session(session, event_id):
    session = session or {}
    if (session.get("mode") or "subscription") != "subscription":
        logging.warning("PULSE_FOUNDER_CHECKOUT_WRONG_MODE event_id=%s session_id=%s mode=%s", event_id, session.get("id"), session.get("mode"))
        return None
    subscription_id = session.get("subscription") or ""
    subscription = fetch_stripe_subscription(subscription_id) if subscription_id else {}
    if subscription_id and subscription and not stripe_subscription_includes_founder(subscription):
        logging.warning("PULSE_FOUNDER_SESSION_PRICE_MISMATCH event_id=%s session_id=%s", event_id, session.get("id"))
        return None
    user_id = founder_user_from_stripe_object(session, subscription)
    if not user_id:
        record_unmatched_payment({"id": event_id, "type": "checkout.session.completed"}, session, "Founder checkout could not resolve local user")
        return None
    if (session.get("payment_status") or "").lower() not in {"paid", "no_payment_required"} and not subscription_id:
        logging.warning("PULSE_FOUNDER_CHECKOUT_NOT_PAID event_id=%s user_id=%s session_id=%s status=%s", event_id, user_id, session.get("id"), session.get("payment_status"))
        return user_id
    result = premium_entitlement_service.grant_founder_membership(user_id, 0, "stripe_checkout")
    price = first_stripe_subscription_price(subscription)
    premium_entitlement_service.update_founder_stripe_subscription(
        user_id,
        stripe_customer_id=session.get("customer") or (subscription or {}).get("customer") or "",
        stripe_subscription_id=subscription_id,
        stripe_checkout_session_id=session.get("id") or "",
        stripe_price_id=price.get("price_id") or STRIPE_FOUNDER_PRICE_ID,
        stripe_product_id=price.get("product_id") or "",
        provider_status=(subscription or {}).get("status") or session.get("payment_status") or "active",
        status="active",
        current_period_start=stripe_period_end_to_iso((subscription or {}).get("current_period_start")),
        current_period_end=stripe_period_end_to_iso((subscription or {}).get("current_period_end")),
        cancel_at_period_end=bool((subscription or {}).get("cancel_at_period_end")),
        canceled_at=stripe_period_end_to_iso((subscription or {}).get("canceled_at")),
        metadata={"event_id": event_id, "founder_number": result.get("founder_number"), "source": "stripe_checkout"},
    )
    record_payment_record(
        user_id,
        stripe_event_id=event_id,
        stripe_session_id=session.get("id") or "",
        stripe_customer_id=session.get("customer") or "",
        stripe_subscription_id=subscription_id,
        payment_intent_id=session.get("payment_intent") or "",
        amount=(session.get("amount_total") / 100 if session.get("amount_total") else None),
        currency=session.get("currency", "usd"),
        status="succeeded",
        payment_type="stripe_founder",
        metadata={"plan_key": "founder_premium", "founder_number": result.get("founder_number")},
    )
    log_product_event(user_id, "founder_subscription_active", {"event_id": event_id})
    notify_payment_status(
        user_id,
        "payment_success",
        "Founder Premium activated",
        "Stripe confirmed your Founder Premium subscription. Your Founder benefits are active.",
        "/dashboard/economy/subscriptions",
        stripe_event_id=event_id,
        entity_id=session.get("id") or "",
        metadata={"plan_key": "founder_premium", "stripe_session_id": session.get("id") or "", "stripe_subscription_id": subscription_id},
    )
    logging.info("PULSE_FOUNDER_ACTIVATED_FROM_CHECKOUT event_id=%s user_id=%s founder_number=%s", event_id, user_id, result.get("founder_number"))
    return user_id


def sync_founder_subscription_from_stripe(subscription, event_id, event_type):
    subscription = subscription or {}
    if not stripe_subscription_includes_founder(subscription):
        return None
    user_id = founder_user_from_stripe_object(subscription, subscription)
    if not user_id:
        record_unmatched_payment({"id": event_id, "type": event_type}, subscription, "Founder subscription could not resolve local user")
        return None
    raw_status = (subscription.get("status") or "").lower()
    active = raw_status in {"active", "trialing"}
    should_notify = str(event_type or "").startswith("customer.subscription")
    price = first_stripe_subscription_price(subscription)
    period_end = stripe_period_end_to_iso(subscription.get("current_period_end")) or stripe_period_end_to_iso(subscription.get("trial_end"))
    if active:
        result = premium_entitlement_service.grant_founder_membership(user_id, 0, "stripe_subscription")
        local_status = "active"
        logging.info("PULSE_FOUNDER_SUBSCRIPTION_ACTIVE event_id=%s user_id=%s founder_number=%s", event_id, user_id, result.get("founder_number"))
        if should_notify:
            notify_payment_status(
                user_id,
                "subscription_update",
                "Founder Premium active",
                "Stripe confirmed your Founder Premium subscription status.",
                "/dashboard/economy/subscriptions",
                stripe_event_id=event_id,
                entity_id=subscription.get("id") or "",
                metadata={"plan_key": "founder_premium", "stripe_subscription_id": subscription.get("id") or "", "stripe_status": raw_status},
            )
    elif raw_status in {"canceled", "incomplete_expired", "unpaid"} or event_type == "customer.subscription.deleted":
        premium_entitlement_service.revoke_premium_access(user_id, 0, f"stripe_subscription_{raw_status or 'deleted'}")
        local_status = "revoked"
        logging.info("PULSE_FOUNDER_SUBSCRIPTION_REVOKED event_id=%s user_id=%s status=%s", event_id, user_id, raw_status)
        if should_notify:
            notify_payment_status(
                user_id,
                "subscription_canceled",
                "Founder Premium updated",
                "Stripe reported that your Founder Premium subscription is no longer active.",
                "/dashboard/economy/subscriptions",
                stripe_event_id=event_id,
                entity_id=subscription.get("id") or "",
                metadata={"plan_key": "founder_premium", "stripe_subscription_id": subscription.get("id") or "", "stripe_status": raw_status},
            )
    else:
        local_status = raw_status or "inactive"
        logging.info("PULSE_FOUNDER_SUBSCRIPTION_STATUS event_id=%s user_id=%s status=%s", event_id, user_id, raw_status)
        if should_notify:
            notify_payment_status(
                user_id,
                "subscription_update",
                "Founder Premium status updated",
                f"Stripe reported your Founder Premium status as {raw_status or 'inactive'}.",
                "/dashboard/economy/subscriptions",
                stripe_event_id=event_id,
                entity_id=subscription.get("id") or "",
                metadata={"plan_key": "founder_premium", "stripe_subscription_id": subscription.get("id") or "", "stripe_status": raw_status},
            )
    premium_entitlement_service.update_founder_stripe_subscription(
        user_id,
        stripe_customer_id=subscription.get("customer") or "",
        stripe_subscription_id=subscription.get("id") or "",
        stripe_price_id=price.get("price_id") or STRIPE_FOUNDER_PRICE_ID,
        stripe_product_id=price.get("product_id") or "",
        provider_status=raw_status,
        status=local_status,
        current_period_start=stripe_period_end_to_iso(subscription.get("current_period_start")),
        current_period_end=period_end,
        cancel_at_period_end=bool(subscription.get("cancel_at_period_end")),
        canceled_at=stripe_period_end_to_iso(subscription.get("canceled_at")),
        metadata={"event_id": event_id, "event_type": event_type, "stripe_status": raw_status},
    )
    log_product_event(user_id, "founder_subscription_updated", {"event_id": event_id, "stripe_status": raw_status})
    return user_id


def sync_founder_invoice_from_stripe(invoice, event_id, event_type):
    invoice = invoice or {}
    subscription_id = invoice.get("subscription") or ""
    subscription = fetch_stripe_subscription(subscription_id) if subscription_id else {}
    if not subscription or not stripe_subscription_includes_founder(subscription):
        return None
    user_id = founder_user_from_stripe_object(invoice, subscription)
    if not user_id:
        record_unmatched_payment({"id": event_id, "type": event_type}, invoice, "Founder invoice could not resolve local user")
        return None
    if event_type in {"invoice.paid", "invoice.payment_succeeded"}:
        premium_entitlement_service.grant_founder_membership(user_id, 0, "stripe_invoice")
        record_payment_record(
            user_id,
            stripe_event_id=event_id,
            stripe_customer_id=invoice.get("customer") or "",
            stripe_subscription_id=subscription_id,
            invoice_id=invoice.get("id") or "",
            payment_intent_id=invoice.get("payment_intent") or "",
            amount=stripe_amount_to_decimal(invoice.get("amount_paid")),
            currency=invoice.get("currency", "usd"),
            status="succeeded",
            payment_type="stripe_founder_invoice",
            metadata={"plan_key": "founder_premium"},
        )
        notify_payment_status(
            user_id,
            "payment_success",
            "Founder Premium payment confirmed",
            "Stripe confirmed your Founder Premium invoice payment.",
            "/dashboard/economy/subscriptions",
            stripe_event_id=event_id,
            entity_id=invoice.get("id") or "",
            metadata={"plan_key": "founder_premium", "invoice_id": invoice.get("id") or "", "stripe_subscription_id": subscription_id},
        )
        sync_founder_subscription_from_stripe(subscription, event_id, "invoice.subscription.updated")
    elif event_type == "invoice.payment_failed":
        premium_entitlement_service.update_founder_stripe_subscription(
            user_id,
            stripe_customer_id=invoice.get("customer") or "",
            stripe_subscription_id=subscription_id,
            provider_status="past_due",
            status="past_due",
            current_period_end=stripe_period_end_to_iso(subscription.get("current_period_end")),
            metadata={"event_id": event_id, "event_type": event_type},
        )
        notify_payment_status(
            user_id,
            "payment_failed",
            "Founder Premium payment failed",
            "Stripe could not complete your Founder Premium invoice payment. Review billing to keep access active.",
            "/dashboard/economy/subscriptions",
            stripe_event_id=event_id,
            entity_id=invoice.get("id") or "",
            metadata={"plan_key": "founder_premium", "invoice_id": invoice.get("id") or "", "stripe_subscription_id": subscription_id},
        )
        log_product_event(user_id, "founder_subscription_payment_failed", {"event_id": event_id, "invoice": invoice.get("id") or ""})
    return user_id


@webhook_app.route("/stripe-webhook", methods=["GET"])
@webhook_app.route("/stripe/webhook", methods=["GET"])
@webhook_app.route("/api/stripe/webhook", methods=["GET"])
@webhook_app.route("/webhook/stripe", methods=["GET"])
@webhook_app.route("/webhooks/stripe", methods=["GET"])
def stripe_webhook_health():
    return jsonify({
        "ok": True,
        "route": "stripe-webhook",
        "webhook_secret_configured": bool(STRIPE_WEBHOOK_SECRET),
    })


@webhook_app.route("/stripe-webhook", methods=["POST"])
@webhook_app.route("/stripe/webhook", methods=["POST"])
@webhook_app.route("/api/stripe/webhook", methods=["POST"])
@webhook_app.route("/webhook/stripe", methods=["POST"])
@webhook_app.route("/webhooks/stripe", methods=["POST"])
def stripe_webhook():
    init_db()
    payload = request.data
    sig_header = request.headers.get("Stripe-Signature")
    logging.info("STRIPE_WEBHOOK_RECEIVED path=%s payload_bytes=%s signature_present=%s", request.path, len(payload or b""), bool(sig_header))

    try:
        if STRIPE_WEBHOOK_SECRET:
            stripe.Webhook.construct_event(
                payload,
                sig_header,
                STRIPE_WEBHOOK_SECRET
            )
            event = json.loads(payload.decode("utf-8"))
            logging.info("STRIPE_SIGNATURE_VERIFIED signature_present=%s", bool(sig_header))
        else:
            logging.error("STRIPE_WEBHOOK_SECRET missing. Refusing unsigned live Stripe webhook; configure Railway STRIPE_WEBHOOK_SECRET.")
            return "Webhook secret missing", 503
    except Exception as e:
        logging.exception("Stripe webhook error details: %s", e)
        return "Invalid", 400

    event_type = event.get("type")
    if not event_type or not isinstance(event.get("data"), dict):
        logging.warning("Stripe webhook invalid event payload event_id=%s event_type=%s", event.get("id"), event_type)
        return "Invalid", 400

    logging.info("STRIPE_EVENT_RECEIVED event_type=%s event_id=%s", event_type, event.get("id"))
    logging.info("STRIPE_EVENT_TYPE event_type=%s event_id=%s", event_type, event.get("id"))
    logging.info("stripe webhook received event_type=%s event_id=%s", event_type, event.get("id"))
    event_id = event.get("id", "")
    webhook_record = creator_economy_service.record_webhook_event(event_id, event_type, event, status="received")
    if webhook_record.get("duplicate"):
        logging.info("Payment webhook duplicate skipped provider_event_id=%s event_type=%s", event_id, event_type)
        return "OK", 200
    if stripe_event_processed(event_id):
        logging.info("Stripe webhook duplicate skipped event_id=%s event_type=%s", event_id, event.get("type"))
        creator_economy_service.update_webhook_event(event_id, "skipped", "legacy stripe_events already processed")
        return "OK", 200
    resolved_event_user_id = None

    if event_type == "checkout.session.completed":
        session = event["data"]["object"]
        session_id = session.get("id")
        logging.info("STRIPE_USER_MATCH_START event_id=%s object_id=%s customer_id=%s", event_id, session_id, session.get("customer"))
        user_id, resolved_email = resolve_checkout_session_user(session)
        payment_status = session.get("payment_status")
        subscription_id = session.get("subscription")
        customer_id = session.get("customer")
        metadata = session.get("metadata") or {}
        if metadata.get("purpose") == "pulse_ad_wallet_funding":
            conn = db()
            conn.row_factory = sqlite3.Row
            try:
                if payment_status in {"paid", "no_payment_required"}:
                    pulse_ad_payments.credit_wallet_from_stripe_session(conn, event_id, session)
                else:
                    logging.warning("PulseSoc ad wallet checkout completed without paid status event_id=%s status=%s", event_id, payment_status)
            finally:
                conn.close()
            creator_economy_service.update_webhook_event(event_id, "processed")
            record_stripe_event(event, "processed", safe_int(metadata.get("user_id"), 0) or None)
            return "OK", 200
        if metadata.get("transaction_id"):
            tx_id = safe_int(metadata.get("transaction_id"), 0)
            if payment_status in {"paid", "no_payment_required"} and tx_id:
                creator_economy_service.attach_checkout(tx_id, provider_checkout_id=session_id, provider_payment_id=session.get("payment_intent") or "")
                creator_economy_service.mark_transaction_paid(tx_id, provider_payment_id=session.get("payment_intent") or "", provider_reference=session_id)
                if metadata.get("item_type") == "premium" and metadata.get("buyer_user_id"):
                    premium_entitlement_service.sync_subscription_entitlements(int(metadata.get("buyer_user_id") or 0), metadata.get("item_id") or "pulse_premium", "active", source="stripe_checkout")
                conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
                if metadata.get("seller_user_id"):
                    notify_user(cur, int(metadata.get("seller_user_id") or 0), "seller_payment", "Payment received", "A buyer completed checkout. Your pending balance has been updated.", f"/pulse/{metadata.get('seller_type')}/payouts")
                if metadata.get("buyer_user_id"):
                    notify_user(cur, int(metadata.get("buyer_user_id") or 0), "purchase", "Payment complete", "Your purchase was completed successfully.", "/pulse")
                conn.commit(); conn.close()
            creator_economy_service.update_webhook_event(event_id, "processed")
            record_stripe_event(event, "processed", safe_int(metadata.get("buyer_user_id"), 0) or None)
            return "OK", 200
        if metadata.get("seller_transaction_id"):
            tx_id = safe_int(metadata.get("seller_transaction_id"), 0)
            now = datetime.utcnow().isoformat(timespec="seconds")
            conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
            cur.execute("SELECT * FROM seller_transactions WHERE id=? LIMIT 1", (tx_id,))
            tx = dict(cur.fetchone() or {})
            if tx:
                status = "checkout_completed" if payment_status in {"paid", "no_payment_required"} else f"checkout_{payment_status or 'completed'}"
                cur.execute(
                    "UPDATE seller_transactions SET status=?, stripe_checkout_session_id=?, stripe_payment_intent_id=?, updated_at=? WHERE id=?",
                    (status, session_id, session.get("payment_intent") or "", now, tx_id),
                )
                notify_user(cur, tx.get("seller_user_id"), "seller_payment", "Payment received", "A buyer completed checkout. Your payout status will update after Stripe settlement.", "/admin/payments" if False else f"/pulse/{tx.get('seller_type')}/payouts")
                notify_user(cur, tx.get("buyer_user_id"), "purchase", "Payment complete", "Your purchase was completed successfully.", "/pulse")
                conn.commit()
                resolved_event_user_id = int(tx.get("buyer_user_id") or 0) or None
            conn.close()
            record_stripe_event(event, "processed", resolved_event_user_id)
            creator_economy_service.update_webhook_event(event_id, "processed")
            return "OK", 200
        if stripe_checkout_session_is_founder(session):
            resolved_event_user_id = activate_founder_from_stripe_session(session, event_id)
            record_stripe_event(event, "processed", resolved_event_user_id)
            creator_economy_service.update_webhook_event(event_id, "processed")
            return "OK", 200
        logging.info(
            "checkout.session.completed received event_id=%s session_id=%s customer_id=%s customer_email=%s client_reference_id=%s metadata_user_id=%s payment_status=%s subscription_id=%s resolved_user_id=%s",
            event_id,
            session_id,
            customer_id,
            bool(resolved_email),
            session.get("client_reference_id"),
            metadata.get("user_id"),
            payment_status,
            subscription_id,
            user_id,
        )
        if user_id:
            logging.info("STRIPE_USER_MATCHED event_id=%s user_id=%s session_id=%s", event_id, user_id, session_id)
            resolved_event_user_id = user_id
            customer_details = session.get("customer_details") or {}
            customer_email = customer_details.get("email") or session.get("customer_email") or resolved_email
            if customer_email and is_valid_email(customer_email):
                save_user_email(user_id, customer_email)
            subscription = fetch_stripe_subscription(subscription_id) if subscription_id else None
            period_end = (
                stripe_period_end_to_iso((subscription or {}).get("current_period_end"))
                or stripe_period_end_to_iso((subscription or {}).get("trial_end"))
            ) if subscription else None
            if payment_status == "paid" or subscription_id:
                timestamp = datetime.now().isoformat()
                logging.info("STRIPE_PRO_ACTIVATION_START event_id=%s user_id=%s session_id=%s subscription_id=%s", event_id, user_id, session_id, subscription_id)
                activated_user_id = activate_pro(
                    user_id,
                    payment_type="stripe",
                    stripe_customer_id=customer_id,
                    stripe_session_id=session_id,
                    stripe_subscription_id=subscription_id,
                    subscription_status="active" if payment_status == "paid" else ((subscription or {}).get("status") or "active"),
                    pro_expires_at=period_end,
                    stripe_event_id=event_id,
                    payment_status=payment_status or "paid",
                    payment_amount=(session.get("amount_total") / 100 if session.get("amount_total") else None),
                    payment_currency=session.get("currency", "usd"),
                )
                logging.info("STRIPE_PRO_ACTIVATION_COMMITTED event_id=%s user_id=%s activated_user_id=%s", event_id, user_id, activated_user_id)
                logging.info("STRIPE_USER_UPGRADED event_id=%s user_id=%s activated_user_id=%s", event_id, user_id, activated_user_id)
                save_payment_verification(
                    user_id,
                    txid=session_id,
                    payment_type="stripe",
                    amount=(session.get("amount_total") / 100 if session.get("amount_total") else None),
                    status="verified",
                    details=f"Stripe checkout.session.completed at {timestamp}",
                )
                record_payment_record(
                    activated_user_id or user_id,
                    stripe_event_id=event_id,
                    stripe_session_id=session_id,
                    stripe_customer_id=customer_id,
                    stripe_subscription_id=subscription_id,
                    payment_intent_id=session.get("payment_intent") or "",
                    amount=(session.get("amount_total") / 100 if session.get("amount_total") else None),
                    currency=session.get("currency", "usd"),
                    status="succeeded",
                )
                logging.info("TRANSACTION_CREATED event_id=%s user_id=%s session_id=%s amount=%s", event_id, activated_user_id or user_id, session_id, session.get("amount_total"))
                if activated_user_id:
                    send_telegram_confirmation(
                        activated_user_id,
                        "✅ PulseSoc Premium activated successfully.\n\n"
                        "Your card payment was confirmed by Stripe, and your Premium access is now active.\n\n"
                        "Educational only — not financial advice.\n"
                        "CoinPilotX will never ask for your seed phrase or private key."
                    )
                user = load_account_by_id(activated_user_id or user_id)
                if user and has_pro_access(user):
                    logging.info("PAYMENT_SUCCESS_VERIFIED event_id=%s user_id=%s", event_id, user["user_id"])
                    send_successful_payment_email_bundle(user, {
                        "stripe_event_id": event_id,
                        "stripe_session_id": session_id,
                        "payment_id": session_id or session.get("payment_intent") or "",
                        "amount": (session.get("amount_total") / 100 if session.get("amount_total") else None),
                        "currency": session.get("currency", "usd"),
                        "billing_date": datetime.now().strftime("%b %d, %Y"),
                        "next_billing_date": format_date(period_end) if period_end else "",
                    })
                    logging.info("upgrade confirmation email sent/skipped after successful DB Pro update user_id=%s event_id=%s", user["user_id"], event_id)
                logging.info("Checkout session activated Pro user_id=%s session_id=%s database_commit_success=%s", user_id, session_id, bool(activated_user_id))
            else:
                save_payment_verification(
                    user_id,
                    txid=session_id,
                    payment_type="stripe",
                    amount=None,
                    status=f"not_activated_{payment_status or 'unknown'}",
                    details="Stripe checkout completed but payment_status was not paid.",
                )
                logging.warning("Stripe session not activated user_id=%s session_id=%s payment_status=%s", user_id, session_id, payment_status)
        else:
            logging.error("STRIPE_USER_NOT_FOUND event_id=%s session_id=%s customer_id=%s email_present=%s", event_id, session_id, customer_id, bool(resolved_email))
            logging.error("checkout.session.completed could not resolve local user session_id=%s customer_id=%s email=%s", session_id, customer_id, bool(resolved_email))
            record_unmatched_payment(event, session, "checkout.session.completed could not resolve local user")

    if event_type in {"customer.subscription.created", "customer.subscription.updated", "customer.subscription.deleted"}:
        subscription_object = event["data"]["object"]
        logging.info("STRIPE_USER_MATCH_START event_id=%s object_id=%s customer_id=%s", event_id, subscription_object.get("id"), subscription_object.get("customer"))
        if stripe_subscription_includes_founder(subscription_object):
            synced_user_id = sync_founder_subscription_from_stripe(subscription_object, event_id, event_type)
            record_stripe_event(event, "processed", synced_user_id)
            creator_economy_service.update_webhook_event(event_id, "processed")
            return "OK", 200
        synced_user_id = sync_stripe_subscription(event["data"]["object"])
        if synced_user_id:
            resolved_event_user_id = synced_user_id
        if synced_user_id and event_type in {"customer.subscription.created", "customer.subscription.updated"}:
            subscription = event["data"]["object"]
            if (subscription.get("status") or "").lower() == "active":
                user = load_account_by_id(synced_user_id)
                if user:
                    logging.info("PAYMENT_SUCCESS_VERIFIED subscription_event=%s user_id=%s", event_id, synced_user_id)
                    send_successful_payment_email_bundle(user, {
                        "stripe_event_id": event_id,
                        "stripe_session_id": subscription.get("latest_invoice") or subscription.get("id"),
                        "payment_id": subscription.get("latest_invoice") or subscription.get("id"),
                        "next_billing_date": format_date(stripe_period_end_to_iso(subscription.get("current_period_end"))),
                    })
                    logging.info("upgrade confirmation email sent/skipped for subscription event user_id=%s event_id=%s", synced_user_id, event_id)
        if synced_user_id and event_type == "customer.subscription.deleted":
            subscription = event["data"]["object"]
            user = load_account_by_id(synced_user_id)
            if user:
                send_subscription_canceled_email(user, {
                    "access_until": format_date(stripe_period_end_to_iso(subscription.get("current_period_end"))),
                    "stripe_event_id": event_id,
                    "subscription_id": subscription.get("id") or "",
                })
        if not synced_user_id:
            logging.error("STRIPE_USER_NOT_FOUND event_id=%s object_id=%s customer_id=%s", event_id, event["data"]["object"].get("id"), event["data"]["object"].get("customer"))
            record_unmatched_payment(event, event["data"]["object"], "subscription event could not resolve local user")

    if event_type in {"invoice.paid", "invoice.payment_succeeded", "invoice.payment_failed"}:
        invoice_object = event["data"]["object"]
        logging.info("STRIPE_USER_MATCH_START event_id=%s object_id=%s customer_id=%s", event_id, invoice_object.get("id"), invoice_object.get("customer"))
        founder_invoice_user_id = sync_founder_invoice_from_stripe(invoice_object, event_id, event_type)
        if founder_invoice_user_id:
            record_stripe_event(event, "processed", founder_invoice_user_id)
            creator_economy_service.update_webhook_event(event_id, "processed")
            return "OK", 200
        synced_user_id = sync_stripe_invoice(event["data"]["object"], event_type)
        if synced_user_id:
            resolved_event_user_id = synced_user_id
        if synced_user_id and event_type in {"invoice.paid", "invoice.payment_succeeded"}:
            invoice = event["data"]["object"]
            user = load_account_by_id(synced_user_id)
            if user:
                amount = invoice.get("amount_paid")
                record_payment_record(
                    synced_user_id,
                    stripe_event_id=event_id,
                    stripe_customer_id=invoice.get("customer") or "",
                    stripe_subscription_id=invoice.get("subscription") or "",
                    invoice_id=invoice.get("id") or "",
                    payment_intent_id=invoice.get("payment_intent") or "",
                    amount=(amount / 100 if amount else None),
                    currency=invoice.get("currency", "usd"),
                    status="succeeded",
                )
                logging.info("PAYMENT_SUCCESS_VERIFIED invoice_event=%s user_id=%s", event_id, synced_user_id)
                send_successful_payment_email_bundle(user, {
                    "stripe_event_id": event_id,
                    "stripe_session_id": invoice.get("id"),
                    "invoice_id": invoice.get("id"),
                    "payment_id": invoice.get("id") or invoice.get("payment_intent") or "",
                    "amount": (amount / 100 if amount else None),
                    "currency": invoice.get("currency", "usd"),
                    "billing_date": datetime.now().strftime("%b %d, %Y"),
                })
                logging.info("upgrade confirmation email sent/skipped for invoice event user_id=%s event_id=%s", synced_user_id, event_id)
        if synced_user_id and event_type == "invoice.payment_failed":
            invoice = event["data"]["object"]
            user = load_account_by_id(synced_user_id)
            if user:
                send_payment_issue_email(user, {"invoice_id": invoice.get("id"), "stripe_event_id": event_id})
        if not synced_user_id:
            logging.error("STRIPE_USER_NOT_FOUND event_id=%s object_id=%s customer_id=%s", event_id, event["data"]["object"].get("id"), event["data"]["object"].get("customer"))
            record_unmatched_payment(event, event["data"]["object"], "invoice event could not resolve local user")

    if event_type == "payment_intent.succeeded":
        payment_intent = event["data"]["object"]
        metadata = payment_intent.get("metadata") or {}
        if metadata.get("transaction_id"):
            tx_id = safe_int(metadata.get("transaction_id"), 0)
            if tx_id:
                creator_economy_service.attach_checkout(tx_id, provider_payment_id=payment_intent.get("id") or "")
                creator_economy_service.mark_transaction_paid(tx_id, provider_payment_id=payment_intent.get("id") or "", provider_reference=event_id)
                creator_economy_service.update_webhook_event(event_id, "processed")
                record_stripe_event(event, "processed", safe_int(metadata.get("buyer_user_id"), 0) or None)
                return "OK", 200
        if metadata.get("seller_transaction_id"):
            tx_id = safe_int(metadata.get("seller_transaction_id"), 0)
            now = datetime.utcnow().isoformat(timespec="seconds")
            conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
            cur.execute("SELECT * FROM seller_transactions WHERE id=? LIMIT 1", (tx_id,))
            tx = dict(cur.fetchone() or {})
            if tx:
                cur.execute("UPDATE seller_transactions SET status='paid', stripe_payment_intent_id=?, updated_at=? WHERE id=?", (payment_intent.get("id") or "", now, tx_id))
                notify_user(cur, tx.get("seller_user_id"), "seller_payment", "Payment succeeded", "Stripe confirmed a seller payment. Net payout is tracked in your payout dashboard.", f"/pulse/{tx.get('seller_type')}/payouts")
                resolved_event_user_id = int(tx.get("buyer_user_id") or 0) or None
                conn.commit()
            conn.close()
            record_stripe_event(event, "processed", resolved_event_user_id)
            creator_economy_service.update_webhook_event(event_id, "processed")
            return "OK", 200
        customer_id = payment_intent.get("customer") or ""
        user_id = find_user_by_stripe(
            customer_id=customer_id,
            subscription_id=None,
            metadata_user_id=metadata.get("user_id") or metadata.get("client_reference_id"),
            customer_email=metadata.get("email"),
        )
        if user_id:
            resolved_event_user_id = user_id
            amount = payment_intent.get("amount_received") or payment_intent.get("amount")
            activated_user_id = activate_pro(
                user_id,
                payment_type="stripe",
                stripe_customer_id=customer_id,
                subscription_status="active",
                pro_expires_at=default_pro_period_end(),
                stripe_event_id=event_id,
                payment_status="paid",
                payment_amount=(amount / 100 if amount else None),
                payment_currency=payment_intent.get("currency", "usd"),
            )
            record_payment_record(
                activated_user_id or user_id,
                stripe_event_id=event_id,
                stripe_customer_id=customer_id,
                payment_intent_id=payment_intent.get("id") or "",
                amount=(amount / 100 if amount else None),
                currency=payment_intent.get("currency", "usd"),
                status="succeeded",
            )
            user = load_account_by_id(activated_user_id or user_id)
            if user and has_pro_access(user):
                send_successful_payment_email_bundle(user, {
                    "stripe_event_id": event_id,
                    "payment_id": payment_intent.get("id") or "",
                    "amount": (amount / 100 if amount else None),
                    "currency": payment_intent.get("currency", "usd"),
                    "billing_date": datetime.now().strftime("%b %d, %Y"),
                    "next_billing_date": format_date(user.get("pro_expires_at") or user.get("subscription_expires_at")),
                })
            logging.info("PAYMENT_INTENT_PRO_ACTIVATED event_id=%s user_id=%s activated_user_id=%s", event_id, user_id, activated_user_id)
        else:
            logging.error("STRIPE_USER_NOT_FOUND event_id=%s object_id=%s customer_id=%s", event_id, payment_intent.get("id"), customer_id)
            record_unmatched_payment(event, payment_intent, "payment_intent.succeeded could not resolve local user")

    if event_type == "payment_intent.payment_failed":
        payment_intent = event["data"]["object"]
        metadata = payment_intent.get("metadata") or {}
        tx_id = safe_int(metadata.get("transaction_id") or metadata.get("seller_transaction_id"), 0)
        failure = payment_intent.get("last_payment_error") or {}
        now = datetime.utcnow().isoformat(timespec="seconds")
        if tx_id:
            conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
            cur.execute("UPDATE creator_transactions SET status='failed', updated_at=? WHERE id=?", (now, tx_id))
            cur.execute("UPDATE seller_transactions SET status='failed', metadata_json=?, updated_at=? WHERE id=?", (json.dumps({"stripe_event_id": event_id, "failure": failure}, default=str)[:4000], now, tx_id))
            conn.commit(); conn.close()
            resolved_event_user_id = safe_int(metadata.get("buyer_user_id"), 0) or resolved_event_user_id
        else:
            customer_id = payment_intent.get("customer") or ""
            user_id = find_user_by_stripe(
                customer_id=customer_id,
                subscription_id=None,
                metadata_user_id=metadata.get("user_id") or metadata.get("client_reference_id"),
                customer_email=metadata.get("email"),
            )
            if user_id:
                resolved_event_user_id = user_id
                record_payment_record(
                    user_id,
                    stripe_event_id=event_id,
                    stripe_customer_id=customer_id,
                    payment_intent_id=payment_intent.get("id") or "",
                    amount=stripe_amount_to_decimal(payment_intent.get("amount")),
                    currency=payment_intent.get("currency", "usd"),
                    status="failed",
                    payment_type="stripe_payment_intent",
                    metadata={"failure": failure},
                )
                notify_payment_status(
                    user_id,
                    "payment_failed",
                    "Payment failed",
                    "Stripe reported a failed payment. Review billing to keep PulseSoc access current.",
                    "/dashboard/economy/subscriptions",
                    stripe_event_id=event_id,
                    entity_id=payment_intent.get("id") or "",
                    metadata={"payment_intent_id": payment_intent.get("id") or "", "failure": failure},
                )
            else:
                record_unmatched_payment(event, payment_intent, "payment_intent.payment_failed could not resolve local user")

    if event_type in {"account.updated", "payout.paid", "payout.failed", "charge.refunded", "charge.dispute.created"}:
        obj = event["data"]["object"]
        now = datetime.utcnow().isoformat(timespec="seconds")
        conn = db(); conn.row_factory = sqlite3.Row; cur = conn.cursor()
        if event_type == "account.updated":
            acct = obj.get("id") or ""
            requirements = (obj.get("requirements") or {}).get("currently_due") or []
            cur.execute(
                """
                UPDATE seller_payout_accounts
                SET onboarding_status=?, payouts_enabled=?, charges_enabled=?, missing_requirements_json=?, last_checked_at=?, updated_at=?
                WHERE connected_account_id=?
                """,
                ("complete" if obj.get("payouts_enabled") and obj.get("charges_enabled") else "requirements_due", 1 if obj.get("payouts_enabled") else 0, 1 if obj.get("charges_enabled") else 0, json.dumps(requirements, default=str), now, now, acct),
            )
        elif event_type in {"payout.paid", "payout.failed"}:
            destination = obj.get("destination") or obj.get("account") or ""
            cur.execute("SELECT * FROM seller_payout_accounts WHERE connected_account_id=? LIMIT 1", (destination,))
            account = dict(cur.fetchone() or {})
            if account:
                cur.execute(
                    "INSERT INTO seller_payouts (user_id, seller_type, amount_cents, currency, status, provider, provider_payout_id, failure_reason, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 'stripe', ?, ?, ?, ?)",
                    (account.get("user_id"), account.get("seller_type"), int(obj.get("amount") or 0), (obj.get("currency") or "usd").upper(), "paid" if event_type == "payout.paid" else "failed", obj.get("id") or "", obj.get("failure_message") or "", now, now),
                )
        else:
            metadata = obj.get("metadata") or {}
            if metadata.get("transaction_id"):
                tx_id = safe_int(metadata.get("transaction_id"), 0)
                if tx_id:
                    if event_type == "charge.refunded":
                        creator_economy_service.handle_refund(tx_id, int(obj.get("amount_refunded") or obj.get("amount") or 0), provider_reference=obj.get("id") or event_id)
                    elif event_type == "charge.dispute.created":
                        conn2 = db(); cur2 = conn2.cursor()
                        cur2.execute("UPDATE creator_transactions SET status='disputed', updated_at=? WHERE id=?", (now, tx_id))
                        conn2.commit(); conn2.close()
            tx_id = safe_int(metadata.get("seller_transaction_id"), 0)
            if tx_id:
                status = "refunded" if event_type == "charge.refunded" else "dispute_opened"
                cur.execute("UPDATE seller_transactions SET status=?, updated_at=? WHERE id=?", (status, now, tx_id))
        conn.commit(); conn.close()

    record_stripe_event(event, "processed", resolved_event_user_id)
    creator_economy_service.update_webhook_event(event_id, "processed")
    return "OK", 200

def scan_confirm_menu():
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("✅ Yes, scan it", callback_data="scan_confirm"),
            InlineKeyboardButton("❌ No, don’t scan", callback_data="scan_cancel"),
        ]
    ])


def ensure_user(user):
    conn = db()
    cur = conn.cursor()

    cur.execute("SELECT user_id FROM users WHERE user_id=?", (user.id,))
    exists = cur.fetchone()

    if not exists:
        cur.execute("""
        INSERT INTO users (user_id, username, display_name, email, signup_time, onboarding_complete, alerts_enabled)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """, (
            user.id,
            user.username,
            user.first_name or "",
            "",
            datetime.now().isoformat(),
            0,
            0
        ))

        for asset in ["BTC", "ETH", "SOL"]:
            cur.execute("INSERT OR IGNORE INTO watchlists VALUES (?, ?)", (user.id, asset))
            cur.execute("INSERT OR IGNORE INTO manual_portfolio VALUES (?, ?, ?)", (user.id, asset, 0.0))
            cur.execute("INSERT OR IGNORE INTO paper_portfolio VALUES (?, ?, ?)", (user.id, asset, 0.0))

        cur.execute("INSERT OR IGNORE INTO paper_portfolio VALUES (?, ?, ?)", (user.id, "USD", 10000.0))

    conn.commit()
    conn.close()


def get_user_name(user_id):
    conn = db()
    cur = conn.cursor()
    cur.execute("SELECT display_name FROM users WHERE user_id=?", (user_id,))
    row = cur.fetchone()
    conn.close()
    return row[0] if row and row[0] else "friend"


def onboarding_complete(user_id):
    conn = db()
    cur = conn.cursor()
    cur.execute("SELECT onboarding_complete FROM users WHERE user_id=?", (user_id,))
    row = cur.fetchone()
    conn.close()
    return bool(row and row[0] == 1)


def save_user_name(user_id, name):
    conn = db()
    cur = conn.cursor()
    cur.execute("UPDATE users SET display_name=? WHERE user_id=?", (name, user_id))
    conn.commit()
    conn.close()


def save_user_email(user_id, email):
    conn = db()
    cur = conn.cursor()
    cur.execute("UPDATE users SET email=?, onboarding_complete=1 WHERE user_id=?", (email, user_id))
    conn.commit()
    conn.close()
    user = load_account_by_id(user_id)
    if user:
        sync_brevo_contact_safe({**user, "source": "telegram_email"}, entity_type="user", entity_id=user_id)


def is_valid_email(email):
    return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", (email or "").strip()))


def get_user_email(user_id):
    conn = db()
    cur = conn.cursor()
    cur.execute("SELECT email FROM users WHERE user_id=?", (user_id,))
    row = cur.fetchone()
    conn.close()
    return row[0] if row and row[0] else ""


def brevo_config_diagnostics():
    status = email_service_service.provider_status()
    sender_email = status.get("sender_email") or ""
    return {
        "provider": "brevo",
        "ready": bool(status.get("ready")),
        "enabled": bool(status.get("enabled")),
        "api_key_configured": bool(status.get("api_key_configured")),
        "api_key_source": status.get("api_key_source") or "",
        "api_key_has_surrounding_whitespace": bool(status.get("api_key_has_surrounding_whitespace")),
        "sender_email_configured": bool(status.get("sender_email_configured")),
        "sender_name_configured": bool(status.get("sender_name_configured")),
        "default_from_email_configured": bool(status.get("default_from_email_configured")),
        "support_email_configured": bool(status.get("support_email_configured")),
        "security_email_configured": bool(status.get("security_email_configured")),
        "public_base_url_configured": bool(os.getenv("PUBLIC_BASE_URL") or os.getenv("PULSE_APP_URL") or os.getenv("APP_BASE_URL")),
        "missing_fields": list(status.get("missing_fields") or []),
        "sender_email": sender_email,
        "sender_email_masked": mask_email(sender_email) if sender_email else "",
        "sender_name": status.get("sender_name") or "",
        "sender_email_source": status.get("sender_email_source") or "",
        "sender_name_source": status.get("sender_name_source") or "",
        "sender_domain": status.get("sender_domain") or "",
        "using_default_sender": bool(status.get("using_default_sender")),
        "public_base_url": public_app_base_url(),
    }


def safe_brevo_error_reason(result=None, fallback=""):
    result = result or {}
    missing = result.get("missing_fields") or []
    status_code = result.get("status_code")
    if missing:
        return "Brevo is not fully configured. Missing: " + ", ".join(str(x) for x in missing)
    if result.get("error_code") == "brevo_unauthorized_ip":
        return "Brevo rejected the request because the Railway server IP is not authorized in Brevo."
    if status_code == 401 or result.get("error_code") == "brevo_unauthorized":
        return "Brevo rejected the request. Check BREVO_API_KEY in Railway."
    if status_code == 403 or result.get("error_code") == "brevo_forbidden":
        return "Brevo rejected the sender or domain. Verify BREVO_SENDER_EMAIL and domain authentication in Brevo."
    if status_code == 429 or result.get("error_code") == "brevo_rate_limited":
        return "Brevo rate limit reached. Retry shortly."
    raw = str(result.get("error") or fallback or "").strip()
    if not raw:
        response = result.get("response") or {}
        if isinstance(response, dict):
            raw = str(response.get("message") or response.get("code") or "").strip()
    return clean_html(raw or "Email provider rejected or unavailable.")[:500]


def email_status_from_result(result):
    if result.get("ok"):
        return "sent_brevo"
    if result.get("missing_fields") or result.get("error_code") == "brevo_not_configured":
        return "failed_brevo_not_configured"
    if result.get("error_code") == "brevo_unauthorized_ip":
        return "failed_brevo_unauthorized_ip"
    if result.get("status_code") == 401 or result.get("error_code") == "brevo_unauthorized":
        return "failed_brevo_401"
    if result.get("status_code") == 403 or result.get("error_code") == "brevo_forbidden":
        return "failed_brevo_403"
    if result.get("status_code") == 429 or result.get("error_code") == "brevo_rate_limited":
        return "failed_brevo_rate_limited"
    return f"failed_brevo_{result.get('status_code') or 'not_configured'}"


def log_email_status(user_id, email, subject, status, email_type="", provider="brevo", provider_status_code=None, provider_message_id="", safe_error_reason="", metadata=None, trace_id="", retry_count=0):
    subject_lower = (subject or "").lower()
    email_type = email_type or "transactional"
    if email_type == "transactional":
        if "welcome" in subject_lower:
            email_type = "welcome"
        elif "reset" in subject_lower:
            email_type = "password_reset"
        elif "password was changed" in subject_lower:
            email_type = "password_changed"
        elif "upgrade" in subject_lower or "subscription" in subject_lower:
            email_type = "subscription"
        elif "verify" in subject_lower:
            email_type = "email_verification"
    trace_id = trace_id or secrets.token_hex(6)
    conn = None
    try:
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO email_logs
            (user_id, email, recipient_email, email_type, subject, status, provider, provider_status_code,
             provider_message_id, safe_error_reason, error_message, metadata, trace_id, retry_count, delivery_status, created_at, sent_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                user_id,
                email,
                email,
                email_type,
                subject,
                status,
                provider or "brevo",
                provider_status_code,
                provider_message_id or "",
                safe_error_reason or "",
                safe_error_reason or "",
                json.dumps(metadata or {}, default=str)[:2000],
                trace_id,
                int(retry_count or 0),
                "sent" if str(status or "").startswith("sent") else "failed" if str(status or "").startswith("failed") else "",
                datetime.now().isoformat(),
                datetime.now().isoformat() if str(status or "").startswith("sent") else "",
            )
        )
        conn.commit()
        return True
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.warning("EMAIL_STATUS_LOG_FAILED trace_id=%s status=%s error=%s", trace_id, status, exc.__class__.__name__)
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def finalize_email_log_for_trace(trace_id, queued_row, status, result=None, safe_error_reason="", retry_count=0, delivery_status=""):
    """Update the original queued email log after the outbox job reaches Brevo."""
    trace_id = str(trace_id or "").strip()
    result = result or {}
    if not trace_id:
        return False
    sent_at = datetime.now().isoformat() if str(status or "").startswith("sent") else ""
    metadata = {
        "queue_id": (queued_row or {}).get("id"),
        "queue_status": delivery_status or status,
        "provider_response": result.get("provider_response") or result.get("response") or {},
        "missing_fields": result.get("missing_fields") or [],
    }
    conn = None
    try:
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            UPDATE email_logs
            SET status=?, provider=?, provider_status_code=?, provider_message_id=?,
                safe_error_reason=?, error_message=?, retry_count=?, delivery_status=?,
                sent_at=CASE WHEN ?<>'' THEN ? ELSE sent_at END,
                metadata=?
            WHERE trace_id=?
            """,
            (
                status,
                "brevo",
                result.get("status_code"),
                str(result.get("message_id") or "")[:240],
                safe_error_reason or "",
                safe_error_reason or "",
                int(retry_count or 0),
                delivery_status or ("sent" if str(status or "").startswith("sent") else "failed" if str(status or "").startswith("failed") else ""),
                sent_at,
                sent_at,
                json.dumps(metadata, default=str)[:2000],
                trace_id,
            ),
        )
        updated = int(getattr(cur, "rowcount", 0) or 0)
        conn.commit()
        return updated > 0
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.warning("EMAIL_LOG_FINALIZE_FAILED trace_id=%s status=%s error=%s", trace_id, status, exc.__class__.__name__)
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def queue_failed_email(user_id, recipient_email, email_type, subject, html_body="", text_body="", error_message="", metadata=None, *, idempotency_key="", due_now=False):
    """Persist an email outbox job without contacting the provider."""
    conn = None
    trace_id = secrets.token_hex(8)
    try:
        conn = db()
        cur = conn.cursor()
        now = datetime.now().isoformat()
        key = str(idempotency_key or "")[:240]
        if key:
            cur.execute(
                "SELECT id, status, trace_id FROM failed_email_queue WHERE idempotency_key=? ORDER BY id DESC LIMIT 1",
                (key,),
            )
            existing = cur.fetchone()
            if existing and str(existing[1] or "") not in {"dead_letter", "cancelled"}:
                return {"ok": True, "status": str(existing[1] or "queued"), "id": int(existing[0] or 0), "trace_id": str(existing[2] or trace_id), "duplicate": True}
        next_retry_at = now if due_now else (datetime.now() + timedelta(minutes=5)).isoformat()
        cur.execute(
            """
            INSERT INTO failed_email_queue
            (user_id, recipient_email, email_type, subject, html_body, text_body, metadata, status,
             retry_count, max_attempts, last_error, next_retry_at, trace_id, idempotency_key, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', 0, 5, ?, ?, ?, ?, ?, ?)
            """,
            (
                user_id or 0,
                recipient_email or "",
                email_type or "transactional",
                subject or "",
                html_body or "",
                text_body or "",
                json.dumps(metadata or {}),
                str(error_message or "")[:1000],
                next_retry_at,
                trace_id,
                key,
                now,
                now,
            ),
        )
        queue_id = int(cur.lastrowid or 0)
        conn.commit()
        logging.info("EMAIL_JOB_QUEUED id=%s trace_id=%s user_id=%s email_type=%s", queue_id, trace_id, user_id or 0, email_type or "transactional")
        if due_now:
            schedule_email_delivery_processing(reason="email_job_queued")
        return {"ok": True, "status": "queued", "id": queue_id, "trace_id": trace_id}
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.warning("EMAIL_JOB_ENQUEUE_FAILED user_id=%s email_type=%s error=%s detail=%s", user_id or 0, email_type or "transactional", exc.__class__.__name__, str(exc)[:300])
        return {"ok": False, "status": "failed", "trace_id": trace_id, "error": exc.__class__.__name__}
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def enqueue_platform_email(to_email, subject, text_body, html_body="", user_id=None, *, email_type="transactional", idempotency_key="", metadata=None):
    if not to_email:
        return {"ok": False, "status": "skipped", "trace_id": secrets.token_hex(8)}
    result = queue_failed_email(
        user_id or 0,
        to_email,
        email_type,
        subject,
        html_body,
        text_body,
        metadata=metadata,
        idempotency_key=idempotency_key,
        due_now=True,
    )
    try:
        log_email_status(
            user_id or 0,
            to_email,
            subject,
            "queued",
            email_type=email_type,
            metadata={**(metadata or {}), "queue_id": result.get("id")},
            trace_id=result.get("trace_id") or "",
        )
    except Exception as exc:
        logging.warning("EMAIL_QUEUED_LOG_FAILED trace_id=%s error=%s", result.get("trace_id"), exc.__class__.__name__)
    return result


def _email_retry_at(attempts):
    delay_seconds = min(3600, 30 * (2 ** max(0, int(attempts or 1) - 1)))
    return (datetime.now() + timedelta(seconds=delay_seconds)).isoformat()


def process_email_delivery_jobs(limit=10, provider_send=None):
    """Claim and process a bounded batch without recursively creating jobs."""
    provider_send = provider_send or email_service_service.send_email
    limit = max(1, min(int(limit or 10), 50))
    now = datetime.now().isoformat()
    conn = db()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM failed_email_queue
        WHERE status IN ('pending','failed','retry_ready')
          AND retry_count < COALESCE(max_attempts, 5)
          AND (next_retry_at IS NULL OR next_retry_at='' OR next_retry_at<=?)
        ORDER BY created_at ASC
        LIMIT ?
        """,
        (now, limit),
    )
    rows = [dict(row) for row in cur.fetchall()]
    conn.close()
    sent = retried = dead_letter = 0
    for row in rows:
        queue_id = int(row.get("id") or 0)
        attempts = int(row.get("retry_count") or 0) + 1
        conn = db()
        cur = conn.cursor()
        cur.execute(
            "UPDATE failed_email_queue SET status='processing', retry_count=?, updated_at=? WHERE id=? AND status IN ('pending','failed','retry_ready')",
            (attempts, datetime.now().isoformat(), queue_id),
        )
        claimed = int(getattr(cur, "rowcount", 0) or 0) > 0
        conn.commit()
        conn.close()
        if not claimed:
            continue
        try:
            result = provider_send(
                row.get("recipient_email") or "",
                row.get("subject") or "PulseSoc notification",
                row.get("html_body") or row.get("text_body") or "",
                text_body=row.get("text_body") or "",
                email_type=row.get("email_type") or "transactional",
                user_id=row.get("user_id") or 0,
            ) or {}
        except Exception as exc:
            result = {"ok": False, "error": str(exc), "status_code": None, "response": {}}
        ok = bool(result.get("ok"))
        max_attempts = int(row.get("max_attempts") or 5)
        final_status = "sent" if ok else "dead_letter" if attempts >= max_attempts else "retry_ready"
        email_log_status = email_status_from_result(result)
        next_retry_at = "" if ok or final_status == "dead_letter" else _email_retry_at(attempts)
        safe_error = "" if ok else safe_brevo_error_reason(result)
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            UPDATE failed_email_queue
            SET status=?, last_error=?, next_retry_at=?, provider_status_code=?, provider_message_id=?,
                processed_at=?, updated_at=?
            WHERE id=?
            """,
            (
                final_status,
                safe_error[:1000],
                next_retry_at,
                result.get("status_code"),
                str(result.get("message_id") or "")[:240],
                datetime.now().isoformat() if final_status in {"sent", "dead_letter"} else "",
                datetime.now().isoformat(),
                queue_id,
            ),
        )
        conn.commit()
        conn.close()
        if ok:
            sent += 1
        elif final_status == "dead_letter":
            dead_letter += 1
        else:
            retried += 1
        if not finalize_email_log_for_trace(
            row.get("trace_id") or "",
            row,
            email_log_status,
            result,
            safe_error,
            attempts,
            "sent" if ok else final_status,
        ):
            log_email_status(
                row.get("user_id") or 0,
                row.get("recipient_email") or "",
                row.get("subject") or "",
                email_log_status,
                email_type=row.get("email_type") or "transactional",
                provider="brevo",
                provider_status_code=result.get("status_code"),
                provider_message_id=result.get("message_id") or "",
                safe_error_reason=safe_error,
                metadata={"queue_id": queue_id, "queue_status": final_status},
                trace_id=row.get("trace_id") or "",
                retry_count=attempts,
            )
        logging.info("EMAIL_JOB_PROCESSED id=%s trace_id=%s status=%s attempts=%s", queue_id, row.get("trace_id") or "", final_status, attempts)
    return {"attempted": len(rows), "sent": sent, "retry": retried, "dead_letter": dead_letter}


def schedule_email_delivery_processing(reason="enqueue"):
    if os.getenv("EMAIL_OPPORTUNISTIC_PROCESSOR_ENABLED", "1").strip().lower() in {"0", "false", "off", "no"}:
        return {"ok": True, "scheduled": False, "reason": "disabled"}
    if not EMAIL_DELIVERY_PROCESSOR_LOCK.acquire(blocking=False):
        return {"ok": True, "scheduled": False, "reason": "already_running"}

    def _run():
        try:
            result = process_email_delivery_jobs(limit=int(os.getenv("EMAIL_OPPORTUNISTIC_PROCESSOR_LIMIT", "10") or 10))
            logging.info("EMAIL_PROCESSOR_COMPLETE reason=%s result=%s", reason, result)
        except Exception as exc:
            logging.exception("EMAIL_PROCESSOR_FAILED reason=%s error=%s", reason, exc)
        finally:
            EMAIL_DELIVERY_PROCESSOR_LOCK.release()

    try:
        timer = threading.Timer(0.5, _run)
        timer.daemon = True
        timer.name = "email-delivery-opportunistic"
        timer.start()
        return {"ok": True, "scheduled": True, "reason": reason}
    except Exception:
        EMAIL_DELIVERY_PROCESSOR_LOCK.release()
        raise


def retry_failed_email_queue(limit=50):
    limit = max(1, min(int(limit or 50), 200))
    conn = db()
    cur = conn.cursor()
    now = datetime.now().isoformat()
    cur.execute(
        """
        UPDATE failed_email_queue
        SET status='retry_ready', next_retry_at=?, updated_at=?
        WHERE id IN (
            SELECT id FROM failed_email_queue
            WHERE status IN ('pending','failed','retry_ready')
              AND retry_count < COALESCE(max_attempts, 5)
            ORDER BY created_at ASC
            LIMIT ?
        )
        """,
        (now, now, limit),
    )
    conn.commit()
    conn.close()
    result = process_email_delivery_jobs(limit=limit)
    logging.info("FAILED_EMAIL_QUEUE_RETRY result=%s", result)
    return result


def send_email_confirmation(user_id, to_email, subject, body):
    logging.info("Attempting transactional confirmation email for user_id: %s", user_id)
    return send_platform_email(to_email, subject, body, body.replace("\n", "<br>"), user_id)


def email_sender_identity():
    config = email_service_service.sender_config()
    return config["email"], config["name"]


def send_platform_email(to_email, subject, text_body, html_body="", user_id=None, *, email_type="transactional", trace_id="", idempotency_key="", queue_on_failure=True):
    send_platform_email.last_response = ""
    send_platform_email.last_error = ""
    trace_id = trace_id or secrets.token_hex(8)
    if not to_email:
        log_email_status(user_id or 0, "", subject, "skipped_no_email", email_type=email_type, trace_id=trace_id)
        send_platform_email.last_error = "skipped_no_email"
        return False
    from_email, from_name = email_sender_identity()
    provider = email_service_service.provider_status()
    logging.info(
        "Email send requested: provider=brevo user_id=%s to_domain=%s from=%s brevo_key_loaded=%s",
        user_id or 0,
        to_email.split("@")[-1] if "@" in to_email else "invalid",
        from_email,
        bool(provider.get("api_key_configured")),
    )
    try:
        result = email_service_service.send_email(
            to_email,
            subject,
            html_body or text_body.replace("\n", "<br>"),
            text_body=text_body,
            email_type=email_type,
            user_id=user_id,
        )
        ok = bool(result.get("ok"))
        send_platform_email.last_response = f"brevo_status={result.get('status_code')} body={json.dumps(result.get('response') or {})[:1200]}"
        send_platform_email.last_error = safe_brevo_error_reason(result)
        logging.info("Brevo API response status_code=%s body=%s", result.get("status_code"), json.dumps(result.get("response") or {})[:1200])
        message_id = result.get("message_id") or ""
        status = email_status_from_result(result)
        log_email_status(
            user_id or 0,
            to_email,
            subject,
            status,
            email_type=email_type,
            provider="brevo",
            provider_status_code=result.get("status_code"),
            provider_message_id=message_id,
            safe_error_reason="" if ok else send_platform_email.last_error,
            metadata={"missing_fields": result.get("missing_fields") or []},
            trace_id=trace_id,
        )
        if not ok and queue_on_failure:
            queue_failed_email(user_id or 0, to_email, email_type, subject, html_body, text_body, send_platform_email.last_error, idempotency_key=idempotency_key)
        return ok
    except Exception as exc:
        logging.info("Platform email failed: %s", exc)
        send_platform_email.last_error = str(exc)[:1000]
        log_email_status(user_id or 0, to_email, subject, "failed_brevo_exception", email_type=email_type, safe_error_reason=send_platform_email.last_error, trace_id=trace_id)
        if queue_on_failure:
            queue_failed_email(user_id or 0, to_email, email_type, subject, html_body, text_body, send_platform_email.last_error, idempotency_key=idempotency_key)
        return False


def send_channel_email(to_email, subject, html_body, text_body="", user_id=0, email_type="transactional", channel="transactional"):
    result = email_service_service.send_email(
        to_email,
        subject,
        html_body,
        text_body=text_body or clean_html(html_body),
        email_type=email_type,
        user_id=user_id,
        channel=channel,
    )
    status = email_status_from_result(result)
    safe_error = "" if result.get("ok") else safe_brevo_error_reason(result)
    if not result.get("ok"):
        queue_failed_email(user_id or 0, to_email, email_type, subject, html_body, text_body, safe_error, {"channel": channel, "missing_fields": result.get("missing_fields") or []})
    log_email_status(
        user_id or 0,
        to_email,
        subject,
        status,
        email_type=email_type,
        provider="brevo",
        provider_status_code=result.get("status_code"),
        provider_message_id=result.get("message_id") or "",
        safe_error_reason=safe_error,
        metadata={"channel": channel, "missing_fields": result.get("missing_fields") or []},
    )
    return bool(result.get("ok"))


