def telegram_token_configured():
    token = (BOT_TOKEN or "").strip()
    if not token:
        logging.warning("TELEGRAM_DISABLED reason=missing_bot_token")
        return False
    if ":" not in token or len(token) < 20:
        logging.warning("TELEGRAM_DISABLED reason=invalid_bot_token_shape")
        return False
    return True


def _mask_telegram_id(value):
    text = str(value or "")
    if len(text) <= 4:
        return "****" if text else ""
    return f"{text[:2]}***{text[-2:]}"


def _telegram_message_text(update):
    message = getattr(update, "effective_message", None)
    text = getattr(message, "text", "") or getattr(message, "caption", "") or ""
    return str(text).strip()[:700]


def _telegram_username(update):
    user = getattr(update, "effective_user", None)
    return (getattr(user, "username", "") or getattr(user, "first_name", "") or "")[:120]


def _telegram_user_id(update):
    user = getattr(update, "effective_user", None)
    return str(getattr(user, "id", "") or "")


def telegram_trace(event_type, update=None, handler="", latency_ms=None, exception_text="", message_text=None, telegram_user_id=None, username="", chat_id=""):
    created_at = datetime.utcnow().isoformat(timespec="seconds")
    if update is not None:
        telegram_user_id = telegram_user_id or _telegram_user_id(update)
        username = username or _telegram_username(update)
        chat = getattr(update, "effective_chat", None)
        chat_id = chat_id or getattr(chat, "id", "")
        message_text = _telegram_message_text(update) if message_text is None else message_text
    masked_chat = _mask_telegram_id(chat_id)
    safe_message = str(message_text or "")[:700]
    safe_exception = str(exception_text or "")[:1000]
    safe_latency = int(latency_ms or 0)
    logging.info(
        "%s timestamp=%s telegram_user_id=%s username=%s chat=%s handler=%s latency_ms=%s message=%s exception=%s",
        event_type,
        created_at,
        telegram_user_id or "",
        username or "",
        masked_chat,
        handler or "",
        safe_latency,
        safe_message[:240],
        safe_exception[:240],
    )
    try:
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO telegram_debug_events
            (event_type, telegram_user_id, username, chat_id_masked, message_text, handler, latency_ms, exception_text, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (event_type, str(telegram_user_id or ""), username or "", masked_chat, safe_message, handler or "", safe_latency, safe_exception, created_at),
        )
        conn.commit()
        conn.close()
    except Exception:
        logging.debug("Telegram debug event write failed", exc_info=True)


async def attempt_safe_reply(update, context, text="PulseSoc hit a temporary response issue. Please try again in a moment."):
    chat_id = getattr(getattr(update, "effective_chat", None), "id", None)
    try:
        telegram_trace("TELEGRAM_SEND_ATTEMPT", update, handler="safe_fallback")
        if getattr(update, "message", None):
            await update.message.reply_text(text)
        elif chat_id and context and getattr(context, "bot", None):
            await context.bot.send_message(chat_id=chat_id, text=text)
        else:
            telegram_trace("TELEGRAM_SEND_FAILURE", update, handler="safe_fallback", exception_text="No message or chat id available")
            return False
        now_iso = datetime.utcnow().isoformat(timespec="seconds")
        TELEGRAM_RUNTIME_STATE["last_outbound_reply_at"] = now_iso
        TELEGRAM_RUNTIME_STATE["last_successful_reply_at"] = now_iso
        telegram_trace("TELEGRAM_SEND_SUCCESS", update, handler="safe_fallback")
        record_worker_heartbeat("telegram_worker", "safe_reply_sent", metadata={
            "last_outbound_reply_at": now_iso,
            "last_successful_reply_at": now_iso,
            "chat_id_masked": _mask_telegram_id(chat_id),
        })
        return True
    except Exception as exc:
        TELEGRAM_RUNTIME_STATE["last_error"] = str(exc)
        telegram_trace("TELEGRAM_SEND_FAILURE", update, handler="safe_fallback", exception_text=str(exc))
        return False


def wrap_telegram_handler(handler, handler_name):
    async def wrapped(update: Update, context: ContextTypes.DEFAULT_TYPE):
        start_ts = time.time()
        TELEGRAM_RUNTIME_STATE["last_handler"] = handler_name
        telegram_trace("TELEGRAM_HANDLER_SELECTED", update, handler=handler_name)
        if handler_name in {"link", "connect"}:
            telegram_trace("TELEGRAM_LINK_HANDLER_START", update, handler=handler_name)
        try:
            result = await handler(update, context)
            latency = int((time.time() - start_ts) * 1000)
            TELEGRAM_RUNTIME_STATE["last_handler_latency_ms"] = latency
            return result
        except Exception as exc:
            latency = int((time.time() - start_ts) * 1000)
            TELEGRAM_RUNTIME_STATE["last_error"] = str(exc)
            TELEGRAM_RUNTIME_STATE["last_handler_latency_ms"] = latency
            telegram_trace("TELEGRAM_HANDLER_EXCEPTION", update, handler=handler_name, latency_ms=latency, exception_text=str(exc))
            logging.exception("TELEGRAM_HANDLER_EXCEPTION handler=%s error=%s", handler_name, exc)
            await attempt_safe_reply(update, context)
            return None
    return wrapped


def record_worker_heartbeat(worker_name, status="healthy", last_error="", metadata=None):
    try:
        conn = db()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO worker_heartbeats (worker_name, status, last_seen_at, last_error, metadata_json)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(worker_name) DO UPDATE SET
                status=excluded.status,
                last_seen_at=excluded.last_seen_at,
                last_error=excluded.last_error,
                metadata_json=excluded.metadata_json
            """,
            (worker_name, status, datetime.utcnow().isoformat(timespec="seconds"), str(last_error or "")[:1000], json.dumps(metadata or {})),
        )
        conn.commit()
        conn.close()
    except Exception:
        logging.exception("Worker heartbeat write failed for %s", worker_name)


def get_worker_heartbeat(worker_name):
    try:
        conn = db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("SELECT * FROM worker_heartbeats WHERE worker_name=? LIMIT 1", (worker_name,))
        row = cur.fetchone()
        conn.close()
        return dict(row) if row else {}
    except Exception:
        return {}


async def telegram_runtime_heartbeat(context: ContextTypes.DEFAULT_TYPE):
    record_worker_heartbeat("telegram_worker", "polling", metadata={
        "mode": TELEGRAM_RUNTIME_STATE.get("mode"),
        "command_handler_registered": TELEGRAM_RUNTIME_STATE.get("command_handler_registered"),
        "text_handler_registered": TELEGRAM_RUNTIME_STATE.get("text_handler_registered"),
        "openai_key_present": bool(os.getenv("OPENAI_API_KEY")),
        "last_successful_reply_at": TELEGRAM_RUNTIME_STATE.get("last_successful_reply_at"),
    })


async def telegram_activity_probe(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.effective_chat.id if update.effective_chat else ""
    username = getattr(update.effective_user, "username", "") if update.effective_user else ""
    message = update.effective_message
    message_type = "command" if message and message.text and message.text.strip().startswith("/") else "text" if message and message.text else "other"
    TELEGRAM_RUNTIME_STATE["last_inbound_update_at"] = datetime.utcnow().isoformat(timespec="seconds")
    logging.info(
        "TELEGRAM_INBOUND chat=%s username=%s type=%s handler_probe=received",
        _mask_telegram_id(chat_id),
        username or "",
        message_type,
    )
    telegram_trace("TELEGRAM_INBOUND", update, handler="activity_probe")
    record_worker_heartbeat("telegram_worker", "inbound", metadata={
        "last_inbound_update_at": TELEGRAM_RUNTIME_STATE["last_inbound_update_at"],
        "last_message_type": message_type,
        "chat_id_masked": _mask_telegram_id(chat_id),
        "username": username or "",
    })


async def telegram_startup(application):
    try:
        openai_present = bool(os.getenv("OPENAI_API_KEY"))
        TELEGRAM_RUNTIME_STATE["openai_key_present"] = openai_present
        logging.info("OPENAI_KEY_PRESENT=%s", str(openai_present).lower())
        info = await application.bot.get_webhook_info()
        webhook_url = getattr(info, "url", "") or ""
        TELEGRAM_RUNTIME_STATE["last_webhook_status"] = "set" if webhook_url else "empty"
        if webhook_url:
            await application.bot.delete_webhook(drop_pending_updates=False)
            logging.info("TELEGRAM_WEBHOOK_CLEARED before_polling url_present=true")
            TELEGRAM_RUNTIME_STATE["last_webhook_status"] = "cleared"
        me = await application.bot.get_me()
        logging.info("TELEGRAM_POLLING_STARTED bot_username=%s command_handlers=%s text_handler=%s", getattr(me, "username", ""), TELEGRAM_RUNTIME_STATE.get("command_handler_registered"), TELEGRAM_RUNTIME_STATE.get("text_handler_registered"))
        record_worker_heartbeat("telegram_worker", "polling", metadata={
            "mode": "polling",
            "bot_username": getattr(me, "username", ""),
            "webhook_was_set": bool(webhook_url),
            "webhook_status": TELEGRAM_RUNTIME_STATE.get("last_webhook_status"),
            "openai_key_present": openai_present,
            "command_handler_registered": True,
            "text_handler_registered": True,
        })
    except Exception as exc:
        TELEGRAM_RUNTIME_STATE["last_error"] = str(exc)
        record_worker_heartbeat("telegram_worker", "startup_error", str(exc), {"mode": "polling"})
        logging.exception("TELEGRAM_STARTUP_HEALTH_FAILED error=%s", exc)


def build_telegram_application(token=None):
    token = token or BOT_TOKEN
    app = ApplicationBuilder().token(token).post_init(telegram_startup).build()
    job_queue = app.job_queue
    if job_queue:
        job_queue.run_repeating(send_menu_job, interval=10800, first=30)
        job_queue.run_repeating(telegram_runtime_heartbeat, interval=45, first=5)
    else:
        logging.warning("TELEGRAM_JOB_QUEUE_DISABLED reason=missing_job_queue")

    command_handlers = {
        "start": start,
        "about": about,
        "help": help_command,
        "price": price,
        "track": track,
        "watchlist": website_watchlist_command,
        "portfolio": website_portfolio_command,
        "alerts": website_alerts_command,
        "alerts_on": alerts_on,
        "alerts_off": alerts_off,
        "addholding": addholding,
        "removeholding": removeholding,
        "myportfolio": myportfolio,
        "paper": paper,
        "deposit": deposit,
        "exchange": exchange,
        "signal": signal,
        "verify_payment": verify_payment,
        "analysis": analysis_command,
        "markets": markets_command,
        "market": market_command,
        "btc": btc_command,
        "topvolume": topvolume_command,
        "gainers": gainers_command,
        "losers": losers_command,
        "daysignal": daysignal_command,
        "ask": ask_command,
        "chart": chart_command,
        "feargreed": feargreed_command,
        "whales": whales_command,
        "whalebtc": whalebtc_command,
        "whalealerts": whalealerts_command,
        "btcstats": btcstats_command,
        "network": network_command,
        "fees": fees_command,
        "mempool": mempool_command,
        "checktx": checktx_command,
        "connectwallet": connectwallet_command,
        "walletinfo": walletinfo_command,
        "walletscan": walletscan_command,
        "scamintel": scamintel_command,
        "chainintel": chainintel_command,
        "marketpressure": marketpressure_command,
        "mining": mining_command,
        "difficulty": difficulty_command,
        "networkhealth": networkhealth_command,
        "signals": signals_command,
        "portfolio_live": portfolio_live_command,
        "setbalance": setbalance_command,
        "clearbalance": clearbalance_command,
        "portfolio_advice": portfolio_advice_command,
        "subscribe": subscribe_command,
        "upgrade": upgrade_command,
        "chat": chat_command,
        "setemail": setemail_command,
        "myemail": myemail_command,
        "account": account_command,
        "connect": connect_account_command,
        "link": connect_account_command,
        "status": status_command,
        "unlink": unlink_command,
        "help_account": help_account_command,
        "connectwebsite": connectwebsite_command,
        "admin": admin_command,
        "cryptonews": cryptonews_command,
        "marketevents": marketevents_command,
        "wisdom": wisdom_command,
        "scamstories": scamstories_command,
        "countrynews": countrynews_command,
        "sportsedge": sportsedge_command,
        "livegames": livegames_command,
        "gameedge": gameedge_command,
    }
    app.add_handler(MessageHandler(filters.ALL, telegram_activity_probe), group=-1)
    for command, handler in command_handlers.items():
        app.add_handler(CommandHandler(command, wrap_telegram_handler(handler, command)))
    app.add_handler(CallbackQueryHandler(wrap_telegram_handler(button_handler, "callback_query")))
    app.add_handler(MessageHandler(filters.VOICE, wrap_telegram_handler(voice_assistant, "voice")))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, wrap_telegram_handler(handle_message, "normal_text")))
    app.add_error_handler(telegram_error_handler)
    registered = set(command_handlers)
    TELEGRAM_RUNTIME_STATE["command_handler_registered"] = TELEGRAM_REQUIRED_COMMANDS.issubset(registered)
    TELEGRAM_RUNTIME_STATE["text_handler_registered"] = True
    return app


def keep_web_process_alive_without_telegram():
    logging.warning("Telegram subsystem disabled; Flask web app remains active.")
    while True:
        time.sleep(3600)


def main():
    init_db()
    run_trial_maintenance(force=True)
    print(f"{BOT_NAME} starting...")

    if not telegram_token_configured():
        record_worker_heartbeat("telegram_worker", "disabled", "missing or invalid bot token", {"mode": "polling"})
        keep_web_process_alive_without_telegram()

    try:
        app = build_telegram_application(BOT_TOKEN)
    except Exception as exc:
        TELEGRAM_RUNTIME_STATE["last_error"] = str(exc)
        record_worker_heartbeat("telegram_worker", "startup_error", str(exc), {"mode": "polling"})
        logging.warning("TELEGRAM_DISABLED reason=startup_error error=%s", exc)
        keep_web_process_alive_without_telegram()

    job_queue = app.job_queue
    if job_queue:
        job_queue.run_repeating(market_signal_job, interval=SIGNAL_CHECK_SECONDS, first=10)
        job_queue.run_repeating(hourly_market_update, interval=HOURLY_UPDATE_SECONDS, first=30)
        job_queue.run_repeating(whale_alert_job, interval=WHALE_CHECK_SECONDS, first=45)
        job_queue.run_repeating(portfolio_tracking_job, interval=PORTFOLIO_TRACK_SECONDS, first=60)
        job_queue.run_repeating(trial_maintenance_job, interval=3600, first=120)

    try:
        logging.info("TELEGRAM_POLLING_STARTED command_handlers=%s text_handler=%s openai_key_present=%s", TELEGRAM_RUNTIME_STATE.get("command_handler_registered"), TELEGRAM_RUNTIME_STATE.get("text_handler_registered"), bool(os.getenv("OPENAI_API_KEY")))
        record_worker_heartbeat("telegram_worker", "polling_starting", metadata={"mode": "polling", "command_handler_registered": TELEGRAM_RUNTIME_STATE.get("command_handler_registered"), "text_handler_registered": TELEGRAM_RUNTIME_STATE.get("text_handler_registered")})
        app.run_polling(drop_pending_updates=False)
    except Exception as exc:
        TELEGRAM_RUNTIME_STATE["last_error"] = str(exc)
        record_worker_heartbeat("telegram_worker", "polling_error", str(exc), {"mode": "polling"})
        logging.warning("TELEGRAM_DISABLED reason=polling_startup_error error=%s", exc)
        keep_web_process_alive_without_telegram()


def initialize_database_for_web_startup():
    global INIT_DB_THREAD_STARTED
    if os.getenv("COINPILOTX_INIT_DB_ON_IMPORT", "1").strip().lower() in {"0", "false", "no", "off"}:
        logging.info("DB init on import disabled by COINPILOTX_INIT_DB_ON_IMPORT.")
        return
    startup_mode = os.getenv("COINPILOTX_DB_INIT_STARTUP_MODE", "").strip().lower()
    if not startup_mode:
        startup_mode = "async" if _deployment_environment_enabled() else "sync"
    if startup_mode == "sync" or os.getenv("COINPILOTX_SYNC_DB_INIT_ON_IMPORT", "").strip().lower() in {"1", "true", "yes", "on"}:
        init_db()
        return
    if INIT_DB_THREAD_STARTED:
        logging.info("DB_INIT_BACKGROUND_SKIPPED_ALREADY_STARTED")
        return
    INIT_DB_THREAD_STARTED = True

    def _run_startup_init():
        try:
            init_db()
        except Exception as exc:
            logging.exception("DB_INIT_BACKGROUND_FAILED error=%s", exc)

    threading.Thread(target=_run_startup_init, name="coinpilotx-db-init", daemon=True).start()
    logging.info("DB_INIT_BACKGROUND_STARTED")


if __name__ != "__main__":
    initialize_database_for_web_startup()


if __name__ == "__main__":
    threading.Thread(target=run_webhook, daemon=True).start()
    main()

print("CoinPilotX web boot complete", flush=True)
